import { db } from '../firebase';
import { 
  doc, 
  setDoc, 
  getDoc, 
  collection, 
  onSnapshot, 
  addDoc, 
  updateDoc, 
  deleteDoc,
  query,
  orderBy,
  writeBatch
} from 'firebase/firestore';
import { FamilyProfile, Expense, ShoppingItem, Store, RecurringExpense, Income, Member } from '../types';

// --- FAMILY MANAGEMENT ---

export const createFamilyGroup = async (familyName: string, initialMembers: Member[]): Promise<FamilyProfile> => {
  // Genera un codice famiglia semplice (es. ROSSI-1234)
  const code = `${familyName.toUpperCase().replace(/[^A-Z]/g, '')}-${Math.floor(1000 + Math.random() * 9000)}`;

  const newProfile: FamilyProfile = {
    id: code,
    familyName,
    members: initialMembers,
    createdAt: Date.now()
  };

  // Salva il profilo principale
  await setDoc(doc(db, "families", code), newProfile);
  return newProfile;
};

export const joinFamilyGroup = async (familyId: string): Promise<FamilyProfile | null> => {
  const docRef = doc(db, "families", familyId);
  const docSnap = await getDoc(docRef);

  if (docSnap.exists()) {
    return docSnap.data() as FamilyProfile;
  } else {
    return null;
  }
};

// --- REALTIME LISTENERS ---

// Helper generico per ascoltare una sub-collezione
export const subscribeToCollection = (
  familyId: string, 
  collectionName: string, 
  callback: (data: any[]) => void
) => {
  const q = query(collection(db, "families", familyId, collectionName));

  return onSnapshot(q, (snapshot) => {
    const items = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
    callback(items);
  });
};

// --- CRUD OPERATIONS ---

// Expenses
export const addExpenseToFirebase = async (familyId: string, expense: Expense) => {
  // Usa l'ID generato dall'app come ID del documento per consistenza
  await setDoc(doc(db, "families", familyId, "expenses", expense.id), expense);
};
export const updateExpenseInFirebase = async (familyId: string, expense: Expense) => {
  await updateDoc(doc(db, "families", familyId, "expenses", expense.id), { ...expense });
};
export const deleteExpenseFromFirebase = async (familyId: string, expenseId: string) => {
  await deleteDoc(doc(db, "families", familyId, "expenses", expenseId));
};

// Shopping List
