};
export const updateShoppingItemInFirebase = async (familyId: string, item: ShoppingItem) => {
  await updateDoc(doc(db, "families", familyId, "shoppingList", item.id), { ...item });
};
export const deleteShoppingItemFromFirebase = async (familyId: string, itemId: string) => {
  await deleteDoc(doc(db, "families", familyId, "shoppingList", itemId));
};

// Incomes
