import React, { useState } from 'react';
import { FamilyProfile, Member } from '../types';
import { createFamilyGroup, joinFamilyGroup } from '../services/firebaseService';
import { Users, ArrowRight, UserPlus, LogIn, Sparkles, Loader2, AlertCircle } from 'lucide-react';

interface LoginScreenProps {
  existingProfile: FamilyProfile | null;
  onLogin: () => void;
  onSetupComplete: (profile: FamilyProfile) => void;
  onResetProfile: () => void;
}

const COLORS = ['#10B981', '#3B82F6', '#F59E0B', '#EC4899', '#8B5CF6', '#6366F1'];

export const LoginScreen: React.FC<LoginScreenProps> = ({ existingProfile, onLogin, onSetupComplete, onResetProfile }) => {
  const [mode, setMode] = useState<'welcome' | 'create' | 'join'>('welcome');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // Create State
  const [familyName, setFamilyName] = useState('');
  const [members, setMembers] = useState<Member[]>([
    { id: '1', name: 'Papà', color: COLORS[1] },
    { id: '2', name: 'Mamma', color: COLORS[3] }
  ]);
  const [newMemberName, setNewMemberName] = useState('');

  // Join State
  const [joinCode, setJoinCode] = useState('');

  // Se esiste già un profilo salvato localmente, proviamo ad accedere automaticamente o mostriamo bentornato
  // Ma in questo nuovo flusso, se c'è un profilo, App.tsx dovrebbe averlo già gestito. 
  // Se siamo qui, probabilmente è il primo accesso o logout.

  const handleAddMember = () => {
    if (!newMemberName.trim()) return;
    const color = COLORS[members.length % COLORS.length];
    setMembers([...members, { id: crypto.randomUUID(), name: newMemberName.trim(), color }]);
    setNewMemberName('');
  };

  const handleCreateSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!familyName || members.length === 0) {
      setError('Inserisci il nome della famiglia e almeno un membro.');
      return;
    }

    setLoading(true);
    setError('');
    try {
      const profile = await createFamilyGroup(familyName, members);
      onSetupComplete(profile);
    } catch (err) {
      console.error(err);
      setError('Errore durante la creazione. Riprova.');
    } finally {
      setLoading(false);
    }
  };

  const handleJoinSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!joinCode.trim()) return;

    setLoading(true);
    setError('');
    try {
      const profile = await joinFamilyGroup(joinCode.trim().toUpperCase());
      if (profile) {
        onSetupComplete(profile);
      } else {
        setError('Codice famiglia non trovato. Controlla e riprova.');
      }
    } catch (err) {
      console.error(err);
      setError('Errore di connessione. Riprova.');
    } finally {
      setLoading(false);
    }
  };

  if (mode === 'welcome') {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
        <div className="bg-white p-8 rounded-3xl shadow-xl max-w-md w-full border border-gray-100 text-center space-y-8">
           <div className="space-y-2">
             <div className="bg-gradient-to-tr from-emerald-400 to-teal-600 w-20 h-20 rounded-2xl flex items-center justify-center mx-auto shadow-lg transform -rotate-6">
                <Sparkles className="w-10 h-10 text-white" />
             </div>
             <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">Spese Familiari</h1>
             <p className="text-gray-500 text-lg">Sincronizza le spese con tutta la famiglia, in tempo reale.</p>
           </div>

           <div className="space-y-4 pt-4">
              <button 
                onClick={() => setMode('create')}
                className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-4 px-6 rounded-2xl transition-all shadow-md hover:shadow-lg flex items-center justify-center gap-3 text-lg"
              >
                <UserPlus className="w-6 h-6" /> Crea Nuova Famiglia
              </button>

              <button 
                onClick={() => setMode('join')}
                className="w-full bg-white border-2 border-emerald-100 hover:border-emerald-300 text-emerald-800 font-bold py-4 px-6 rounded-2xl transition-all flex items-center justify-center gap-3 text-lg"
              >
                <LogIn className="w-6 h-6" /> Ho un Codice Famiglia
              </button>
           </div>

           <p className="text-xs text-gray-400">Nessun account richiesto. Solo un codice condiviso.</p>
        </div>
      </div>
    );
  }

  if (mode === 'create') {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
        <div className="bg-white p-8 rounded-3xl shadow-xl max-w-md w-full border border-gray-100 relative">
          <button onClick={() => setMode('welcome')} className="absolute top-4 left-4 text-gray-400 hover:text-gray-600">Indietro</button>

          <div className="text-center mb-6 mt-2">
            <h2 className="text-2xl font-bold text-gray-800">Crea Spazio</h2>
            <p className="text-gray-500 text-sm">Genereremo un codice unico per voi.</p>
          </div>

          <form onSubmit={handleCreateSubmit} className="space-y-6">
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-wide mb-1">Cognome / Nome Gruppo</label>
              <input
                type="text"
                value={familyName}
                onChange={(e) => setFamilyName(e.target.value)}
                placeholder="Es. Famiglia Rossi"
                className="w-full rounded-xl border border-gray-300 p-3.5 focus:border-emerald-500 outline-none transition-all"
                required
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-wide mb-2">Chi ne fa parte?</label>
              <div className="flex flex-wrap gap-2 mb-3">
                {members.map((m) => (
                  <span key={m.id} className="px-3 py-1 rounded-full bg-emerald-50 text-emerald-800 text-sm flex items-center gap-1 border border-emerald-100">
                     <span className="w-2 h-2 rounded-full" style={{ backgroundColor: m.color }}></span>
                     {m.name}
                  </span>
                ))}
              </div>
              <div className="flex gap-2">
                <input
                  type="text"
                  value={newMemberName}
                  onChange={(e) => setNewMemberName(e.target.value)}
                  placeholder="Nome membro..."
                  className="flex-1 rounded-xl border border-gray-300 p-2.5 text-sm focus:border-emerald-500 outline-none"
                />
                <button
                  type="button"
                  onClick={handleAddMember}
                  className="bg-emerald-100 text-emerald-700 p-2.5 rounded-xl hover:bg-emerald-200"
                >
                  <UserPlus className="w-5 h-5" />
                </button>
              </div>
            </div>

            {error && <div className="flex items-center gap-2 text-red-500 text-sm bg-red-50 p-3 rounded-xl"><AlertCircle className="w-4 h-4" /> {error}</div>}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-4 px-6 rounded-2xl transition-all shadow-md flex items-center justify-center gap-2 disabled:opacity-70"
            >
              {loading ? <Loader2 className="animate-spin" /> : 'Genera Codice Famiglia'}
            </button>
          </form>
        </div>
      </div>
    );
  }

  if (mode === 'join') {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
        <div className="bg-white p-8 rounded-3xl shadow-xl max-w-md w-full border border-gray-100 relative">
          <button onClick={() => setMode('welcome')} className="absolute top-4 left-4 text-gray-400 hover:text-gray-600">Indietro</button>

          <div className="text-center mb-8 mt-2">
            <h2 className="text-2xl font-bold text-gray-800">Unisciti alla Famiglia</h2>
            <p className="text-gray-500 text-sm">Inserisci il codice condiviso da un familiare.</p>
          </div>

          <form onSubmit={handleJoinSubmit} className="space-y-6">
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-wide mb-1">Codice Famiglia</label>
              <input
                type="text"
                value={joinCode}
                onChange={(e) => setJoinCode(e.target.value)}
                placeholder="Es. ROSSI-1234"
                className="w-full rounded-xl border-2 border-gray-300 p-4 text-center text-xl font-mono tracking-widest uppercase focus:border-emerald-500 outline-none transition-all"
                required
              />
            </div>

            {error && <div className="flex items-center gap-2 text-red-500 text-sm bg-red-50 p-3 rounded-xl"><AlertCircle className="w-4 h-4" /> {error}</div>}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-4 px-6 rounded-2xl transition-all shadow-md flex items-center justify-center gap-2 disabled:opacity-70"
            >
              {loading ? <Loader2 className="animate-spin" /> : <><ArrowRight className="w-5 h-5" /> Entra nel Gruppo</>}
            </button>
          </form>
        </div>
      </div>
    );
  }

  return null;
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { DEFAULT_STORES, Expense, Store, RecurringExpense, Frequency, FamilyProfile, SyncData, ShoppingItem, OfferPreferences, Income } from './types';
import { 
  addExpenseToFirebase, updateExpenseInFirebase, deleteExpenseFromFirebase,
  addShoppingItemToFirebase, updateShoppingItemInFirebase, deleteShoppingItemFromFirebase,
  addIncomeToFirebase, deleteIncomeFromFirebase,
  addStoreToFirebase,
  addRecurringToFirebase, deleteRecurringFromFirebase, updateRecurringInFirebase,
  subscribeToCollection
} from './services/firebaseService';

import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { StoreManager } from './components/StoreManager';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { ExpenseFilters, FilterState } from './components/ExpenseFilters';
import { ReceiptScanner } from './components/ReceiptScanner';
import { LoginScreen } from './components/LoginScreen';
import { DataSync } from './components/DataSync';
import { GoogleSheetSync } from './components/GoogleSheetSync';
import { ShoppingListManager } from './components/ShoppingListManager';
import { OffersFinder } from './components/OffersFinder';
import { IncomeManager } from './components/IncomeManager';
import { categorizeExpense, ReceiptData, findFlyerOffers } from './services/geminiService';
import { 
  WalletCards, 
  Download, 
  Share2, 
  LogOut, 
  Table, 
  Menu, 
  X,
  Home,
  History,
  ShoppingCart,
  Percent,
  Repeat,
  BarChart3,
  ChevronRight,
  Coins,
  Copy,
  Check
} from 'lucide-react';

type View = 'dashboard' | 'history' | 'shopping' | 'offers' | 'recurring' | 'analytics' | 'budget';

function App() {
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(() => {
    const saved = localStorage.getItem('familyProfile');
    return saved ? JSON.parse(saved) : null;
  });

  const [isAuthenticated, setIsAuthenticated] = useState(!!familyProfile);

  // Data State - ora inizializzati vuoti e riempiti da Firebase
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [stores, setStores] = useState<Store[]>([]);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [shoppingList, setShoppingList] = useState<ShoppingItem[]>([]);

  // Local preferences (keep in local storage)
  const [offerPrefs, setOfferPrefs] = useState<OfferPreferences>(() => {
    const saved = localStorage.getItem('offerPrefs');
    return saved ? JSON.parse(saved) : { 
      city: '', 
      selectedStores: [], 
      lastCheckDate: 0, 
      hasEnabledNotifications: false 
    };
  });

  const [newOffersCount, setNewOffersCount] = useState(0);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [filters, setFilters] = useState<FilterState>({
    store: '', category: '', startDate: '', endDate: ''
  });

  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [showSync, setShowSync] = useState(false);
  const [showGoogleSheet, setShowGoogleSheet] = useState(false);
  const [copiedCode, setCopiedCode] = useState(false);

  // --- FIREBASE SYNC LOGIC ---
  useEffect(() => {
    if (!isAuthenticated || !familyProfile?.id) return;

    // Sottoscrizione alle collezioni Firebase
    const unsubExpenses = subscribeToCollection(familyProfile.id, "expenses", (data) => {
      // Normalizza i dati se necessario (es. date)
      const sorted = (data as Expense[]).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      setExpenses(sorted);
    });

    const unsubShopping = subscribeToCollection(familyProfile.id, "shoppingList", (data) => {
      setShoppingList(data as ShoppingItem[]);
    });

    const unsubIncomes = subscribeToCollection(familyProfile.id, "incomes", (data) => {
      const sorted = (data as Income[]).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      setIncomes(sorted);
    });

    const unsubStores = subscribeToCollection(familyProfile.id, "stores", (data) => {
      if (data.length > 0) setStores(data as Store[]);
      else setStores(DEFAULT_STORES); // Fallback se DB vuoto
    });

    const unsubRecurring = subscribeToCollection(familyProfile.id, "recurringExpenses", (data) => {
      setRecurringExpenses(data as RecurringExpense[]);
    });

    return () => {
      unsubExpenses();
      unsubShopping();
      unsubIncomes();
      unsubStores();
      unsubRecurring();
    };
  }, [isAuthenticated, familyProfile?.id]);


  // Persistence LocalStorage (Only Profile & Prefs)
  useEffect(() => {
    if (familyProfile) localStorage.setItem('familyProfile', JSON.stringify(familyProfile));
    else localStorage.removeItem('familyProfile');
  }, [familyProfile]);

  useEffect(() => { localStorage.setItem('offerPrefs', JSON.stringify(offerPrefs)); }, [offerPrefs]);

  // --- ACTIONS (Now calling Firebase) ---

  const handleCopyCode = () => {
    if (familyProfile?.id) {
        navigator.clipboard.writeText(familyProfile.id);
        setCopiedCode(true);
        setTimeout(() => setCopiedCode(false), 2000);
    }
  };

  useEffect(() => {
    const checkOffersInBackground = async () => {
      if (!offerPrefs.city || offerPrefs.selectedStores.length === 0) return;
      const now = Date.now();
      if (now - offerPrefs.lastCheckDate > (24 * 60 * 60 * 1000)) {
        try {
          const results = await findFlyerOffers(offerPrefs.city, offerPrefs.selectedStores);
          if (results.length > 0) {
            setNewOffersCount(results.length);
          }
          setOfferPrefs(prev => ({ ...prev, lastCheckDate: now }));
        } catch (e) {}
      }
    };
    const timer = setTimeout(() => { checkOffersInBackground(); }, 5000);
    return () => clearTimeout(timer);
  }, [offerPrefs.city, offerPrefs.selectedStores, offerPrefs.lastCheckDate]);

  const categories = useMemo(() => {
    const unique = new Set(expenses.map(e => e.category));
    return Array.from(unique).sort();
  }, [expenses]);

  const filteredExpenses = useMemo(() => {
    return expenses.filter(expense => {
      const matchStore = filters.store ? expense.store === filters.store : true;
      const matchCategory = filters.category ? expense.category === filters.category : true;
      const matchStartDate = filters.startDate ? new Date(expense.date) >= new Date(filters.startDate) : true;
      const matchEndDate = filters.endDate ? new Date(expense.date) <= new Date(filters.endDate + 'T23:59:59') : true;
      return matchStore && matchCategory && matchStartDate && matchEndDate;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [expenses, filters]);

  const filteredTotal = useMemo(() => {
    return filteredExpenses.reduce((sum, e) => sum + e.total, 0);
  }, [filteredExpenses]);

  const dueRecurringExpenses = useMemo(() => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return recurringExpenses.filter(r => new Date(r.nextDueDate) <= today);
  }, [recurringExpenses]);

  const productHistoryMap = useMemo(() => {
    const map: Record<string, string> = {};
    expenses.forEach(e => {
        map[e.product] = e.store;
    });
    return map;
  }, [expenses]);

  const handleLogin = () => setIsAuthenticated(true);

  const handleSetupComplete = (profile: FamilyProfile) => {
    setFamilyProfile(profile);
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setFamilyProfile(null);
    localStorage.removeItem('familyProfile');
    setIsMenuOpen(false);
  };

  const handleResetProfile = () => {
    handleLogout();
  };

  const handleOfferPrefsChange = (city: string, stores: string[], notificationsEnabled: boolean) => {
    setOfferPrefs(prev => ({ ...prev, city, selectedStores: stores, hasEnabledNotifications: notificationsEnabled }));
  };

  const handleAddExpense = async (product: string, quantity: number, unitPrice: number, total: number, store: string) => {
    if (!familyProfile?.id) return;
    setIsAIProcessing(true);
    const category = await categorizeExpense(product, store);

    const newExpense: Expense = {
      id: crypto.randomUUID(),
      product, quantity, unitPrice, total, store,
      date: new Date().toISOString(),
      category
    };

    await addExpenseToFirebase(familyProfile.id, newExpense);
    setIsAIProcessing(false);
  };

  const handleAddIncome = async (source: string, amount: number, date: string) => {
    if (!familyProfile?.id) return;
    const newIncome: Income = {
      id: crypto.randomUUID(),
      source,
      amount,
      date
    };
    await addIncomeToFirebase(familyProfile.id, newIncome);
  };

  const handleDeleteIncome = async (id: string) => {
    if (!familyProfile?.id) return;
    await deleteIncomeFromFirebase(familyProfile.id, id);
  };

  const handleUpdateExpense = async (updated: Expense) => {
    if (!familyProfile?.id) return;
    await updateExpenseInFirebase(familyProfile.id, updated);
  };

  const handleDeleteExpense = async (id: string) => {
    if (!familyProfile?.id) return;
    if (confirm('Sei sicuro di voler eliminare questa spesa?')) {
      await deleteExpenseFromFirebase(familyProfile.id, id);
    }
  };

  const handleScanComplete = (data: ReceiptData) => {
    if (!familyProfile?.id) return;
    const storeExists = stores.some(s => s.name.toLowerCase() === data.store.toLowerCase());
    if (!storeExists && data.store) handleAddStore(data.store);

    data.items.forEach(async (item) => {
        const newExpense: Expense = {
            id: crypto.randomUUID(),
            product: item.product, quantity: item.quantity, unitPrice: item.unitPrice, total: item.total,
            store: data.store || 'Non specificato',
            date: data.date || new Date().toISOString(),
            category: item.category
        };
        await addExpenseToFirebase(familyProfile.id, newExpense);
    });

    alert(`Aggiunti ${data.items.length} prodotti con successo!`);
  };

  const handleExportCSV = () => {
    const headers = ["Data", "Prodotto", "Negozio", "Categoria", "Quantità", "Prezzo Unit.", "Totale"];
    const rows = expenses.map(e => {
       return [
        new Date(e.date).toLocaleDateString(),
        `"${e.product.replace(/"/g, '""')}"`, `"${e.store}"`, e.category, e.quantity, e.unitPrice.toFixed(2), e.total.toFixed(2)
      ].join(",");
    });
    const blob = new Blob([[headers.join(","), ...rows].join("\n")], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `spese_${new Date().toISOString().slice(0,10)}.csv`;
    link.click();
  };

  const handleAddStore = async (name: string) => {
    if (!familyProfile?.id) return;
    if (!stores.find(s => s.name.toLowerCase() === name.toLowerCase())) {
        const newStore = { id: crypto.randomUUID(), name };
        await addStoreToFirebase(familyProfile.id, newStore);
    }
  };

  const handleAddRecurring = async (product: string, amount: number, store: string, frequency: Frequency, nextDate: string) => {
    if (!familyProfile?.id) return;
    await addRecurringToFirebase(familyProfile.id, { id: crypto.randomUUID(), product, amount, store, frequency, nextDueDate: nextDate });
  };

  const handleDeleteRecurring = async (id: string) => {
    if (!familyProfile?.id) return;
    await deleteRecurringFromFirebase(familyProfile.id, id);
  };

  const handleProcessRecurring = async (recExpense: RecurringExpense) => {
    if (!familyProfile?.id) return;
    await handleAddExpense(recExpense.product, 1, recExpense.amount, recExpense.amount, recExpense.store);
    const nextDate = new Date(recExpense.nextDueDate);
    if (recExpense.frequency === 'settimanale') nextDate.setDate(nextDate.getDate() + 7);
    if (recExpense.frequency === 'mensile') nextDate.setMonth(nextDate.getMonth() + 1);
    if (recExpense.frequency === 'annuale') nextDate.setFullYear(nextDate.getFullYear() + 1);

    await updateRecurringInFirebase(familyProfile.id, { ...recExpense, nextDueDate: nextDate.toISOString().split('T')[0] });
  };

  const handleAddShoppingItem = async (product: string, store: string) => {
    if (!familyProfile?.id) return;
    await addShoppingItemToFirebase(familyProfile.id, { id: crypto.randomUUID(), product, store, completed: false });
  };

  const handleToggleShoppingItem = async (id: string) => {
    if (!familyProfile?.id) return;
    const item = shoppingList.find(i => i.id === id);
    if (item) {
        await updateShoppingItemInFirebase(familyProfile.id, { ...item, completed: !item.completed });
    }
  };

  const handleDeleteShoppingItem = async (id: string) => {
    if (!familyProfile?.id) return;
    await deleteShoppingItemFromFirebase(familyProfile.id, id);
  };

  const MenuButton: React.FC<{ view: View, icon: React.ReactNode, label: string, badge?: number }> = ({ view, icon, label, badge }) => (
    <button 
      onClick={() => { setCurrentView(view); if(view === 'offers') setNewOffersCount(0); setIsMenuOpen(false); }}
      className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl transition-colors relative ${
        currentView === view ? 'bg-emerald-100 text-emerald-800 font-bold' : 'text-gray-700 hover:bg-gray-100 font-medium'
      }`}
    >
      {React.cloneElement(icon as React.ReactElement<any>, { className: 'w-6 h-6' })}
      <span className="text-lg">{label}</span>
      {badge ? <span className="bg-red-500 text-white text-xs font-bold px-2 py-0.5 rounded-full absolute right-10">{badge}</span> : null}
      {currentView === view && <ChevronRight className="w-5 h-5 ml-auto text-emerald-600" />}
    </button>
  );

  const renderContent = () => {
    switch(currentView) {
      case 'dashboard': return (
          <div className="space-y-6 animate-in fade-in">
             <DueExpensesAlert dueExpenses={dueRecurringExpenses} onProcessExpense={handleProcessRecurring} />
             <ReceiptScanner onScanComplete={handleScanComplete} />
             <ExpenseForm 
                stores={stores} members={familyProfile?.members || []}
                existingProducts={Array.from(new Set(expenses.map(e => e.product)))}
                productHistory={productHistoryMap}
                onAddExpense={handleAddExpense} isAnalyzing={isAIProcessing}
             />
             <StoreManager onAddStore={handleAddStore} />
          </div>
        );
      case 'history': return (
          <div className="space-y-4 animate-in fade-in">
            <div className="flex justify-between items-center mb-4">
                <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-3"><History className="w-7 h-7 text-emerald-600" /> Storico Transazioni</h2>
                {expenses.length > 0 && <button onClick={handleExportCSV} className="flex items-center gap-2 text-sm font-bold text-emerald-600 bg-emerald-50 px-4 py-3 rounded-xl border border-emerald-100"><Download className="w-5 h-5" /> Esporta</button>}
            </div>
            <ExpenseFilters stores={stores} categories={categories} filters={filters} onFilterChange={(k, v) => setFilters(p => ({ ...p, [k]: v }))} onClearFilters={() => setFilters({ store: '', category: '', startDate: '', endDate: '' })} />
            {(filters.store || filters.category || filters.startDate || filters.endDate) && (
                <div className="bg-emerald-50 border border-emerald-200 rounded-xl p-4 mb-4 flex justify-between items-center">
                    <span className="text-base text-emerald-800 font-bold">Totale spese filtrate:</span>
                    <span className="text-xl font-extrabold text-emerald-700">€{filteredTotal.toFixed(2)}</span>
                </div>
            )}
            <ExpenseList expenses={filteredExpenses} members={familyProfile?.members || []} stores={stores} onDelete={handleDeleteExpense} onEdit={handleUpdateExpense} />
          </div>
        );
      case 'shopping': return (
           <div className="animate-in fade-in">
             <div className="mb-6"><h2 className="text-2xl font-bold text-gray-800 flex items-center gap-3"><ShoppingCart className="w-7 h-7 text-orange-500" /> Lista della Spesa</h2></div>
             <ShoppingListManager items={shoppingList} stores={stores} productHistory={productHistoryMap} onAddItem={handleAddShoppingItem} onToggleItem={handleToggleShoppingItem} onDeleteItem={handleDeleteShoppingItem} />
           </div>
        );
      case 'offers': return (
          <div className="animate-in fade-in">
            <div className="mb-6"><h2 className="text-2xl font-bold text-gray-800 flex items-center gap-3"><Percent className="w-7 h-7 text-red-500" /> Caccia alle Offerte</h2></div>
            <OffersFinder stores={stores} savedCity={offerPrefs.city} savedStores={offerPrefs.selectedStores} notificationsEnabled={offerPrefs.hasEnabledNotifications} onPreferencesChange={handleOfferPrefsChange} />
          </div>
        );
      case 'recurring': return (
          <div className="animate-in fade-in">
            <div className="mb-6"><h2 className="text-2xl font-bold text-gray-800 flex items-center gap-3"><Repeat className="w-7 h-7 text-purple-600" /> Spese Ricorrenti</h2></div>
             <RecurringManager recurringExpenses={recurringExpenses} stores={stores} onAddRecurring={handleAddRecurring} onDeleteRecurring={handleDeleteRecurring} />
          </div>
        );
      case 'analytics': return (
          <div className="animate-in fade-in">
             <div className="mb-6"><h2 className="text-2xl font-bold text-gray-800 flex items-center gap-3"><BarChart3 className="w-7 h-7 text-indigo-600" /> Analisi & Consigli</h2></div>
             <Analytics expenses={filteredExpenses} />
             <AIInsight expenses={filteredExpenses} />
          </div>
        );
      case 'budget': return (
          <div className="animate-in fade-in">
              <div className="mb-6"><h2 className="text-2xl font-bold text-gray-800 flex items-center gap-3"><Coins className="w-7 h-7 text-yellow-500" /> Bilancio & Guadagni</h2></div>
              <IncomeManager incomes={incomes} expenses={expenses} onAddIncome={handleAddIncome} onDeleteIncome={handleDeleteIncome} />
          </div>
      );
      default: return null;
    }
  };

  if (!isAuthenticated) return <LoginScreen existingProfile={familyProfile} onLogin={handleLogin} onSetupComplete={handleSetupComplete} onResetProfile={handleResetProfile} />;

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans pb-24 safe-area-top">
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30">
        <div className="max-w-5xl mx-auto px-4 h-18 flex items-center justify-between py-3">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMenuOpen(true)} className="p-3 -ml-2 text-gray-700 hover:bg-gray-100 rounded-xl transition-colors active:scale-95 relative">
                <Menu className="w-7 h-7" />
                {newOffersCount > 0 && <span className="absolute top-2 right-2 w-3 h-3 bg-red-500 rounded-full border-2 border-white"></span>}
             </button>
             <div className="flex items-center gap-3 overflow-hidden" onClick={() => setCurrentView('dashboard')}>
                <div className="bg-emerald-100 p-2 rounded-xl flex-shrink-0"><WalletCards className="w-6 h-6 text-emerald-600" /></div>
                <div className="min-w-0 cursor-pointer">
                    <h1 className="font-bold text-lg leading-tight text-gray-800 truncate">Spese {familyProfile?.familyName}</h1>
                </div>
             </div>
          </div>
          <div className="flex items-center gap-2">
             <div className="hidden md:flex items-center gap-2">
               <button onClick={() => setCurrentView('shopping')} className="p-3 text-gray-500 hover:text-emerald-600" title="Lista Spesa"><ShoppingCart className="w-6 h-6" /></button>
               <button onClick={() => setCurrentView('history')} className="p-3 text-gray-500 hover:text-emerald-600" title="Storico"><History className="w-6 h-6" /></button>
             </div>
