                 <button onClick={() => setIsMenuOpen(false)} className="p-3 hover:bg-gray-200 rounded-full"><X className="w-6 h-6 text-gray-500" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-2">
                 {/* COPY CODE SHORTCUT */}
                 <button 
                    onClick={handleCopyCode} 
                    className={`w-full flex items-center justify-between p-3 rounded-lg border text-sm font-medium mb-4 transition-colors ${copiedCode ? 'bg-green-50 border-green-200 text-green-700' : 'bg-gray-50 border-gray-200 text-gray-600'}`}
                 >
                    <span className="flex items-center gap-2"><Share2 className="w-4 h-4" /> Copia Codice Famiglia</span>
