Ecco l'implementazione per collegare la tua app a Supabase.

Questa modifica trasforma l'app da "locale" (localStorage) a "cloud" (Supabase).
Ho creato un servizio dedicato che gestisce tutte le chiamate al database e ho aggiornato `App.tsx` per caricare e salvare i dati su Supabase invece che solo nel browser.

### ⚠️ Istruzioni Importanti (Da fare prima)

Poiché non posso accedere al tuo pannello Supabase, devi eseguire questo script SQL nell'**SQL Editor** di Supabase per creare le tabelle necessarie:

```sql
-- Abilita l'estensione UUID se non presente
create extension if not exists "uuid-ossp";

-- Tabella Famiglie
create table families (
  id text primary key,
  family_name text not null,
  members jsonb, -- Salviamo i membri come JSON per semplicità
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- Tabella Spese
create table expenses (
  id uuid default uuid_generate_v4() primary key,
  family_id text references families(id) on delete cascade,
  product text not null,
  quantity numeric default 1,
  unit_price numeric default 0,
  total numeric not null,
  store text not null,
  date timestamp with time zone not null,
  category text not null,
  member_id text
);

-- Tabella Entrate
create table incomes (
  id uuid default uuid_generate_v4() primary key,
  family_id text references families(id) on delete cascade,
  source text not null,
  amount numeric not null,
  date timestamp with time zone not null
);

-- Tabella Negozi
create table stores (
  id uuid default uuid_generate_v4() primary key,
  family_id text references families(id) on delete cascade,
  name text not null
);

-- Tabella Categorie
create table categories (
  id uuid default uuid_generate_v4() primary key,
  family_id text references families(id) on delete cascade,
  name text not null,
  icon text not null,
  color text not null
);

-- Tabella Spese Ricorrenti
create table recurring_expenses (
  id uuid default uuid_generate_v4() primary key,
  family_id text references families(id) on delete cascade,
  product text not null,
  amount numeric not null,
  store text not null,
  frequency text not null,
  next_due_date timestamp with time zone not null,
  reminder_days integer default 0
);

-- Tabella Lista Spesa
create table shopping_list (
  id uuid default uuid_generate_v4() primary key,
  family_id text references families(id) on delete cascade,
  product text not null,
  store text not null,
  completed boolean default false
);

-- Disabilita RLS per permettere l'accesso pubblico (visto che l'app usa ID generati lato client)
-- Nota: In produzione dovresti implementare Auth
alter table families enable row level security;
create policy "Public Access" on families for all using (true) with check (true);

alter table expenses enable row level security;
create policy "Public Access" on expenses for all using (true) with check (true);

alter table incomes enable row level security;
