import { Sparkles, Loader2, AlertCircle, LogIn, UserPlus } from 'lucide-react';
import { signInWithGoogle, joinFamily, getFamilyProfile } from '../services/supabaseService';
import { supabase } from '../src/supabaseClient';

interface LoginScreenProps {
  existingProfile: FamilyProfile | null;
  onLogin: () => void;
  onSetupComplete: (profile: FamilyProfile) => void;
  onResetProfile: () => void;
  isSupabaseAuth?: boolean; // Se siamo autenticati con Supabase ma serve definire la famiglia
}

export const LoginScreen: React.FC<LoginScreenProps> = ({ existingProfile, onLogin, onSetupComplete, isSupabaseAuth }) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [familyName, setFamilyName] = useState('');
  const [familyIdToJoin, setFamilyIdToJoin] = useState('');
  const [mode, setMode] = useState<'create' | 'join'>('create');

  const handleGoogleLogin = async () => {
    setLoading(true);
    await signInWithGoogle();
  };

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!familyName) {
      setError('Inserisci il nome della famiglia.');
      return;
    }
    setLoading(true);

    const newProfile: FamilyProfile = {
      id: crypto.randomUUID(),
      familyName,
      members: [],
      createdAt: Date.now()
    };

    setTimeout(() => {
        onSetupComplete(newProfile);
        setLoading(false);
    }, 500);
  };

  const handleJoinSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!familyIdToJoin) {
      setError('Inserisci il codice famiglia.');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Utente non autenticato");

      // 1. Verifica che la famiglia esista
      const profile = await getFamilyProfile(familyIdToJoin);
      if (!profile) {
        throw new Error("Nessuna famiglia trovata con questo codice.");
      }

      // 2. Unisciti
      await joinFamily(user.id, familyIdToJoin, user.user_metadata.full_name || 'Nuovo Membro', false);

      onSetupComplete(profile);
    } catch (err: any) {
      setError(err.message || "Errore durante l'adesione alla famiglia.");
    } finally {
      setLoading(false);
    }
  };

  if (isSupabaseAuth) {
    return (
        <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
          <div className="bg-white p-8 rounded-3xl shadow-xl max-w-md w-full border border-gray-100 text-center">
            <div className="bg-emerald-100 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4">
                <Sparkles className="w-8 h-8 text-emerald-600" />
            </div>
            <h2 className="text-2xl font-bold text-gray-800 mb-2">Benvenuto!</h2>
            <p className="text-gray-500 text-sm mb-6">Scegli come iniziare a gestire le tue spese.</p>

            <div className="flex p-1 bg-gray-100 rounded-xl mb-6">
                <button 
                    onClick={() => setMode('create')}
                    className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${mode === 'create' ? 'bg-white text-emerald-700 shadow-sm' : 'text-gray-500'}`}
                >
                    Crea Nuova
                </button>
                <button 
                    onClick={() => setMode('join')}
                    className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${mode === 'join' ? 'bg-white text-emerald-700 shadow-sm' : 'text-gray-500'}`}
                >
                    Unisciti
                </button>
            </div>

            {error && (
                <div className="bg-red-50 text-red-600 p-3 rounded-xl text-xs flex items-center gap-2 mb-4 animate-in shake">
                    <AlertCircle className="w-4 h-4 flex-shrink-0" />
                    {error}
                </div>
            )}

            {mode === 'create' ? (
                <form onSubmit={handleCreateSubmit} className="space-y-4">
                    <input
                        type="text"
                        value={familyName}
                        onChange={(e) => setFamilyName(e.target.value)}
                        placeholder="Es. Famiglia Rossi"
                        className="w-full rounded-xl border border-gray-300 p-3.5 focus:border-emerald-500 outline-none transition-all"
                        required
                    />
                    <button
                        type="submit"
                        disabled={loading}
                        className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-4 rounded-xl shadow-md flex items-center justify-center gap-2"
                    >
                        {loading ? <Loader2 className="animate-spin" /> : 'Crea Famiglia'}
                    </button>
                </form>
            ) : (
                <form onSubmit={handleJoinSubmit} className="space-y-4">
                    <input
                        type="text"
                        value={familyIdToJoin}
                        onChange={(e) => setFamilyIdToJoin(e.target.value)}
                        placeholder="Incolla il Codice Famiglia"
                        className="w-full rounded-xl border border-gray-300 p-3.5 focus:border-emerald-500 outline-none transition-all font-mono text-sm"
                        required
                    />
                    <button
                        type="submit"
                        disabled={loading}
                        className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 rounded-xl shadow-md flex items-center justify-center gap-2"
                    >
                        {loading ? <Loader2 className="animate-spin" /> : <><UserPlus className="w-5 h-5" /> Unisciti ora</>}
                    </button>
                </form>
            )}
          </div>
        </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
      <div className="bg-white p-8 rounded-3xl shadow-xl max-w-md w-full border border-gray-100 relative">
        <div className="text-center mb-8 mt-2 space-y-2">
          <div className="bg-gradient-to-tr from-emerald-400 to-teal-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto shadow-lg transform -rotate-3 mb-4">
                <Sparkles className="w-8 h-8 text-white" />
          </div>
          <h2 className="text-2xl font-bold text-gray-800">Spese Familiari AI</h2>
          <p className="text-gray-500 text-sm">Gestisci il bilancio di casa in modo intelligente.</p>
        </div>

        <div className="space-y-4">
            <button
                onClick={handleGoogleLogin}
                disabled={loading}
                className="w-full flex items-center justify-center gap-3 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 font-bold py-4 px-6 rounded-2xl transition-all shadow-sm disabled:opacity-70"
            >
                {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : (
                    <>
                        <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" alt="Google" className="w-5 h-5" />
                        Accedi con Google
                    </>
                )}
            </button>

            <div className="relative my-6">
                <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-gray-200"></div></div>
                <div className="relative flex justify-center text-xs uppercase"><span className="bg-white px-2 text-gray-400">Oppure</span></div>
            </div>

            <p className="text-center text-xs text-gray-400">
                L'accesso con Google permette di sincronizzare i dati su tutti i tuoi dispositivi in tempo reale.
            </p>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, RecurringExpense, Frequency, FamilyProfile, SyncData, ShoppingItem, OfferPreferences, Income, CategoryDefinition } from './types';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { StoreManager } from './components/StoreManager';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { ExpenseFilters, FilterState } from './components/ExpenseFilters';
import { ReceiptScanner } from './components/ReceiptScanner';
import { LoginScreen } from './components/LoginScreen';
import { DataSync } from './components/DataSync';
import { GoogleSheetSync } from './components/GoogleSheetSync';
import { ShoppingListManager } from './components/ShoppingListManager';
import { OffersFinder } from './components/OffersFinder';
import { IncomeManager } from './components/IncomeManager';
import { CategoryManager } from './components/CategoryManager';
import { FamilyManager } from './components/FamilyManager';
import { categorizeExpense, ReceiptData, findFlyerOffers } from './services/geminiService';
import { supabase } from './src/supabaseClient';
import * as SupabaseService from './services/supabaseService';
import { 
  WalletCards, 
  Download, 
  Share2, 
  LogOut, 
  Table, 
  Menu, 
  X,
  Home,
  History,
  ShoppingCart,
  Percent,
  Repeat,
  BarChart3,
  ChevronRight,
  Coins,
  Tag,
  Github,
  Cloud,
  User,
  Loader2,
  Users
} from 'lucide-react';

type View = 'dashboard' | 'history' | 'shopping' | 'offers' | 'recurring' | 'analytics' | 'budget' | 'categories' | 'profile';

function App() {
  // --- AUTH STATE ---
  const [session, setSession] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoadingAuth, setIsLoadingAuth] = useState(true);

  // App Data State
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);
  const [categories, setCategories] = useState<CategoryDefinition[]>(DEFAULT_CATEGORIES);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [shoppingList, setShoppingList] = useState<ShoppingItem[]>([]);

  // UI State
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [isLoadingData, setIsLoadingData] = useState(false);
  const [showSync, setShowSync] = useState(false);
  const [showGoogleSheet, setShowGoogleSheet] = useState(false);
  const [newOffersCount, setNewOffersCount] = useState(0);

  const [filters, setFilters] = useState<FilterState>({
    store: '', category: '', startDate: '', endDate: ''
  });

  const [offerPrefs, setOfferPrefs] = useState<OfferPreferences>(() => {
    const saved = localStorage.getItem('offerPrefs');
    return saved ? JSON.parse(saved) : { city: '', selectedStores: [], lastCheckDate: 0, hasEnabledNotifications: false };
  });

  // --- SUPABASE AUTH LISTENER ---
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) checkUserFamily(session.user.id);
      else setIsLoadingAuth(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) checkUserFamily(session.user.id);
      else {
        setIsAuthenticated(false);
        setFamilyProfile(null);
        setIsLoadingAuth(false);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const checkUserFamily = async (userId: string) => {
    setIsLoadingData(true);
    const membership = await SupabaseService.getFamilyForUser(userId);
    if (membership) {
      const profile = await SupabaseService.getFamilyProfile(membership.familyId);
      if (profile) {
        setFamilyProfile(profile);
        setIsAuthenticated(true);
      }
    }
    setIsLoadingAuth(false);
    setIsLoadingData(false);
  };

  // --- DATA LOADING EFFECT ---
  useEffect(() => {
    if (isAuthenticated && familyProfile?.id) {
      const loadAllData = async () => {
        setIsLoadingData(true);
        try {
          const [exp, inc, sto, cat, rec, shop] = await Promise.all([
            SupabaseService.fetchExpenses(familyProfile.id),
            SupabaseService.fetchIncomes(familyProfile.id),
            SupabaseService.fetchStores(familyProfile.id),
            SupabaseService.fetchCategories(familyProfile.id),
            SupabaseService.fetchRecurring(familyProfile.id),
            SupabaseService.fetchShoppingList(familyProfile.id)
          ]);
          setExpenses(exp);
          setIncomes(inc);
          if (sto.length > 0) setStores(sto);
          if (cat.length > 0) setCategories(cat);
          setRecurringExpenses(rec);
          setShoppingList(shop);
        } catch (e) { console.error(e); }
        setIsLoadingData(false);
      };
      loadAllData();
    }
  }, [isAuthenticated, familyProfile?.id]);

  // --- HANDLERS ---
  const handleSetupComplete = async (profile: FamilyProfile) => {
    if (!session?.user) return;

    // Verifica se la famiglia esiste già sul DB (caso "Join") o se va creata
    const existing = await SupabaseService.getFamilyProfile(profile.id);
    if (!existing) {
        await SupabaseService.createFamilyProfile(profile);
    }

    // Associa utente loggato
    await SupabaseService.joinFamily(session.user.id, profile.id, session.user.user_metadata.full_name || 'Membro', !existing);

    setFamilyProfile(profile);
    setIsAuthenticated(true);
  };

  const handleLogout = async () => {
    await SupabaseService.signOut();
    setIsAuthenticated(false);
    setFamilyProfile(null);
    setExpenses([]);
    setIncomes([]);
    setIsMenuOpen(false);
  };

  const handleAddExpense = async (product: string, quantity: number, unitPrice: number, total: number, store: string) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    const category = await categorizeExpense(product, store);
    const newExpense: Expense = { id: crypto.randomUUID(), product, quantity, unitPrice, total, store, date: new Date().toISOString(), category, memberId: session?.user?.id };
    setExpenses(prev => [newExpense, ...prev]);
    setIsAIProcessing(false);
    await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
  };

  const handleUpdateExpense = async (updated: Expense) => {
    if (!familyProfile) return;
    setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e));
    await SupabaseService.updateExpenseInSupabase(familyProfile.id, updated);
  };

  const handleDeleteExpense = async (id: string) => {
    if (confirm('Sei sicuro di voler eliminare questa spesa?')) {
      setExpenses(prev => prev.filter(e => e.id !== id));
      await SupabaseService.deleteExpenseFromSupabase(id);
    }
  };

  const handleAddIncome = async (source: string, amount: number, date: string) => {
    if (!familyProfile) return;
    const newIncome: Income = { id: crypto.randomUUID(), source, amount, date };
    setIncomes(prev => [newIncome, ...prev]);
    await SupabaseService.addIncomeToSupabase(familyProfile.id, newIncome);
  };

  const handleDeleteIncome = async (id: string) => {
    setIncomes(prev => prev.filter(i => i.id !== id));
    await SupabaseService.deleteIncomeFromSupabase(id);
  };

  const handleAddStore = async (name: string) => {
    if (!familyProfile) return;
    if (!stores.find(s => s.name.toLowerCase() === name.toLowerCase())) {
        const newStore = { id: crypto.randomUUID(), name };
        setStores(prev => [...prev, newStore]);
        await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
    }
  };

  const handleCategoriesUpdate = (newCats: CategoryDefinition[]) => {
    if (!familyProfile) return;
    setCategories(newCats);
    SupabaseService.syncCategoriesToSupabase(familyProfile.id, newCats);
  };

  // --- MEMOS & FILTERS ---
  const filteredExpenses = useMemo(() => {
    return expenses.filter(expense => {
      const matchStore = filters.store ? expense.store === filters.store : true;
      const matchCategory = filters.category ? expense.category === filters.category : true;
      const matchStartDate = filters.startDate ? new Date(expense.date) >= new Date(filters.startDate) : true;
      const matchEndDate = filters.endDate ? new Date(expense.date) <= new Date(filters.endDate + 'T23:59:59') : true;
      return matchStore && matchCategory && matchStartDate && matchEndDate;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [expenses, filters]);

  const MenuButton = ({ view, icon, label, badge }: { view: View, icon: any, label: string, badge?: number }) => (
    <button onClick={() => { setCurrentView(view); setIsMenuOpen(false); }} className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl transition-colors ${currentView === view ? 'bg-emerald-100 text-emerald-800 font-bold' : 'text-gray-700 hover:bg-gray-100'}`}>
      {React.cloneElement(icon, { className: 'w-6 h-6' })}
      <span className="text-lg">{label}</span>
      {badge ? <span className="ml-auto bg-red-500 text-white text-xs font-bold px-2 py-0.5 rounded-full">{badge}</span> : null}
      {currentView === view && <ChevronRight className="w-5 h-5 ml-auto text-emerald-600" />}
    </button>
  );

  if (isLoadingAuth) return <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50"><Loader2 className="w-10 h-10 text-emerald-600 animate-spin" /><p className="mt-4 text-gray-500 font-medium">Caricamento sessione...</p></div>;
  if (!session) return <LoginScreen existingProfile={null} onLogin={() => {}} onSetupComplete={handleSetupComplete} onResetProfile={() => {}} />;
  if (!isAuthenticated) return <LoginScreen existingProfile={null} onLogin={() => {}} onSetupComplete={handleSetupComplete} onResetProfile={() => {}} isSupabaseAuth={true} />;

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans pb-24 safe-area-top">
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30">
        <div className="max-w-5xl mx-auto px-4 h-18 flex items-center justify-between py-3">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMenuOpen(true)} className="p-3 -ml-2 text-gray-700 hover:bg-gray-100 rounded-xl relative">
                <Menu className="w-7 h-7" />
                {newOffersCount > 0 && <span className="absolute top-2 right-2 w-3 h-3 bg-red-500 rounded-full border-2 border-white"></span>}
             </button>
             <div className="flex items-center gap-3" onClick={() => setCurrentView('dashboard')}>
                <div className="bg-emerald-100 p-2 rounded-xl"><WalletCards className="w-6 h-6 text-emerald-600" /></div>
                <h1 className="font-bold text-lg text-gray-800 truncate">Spese {familyProfile?.familyName}</h1>
             </div>
          </div>
          <div className="flex items-center gap-2">
             <button onClick={() => setCurrentView('profile')} className="bg-gray-100 p-1.5 rounded-full hover:bg-emerald-50 transition-colors" title="Il mio profilo">
                {session.user.user_metadata.avatar_url ? (
                    <img src={session.user.user_metadata.avatar_url} className="w-8 h-8 rounded-full" alt="User" />
                ) : <User className="w-5 h-5 text-gray-500 m-1" />}
             </button>
          </div>
        </div>
      </header>

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex">
           <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsMenuOpen(false)}></div>
           <div className="relative w-[85%] max-w-xs bg-white h-full shadow-2xl flex flex-col animate-in slide-in-from-left duration-200">
              <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                 <div>
                     <h2 className="font-bold text-xl text-gray-800">Menù</h2>
                     <span className="text-xs text-emerald-600 font-medium flex items-center gap-1 mt-1"><Cloud className="w-3 h-3" /> Cloud Sync Attivo</span>
                 </div>
                 <button onClick={() => setIsMenuOpen(false)} className="p-3 hover:bg-gray-200 rounded-full"><X className="w-6 h-6 text-gray-500" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-2">
                 <MenuButton view="dashboard" icon={<Home />} label="Home & Scansione" />
                 <MenuButton view="budget" icon={<Coins />} label="Bilancio & Guadagni" />
                 <MenuButton view="shopping" icon={<ShoppingCart />} label="Lista Spesa" />
                 <MenuButton view="history" icon={<History />} label="Storico Transazioni" />
                 <MenuButton view="analytics" icon={<BarChart3 />} label="Analisi & Grafici" />
                 <div className="my-2 border-t border-gray-100"></div>
                 <MenuButton view="profile" icon={<Users />} label="Profilo Famiglia" />
                 <MenuButton view="categories" icon={<Tag />} label="Gestisci Categorie" />
                 <div className="my-2 border-t border-gray-100"></div>
                 <button onClick={handleLogout} className="w-full flex items-center gap-4 px-5 py-4 rounded-xl text-red-600 hover:bg-red-50 mt-4 font-bold">
                    <LogOut className="w-6 h-6" />
                    <span className="text-lg">Esci / Logout</span>
                 </button>
              </div>
           </div>
        </div>
      )}

      <main className="max-w-2xl mx-auto px-4 py-6">
        {isLoadingData ? (
          <div className="flex flex-col items-center justify-center py-20">
            <Loader2 className="w-12 h-12 text-emerald-500 animate-spin mb-4" />
            <p className="text-gray-500 font-medium">Sincronizzazione Cloud...</p>
          </div>
        ) : (
          <>
            {currentView === 'dashboard' && (
                <div className="space-y-6 animate-in fade-in">
                    <ReceiptScanner onScanComplete={() => {}} />
                    <ExpenseForm stores={stores} members={[]} existingProducts={[]} productHistory={{}} onAddExpense={handleAddExpense} isAnalyzing={isAIProcessing} />
                    <StoreManager onAddStore={handleAddStore} />
                </div>
            )}
            {currentView === 'history' && <ExpenseList expenses={filteredExpenses} stores={stores} members={[]} onDelete={handleDeleteExpense} onEdit={handleUpdateExpense} categories={categories} />}
            {currentView === 'budget' && <IncomeManager incomes={incomes} expenses={expenses} onAddIncome={handleAddIncome} onDeleteIncome={handleDeleteIncome} />}
            {currentView === 'categories' && <CategoryManager categories={categories} onUpdateCategories={handleCategoriesUpdate} />}
            {currentView === 'profile' && familyProfile && <FamilyManager familyProfile={familyProfile} />}
          </>
        )}
      </main>
    </div>
  );
}

export default App;

import React, { ErrorInfo, ReactNode, Component } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';
import './index.css';

interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

// Simple Error Boundary to catch crashes
// Fix: Added explicit property declarations for state and props as the compiler was failing to resolve them from the base class.
class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  // Added explicit props declaration to resolve property access errors in the render method.
  public props: ErrorBoundaryProps;
  public state: ErrorBoundaryState = { hasError: false, error: null };

  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.props = props;
    this.state = { hasError: false, error: null };
  }

  public static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: '20px', fontFamily: 'sans-serif', color: '#333', textAlign: 'center', marginTop: '50px' }}>
          <h1 style={{color: '#ef4444'}}>Si è verificato un errore imprevisto.</h1>
          <p>L'applicazione non è riuscita a caricarsi.</p>
          <pre style={{ background: '#f3f4f6', padding: '10px', borderRadius: '8px', overflowX: 'auto', textAlign: 'left', maxWidth: '600px', margin: '20px auto' }}>
            {this.state.error?.toString()}
          </pre>
          <button 
            onClick={() => window.location.reload()} 
            style={{ padding: '10px 20px', background: '#10b981', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontSize: '16px' }}
          >
            Ricarica Pagina
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

const rootElement = document.getElementById('root');

if (rootElement) {
  const root = createRoot(rootElement);
  root.render(
    (
      <React.StrictMode>
        <ErrorBoundary>
          <App />
        </ErrorBoundary>
      </React.StrictMode>
    )
  );
} else {
  console.error("Impossibile trovare l'elemento root");
}

import { GoogleGenAI } from "@google/genai";
import { Expense, FlyerOffer } from "../types";

// --- CLIENT INITIALIZATION ---
// Initialize the Gemini client using the environment variable directly as per coding guidelines.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// --- UTILS ---
const cleanJsonString = (str: string) => {
  return str.replace(/```json\n?|```/g, '').trim();
};

// --- CATEGORIZATION ---
export const categorizeExpense = async (product: string, store: string): Promise<string> => {
  try {
    // Categorization is a basic text task.
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Categorize the product "${product}" bought at "${store}" into exactly one of these categories: Alimentari, Trasporti, Casa, Salute, Svago, Abbigliamento, Utenze, Altro. Return ONLY the category name.`,
    });
    return response.text?.trim() || "Generale";
  } catch (error) {
    console.error("AI Categorization failed:", error);
    return "Generale";
  }
};

// --- SPENDING ANALYSIS ---
export const getSpendingAnalysis = async (expenses: Expense[]): Promise<string> => {
  if (expenses.length === 0) return "Nessuna spesa da analizzare.";

  // Simplify data for token limit
  const summary = expenses.map(e => `${e.date.split('T')[0]}: ${e.product} (€${e.total})`).join('\n');

  try {
    // Spending analysis involves reasoning, so we use gemini-3-pro-preview.
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Analizza queste spese familiari recenti e fornisci 3 consigli brevi e pratici in italiano per risparmiare. Sii diretto e amichevole.\n\n${summary}`,
    });
    return response.text || "Analisi non disponibile al momento.";
  } catch (error) {
    console.error("AI Analysis failed:", error);
    return "Impossibile generare l'analisi al momento.";
  }
};

// --- OFFERS FINDER (Simple Link Generation) ---
export const findFlyerOffers = async (city: string, stores: string[]): Promise<FlyerOffer[]> => {
    // Generate static Google Search links for flyers
    // This avoids API permission issues and is always reliable
    const offers: FlyerOffer[] = stores.map(store => ({
        storeName: store,
        flyerLink: `https://www.google.com/search?q=volantino+${encodeURIComponent(store)}+${encodeURIComponent(city)}+attuale`,
        validUntil: 'Vedi volantino',
        topOffers: [] // No extraction without advanced API
    }));

    // Simulate async delay
    return new Promise(resolve => setTimeout(() => resolve(offers), 500));
};

// --- RECEIPT SCANNING ---
export interface ReceiptItem {
  product: string;
  quantity: number;
  unitPrice: number;
  total: number;
  category: string;
}

export interface ReceiptData {
  store: string;
  date: string;
  items: ReceiptItem[];
}

export interface ReceiptScanResult {
  success: boolean;
  data?: ReceiptData;
  error?: string;
}

export const parseReceiptImage = async (base64Image: string, mimeType: string = 'image/jpeg'): Promise<ReceiptScanResult> => {
  try {
    // Receipt parsing from image is a complex multimodal task, so we use gemini-3-pro-preview.
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image
            }
          },
          {
            text: `Analyze this receipt image. Extract the store name, date, and list of items purchased.
            For each item extract: product name, quantity (default to 1 if missing), unit price, and total price.
            Also assign a category to each item (Alimentari, Casa, etc.).

            Return the result in this JSON format:
            {
              "store": "Store Name",
              "date": "YYYY-MM-DD",
              "items": [
                { "product": "Item Name", "quantity": 1, "unitPrice": 10.00, "total": 10.00, "category": "Category" }
              ]
            }
            Return ONLY raw JSON, no markdown blocks.`
          }
        ]
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty response from AI");

    const cleanJson = cleanJsonString(text);
    const data: ReceiptData = JSON.parse(cleanJson);

    // Basic Validation
    if (!data.items || !Array.isArray(data.items)) {
       throw new Error("Invalid JSON structure received");
    }

    return { success: true, data };

  } catch (error) {
    console.error("Receipt parsing error:", error);
    return { 
      success: false, 
      error: "Non sono riuscito a leggere lo scontrino. Assicurati che la foto sia ben illuminata e a fuoco, oppure inserisci i dati manualmente." 
    };
  }
};

import React, { useState } from 'react';
import { FamilyProfile } from '../types';
import { Sparkles, Loader2, AlertCircle, UserPlus } from 'lucide-react';
import { signInWithGoogle, joinFamily, getFamilyProfile } from '../services/supabaseService';
