L'errore **42P01** ("la relazione family_members non esiste") accade perché lo script precedente tentava di creare le regole di sicurezza (Policy) *prima* di aver effettivamente creato le tabelle. In PostgreSQL, l'ordine dei comandi è fondamentale.

Ecco la soluzione definitiva. Segui questi passaggi:

### 1. Azione su Supabase (SQL Editor)
Vai su Supabase -> SQL Editor -> New Query. **Copia e incolla tutto questo blocco in un colpo solo.** Questo script crea prima le tabelle, poi abilita la sicurezza e infine crea le regole di accesso.

```sql
-- 1. CREAZIONE TABELLE (BASE)
CREATE TABLE IF NOT EXISTS families (
  id UUID PRIMARY KEY,
  family_name TEXT NOT NULL,
  members JSONB,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS family_members (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  family_id UUID REFERENCES families(id) ON DELETE CASCADE,
  user_id UUID NOT NULL,
  name TEXT NOT NULL,
  is_admin BOOLEAN DEFAULT FALSE,
  UNIQUE(user_id)
);

-- 2. TABELLE DATI
CREATE TABLE IF NOT EXISTS expenses (
  id UUID PRIMARY KEY,
  family_id UUID REFERENCES families(id) ON DELETE CASCADE,
  product TEXT NOT NULL,
  quantity DECIMAL,
  unit_price DECIMAL,
  total DECIMAL NOT NULL,
  store TEXT,
  category TEXT,
  date TIMESTAMP WITH TIME ZONE,
  member_id UUID
);

CREATE TABLE IF NOT EXISTS incomes (
  id UUID PRIMARY KEY,
  family_id UUID REFERENCES families(id) ON DELETE CASCADE,
  source TEXT,
  amount DECIMAL,
  date TIMESTAMP WITH TIME ZONE
);

CREATE TABLE IF NOT EXISTS stores (
  id UUID PRIMARY KEY,
  family_id UUID REFERENCES families(id) ON DELETE CASCADE,
  name TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS categories (
  id UUID PRIMARY KEY,
  family_id UUID REFERENCES families(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  icon TEXT,
  color TEXT
);

CREATE TABLE IF NOT EXISTS recurring_expenses (
  id UUID PRIMARY KEY,
  family_id UUID REFERENCES families(id) ON DELETE CASCADE,
  product TEXT NOT NULL,
  amount DECIMAL,
  store TEXT,
  frequency TEXT,
  next_due_date TIMESTAMP WITH TIME ZONE,
  reminder_days INTEGER DEFAULT 0
);

CREATE TABLE IF NOT EXISTS shopping_list (
  id UUID PRIMARY KEY,
  family_id UUID REFERENCES families(id) ON DELETE CASCADE,
  product TEXT NOT NULL,
  store TEXT,
  completed BOOLEAN DEFAULT FALSE
);

-- 3. ABILITA ROW LEVEL SECURITY (RLS)
ALTER TABLE families ENABLE ROW LEVEL SECURITY;
ALTER TABLE family_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE expenses ENABLE ROW LEVEL SECURITY;
ALTER TABLE incomes ENABLE ROW LEVEL SECURITY;
ALTER TABLE stores ENABLE ROW LEVEL SECURITY;
ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE recurring_expenses ENABLE ROW LEVEL SECURITY;
ALTER TABLE shopping_list ENABLE ROW LEVEL SECURITY;

-- 4. CREAZIONE DELLE POLICY (REGOLE DI ACCESSO)

-- Policy per i membri: Posso vedere la mia appartenenza
CREATE POLICY "Manage own membership" ON family_members FOR ALL USING (auth.uid() = user_id);

-- Policy per i membri: Posso vedere gli altri membri della mia famiglia
CREATE POLICY "View family members" ON family_members FOR SELECT USING (
  family_id IN (SELECT f.family_id FROM family_members f WHERE f.user_id = auth.uid())
);

-- Policy per la famiglia: Accesso se ne faccio parte
CREATE POLICY "Family access" ON families FOR ALL USING (
  id IN (SELECT f.family_id FROM family_members f WHERE f.user_id = auth.uid())
);

-- Policy per tabelle dati: Accesso limitato ai membri della famiglia corretta
CREATE POLICY "Expenses security" ON expenses FOR ALL USING (family_id IN (SELECT f.family_id FROM family_members f WHERE f.user_id = auth.uid()));
CREATE POLICY "Incomes security" ON incomes FOR ALL USING (family_id IN (SELECT f.family_id FROM family_members f WHERE f.user_id = auth.uid()));
CREATE POLICY "Stores security" ON stores FOR ALL USING (family_id IN (SELECT f.family_id FROM family_members f WHERE f.user_id = auth.uid()));
CREATE POLICY "Categories security" ON categories FOR ALL USING (family_id IN (SELECT f.family_id FROM family_members f WHERE f.user_id = auth.uid()));
CREATE POLICY "Recurring security" ON recurring_expenses FOR ALL USING (family_id IN (SELECT f.family_id FROM family_members f WHERE f.user_id = auth.uid()));
CREATE POLICY "Shopping security" ON shopping_list FOR ALL USING (family_id IN (SELECT f.family_id FROM family_members f WHERE f.user_id = auth.uid()));

-- Permesso speciale per creare una famiglia iniziale
CREATE POLICY "Allow family creation" ON families FOR INSERT WITH CHECK (auth.role() = 'authenticated');
```

### 2. Aggiornamento dell'Applicazione
Rimuoviamo definitivamente il blocco problematico dal file `index.html` e puliamo `App.tsx` per gestire meglio l'inizializzazione.

