            SupabaseService.fetchCategories(familyProfile.id)
          ]);
          setExpenses(exp || []);
          setIncomes(inc || []);
          if (sto && sto.length > 0) setStores(sto);
          if (cat && cat.length > 0) setCategories(cat);
        } catch (e) { 
          console.error("Errore caricamento dati:", e);
        } finally {
          setIsLoadingData(false);
        }
      };
      loadAllData();
    }
  }, [isAuthenticated, familyProfile?.id]);

  const handleSetupComplete = async (profile: FamilyProfile) => {
    if (!session?.user) return;
    try {
      setIsLoadingData(true);
      setError(null);
      const existing = await SupabaseService.getFamilyProfile(profile.id);
      if (!existing) await SupabaseService.createFamilyProfile(profile);
      await SupabaseService.joinFamily(session.user.id, profile.id, session.user.user_metadata.full_name || 'Membro', !existing);
      setFamilyProfile(profile);
      setIsAuthenticated(true);
    } catch (e: any) {
      console.error("Errore setup famiglia:", e);
      alert("Errore: Assicurati di aver incollato lo script SQL su Supabase.");
    } finally {
      setIsLoadingData(false);
    }
  };

  const handleLogout = async () => {
    await SupabaseService.signOut();
    setIsAuthenticated(false);
    setFamilyProfile(null);
    setExpenses([]);
    setIncomes([]);
    setIsMenuOpen(false);
    setError(null);
  };

  const handleAddExpense = async (product: string, quantity: number, unitPrice: number, total: number, store: string) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const category = await categorizeExpense(product, store);
      const newExpense: Expense = { 
        id: crypto.randomUUID(), 
        product, 
        quantity, 
        unitPrice, 
        total, 
        store, 
        date: new Date().toISOString(), 
        category, 
        memberId: session?.user?.id 
      };
      setExpenses(prev => [newExpense, ...prev]);
      await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
    } catch (e) {
      console.error("Errore salvataggio spesa:", e);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleAddIncome = async (source: string, amount: number, date: string) => {
    if (!familyProfile) return;
    try {
      const newIncome: Income = { id: crypto.randomUUID(), source, amount, date };
      setIncomes(prev => [newIncome, ...prev]);
      await SupabaseService.addIncomeToSupabase(familyProfile.id, newIncome);
    } catch (e) {
      console.error("Errore salvataggio entrata:", e);
    }
  };

  const MenuButton = ({ view, icon, label }: { view: View, icon: any, label: string }) => (
    <button 
      onClick={() => { setCurrentView(view); setIsMenuOpen(false); }} 
      className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl transition-colors ${currentView === view ? 'bg-emerald-100 text-emerald-800 font-bold' : 'text-gray-700 hover:bg-gray-100'}`}
    >
      {React.cloneElement(icon, { className: 'w-6 h-6' })}
      <span className="text-lg">{label}</span>
      {currentView === view && <ChevronRight className="w-5 h-5 ml-auto text-emerald-600" />}
    </button>
  );

  if (isLoadingAuth) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50">
        <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
        <p className="mt-4 text-gray-500 font-medium text-sm">Verifica sicurezza...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 p-6">
        <div className="bg-white p-8 rounded-3xl shadow-xl max-w-md w-full border border-red-100 text-center">
          <div className="bg-amber-100 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4">
            <Database className="w-8 h-8 text-amber-600" />
          </div>
          <h2 className="text-xl font-bold text-gray-800 mb-2">Azione Richiesta</h2>
          <p className="text-gray-600 text-sm mb-6 leading-relaxed">{error}</p>
          <div className="space-y-3">
            <button onClick={() => window.location.reload()} className="w-full bg-emerald-600 text-white font-bold py-3 rounded-xl shadow-md transition-transform active:scale-95">
              Ricarica App
            </button>
            <button onClick={handleLogout} className="w-full bg-gray-100 text-gray-700 font-bold py-3 rounded-xl transition-transform active:scale-95">
              Vai al Login
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (!session) return <LoginScreen onSetupComplete={handleSetupComplete} />;

  if (!isAuthenticated && !isLoadingData) {
    return <LoginScreen onSetupComplete={handleSetupComplete} isSupabaseAuth={true} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans pb-24 safe-area-top">
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMenuOpen(true)} className="p-2 -ml-2 text-gray-700 hover:bg-gray-100 rounded-xl">
                <Menu className="w-6 h-6" />
             </button>
             <div className="flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('dashboard')}>
                <WalletCards className="w-6 h-6 text-emerald-600" />
                <h1 className="font-bold text-base text-gray-800 truncate max-w-[150px]">
                  {familyProfile?.familyName || 'Spese Famiglia'}
                </h1>
             </div>
          </div>
          <button onClick={() => setCurrentView('profile')} className="bg-gray-100 p-1 rounded-full border border-gray-200">
             {session?.user?.user_metadata?.avatar_url ? (
               <img src={session.user.user_metadata.avatar_url} className="w-7 h-7 rounded-full" alt="User" />
             ) : (
               <User className="w-4 h-4 text-gray-500 m-1" />
             )}
          </button>
        </div>
      </header>

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex">
           <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsMenuOpen(false)}></div>
           <div className="relative w-[85%] max-w-xs bg-white h-full shadow-2xl flex flex-col animate-in slide-in-from-left duration-200">
              <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                 <div>
                   <h2 className="font-bold text-xl text-gray-800">Menù</h2>
                   <span className="text-xs text-emerald-600 font-medium flex items-center gap-1 mt-1"><Cloud className="w-3 h-3" /> Protezione RLS Attiva</span>
                 </div>
                 <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-gray-200 rounded-full"><X className="w-6 h-6 text-gray-500" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-1">
                 <MenuButton view="dashboard" icon={<Home />} label="Home & Aggiungi" />
                 <MenuButton view="budget" icon={<Coins />} label="Bilancio & Guadagni" />
                 <MenuButton view="history" icon={<History />} label="Storico Transazioni" />
                 <div className="my-2 border-t border-gray-100"></div>
                 <MenuButton view="profile" icon={<Users />} label="Profilo Famiglia" />
                 <MenuButton view="categories" icon={<Tag />} label="Gestisci Categorie" />
                 <button onClick={handleLogout} className="w-full flex items-center gap-4 px-5 py-4 rounded-xl text-red-600 hover:bg-red-50 mt-4 font-bold transition-colors">
                   <LogOut className="w-6 h-6" /> Esci dall'App
                 </button>
              </div>
           </div>
        </div>
      )}

      <main className="max-w-2xl mx-auto px-4 py-6">
        {isLoadingData ? (
          <div className="flex flex-col items-center justify-center py-20">
            <Loader2 className="w-12 h-12 text-emerald-500 animate-spin mb-4" />
            <p className="text-gray-500 font-medium">Sincronizzazione Cloud...</p>
          </div>
        ) : (
          <div className="animate-in fade-in duration-300">
            {currentView === 'dashboard' && (
                <div className="space-y-6">
                    <ExpenseForm 
                      stores={stores} 
                      members={[]} 
                      existingProducts={[]} 
                      productHistory={{}} 
                      onAddExpense={handleAddExpense} 
                      isAnalyzing={isAIProcessing} 
                    />
                    <StoreManager onAddStore={(name) => SupabaseService.addStoreToSupabase(familyProfile!.id, {id: crypto.randomUUID(), name}).then(() => setStores(prev => [...prev, {id: crypto.randomUUID(), name}]))} />
                </div>
            )}
            {currentView === 'history' && (
              <ExpenseList 
                expenses={expenses} 
                stores={stores} 
                categories={categories} 
                onDelete={(id) => SupabaseService.deleteExpenseFromSupabase(id).then(() => setExpenses(prev => prev.filter(e => e.id !== id)))} 
                onEdit={(updated) => {
                  setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e));
                  // Nota: In un'app reale dovresti aggiornare anche Supabase qui
                }} 
              />
            )}
            {currentView === 'budget' && (
              <IncomeManager 
                incomes={incomes} 
                expenses={expenses} 
                onAddIncome={handleAddIncome} 
                onDeleteIncome={(id) => SupabaseService.deleteIncomeFromSupabase(id).then(() => setIncomes(prev => prev.filter(i => i.id !== id)))} 
              />
            )}
            {currentView === 'categories' && (
              <CategoryManager 
                categories={categories} 
                onUpdateCategories={(cats) => {setCategories(cats); SupabaseService.syncCategoriesToSupabase(familyProfile!.id, cats);}} 
              />
            )}
            {currentView === 'profile' && familyProfile && (
              <FamilyManager familyProfile={familyProfile} />
            )}
          </div>
        )}
      </main>
    </div>
  );
}

export default App;

import { supabase } from '../src/supabaseClient';
import { Expense, Income, Store, RecurringExpense, ShoppingItem, FamilyProfile, CategoryDefinition, Member } from '../types';

// --- AUTH ---
export const signInWithGoogle = async () => {
  let redirectUrl = window.location.origin;
  if (redirectUrl.endsWith('/')) {
    redirectUrl = redirectUrl.slice(0, -1);
  }

  const { error } = await supabase.auth.signInWithOAuth({
    provider: 'google',
    options: {
      redirectTo: redirectUrl,
    },
  });

  if (error) throw error;
};

export const signUpWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signUp({ email, password });
};

export const signInWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signInWithPassword({ email, password });
};

export const signOut = async () => {
  await supabase.auth.signOut();
};

export const getCurrentUser = async () => {
  const { data: { user } } = await supabase.auth.getUser();
  return user;
};

// --- FAMILY & MEMBERSHIP ---
export const getFamilyForUser = async (userId: string): Promise<{ familyId: string, isAdmin: boolean } | null> => {
  const { data, error } = await supabase
    .from('family_members')
    .select('family_id, is_admin')
    .eq('user_id', userId)
    .maybeSingle();

  if (error || !data) return null;
  return { familyId: data.family_id, isAdmin: data.is_admin };
};

export const fetchFamilyMembers = async (familyId: string): Promise<Member[]> => {
  const { data, error } = await supabase
    .from('family_members')
    .select('user_id, name, is_admin')
    .eq('family_id', familyId);

  if (error) return [];
  return data.map(m => ({
    id: m.user_id,
    name: m.name,
    color: 'bg-emerald-100 text-emerald-600',
    isAdmin: m.is_admin,
    userId: m.user_id
  }));
};

export const joinFamily = async (userId: string, familyId: string, name: string, isAdmin: boolean = false) => {
  const { error } = await supabase
    .from('family_members')
    .upsert({
      family_id: familyId,
      user_id: userId,
      name: name,
      is_admin: isAdmin
    });
  if (error) throw error;
};

export const getFamilyProfile = async (familyId: string): Promise<FamilyProfile | null> => {
  const { data, error } = await supabase
    .from('families')
    .select('*')
    .eq('id', familyId)
    .single();

  if (error) return null;

  return {
    id: data.id,
    familyName: data.family_name,
    members: data.members || [], 
    createdAt: new Date(data.created_at).getTime()
  };
};

export const createFamilyProfile = async (profile: FamilyProfile): Promise<void> => {
  const { error } = await supabase
    .from('families')
    .upsert({
      id: profile.id,
      family_name: profile.familyName,
      members: profile.members
    });
  if (error) console.error('Error creating family:', error);
};

// --- EXPENSES ---
export const fetchExpenses = async (familyId: string): Promise<Expense[]> => {
  const { data, error } = await supabase
    .from('expenses')
    .select('*')
    .eq('family_id', familyId)
    .order('date', { ascending: false });

  if (error) return [];
  return data.map((e: any) => ({
    id: e.id,
    product: e.product,
    quantity: Number(e.quantity),
    unitPrice: Number(e.unit_price),
    total: Number(e.total),
    store: e.store,
    date: e.date,
    category: e.category,
    memberId: e.member_id
  }));
};

export const addExpenseToSupabase = async (familyId: string, expense: Expense): Promise<void> => {
  const { error } = await supabase
    .from('expenses')
    .insert({
      id: expense.id,
      family_id: familyId,
      product: expense.product,
      quantity: expense.quantity,
      unit_price: expense.unitPrice,
      total: expense.total,
      store: expense.store,
      date: expense.date,
      category: expense.category,
      member_id: expense.memberId
    });
  if (error) throw error;
};

export const deleteExpenseFromSupabase = async (id: string): Promise<void> => {
  await supabase.from('expenses').delete().eq('id', id);
};

export const fetchIncomes = async (familyId: string): Promise<Income[]> => {
  const { data, error } = await supabase.from('incomes').select('*').eq('family_id', familyId).order('date', { ascending: false });
  if (error) return [];
  return data.map((i: any) => ({ id: i.id, source: i.source, amount: Number(i.amount), date: i.date }));
};

export const addIncomeToSupabase = async (familyId: string, income: Income): Promise<void> => {
  await supabase.from('incomes').insert({ id: income.id, family_id: familyId, source: income.source, amount: income.amount, date: income.date });
};

export const deleteIncomeFromSupabase = async (id: string): Promise<void> => {
  await supabase.from('incomes').delete().eq('id', id);
};

export const fetchStores = async (familyId: string): Promise<Store[]> => {
  const { data, error } = await supabase.from('stores').select('*').eq('family_id', familyId);
  return (data || []).map((s: any) => ({ id: s.id, name: s.name }));
};

export const addStoreToSupabase = async (familyId: string, store: Store): Promise<void> => {
  await supabase.from('stores').insert({ id: store.id, family_id: familyId, name: store.name });
};

export const fetchCategories = async (familyId: string): Promise<CategoryDefinition[]> => {
  const { data, error } = await supabase.from('categories').select('*').eq('family_id', familyId);
  return (data || []).map((c: any) => ({ id: c.id, name: c.name, icon: c.icon, color: c.color }));
};

export const syncCategoriesToSupabase = async (familyId: string, categories: CategoryDefinition[]): Promise<void> => {
    const rows = categories.map(c => ({ id: c.id, family_id: familyId, name: c.name, icon: c.icon, color: c.color }));
    await supabase.from('categories').upsert(rows);
};

export const fetchRecurring = async (familyId: string): Promise<RecurringExpense[]> => {
  const { data, error } = await supabase.from('recurring_expenses').select('*').eq('family_id', familyId);
  return (data || []).map((r: any) => ({ id: r.id, product: r.product, amount: Number(r.amount), store: r.store, frequency: r.frequency, nextDueDate: r.next_due_date, reminder_days: r.reminder_days }));
};

export const addRecurringToSupabase = async (familyId: string, item: RecurringExpense): Promise<void> => {
  await supabase.from('recurring_expenses').insert({ id: item.id, family_id: familyId, product: item.product, amount: item.amount, store: item.store, frequency: item.frequency, next_due_date: item.nextDueDate, reminder_days: item.reminderDays });
};

export const deleteRecurringFromSupabase = async (id: string): Promise<void> => {
  await supabase.from('recurring_expenses').delete().eq('id', id);
};

export const fetchShoppingList = async (familyId: string): Promise<ShoppingItem[]> => {
  const { data, error } = await supabase.from('shopping_list').select('*').eq('family_id', familyId);
  return (data || []).map((s: any) => ({ id: s.id, product: s.product, store: s.store, completed: s.completed }));
};

export const addShoppingItemToSupabase = async (familyId: string, item: ShoppingItem): Promise<void> => {
  await supabase.from('shopping_list').insert({ id: item.id, family_id: familyId, product: item.product, store: item.store, completed: item.completed });
};

export const updateShoppingItemInSupabase = async (item: ShoppingItem): Promise<void> => {
  await supabase.from('shopping_list').update({ completed: item.completed }).eq('id', item.id);
};

export const deleteShoppingItemFromSupabase = async (id: string): Promise<void> => {
  await supabase.from('shopping_list').delete().eq('id', id);
};

import React, { useState } from 'react';
import { FamilyProfile } from '../types';
import { Sparkles, Loader2, Mail, Lock, LogIn, UserPlus, AlertCircle, CheckCircle2 } from 'lucide-react';
import { signInWithGoogle, signInWithEmail, signUpWithEmail } from '../services/supabaseService';
import { supabase } from '../src/supabaseClient';

interface LoginScreenProps {
  onSetupComplete: (profile: FamilyProfile) => void;
  isSupabaseAuth?: boolean;
}

export const LoginScreen: React.FC<LoginScreenProps> = ({ onSetupComplete, isSupabaseAuth }) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [familyName, setFamilyName] = useState('');
  const [familyIdToJoin, setFamilyIdToJoin] = useState('');
  const [mode, setMode] = useState<'create' | 'join'>('create');
  const [authMode, setAuthMode] = useState<'google' | 'email'>('google');
  const [isRegistering, setIsRegistering] = useState(false);

  const handleEmailAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSuccess('');

    try {
      if (isRegistering) {
        const { data, error: signUpErr } = await signUpWithEmail(email, password);
        if (signUpErr) throw signUpErr;

        if (data.session) {
          // Se la conferma email è OFF su Supabase, abbiamo già la sessione
          setSuccess("Registrazione completata! Accesso in corso...");
        } else if (data.user) {
          // Se la conferma email è ON, l'utente deve controllare la posta
          setSuccess("Account creato! Controlla la tua email per confermare l'indirizzo.");
          // Opzionalmente torniamo alla modalità login dopo qualche secondo
          setTimeout(() => setIsRegistering(false), 3000);
        }
      } else {
        const { error: signInErr } = await signInWithEmail(email, password);
        if (signInErr) {
          if (signInErr.message.includes("Email not confirmed")) {
            throw new Error("L'email non è stata confermata. Controlla la tua posta o disabilita la conferma su Supabase.");
          }
          throw signInErr;
        }
      }
    } catch (err: any) {
      console.error("Auth Error:", err);
      setError(err.message || "Errore durante l'autenticazione. Verifica i dati inseriti.");
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLoading(true);
    setError('');
    try {
      await signInWithGoogle();
    } catch (err: any) {
      setError("Errore login Google. Verifica la configurazione.");
      setLoading(false);
    }
  };

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!familyName) return;
    setLoading(true);
    const newProfile: FamilyProfile = {
      id: crypto.randomUUID(),
      familyName,
      members: [],
      createdAt: Date.now()
    };
    onSetupComplete(newProfile);
    setLoading(false);
  };

  const handleJoinSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!familyIdToJoin) return;
    setLoading(true);
    setError('');
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Accedi prima per unirti a una famiglia.");

      const { data: profile, error: fetchErr } = await supabase
        .from('families')
        .select('*')
        .eq('id', familyIdToJoin.trim())
        .single();

      if (fetchErr || !profile) throw new Error("Codice famiglia non trovato.");

      onSetupComplete({
        id: profile.id,
        familyName: profile.family_name,
        members: profile.members || [],
        createdAt: new Date(profile.created_at).getTime()
      });
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  if (isSupabaseAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
        <div className="bg-white p-8 rounded-3xl shadow-xl max-w-md w-full border border-gray-100 animate-in fade-in zoom-in">
          <h2 className="text-2xl font-bold text-gray-800 mb-2 text-center">Configurazione Famiglia</h2>
          <p className="text-gray-500 text-sm text-center mb-6">Sei loggato correttamente! Ora crea un gruppo o unisciti a uno esistente.</p>
          <div className="flex p-1 bg-gray-100 rounded-xl mb-6">
            <button onClick={() => setMode('create')} className={`flex-1 py-2.5 text-sm font-bold rounded-lg transition-all ${mode === 'create' ? 'bg-white text-emerald-700 shadow-sm' : 'text-gray-500'}`}>Crea</button>
            <button onClick={() => setMode('join')} className={`flex-1 py-2.5 text-sm font-bold rounded-lg transition-all ${mode === 'join' ? 'bg-white text-emerald-700 shadow-sm' : 'text-gray-500'}`}>Unisciti</button>
          </div>
          {error && <div className="bg-red-50 text-red-600 p-4 rounded-xl text-xs mb-4 border border-red-100 flex items-center gap-2"><AlertCircle className="w-4 h-4" /> {error}</div>}
          {mode === 'create' ? (
            <form onSubmit={handleCreateSubmit} className="space-y-4">
              <input type="text" value={familyName} onChange={(e) => setFamilyName(e.target.value)} placeholder="Nome del gruppo (es. Famiglia Rossi)" className="w-full rounded-xl border border-gray-300 p-4 outline-none focus:border-emerald-500" required />
              <button type="submit" disabled={loading} className="w-full bg-emerald-600 text-white font-bold py-4 rounded-xl shadow-md transition-transform active:scale-95">{loading ? <Loader2 className="animate-spin w-5 h-5 mx-auto" /> : 'Inizia ora'}</button>
            </form>
          ) : (
            <form onSubmit={handleJoinSubmit} className="space-y-4">
              <input type="text" value={familyIdToJoin} onChange={(e) => setFamilyIdToJoin(e.target.value)} placeholder="Incolla il codice ID (es. UUID)" className="w-full rounded-xl border border-gray-300 p-4 outline-none focus:border-emerald-500 font-mono text-sm" required />
              <button type="submit" disabled={loading} className="w-full bg-blue-600 text-white font-bold py-4 rounded-xl shadow-md transition-transform active:scale-95">{loading ? <Loader2 className="animate-spin w-5 h-5 mx-auto" /> : 'Entra nel gruppo'}</button>
            </form>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
      <div className="bg-white p-10 rounded-3xl shadow-2xl max-w-md w-full border border-gray-100 text-center">
        <div className="bg-emerald-500 w-20 h-20 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-xl">
          <Sparkles className="w-10 h-10 text-white" />
        </div>
        <h2 className="text-3xl font-extrabold text-gray-900 mb-2">Spese Famiglia AI</h2>
        <p className="text-gray-500 mb-8">Tieni traccia del bilancio in tempo reale.</p>

        {authMode === 'google' ? (
          <div className="space-y-4">
            <button onClick={handleGoogleLogin} disabled={loading} className="w-full flex items-center justify-center gap-4 bg-white border-2 border-gray-100 hover:border-emerald-500 py-4 px-6 rounded-2xl font-bold transition-all shadow-sm">
              {loading ? <Loader2 className="w-6 h-6 animate-spin text-emerald-600" /> : <><img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" alt="Google" className="w-6 h-6" /> Accedi con Google</>}
            </button>
            <div className="relative py-4">
              <div className="absolute inset-0 flex items-center"><span className="w-full border-t border-gray-100"></span></div>
              <div className="relative flex justify-center text-xs uppercase"><span className="bg-white px-2 text-gray-400">Oppure</span></div>
            </div>
            <button onClick={() => setAuthMode('email')} className="w-full flex items-center justify-center gap-2 text-emerald-600 font-bold text-sm bg-emerald-50 py-3 rounded-xl hover:bg-emerald-100 transition-colors">
              <Mail className="w-4 h-4" /> Usa Email e Password
            </button>
          </div>
        ) : (
          <form onSubmit={handleEmailAuth} className="space-y-4 text-left animate-in fade-in slide-in-from-bottom-2">
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Email</label>
              <div className="relative">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="pl-12 w-full rounded-xl border border-gray-300 p-4 outline-none focus:border-emerald-500 bg-gray-50" placeholder="tua@email.com" required />
              </div>
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Password</label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="pl-12 w-full rounded-xl border border-gray-300 p-4 outline-none focus:border-emerald-500 bg-gray-50" placeholder="Minimo 6 caratteri" minLength={6} required />
              </div>
            </div>

            {error && <div className="bg-red-50 text-red-600 p-4 rounded-xl text-xs border border-red-100 flex items-start gap-2"><AlertCircle className="w-4 h-4 mt-0.5 flex-shrink-0" /> {error}</div>}
            {success && <div className="bg-emerald-50 text-emerald-700 p-4 rounded-xl text-xs border border-emerald-100 flex items-start gap-2"><CheckCircle2 className="w-4 h-4 mt-0.5 flex-shrink-0" /> {success}</div>}

            <button type="submit" disabled={loading} className="w-full bg-emerald-600 text-white font-bold py-4 rounded-xl shadow-md flex items-center justify-center gap-2 transition-all hover:bg-emerald-700 active:scale-95">
              {loading ? <Loader2 className="animate-spin w-5 h-5" /> : (isRegistering ? <><UserPlus className="w-5 h-5" /> Crea Account</> : <><LogIn className="w-5 h-5" /> Accedi</>)}
            </button>
            <div className="flex justify-between items-center mt-4 pt-2">
              <button type="button" onClick={() => { setIsRegistering(!isRegistering); setError(''); setSuccess(''); }} className="text-emerald-600 font-bold text-xs hover:underline">
                {isRegistering ? "Hai già un account? Accedi" : "Nuovo utente? Registrati"}
              </button>
              <button type="button" onClick={() => { setAuthMode('google'); setError(''); setSuccess(''); }} className="text-gray-400 font-bold text-xs">Torna indietro</button>
            </div>
          </form>
        )}
      </div>
    </div>
  );
};

