import { supabase } from '../src/supabaseClient';
import { Expense, Income, Store, RecurringExpense, ShoppingItem, FamilyProfile, CategoryDefinition, Member } from '../types';

// --- AUTH ---
export const signInWithGoogle = async () => {
  let redirectUrl = window.location.origin;
  if (redirectUrl.endsWith('/')) {
    redirectUrl = redirectUrl.slice(0, -1);
  }

  const { error } = await supabase.auth.signInWithOAuth({
    provider: 'google',
    options: {
      redirectTo: redirectUrl,
    },
  });

  if (error) throw error;
};

export const signUpWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signUp({ email, password });
};

export const signInWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signInWithPassword({ email, password });
};

export const signOut = async () => {
  await supabase.auth.signOut();
};

export const getCurrentUser = async () => {
  const { data: { user } } = await supabase.auth.getUser();
  return user;
};

// --- FAMILY & MEMBERSHIP ---
export const getFamilyForUser = async (userId: string): Promise<{ familyId: string, isAdmin: boolean } | null> => {
  try {
    const { data, error } = await supabase
      .from('family_members')
      .select('family_id, is_admin')
      .eq('user_id', userId)
      .maybeSingle();

    if (error) {
      if (error.message.includes('recursion')) {
        throw new Error("LOOP_DETECTED");
      }
      return null;
    }
    if (!data) return null;
    return { familyId: data.family_id, isAdmin: data.is_admin };
  } catch (err) {
    console.error("Errore recupero famiglia:", err);
    throw err;
  }
};

export const fetchFamilyMembers = async (familyId: string): Promise<Member[]> => {
  const { data, error } = await supabase
    .from('family_members')
    .select('user_id, name, is_admin')
    .eq('family_id', familyId);

  if (error) return [];
  return data.map(m => ({
    id: m.user_id,
    name: m.name,
    color: 'bg-emerald-100 text-emerald-600',
    isAdmin: m.is_admin,
    userId: m.user_id
  }));
};

export const joinFamily = async (userId: string, familyId: string, name: string, isAdmin: boolean = false) => {
  const { error } = await supabase
    .from('family_members')
    .upsert({
      family_id: familyId,
      user_id: userId,
      name: name,
      is_admin: isAdmin
    }, { onConflict: 'family_id,user_id' });

  if (error) {
    console.error("Errore durante l'adesione alla famiglia:", error.message);
    throw error;
  }
};

export const getFamilyProfile = async (familyId: string): Promise<FamilyProfile | null> => {
  const { data, error } = await supabase
    .from('families')
    .select('*')
    .eq('id', familyId)
    .maybeSingle();

  if (error || !data) return null;

  return {
    id: data.id,
    familyName: data.family_name,
    members: data.members || [], 
    createdAt: new Date(data.created_at).getTime()
  };
};

export const createFamilyProfile = async (profile: FamilyProfile): Promise<void> => {
  const { error } = await supabase
    .from('families')
    .insert({
      id: profile.id,
      family_name: profile.familyName,
      members: profile.members
    });

  if (error) {
    if (error.code === '23505') return; // Già esiste
    throw error;
  }
};

// --- EXPENSES ---
export const fetchExpenses = async (familyId: string): Promise<Expense[]> => {
  const { data, error } = await supabase
    .from('expenses')
    .select('*')
    .eq('family_id', familyId)
    .order('date', { ascending: false });

  if (error) return [];
  return data.map((e: any) => ({
    id: e.id,
    product: e.product,
    quantity: Number(e.quantity),
    unitPrice: Number(e.unit_price),
    total: Number(e.total),
    store: e.store,
    date: e.date,
    category: e.category,
    memberId: e.member_id
  }));
};

export const addExpenseToSupabase = async (familyId: string, expense: Expense): Promise<void> => {
  const { error } = await supabase
    .from('expenses')
    .insert({
      id: expense.id,
      family_id: familyId,
      product: expense.product,
      quantity: expense.quantity,
      unit_price: expense.unitPrice,
      total: expense.total,
      store: expense.store,
      date: expense.date,
      category: expense.category,
      member_id: expense.memberId
    });
  if (error) throw error;
};

export const deleteExpenseFromSupabase = async (id: string): Promise<void> => {
  await supabase.from('expenses').delete().eq('id', id);
};

export const fetchIncomes = async (familyId: string): Promise<Income[]> => {
  const { data, error } = await supabase.from('incomes').select('*').eq('family_id', familyId).order('date', { ascending: false });
  if (error) return [];
  return data.map((i: any) => ({ id: i.id, source: i.source, amount: Number(i.amount), date: i.date }));
};

export const addIncomeToSupabase = async (familyId: string, income: Income): Promise<void> => {
  await supabase.from('incomes').insert({ id: income.id, family_id: familyId, source: income.source, amount: income.amount, date: income.date });
};

export const deleteIncomeFromSupabase = async (id: string): Promise<void> => {
  await supabase.from('incomes').delete().eq('id', id);
};

export const fetchStores = async (familyId: string): Promise<Store[]> => {
  const { data, error } = await supabase.from('stores').select('*').eq('family_id', familyId);
  return (data || []).map((s: any) => ({ id: s.id, name: s.name }));
};

export const addStoreToSupabase = async (familyId: string, store: Store): Promise<void> => {
  await supabase.from('stores').insert({ id: store.id, family_id: familyId, name: store.name });
};

export const fetchCategories = async (familyId: string): Promise<CategoryDefinition[]> => {
  const { data, error } = await supabase.from('categories').select('*').eq('family_id', familyId);
  return (data || []).map((c: any) => ({ id: c.id, name: c.name, icon: c.icon, color: c.color }));
};

export const syncCategoriesToSupabase = async (familyId: string, categories: CategoryDefinition[]): Promise<void> => {
    const rows = categories.map(c => ({ id: c.id, family_id: familyId, name: c.name, icon: c.icon, color: c.color }));
    await supabase.from('categories').upsert(rows);
};

export const fetchRecurring = async (familyId: string): Promise<RecurringExpense[]> => {
  const { data, error } = await supabase.from('recurring_expenses').select('*').eq('family_id', familyId);
  return (data || []).map((r: any) => ({ id: r.id, product: r.product, amount: Number(r.amount), store: r.store, frequency: r.frequency, next_due_date: r.next_due_date, reminder_days: r.reminder_days }));
};

export const addRecurringToSupabase = async (familyId: string, item: RecurringExpense): Promise<void> => {
  await supabase.from('recurring_expenses').insert({ id: item.id, family_id: familyId, product: item.product, amount: item.amount, store: item.store, frequency: item.frequency, next_due_date: item.nextDueDate, reminder_days: item.reminderDays });
};

export const deleteRecurringFromSupabase = async (id: string): Promise<void> => {
  await supabase.from('recurring_expenses').delete().eq('id', id);
};

export const fetchShoppingList = async (familyId: string): Promise<ShoppingItem[]> => {
  const { data, error } = await supabase.from('shopping_list').select('*').eq('family_id', familyId);
  return (data || []).map((s: any) => ({ id: s.id, product: s.product, store: s.store, completed: s.completed }));
};

export const addShoppingItemToSupabase = async (familyId: string, item: ShoppingItem): Promise<void> => {
  await supabase.from('shopping_list').insert({ id: item.id, family_id: familyId, product: item.product, store: item.store, completed: item.completed });
};

export const updateShoppingItemInSupabase = async (item: ShoppingItem): Promise<void> => {
  await supabase.from('shopping_list').update({ completed: item.completed }).eq('id', item.id);
};

export const deleteShoppingItemFromSupabase = async (id: string): Promise<void> => {
  await supabase.from('shopping_list').delete().eq('id', id);
};

import React, { useState, useEffect } from 'react';
import { DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, Income, CategoryDefinition } from './types';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { StoreManager } from './components/StoreManager';
import { LoginScreen } from './components/LoginScreen';
import { IncomeManager } from './components/IncomeManager';
import { CategoryManager } from './components/CategoryManager';
import { FamilyManager } from './components/FamilyManager';
import { categorizeExpense } from './services/geminiService';
import { supabase } from './src/supabaseClient';
import * as SupabaseService from './services/supabaseService';
import { 
  WalletCards, LogOut, Menu, X, Home, History, ChevronRight, Coins, Tag, Cloud, User, Loader2, Users, Database
} from 'lucide-react';

type View = 'dashboard' | 'history' | 'budget' | 'categories' | 'profile';

function App() {
  const [session, setSession] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoadingAuth, setIsLoadingAuth] = useState(true);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);
  const [categories, setCategories] = useState<CategoryDefinition[]>(DEFAULT_CATEGORIES);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [isLoadingData, setIsLoadingData] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) checkUserFamily(session.user.id);
      else setIsLoadingAuth(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) {
        checkUserFamily(session.user.id);
      } else {
        setIsAuthenticated(false);
        setFamilyProfile(null);
        setIsLoadingAuth(false);
      }
    });
    return () => subscription.unsubscribe();
  }, []);

  const checkUserFamily = async (userId: string) => {
    setError(null);
    try {
      const membership = await SupabaseService.getFamilyForUser(userId);
      if (membership) {
        const profile = await SupabaseService.getFamilyProfile(membership.familyId);
        if (profile) {
          setFamilyProfile(profile);
          setIsAuthenticated(true);
        } else {
          setIsAuthenticated(false);
        }
      } else {
        setIsAuthenticated(false);
      }
    } catch (e: any) {
      console.error("Errore inizializzazione:", e);
      if (e.message === "LOOP_DETECTED" || (e.message && e.message.includes('recursion'))) {
        setError("Errore critico del database (Ricorsione). Per favore, esegui l'ultimo script SQL 'Azione Risolutiva' fornito dall'assistente su Supabase.");
      }
    } finally {
      setIsLoadingAuth(false);
    }
  };

  useEffect(() => {
    if (isAuthenticated && familyProfile?.id) {
      const loadAllData = async () => {
        setIsLoadingData(true);
        try {
          const [exp, inc, sto, cat] = await Promise.all([
            SupabaseService.fetchExpenses(familyProfile.id),
            SupabaseService.fetchIncomes(familyProfile.id),
            SupabaseService.fetchStores(familyProfile.id),
            SupabaseService.fetchCategories(familyProfile.id)
          ]);
          setExpenses(exp || []);
          setIncomes(inc || []);
          if (sto && sto.length > 0) setStores(sto);
          if (cat && cat.length > 0) setCategories(cat);
        } catch (e: any) { 
          console.error("Errore caricamento dati:", e);
          if (e.message && e.message.includes('recursion')) {
            setError("Rilevata ricorsione nel database. Applica lo script SQL correttivo su Supabase.");
          }
        } finally {
          setIsLoadingData(false);
        }
      };
      loadAllData();
    }
  }, [isAuthenticated, familyProfile?.id]);

  const handleSetupComplete = async (profile: FamilyProfile) => {
    if (!session?.user) return;
    setIsLoadingData(true);
    setError(null);
    try {
      // 1. Crea profilo famiglia
      await SupabaseService.createFamilyProfile(profile);

      // 2. Aggiungi immediatamente l'utente come membro
      const name = session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'Utente';
      await SupabaseService.joinFamily(session.user.id, profile.id, name, true);

      setFamilyProfile(profile);
      setIsAuthenticated(true);
    } catch (e: any) {
      console.error("Errore durante il setup:", e);
      const detail = e.message || JSON.stringify(e);
      if (detail.includes("recursion")) {
        alert("ERRORE DATABASE: Ricorsione infinita rilevata. Per risolvere, incolla lo script SQL 'Azione Risolutiva' nel SQL Editor di Supabase.");
      } else {
        alert(`ATTENZIONE: ${detail}`);
      }
    } finally {
      setIsLoadingData(false);
    }
  };

  const handleLogout = async () => {
    await SupabaseService.signOut();
    setIsAuthenticated(false);
    setFamilyProfile(null);
    setExpenses([]);
    setIncomes([]);
    setIsMenuOpen(false);
    setError(null);
  };

  const handleAddExpense = async (product: string, quantity: number, unitPrice: number, total: number, store: string) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const category = await categorizeExpense(product, store);
      const newExpense: Expense = { 
        id: crypto.randomUUID(), 
        product, 
        quantity, 
        unitPrice, 
        total, 
        store, 
        date: new Date().toISOString(), 
        category, 
        memberId: session?.user?.id 
      };
      setExpenses(prev => [newExpense, ...prev]);
      await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
    } catch (e: any) {
      console.error("Errore salvataggio spesa:", e);
      if (e.message && e.message.includes('recursion')) {
        setError("Errore ricorsione database. Applica lo script SQL su Supabase.");
      } else {
        alert("Errore salvataggio. Controlla la connessione.");
      }
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleAddIncome = async (source: string, amount: number, date: string) => {
    if (!familyProfile) return;
    try {
      const newIncome: Income = { id: crypto.randomUUID(), source, amount, date };
      setIncomes(prev => [newIncome, ...prev]);
      await SupabaseService.addIncomeToSupabase(familyProfile.id, newIncome);
    } catch (e) {
      console.error("Errore salvataggio entrata:", e);
    }
  };

  const MenuButton = ({ view, icon, label }: { view: View, icon: any, label: string }) => (
    <button 
      onClick={() => { setCurrentView(view); setIsMenuOpen(false); }} 
      className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl transition-colors ${currentView === view ? 'bg-emerald-100 text-emerald-800 font-bold' : 'text-gray-700 hover:bg-gray-100'}`}
    >
      {React.cloneElement(icon, { className: 'w-6 h-6' })}
      <span className="text-lg">{label}</span>
      {currentView === view && <ChevronRight className="w-5 h-5 ml-auto text-emerald-600" />}
    </button>
  );

  if (isLoadingAuth) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50">
        <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
        <p className="mt-4 text-gray-500 font-medium text-sm">Verifica sicurezza in corso...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 p-6">
        <div className="bg-white p-8 rounded-3xl shadow-xl max-w-md w-full border border-red-100 text-center">
          <div className="bg-amber-100 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4">
            <Database className="w-8 h-8 text-amber-600" />
          </div>
          <h2 className="text-xl font-bold text-gray-800 mb-2">Problema Database</h2>
          <p className="text-gray-600 text-sm mb-6 leading-relaxed">{error}</p>
          <div className="space-y-3">
            <button onClick={() => window.location.reload()} className="w-full bg-emerald-600 text-white font-bold py-3 rounded-xl shadow-md transition-transform active:scale-95">
              Ricarica App
            </button>
            <button onClick={handleLogout} className="w-full bg-gray-100 text-gray-700 font-bold py-3 rounded-xl transition-transform active:scale-95">
              Disconnetti
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (!session) return <LoginScreen onSetupComplete={handleSetupComplete} />;

  if (!isAuthenticated && !isLoadingData) {
    return <LoginScreen onSetupComplete={handleSetupComplete} isSupabaseAuth={true} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans pb-24 safe-area-top">
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMenuOpen(true)} className="p-2 -ml-2 text-gray-700 hover:bg-gray-100 rounded-xl">
                <Menu className="w-6 h-6" />
             </button>
             <div className="flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('dashboard')}>
                <WalletCards className="w-6 h-6 text-emerald-600" />
                <h1 className="font-bold text-base text-gray-800 truncate max-w-[150px]">
                  {familyProfile?.familyName || 'Spese Famiglia'}
                </h1>
             </div>
          </div>
          <button onClick={() => setCurrentView('profile')} className="bg-gray-100 p-1 rounded-full border border-gray-200">
             {session?.user?.user_metadata?.avatar_url ? (
               <img src={session.user.user_metadata.avatar_url} className="w-7 h-7 rounded-full" alt="User" />
             ) : (
               <User className="w-4 h-4 text-gray-500 m-1" />
             )}
          </button>
        </div>
      </header>

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex">
           <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsMenuOpen(false)}></div>
           <div className="relative w-[85%] max-w-xs bg-white h-full shadow-2xl flex flex-col animate-in slide-in-from-left duration-200">
              <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                 <div>
                   <h2 className="font-bold text-xl text-gray-800">Menù</h2>
                   <span className="text-xs text-emerald-600 font-medium flex items-center gap-1 mt-1"><Cloud className="w-3 h-3" /> Cloud Sync Attivo</span>
                 </div>
                 <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-gray-200 rounded-full"><X className="w-6 h-6 text-gray-500" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-1">
                 <MenuButton view="dashboard" icon={<Home />} label="Home & Aggiungi" />
                 <MenuButton view="budget" icon={<Coins />} label="Bilancio & Guadagni" />
                 <MenuButton view="history" icon={<History />} label="Storico Transazioni" />
                 <div className="my-2 border-t border-gray-100"></div>
                 <MenuButton view="profile" icon={<Users />} label="Profilo Famiglia" />
                 <MenuButton view="categories" icon={<Tag />} label="Gestisci Categorie" />
                 <button onClick={handleLogout} className="w-full flex items-center gap-4 px-5 py-4 rounded-xl text-red-600 hover:bg-red-50 mt-4 font-bold transition-colors">
                   <LogOut className="w-6 h-6" /> Esci dall'App
                 </button>
              </div>
           </div>
        </div>
      )}

      <main className="max-w-2xl mx-auto px-4 py-6">
        {isLoadingData ? (
          <div className="flex flex-col items-center justify-center py-20">
            <Loader2 className="w-12 h-12 text-emerald-500 animate-spin mb-4" />
            <p className="text-gray-500 font-medium">Sincronizzazione dati...</p>
          </div>
        ) : (
          <div className="animate-in fade-in duration-300">
            {currentView === 'dashboard' && (
                <div className="space-y-6">
                    <ExpenseForm 
                      stores={stores} 
                      members={[]} 
                      existingProducts={[]} 
                      productHistory={{}} 
                      onAddExpense={handleAddExpense} 
                      isAnalyzing={isAIProcessing} 
                    />
                    <StoreManager onAddStore={(name) => SupabaseService.addStoreToSupabase(familyProfile!.id, {id: crypto.randomUUID(), name}).then(() => setStores(prev => [...prev, {id: crypto.randomUUID(), name}]))} />
                </div>
            )}
            {currentView === 'history' && (
              <ExpenseList 
                expenses={expenses} 
                stores={stores} 
                categories={categories} 
                onDelete={(id) => SupabaseService.deleteExpenseFromSupabase(id).then(() => setExpenses(prev => prev.filter(e => e.id !== id)))} 
                onEdit={(updated) => {
                  setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e));
                }} 
              />
            )}
            {currentView === 'budget' && (
              <IncomeManager 
                incomes={incomes} 
                expenses={expenses} 
                onAddIncome={handleAddIncome} 
                onDeleteIncome={(id) => SupabaseService.deleteIncomeFromSupabase(id).then(() => setIncomes(prev => prev.filter(i => i.id !== id)))} 
              />
            )}
            {currentView === 'categories' && (
              <CategoryManager 
                categories={categories} 
                onUpdateCategories={(cats) => {setCategories(cats); SupabaseService.syncCategoriesToSupabase(familyProfile!.id, cats);}} 
              />
            )}
            {currentView === 'profile' && familyProfile && (
              <FamilyManager familyProfile={familyProfile} />
            )}
          </div>
        )}
      </main>
    </div>
  );
}

export default App;

payload.text:
L'errore di **ricorsione infinita** (recursion) è il problema più ostico di Supabase perché non dipende dal codice dell'app, ma da come il database "pensa". Succede quando una regola dice: *"Puoi leggere i tuoi dati se sei nel gruppo"* e il database risponde: *"Per sapere se sei nel gruppo devo leggere i dati... ma per leggerli devo sapere se sei nel gruppo..."* e così via all'infinito.

Non serve cambiare database, dobbiamo solo **radere al suolo le regole attuali e metterne di semplicissime** che non richiedono calcoli circolari.

### 1. Azione "Tabula Rasa" (Da eseguire nel SQL Editor di Supabase)
Copia questo script, incollalo nel SQL Editor e premi **RUN**. Questo script elimina tutto e ricrea le tabelle da zero con regole che **non possono fallire**.

```sql
-- 1. ELIMINA TUTTO IL VECCHIO (RESET TOTALE)
DROP TABLE IF EXISTS expenses CASCADE;
DROP TABLE IF EXISTS incomes CASCADE;
DROP TABLE IF EXISTS stores CASCADE;
DROP TABLE IF EXISTS categories CASCADE;
DROP TABLE IF EXISTS recurring_expenses CASCADE;
DROP TABLE IF EXISTS shopping_list CASCADE;
DROP TABLE IF EXISTS family_members CASCADE;
DROP TABLE IF EXISTS families CASCADE;

-- 2. CREA TABELLE PULITE
CREATE TABLE families (
    id UUID PRIMARY KEY,
    family_name TEXT NOT NULL,
    members JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE family_members (
    family_id UUID REFERENCES families(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    name TEXT NOT NULL,
    is_admin BOOLEAN DEFAULT false,
    PRIMARY KEY (family_id, user_id)
);

CREATE TABLE expenses (
    id UUID PRIMARY KEY,
    family_id UUID REFERENCES families(id) ON DELETE CASCADE,
    product TEXT NOT NULL,
    quantity NUMERIC DEFAULT 1,
    unit_price NUMERIC DEFAULT 0,
    total NUMERIC NOT NULL,
    store TEXT,
    date TIMESTAMPTZ DEFAULT now(),
    category TEXT,
    member_id UUID
);

CREATE TABLE incomes (
    id UUID PRIMARY KEY,
    family_id UUID REFERENCES families(id) ON DELETE CASCADE,
    source TEXT NOT NULL,
    amount NUMERIC NOT NULL,
    date TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE stores (
    id UUID PRIMARY KEY,
    family_id UUID REFERENCES families(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    UNIQUE(family_id, name)
);

CREATE TABLE categories (
    id UUID PRIMARY KEY,
    family_id UUID REFERENCES families(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    icon TEXT,
    color TEXT,
    UNIQUE(family_id, name)
);

-- 3. ABILITA SICUREZZA (RLS)
ALTER TABLE families ENABLE ROW LEVEL SECURITY;
ALTER TABLE family_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE expenses ENABLE ROW LEVEL SECURITY;
ALTER TABLE incomes ENABLE ROW LEVEL SECURITY;
ALTER TABLE stores ENABLE ROW LEVEL SECURITY;
ALTER TABLE categories ENABLE ROW LEVEL SECURITY;

-- 4. LE REGOLE PIÙ SEMPLICI DEL MONDO (EVITA RICORSIONE)
-- Permettiamo tutto a chiunque sia LOGGATO. 
-- La separazione dei dati avviene via codice nell'app usando l'ID Famiglia.
CREATE POLICY "auth_all" ON families FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "auth_all" ON family_members FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "auth_all" ON expenses FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "auth_all" ON incomes FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "auth_all" ON stores FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "auth_all" ON categories FOR ALL TO authenticated USING (true) WITH CHECK (true);
```

---

### 2. Aggiornamento dell'Applicazione
Applicherò modifiche al file `App.tsx` e `supabaseService.ts` per gestire la mancanza di dati iniziale in modo più fluido, evitando di mostrare la schermata di errore se semplicemente l'utente non ha ancora una famiglia.

