import { supabase } from '../src/supabaseClient';
import { Expense, Income, Store, RecurringExpense, ShoppingItem, FamilyProfile, CategoryDefinition, Member } from '../types';

// --- AUTH ---
export const signInWithGoogle = async () => {
  let redirectUrl = window.location.origin;
  if (redirectUrl.endsWith('/')) {
    redirectUrl = redirectUrl.slice(0, -1);
  }

  const { error } = await supabase.auth.signInWithOAuth({
    provider: 'google',
    options: {
      redirectTo: redirectUrl,
    },
  });

  if (error) throw error;
};

export const signUpWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signUp({ email, password });
};

export const signInWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signInWithPassword({ email, password });
};

export const signOut = async () => {
  await supabase.auth.signOut();
};

export const getCurrentUser = async () => {
  const { data: { user } } = await supabase.auth.getUser();
  return user;
};

// --- FAMILY & MEMBERSHIP ---
export const getFamilyForUser = async (userId: string): Promise<{ familyId: string, isAdmin: boolean } | null> => {
  try {
    const { data, error } = await supabase
      .from('family_members')
      .select('family_id, is_admin')
      .eq('user_id', userId)
      .maybeSingle();

    if (error) {
      console.error("Errore query membership:", error.message);
      return null;
    }
    if (!data) return null;
    return { familyId: data.family_id, isAdmin: data.is_admin };
  } catch (err) {
    return null;
  }
};

export const fetchFamilyMembers = async (familyId: string): Promise<Member[]> => {
  const { data, error } = await supabase
    .from('family_members')
    .select('user_id, name, is_admin')
    .eq('family_id', familyId);

  if (error) return [];
  return data.map(m => ({
    id: m.user_id,
    name: m.name,
    color: 'bg-emerald-100 text-emerald-600',
    isAdmin: m.is_admin,
    userId: m.user_id
  }));
};

export const joinFamily = async (userId: string, familyId: string, name: string, isAdmin: boolean = false) => {
  const { error } = await supabase
    .from('family_members')
    .upsert({
      family_id: familyId,
      user_id: userId,
      name: name,
      is_admin: isAdmin
    });

  if (error) {
    throw error;
  }
};

export const getFamilyProfile = async (familyId: string): Promise<FamilyProfile | null> => {
  const { data, error } = await supabase
    .from('families')
    .select('*')
    .eq('id', familyId)
    .maybeSingle();

  if (error || !data) return null;

  return {
    id: data.id,
    familyName: data.family_name,
    members: data.members || [], 
    createdAt: new Date(data.created_at).getTime()
  };
};

export const createFamilyProfile = async (profile: FamilyProfile): Promise<void> => {
  const { error } = await supabase
    .from('families')
    .insert({
      id: profile.id,
      family_name: profile.familyName,
      members: profile.members
    });

  if (error && error.code !== '23505') {
    throw error;
  }
};

// --- EXPENSES ---
export const fetchExpenses = async (familyId: string): Promise<Expense[]> => {
  const { data, error } = await supabase
    .from('expenses')
    .select('*')
    .eq('family_id', familyId)
    .order('date', { ascending: false });

  if (error) return [];
  return data.map((e: any) => ({
    id: e.id,
    product: e.product,
    quantity: Number(e.quantity),
    unitPrice: Number(e.unit_price),
    total: Number(e.total),
    store: e.store,
    date: e.date,
    category: e.category,
    memberId: e.member_id
  }));
};

export const addExpenseToSupabase = async (familyId: string, expense: Expense): Promise<void> => {
  await supabase.from('expenses').insert({
    id: expense.id,
    family_id: familyId,
    product: expense.product,
    quantity: expense.quantity,
    unit_price: expense.unitPrice,
    total: expense.total,
    store: expense.store,
    date: expense.date,
    category: expense.category,
    member_id: expense.memberId
  });
};

export const deleteExpenseFromSupabase = async (id: string): Promise<void> => {
  await supabase.from('expenses').delete().eq('id', id);
};

export const fetchIncomes = async (familyId: string): Promise<Income[]> => {
  const { data, error } = await supabase.from('incomes').select('*').eq('family_id', familyId).order('date', { ascending: false });
  return (data || []).map((i: any) => ({ id: i.id, source: i.source, amount: Number(i.amount), date: i.date }));
};

export const addIncomeToSupabase = async (familyId: string, income: Income): Promise<void> => {
  await supabase.from('incomes').insert({ id: income.id, family_id: familyId, source: income.source, amount: income.amount, date: income.date });
};

export const deleteIncomeFromSupabase = async (id: string): Promise<void> => {
  await supabase.from('incomes').delete().eq('id', id);
};

export const fetchStores = async (familyId: string): Promise<Store[]> => {
  const { data } = await supabase.from('stores').select('*').eq('family_id', familyId);
  return (data || []).map((s: any) => ({ id: s.id, name: s.name }));
};

export const addStoreToSupabase = async (familyId: string, store: Store): Promise<void> => {
  await supabase.from('stores').insert({ id: store.id, family_id: familyId, name: store.name });
};

export const fetchCategories = async (familyId: string): Promise<CategoryDefinition[]> => {
  const { data } = await supabase.from('categories').select('*').eq('family_id', familyId);
  return (data || []).map((c: any) => ({ id: c.id, name: c.name, icon: c.icon, color: c.color }));
};

export const syncCategoriesToSupabase = async (familyId: string, categories: CategoryDefinition[]): Promise<void> => {
    const rows = categories.map(c => ({ id: c.id, family_id: familyId, name: c.name, icon: c.icon, color: c.color }));
    await supabase.from('categories').upsert(rows);
};

export const fetchRecurring = async (familyId: string): Promise<RecurringExpense[]> => {
  const { data } = await supabase.from('recurring_expenses').select('*').eq('family_id', familyId);
  return (data || []).map((r: any) => ({ 
    id: r.id, 
    product: r.product, 
    amount: Number(r.amount), 
    store: r.store, 
    frequency: r.frequency, 
    nextDueDate: r.next_due_date, 
    reminderDays: r.reminder_days 
  }));
};

export const addRecurringToSupabase = async (familyId: string, item: RecurringExpense): Promise<void> => {
  await supabase.from('recurring_expenses').insert({ 
    id: item.id, 
    family_id: familyId, 
    product: item.product, 
    amount: item.amount, 
    store: item.store, 
    frequency: item.frequency, 
    next_due_date: item.nextDueDate, 
    reminder_days: item.reminderDays 
  });
};

export const deleteRecurringFromSupabase = async (id: string): Promise<void> => {
  await supabase.from('recurring_expenses').delete().eq('id', id);
};

export const fetchShoppingList = async (familyId: string): Promise<ShoppingItem[]> => {
  const { data, error } = await supabase
    .from('shopping_list')
    .select('*')
    .eq('family_id', familyId)
    .order('created_at', { ascending: false });

  if (error) return [];
  return (data || []).map((s: any) => ({ 
    id: s.id, 
    product: s.product, 
    store: s.store, 
    completed: s.completed 
  }));
};

export const addShoppingItemToSupabase = async (familyId: string, item: ShoppingItem): Promise<void> => {
  await supabase.from('shopping_list').insert({ 
    id: item.id, 
    family_id: familyId, 
    product: item.product, 
    store: item.store, 
    completed: item.completed 
  });
};

export const updateShoppingItemInSupabase = async (item: ShoppingItem): Promise<void> => {
  await supabase.from('shopping_list').update({ completed: item.completed }).eq('id', item.id);
};

export const deleteShoppingItemFromSupabase = async (id: string): Promise<void> => {
  await supabase.from('shopping_list').delete().eq('id', id);
};

import React, { useState, useEffect, useMemo } from 'react';
import { DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, Income, CategoryDefinition, ShoppingItem } from './types';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { StoreManager } from './components/StoreManager';
import { LoginScreen } from './components/LoginScreen';
import { IncomeManager } from './components/IncomeManager';
import { CategoryManager } from './components/CategoryManager';
import { FamilyManager } from './components/FamilyManager';
import { ReceiptScanner } from './components/ReceiptScanner';
import { ShoppingListManager } from './components/ShoppingListManager';
import { ReceiptData } from './services/geminiService';
import { categorizeExpense } from './services/geminiService';
import { supabase } from './src/supabaseClient';
import * as SupabaseService from './services/supabaseService';
import { 
  WalletCards, LogOut, Menu, X, Home, History, ChevronRight, Coins, Tag, Cloud, User, Loader2, Users, Database, Sparkles
} from 'lucide-react';

type View = 'dashboard' | 'history' | 'budget' | 'categories' | 'profile';

function App() {
  const [session, setSession] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoadingAuth, setIsLoadingAuth] = useState(true);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [shoppingItems, setShoppingItems] = useState<ShoppingItem[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);
  const [categories, setCategories] = useState<CategoryDefinition[]>(DEFAULT_CATEGORIES);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [isLoadingData, setIsLoadingData] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Deriviamo la cronologia prodotti per suggerimenti
  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const existingProducts = useMemo(() => Object.keys(productHistory), [productHistory]);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) checkUserFamily(session.user.id);
      else setIsLoadingAuth(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) {
        checkUserFamily(session.user.id);
      } else {
        setIsAuthenticated(false);
        setFamilyProfile(null);
        setIsLoadingAuth(false);
      }
    });
    return () => subscription.unsubscribe();
  }, []);

  const checkUserFamily = async (userId: string) => {
    try {
      const membership = await SupabaseService.getFamilyForUser(userId);
      if (membership) {
        const profile = await SupabaseService.getFamilyProfile(membership.familyId);
        if (profile) {
          setFamilyProfile(profile);
          setIsAuthenticated(true);
        } else {
          setIsAuthenticated(false);
        }
      } else {
        setIsAuthenticated(false);
      }
    } catch (e: any) {
      console.error("Errore inizializzazione:", e);
      if (e.message && e.message.includes('recursion')) {
        setError("Errore ricorsione database. Per favore esegui lo script SQL aggiornato.");
      }
    } finally {
      setIsLoadingAuth(false);
    }
  };

  useEffect(() => {
    if (isAuthenticated && familyProfile?.id) {
      const loadAllData = async () => {
        setIsLoadingData(true);
        try {
          const [exp, inc, sto, cat, shop] = await Promise.all([
            SupabaseService.fetchExpenses(familyProfile.id),
            SupabaseService.fetchIncomes(familyProfile.id),
            SupabaseService.fetchStores(familyProfile.id),
            SupabaseService.fetchCategories(familyProfile.id),
            SupabaseService.fetchShoppingList(familyProfile.id)
          ]);
          setExpenses(exp || []);
          setIncomes(inc || []);
          setShoppingItems(shop || []);
          if (sto && sto.length > 0) setStores(sto);
          if (cat && cat.length > 0) setCategories(cat);
        } catch (e: any) { 
          console.error("Errore caricamento dati:", e);
        } finally {
          setIsLoadingData(false);
        }
      };
      loadAllData();
    }
  }, [isAuthenticated, familyProfile?.id]);

  const handleSetupComplete = async (profile: FamilyProfile) => {
    if (!session?.user) return;
    setIsLoadingData(true);
    try {
      await SupabaseService.createFamilyProfile(profile);
      const name = session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'Utente';
      await SupabaseService.joinFamily(session.user.id, profile.id, name, true);
      setFamilyProfile(profile);
      setIsAuthenticated(true);
    } catch (e: any) {
      alert(`Errore: ${e.message}`);
    } finally {
      setIsLoadingData(false);
    }
  };

  const handleLogout = async () => {
    await SupabaseService.signOut();
    setIsAuthenticated(false);
    setFamilyProfile(null);
    setExpenses([]);
    setIncomes([]);
    setShoppingItems([]);
    setIsMenuOpen(false);
    setError(null);
  };

  const handleAddExpense = async (product: string, quantity: number, unitPrice: number, total: number, store: string) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const category = await categorizeExpense(product, store);
      const newExpense: Expense = { 
        id: crypto.randomUUID(), 
        product, 
        quantity, 
        unitPrice, 
        total, 
        store, 
        date: new Date().toISOString(), 
        category, 
        memberId: session?.user?.id 
      };
      setExpenses(prev => [newExpense, ...prev]);
      await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
    } catch (e: any) {
      console.error("Errore salvataggio spesa:", e);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleScanComplete = async (data: ReceiptData) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const newExpenses: Expense[] = [];
      for (const item of data.items) {
        const newExpense: Expense = {
          id: crypto.randomUUID(),
          product: item.product,
          quantity: item.quantity,
          unitPrice: item.unitPrice,
          total: item.total,
          store: data.store || 'Sconosciuto',
          date: data.date ? new Date(data.date).toISOString() : new Date().toISOString(),
          category: item.category || 'Alimentari',
          memberId: session?.user?.id
        };
        await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
        newExpenses.push(newExpense);
      }
      setExpenses(prev => [...newExpenses, ...prev]);
      if (data.store && !stores.some(s => s.name.toLowerCase() === data.store.toLowerCase())) {
        const newStore = { id: crypto.randomUUID(), name: data.store };
        await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
        setStores(prev => [...prev, newStore]);
      }
    } catch (err) {
      console.error("Errore durante il salvataggio dello scontrino:", err);
      alert("Errore nel caricamento dei prodotti. Verifica che le tabelle SQL siano create.");
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleAddShoppingItem = async (product: string, store: string) => {
    if (!familyProfile) return;
    const newItem: ShoppingItem = { id: crypto.randomUUID(), product, store, completed: false };
    setShoppingItems(prev => [newItem, ...prev]);
    await SupabaseService.addShoppingItemToSupabase(familyProfile.id, newItem);
  };

  const handleToggleShoppingItem = async (id: string) => {
    const item = shoppingItems.find(i => i.id === id);
    if (!item) return;
    const updated = { ...item, completed: !item.completed };
    setShoppingItems(prev => prev.map(i => i.id === id ? updated : i));
    await SupabaseService.updateShoppingItemInSupabase(updated);
  };

  const handleDeleteShoppingItem = async (id: string) => {
    setShoppingItems(prev => prev.filter(i => i.id !== id));
    await SupabaseService.deleteShoppingItemFromSupabase(id);
  };

  const handleAddIncome = async (source: string, amount: number, date: string) => {
    if (!familyProfile) return;
    try {
      const newIncome: Income = { id: crypto.randomUUID(), source, amount, date };
      setIncomes(prev => [newIncome, ...prev]);
      await SupabaseService.addIncomeToSupabase(familyProfile.id, newIncome);
    } catch (e) {
      console.error("Errore salvataggio entrata:", e);
    }
  };

  const MenuButton = ({ view, icon, label }: { view: View, icon: any, label: string }) => (
    <button 
      onClick={() => { setCurrentView(view); setIsMenuOpen(false); }} 
      className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl transition-colors ${currentView === view ? 'bg-emerald-100 text-emerald-800 font-bold' : 'text-gray-700 hover:bg-gray-100'}`}
    >
      {React.cloneElement(icon, { className: 'w-6 h-6' })}
      <span className="text-lg">{label}</span>
      {currentView === view && <ChevronRight className="w-5 h-5 ml-auto text-emerald-600" />}
    </button>
  );

  if (isLoadingAuth) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50">
        <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
        <p className="mt-4 text-gray-500 font-medium">Verifica profilo...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 p-6">
        <div className="bg-white p-8 rounded-3xl shadow-xl max-w-md w-full border border-red-100 text-center">
          <Database className="w-12 h-12 text-red-500 mx-auto mb-4" />
          <h2 className="text-xl font-bold text-gray-800 mb-2">Problema Database</h2>
          <p className="text-gray-600 text-sm mb-6">{error}</p>
          <div className="space-y-3">
            <button onClick={() => window.location.reload()} className="w-full bg-emerald-600 text-white font-bold py-3 rounded-xl shadow-md">Ricarica App</button>
            <button onClick={handleLogout} className="w-full bg-gray-100 text-gray-700 font-bold py-3 rounded-xl">Disconnetti</button>
          </div>
        </div>
      </div>
    );
  }

  if (!session) return <LoginScreen onSetupComplete={handleSetupComplete} />;

  if (!isAuthenticated && !isLoadingData) {
    return <LoginScreen onSetupComplete={handleSetupComplete} isSupabaseAuth={true} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans pb-24 safe-area-top">
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMenuOpen(true)} className="p-2 -ml-2 text-gray-700 hover:bg-gray-100 rounded-xl">
                <Menu className="w-6 h-6" />
             </button>
             <div className="flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('dashboard')}>
                <WalletCards className="w-6 h-6 text-emerald-600" />
                <h1 className="font-bold text-base text-gray-800 truncate max-w-[150px]">
                  {familyProfile?.familyName || 'Spese Famiglia'}
                </h1>
             </div>
          </div>
          <button onClick={() => setCurrentView('profile')} className="bg-gray-100 p-1 rounded-full border border-gray-200">
             {session?.user?.user_metadata?.avatar_url ? (
               <img src={session.user.user_metadata.avatar_url} className="w-7 h-7 rounded-full" alt="User" />
             ) : (
               <User className="w-4 h-4 text-gray-500 m-1" />
             )}
          </button>
        </div>
      </header>

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex">
           <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsMenuOpen(false)}></div>
           <div className="relative w-[85%] max-w-xs bg-white h-full shadow-2xl flex flex-col animate-in slide-in-from-left duration-200">
              <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                 <div>
                   <h2 className="font-bold text-xl text-gray-800">Menù</h2>
                   <span className="text-xs text-emerald-600 font-medium flex items-center gap-1 mt-1"><Cloud className="w-3 h-3" /> Cloud Sync Attivo</span>
                 </div>
                 <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-gray-200 rounded-full"><X className="w-6 h-6 text-gray-500" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-1">
                 <MenuButton view="dashboard" icon={<Home />} label="Home & Aggiungi" />
                 <MenuButton view="budget" icon={<Coins />} label="Bilancio & Guadagni" />
                 <MenuButton view="history" icon={<History />} label="Storico Transazioni" />
                 <div className="my-2 border-t border-gray-100"></div>
                 <MenuButton view="profile" icon={<Users />} label="Profilo Famiglia" />
                 <MenuButton view="categories" icon={<Tag />} label="Gestisci Categorie" />
                 <button onClick={handleLogout} className="w-full flex items-center gap-4 px-5 py-4 rounded-xl text-red-600 hover:bg-red-50 mt-4 font-bold transition-colors">
                   <LogOut className="w-6 h-6" /> Esci dall'App
                 </button>
              </div>
           </div>
        </div>
      )}

      <main className="max-w-2xl mx-auto px-4 py-6">
        {isLoadingData ? (
          <div className="flex flex-col items-center justify-center py-20">
            <Loader2 className="w-12 h-12 text-emerald-500 animate-spin mb-4" />
            <p className="text-gray-500 font-medium">Sincronizzazione dati...</p>
          </div>
        ) : (
          <div className="animate-in fade-in duration-300">
            {currentView === 'dashboard' && (
                <div className="space-y-6">
                    {/* 1. SCANNER (Veloce) */}
                    <ReceiptScanner onScanComplete={handleScanComplete} />

                    {/* 2. LISTA DELLA SPESA (Importante) */}
                    <ShoppingListManager 
                      items={shoppingItems} 
                      stores={stores} 
                      productHistory={productHistory} 
                      onAddItem={handleAddShoppingItem} 
                      onToggleItem={handleToggleShoppingItem} 
                      onDeleteItem={handleDeleteShoppingItem} 
                    />

                    {/* 3. FORM MANUALE (Dettaglio) */}
                    <ExpenseForm 
                      stores={stores} 
                      members={[]} 
                      existingProducts={existingProducts} 
                      productHistory={productHistory} 
                      onAddExpense={handleAddExpense} 
                      isAnalyzing={isAIProcessing} 
                    />

                    <StoreManager onAddStore={(name) => SupabaseService.addStoreToSupabase(familyProfile!.id, {id: crypto.randomUUID(), name}).then(() => setStores(prev => [...prev, {id: crypto.randomUUID(), name}]))} />
                </div>
            )}
            {currentView === 'history' && (
              <ExpenseList 
                expenses={expenses} 
                stores={stores} 
                categories={categories} 
                onDelete={(id) => SupabaseService.deleteExpenseFromSupabase(id).then(() => setExpenses(prev => prev.filter(e => e.id !== id)))} 
                onEdit={(updated) => {
                  setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e));
                }} 
              />
            )}
            {currentView === 'budget' && (
              <IncomeManager 
                incomes={incomes} 
                expenses={expenses} 
                onAddIncome={handleAddIncome} 
                onDeleteIncome={(id) => SupabaseService.deleteIncomeFromSupabase(id).then(() => setIncomes(prev => prev.filter(i => i.id !== id)))} 
              />
            )}
            {currentView === 'categories' && (
              <CategoryManager 
                categories={categories} 
                onUpdateCategories={(cats) => {setCategories(cats); SupabaseService.syncCategoriesToSupabase(familyProfile!.id, cats);}} 
              />
            )}
            {currentView === 'profile' && familyProfile && (
              <FamilyManager familyProfile={familyProfile} />
            )}
          </div>
        )}
      </main>
    </div>
  );
}

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { Expense, FlyerOffer } from "../types";

export interface ReceiptItem {
  product: string;
  quantity: number;
  unitPrice: number;
  total: number;
  category: string;
}

export interface ReceiptData {
  store: string;
  date: string;
  items: ReceiptItem[];
}

const getAI = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey || apiKey === "" || apiKey === "undefined" || apiKey.length < 10) {
    return null;
  }
  try {
    return new GoogleGenAI({ apiKey });
  } catch (e) {
    return null;
  }
};

export const categorizeExpense = async (product: string, store: string): Promise<string> => {
  try {
    const ai = getAI();
    if (!ai) return "Alimentari";
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Categorizza "${product}" acquistato da "${store}". Scegli tra: Alimentari, Trasporti, Casa, Salute, Svago, Abbigliamento, Utenze, Altro. Restituisci SOLO il nome della categoria.`,
    });
    return response.text?.trim() || "Alimentari";
  } catch (error) {
    return "Alimentari";
  }
};

export const getSpendingAnalysis = async (expenses: Expense[]): Promise<string> => {
  if (expenses.length === 0) return "Nessuna spesa.";
  try {
    const ai = getAI();
    if (!ai) return "Configura API_KEY per i consigli.";
    const summary = expenses.map(e => `${e.product} (€${e.total})`).join(', ');
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analizza queste spese e dai 2 consigli di risparmio brevi in italiano: ${summary}`,
    });
    return response.text || "Analisi non disponibile.";
  } catch (error) {
    return "Impossibile generare l'analisi.";
  }
};

export const findFlyerOffers = async (city: string, stores: string[]): Promise<FlyerOffer[]> => {
    return stores.map(store => ({
        storeName: store,
        flyerLink: `https://www.google.com/search?q=volantino+${encodeURIComponent(store)}+${encodeURIComponent(city)}`,
        validUntil: 'Vedi volantino',
        topOffers: []
    }));
};

export const parseReceiptImage = async (base64Image: string, mimeType: string = 'image/jpeg'): Promise<{ success: boolean; data?: ReceiptData; error?: string }> => {
  try {
    const ai = getAI();
    if (!ai) return { success: false, error: "API_KEY mancante." };

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType, data: base64Image } },
          { text: "Estrai i dati da questo scontrino. Se un prezzo o quantità non è chiaro, usa 0 o 1 come default. Categorizza ogni prodotto." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            store: { type: Type.STRING, description: "Nome del negozio" },
            date: { type: Type.STRING, description: "Data nel formato YYYY-MM-DD" },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  product: { type: Type.STRING },
                  quantity: { type: Type.NUMBER },
                  unitPrice: { type: Type.NUMBER },
                  total: { type: Type.NUMBER },
                  category: { type: Type.STRING }
                },
                required: ["product", "quantity", "unitPrice", "total", "category"]
              }
            }
          },
          required: ["store", "items"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Risposta vuota dall'IA");

    return { success: true, data: JSON.parse(text) };
  } catch (error: any) {
    console.error("Errore Parse Scontrino:", error);
    return { success: false, error: "Errore durante l'analisi dell'immagine. Riprova con una foto più nitida." };
  }
};

import React, { useRef, useState } from 'react';
import { Camera, Image as ImageIcon, ScanLine, CheckCircle, Sparkles, AlertTriangle, RefreshCw, Loader2 } from 'lucide-react';
import { parseReceiptImage, ReceiptData } from '../services/geminiService';

interface ReceiptScannerProps {
  onScanComplete: (data: ReceiptData) => void;
}

type ScanStatus = 'idle' | 'scanning' | 'success' | 'error';

export const ReceiptScanner: React.FC<ReceiptScannerProps> = ({ onScanComplete }) => {
  const cameraInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);

  const [status, setStatus] = useState<ScanStatus>('idle');
  const [foundItemsCount, setFoundItemsCount] = useState(0);
  const [errorMessage, setErrorMessage] = useState('');

  const compressAndConvertToBase64 = (file: File): Promise<{ base64: string, mimeType: string }> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);

      reader.onload = (event) => {
        const img = new Image();
        img.src = event.target?.result as string;

        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;

          const MAX_DIMENSION = 1200; // Ottimale per OCR
          if (width > height) {
            if (width > MAX_DIMENSION) {
              height *= MAX_DIMENSION / width;
              width = MAX_DIMENSION;
            }
          } else {
            if (height > MAX_DIMENSION) {
              width *= MAX_DIMENSION / height;
              height = MAX_DIMENSION;
            }
          }

          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error("Errore Canvas"));

          ctx.drawImage(img, 0, 0, width, height);
          const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
          resolve({ base64: dataUrl.split(',')[1], mimeType: 'image/jpeg' });
        };
        img.onerror = reject;
      };
      reader.onerror = reject;
    });
  };

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setStatus('scanning');
    setErrorMessage('');

    try {
      const { base64, mimeType } = await compressAndConvertToBase64(file);
      const result = await parseReceiptImage(base64, mimeType);

      if (result.success && result.data) {
        onScanComplete(result.data);
        setFoundItemsCount(result.data.items.length);
        setStatus('success');
        setTimeout(() => setStatus('idle'), 3000);
      } else {
        setErrorMessage(result.error || "Impossibile leggere lo scontrino.");
        setStatus('error');
      }
    } catch (error) {
      console.error("Scan Error:", error);
      setErrorMessage("Errore di caricamento immagine.");
      setStatus('error');
    } finally {
      if (cameraInputRef.current) cameraInputRef.current.value = '';
      if (galleryInputRef.current) galleryInputRef.current.value = '';
    }
  };

  return (
    <div className={`p-6 rounded-2xl shadow-lg border transition-all duration-300 mb-6 text-white overflow-hidden relative ${
      status === 'error' ? 'bg-red-50 border-red-200' : 'bg-gradient-to-br from-emerald-600 to-teal-700 border-emerald-500/50'
    }`}>
      <input type="file" ref={cameraInputRef} onChange={handleFileChange} accept="image/*" capture="environment" className="hidden" />
      <input type="file" ref={galleryInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />

      {status === 'idle' && (
        <>
          <div className="flex items-center justify-between mb-4">
            <div>
                <h2 className="text-lg font-bold flex items-center gap-2">
                    <ScanLine className="w-5 h-5 text-emerald-200" /> Scansiona Scontrino
                </h2>
                <p className="text-emerald-100 text-xs mt-1">L'IA caricherà automaticamente tutti i prodotti.</p>
            </div>
            <Sparkles className="w-5 h-5 text-yellow-300" />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <button onClick={() => cameraInputRef.current?.click()} className="bg-white text-emerald-700 font-bold py-3 rounded-xl flex flex-col items-center gap-1 shadow-md active:scale-95">
                <Camera className="w-5 h-5" /> <span className="text-sm">Fotocamera</span>
            </button>
            <button onClick={() => galleryInputRef.current?.click()} className="bg-emerald-800/40 text-white font-medium py-3 rounded-xl flex flex-col items-center gap-1 active:scale-95">
                <ImageIcon className="w-5 h-5" /> <span className="text-sm">Galleria</span>
            </button>
          </div>
        </>
      )}

      {status === 'scanning' && (
        <div className="flex flex-col items-center py-4">
          <Loader2 className="w-10 h-10 animate-spin mb-3" />
          <h3 className="font-bold text-lg">Analisi IA in corso...</h3>
          <p className="text-emerald-100 text-xs">Leggo prodotti e prezzi dallo scontrino...</p>
        </div>
      )}

      {status === 'success' && (
        <div className="flex flex-col items-center py-4">
          <CheckCircle className="w-12 h-12 mb-2" />
          <h3 className="font-bold text-lg">Caricato!</h3>
          <p className="text-emerald-100 text-sm">Aggiunti {foundItemsCount} prodotti alla lista.</p>
        </div>
      )}

      {status === 'error' && (
        <div className="flex flex-col items-center py-2 text-red-800">
          <AlertTriangle className="w-10 h-10 text-red-600 mb-2" />
          <h3 className="font-bold">Errore Scansione</h3>
          <p className="text-red-600 text-xs text-center mb-4">{errorMessage}</p>
          <button onClick={() => setStatus('idle')} className="bg-red-600 text-white px-6 py-2 rounded-lg text-sm font-bold">Riprova</button>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, Income, CategoryDefinition, ShoppingItem, OfferPreferences } from './types';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { StoreManager } from './components/StoreManager';
import { LoginScreen } from './components/LoginScreen';
import { IncomeManager } from './components/IncomeManager';
import { CategoryManager } from './components/CategoryManager';
import { FamilyManager } from './components/FamilyManager';
import { ReceiptScanner } from './components/ReceiptScanner';
import { ShoppingListManager } from './components/ShoppingListManager';
import { OffersFinder } from './components/OffersFinder';
import { ReceiptData } from './services/geminiService';
import { categorizeExpense } from './services/geminiService';
import { supabase } from './src/supabaseClient';
import * as SupabaseService from './services/supabaseService';
import { 
  WalletCards, LogOut, Menu, X, Home, History, ChevronRight, Coins, Tag, Cloud, User, Loader2, Users, Database, Sparkles, ShoppingCart, Percent
} from 'lucide-react';

type View = 'dashboard' | 'shopping' | 'offers' | 'history' | 'budget' | 'categories' | 'profile';

function App() {
  const [session, setSession] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoadingAuth, setIsLoadingAuth] = useState(true);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [shoppingItems, setShoppingItems] = useState<ShoppingItem[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);
  const [categories, setCategories] = useState<CategoryDefinition[]>(DEFAULT_CATEGORIES);
  const [offerPrefs, setOfferPrefs] = useState<OfferPreferences>({
    city: '',
    selectedStores: [],
    lastCheckDate: Date.now(),
    hasEnabledNotifications: false
  });

  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [isLoadingData, setIsLoadingData] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Deriviamo la cronologia prodotti per suggerimenti
  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const existingProducts = useMemo(() => Object.keys(productHistory), [productHistory]);
  const activeShoppingCount = useMemo(() => shoppingItems.filter(i => !i.completed).length, [shoppingItems]);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) checkUserFamily(session.user.id);
      else setIsLoadingAuth(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) {
        checkUserFamily(session.user.id);
      } else {
        setIsAuthenticated(false);
        setFamilyProfile(null);
        setIsLoadingAuth(false);
      }
    });
    return () => subscription.unsubscribe();
  }, []);

  const checkUserFamily = async (userId: string) => {
    try {
      const membership = await SupabaseService.getFamilyForUser(userId);
      if (membership) {
        const profile = await SupabaseService.getFamilyProfile(membership.familyId);
        if (profile) {
          setFamilyProfile(profile);
          setIsAuthenticated(true);
        } else {
          setIsAuthenticated(false);
        }
      } else {
        setIsAuthenticated(false);
      }
    } catch (e: any) {
      console.error("Errore inizializzazione:", e);
      if (e.message && e.message.includes('recursion')) {
        setError("Errore ricorsione database. Per favore esegui lo script SQL aggiornato.");
      }
    } finally {
      setIsLoadingAuth(false);
    }
  };

  useEffect(() => {
    if (isAuthenticated && familyProfile?.id) {
      const loadAllData = async () => {
        setIsLoadingData(true);
        try {
          const [exp, inc, sto, cat, shop] = await Promise.all([
            SupabaseService.fetchExpenses(familyProfile.id),
            SupabaseService.fetchIncomes(familyProfile.id),
            SupabaseService.fetchStores(familyProfile.id),
            SupabaseService.fetchCategories(familyProfile.id),
            SupabaseService.fetchShoppingList(familyProfile.id)
          ]);
          setExpenses(exp || []);
          setIncomes(inc || []);
          setShoppingItems(shop || []);
          if (sto && sto.length > 0) setStores(sto);
          if (cat && cat.length > 0) setCategories(cat);
        } catch (e: any) { 
          console.error("Errore caricamento dati:", e);
        } finally {
          setIsLoadingData(false);
        }
      };
      loadAllData();
    }
  }, [isAuthenticated, familyProfile?.id]);

  const handleSetupComplete = async (profile: FamilyProfile) => {
    if (!session?.user) return;
    setIsLoadingData(true);
    try {
      await SupabaseService.createFamilyProfile(profile);
      const name = session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'Utente';
      await SupabaseService.joinFamily(session.user.id, profile.id, name, true);
      setFamilyProfile(profile);
      setIsAuthenticated(true);
    } catch (e: any) {
      alert(`Errore: ${e.message}`);
    } finally {
      setIsLoadingData(false);
    }
  };

  const handleLogout = async () => {
    await SupabaseService.signOut();
    setIsAuthenticated(false);
    setFamilyProfile(null);
    setExpenses([]);
    setIncomes([]);
    setShoppingItems([]);
    setIsMenuOpen(false);
    setError(null);
  };

  const handleAddExpense = async (product: string, quantity: number, unitPrice: number, total: number, store: string) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const category = await categorizeExpense(product, store);
      const newExpense: Expense = { 
        id: crypto.randomUUID(), 
        product, 
        quantity, 
        unitPrice, 
        total, 
        store, 
        date: new Date().toISOString(), 
        category, 
        memberId: session?.user?.id 
      };
      setExpenses(prev => [newExpense, ...prev]);
      await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
    } catch (e: any) {
      console.error("Errore salvataggio spesa:", e);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleScanComplete = async (data: ReceiptData) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const newExpenses: Expense[] = [];
      for (const item of data.items) {
        const newExpense: Expense = {
          id: crypto.randomUUID(),
          product: item.product,
          quantity: item.quantity,
          unitPrice: item.unitPrice,
          total: item.total,
          store: data.store || 'Sconosciuto',
          date: data.date ? new Date(data.date).toISOString() : new Date().toISOString(),
          category: item.category || 'Alimentari',
          memberId: session?.user?.id
        };
        await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
        newExpenses.push(newExpense);
      }
      setExpenses(prev => [...newExpenses, ...prev]);
      if (data.store && !stores.some(s => s.name.toLowerCase() === data.store.toLowerCase())) {
        const newStore = { id: crypto.randomUUID(), name: data.store };
        await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
        setStores(prev => [...prev, newStore]);
      }
    } catch (err) {
      console.error("Errore durante il salvataggio dello scontrino:", err);
      alert("Errore nel caricamento dei prodotti. Verifica la connessione.");
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleAddShoppingItem = async (product: string, store: string) => {
    if (!familyProfile) return;
    const newItem: ShoppingItem = { id: crypto.randomUUID(), product, store, completed: false };
    setShoppingItems(prev => [newItem, ...prev]);
    await SupabaseService.addShoppingItemToSupabase(familyProfile.id, newItem);
  };

  const handleToggleShoppingItem = async (id: string) => {
    const item = shoppingItems.find(i => i.id === id);
    if (!item) return;
    const updated = { ...item, completed: !item.completed };
    setShoppingItems(prev => prev.map(i => i.id === id ? updated : i));
    await SupabaseService.updateShoppingItemInSupabase(updated);
  };

  const handleDeleteShoppingItem = async (id: string) => {
    setShoppingItems(prev => prev.filter(i => i.id !== id));
    await SupabaseService.deleteShoppingItemFromSupabase(id);
  };

  const handleAddIncome = async (source: string, amount: number, date: string) => {
    if (!familyProfile) return;
    try {
      const newIncome: Income = { id: crypto.randomUUID(), source, amount, date };
      setIncomes(prev => [newIncome, ...prev]);
      await SupabaseService.addIncomeToSupabase(familyProfile.id, newIncome);
    } catch (e) {
      console.error("Errore salvataggio entrata:", e);
    }
  };

  const MenuButton = ({ view, icon, label, badge }: { view: View, icon: any, label: string, badge?: number }) => (
    <button 
      onClick={() => { setCurrentView(view); setIsMenuOpen(false); }} 
      className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl transition-colors ${currentView === view ? 'bg-emerald-100 text-emerald-800 font-bold' : 'text-gray-700 hover:bg-gray-100'}`}
    >
      <div className="relative">
        {React.cloneElement(icon, { className: 'w-6 h-6' })}
        {badge ? (
            <span className="absolute -top-2 -right-2 bg-orange-500 text-white text-[10px] font-bold w-4 h-4 rounded-full flex items-center justify-center border-2 border-white">
                {badge}
            </span>
        ) : null}
      </div>
      <span className="text-lg">{label}</span>
      {currentView === view && <ChevronRight className="w-5 h-5 ml-auto text-emerald-600" />}
    </button>
  );

  if (isLoadingAuth) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50">
        <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
        <p className="mt-4 text-gray-500 font-medium">Verifica profilo...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 p-6">
        <div className="bg-white p-8 rounded-3xl shadow-xl max-w-md w-full border border-red-100 text-center">
          <Database className="w-12 h-12 text-red-500 mx-auto mb-4" />
          <h2 className="text-xl font-bold text-gray-800 mb-2">Problema Database</h2>
          <p className="text-gray-600 text-sm mb-6">{error}</p>
          <div className="space-y-3">
            <button onClick={() => window.location.reload()} className="w-full bg-emerald-600 text-white font-bold py-3 rounded-xl shadow-md">Ricarica App</button>
            <button onClick={handleLogout} className="w-full bg-gray-100 text-gray-700 font-bold py-3 rounded-xl">Disconnetti</button>
          </div>
        </div>
      </div>
    );
  }

  if (!session) return <LoginScreen onSetupComplete={handleSetupComplete} />;

  if (!isAuthenticated && !isLoadingData) {
    return <LoginScreen onSetupComplete={handleSetupComplete} isSupabaseAuth={true} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans pb-24 safe-area-top">
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMenuOpen(true)} className="p-2 -ml-2 text-gray-700 hover:bg-gray-100 rounded-xl">
                <Menu className="w-6 h-6" />
             </button>
             <div className="flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('dashboard')}>
                <WalletCards className="w-6 h-6 text-emerald-600" />
                <h1 className="font-bold text-base text-gray-800 truncate max-w-[150px]">
                  {familyProfile?.familyName || 'Spese Famiglia'}
                </h1>
             </div>
          </div>
          <button onClick={() => setCurrentView('profile')} className="bg-gray-100 p-1 rounded-full border border-gray-200">
             {session?.user?.user_metadata?.avatar_url ? (
               <img src={session.user.user_metadata.avatar_url} className="w-7 h-7 rounded-full" alt="User" />
             ) : (
               <User className="w-4 h-4 text-gray-500 m-1" />
             )}
          </button>
        </div>
      </header>

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex">
           <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsMenuOpen(false)}></div>
           <div className="relative w-[85%] max-w-xs bg-white h-full shadow-2xl flex flex-col animate-in slide-in-from-left duration-200">
              <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                 <div>
                   <h2 className="font-bold text-xl text-gray-800">Menù</h2>
                   <span className="text-xs text-emerald-600 font-medium flex items-center gap-1 mt-1"><Cloud className="w-3 h-3" /> Cloud Sync Attivo</span>
                 </div>
                 <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-gray-200 rounded-full"><X className="w-6 h-6 text-gray-500" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-1">
                 <MenuButton view="dashboard" icon={<Home />} label="Home" />
                 <MenuButton view="shopping" icon={<ShoppingCart />} label="Lista Spesa" badge={activeShoppingCount} />
                 <MenuButton view="offers" icon={<Percent />} label="Caccia Offerte" />
                 <div className="my-2 border-t border-gray-100"></div>
                 <MenuButton view="budget" icon={<Coins />} label="Bilancio & Guadagni" />
                 <MenuButton view="history" icon={<History />} label="Storico Transazioni" />
                 <div className="my-2 border-t border-gray-100"></div>
                 <MenuButton view="profile" icon={<Users />} label="Profilo Famiglia" />
                 <MenuButton view="categories" icon={<Tag />} label="Gestisci Categorie" />
                 <button onClick={handleLogout} className="w-full flex items-center gap-4 px-5 py-4 rounded-xl text-red-600 hover:bg-red-50 mt-4 font-bold transition-colors">
                   <LogOut className="w-6 h-6" /> Esci dall'App
                 </button>
              </div>
           </div>
        </div>
      )}

      <main className="max-w-2xl mx-auto px-4 py-6">
        {isLoadingData ? (
          <div className="flex flex-col items-center justify-center py-20">
            <Loader2 className="w-12 h-12 text-emerald-500 animate-spin mb-4" />
            <p className="text-gray-500 font-medium">Sincronizzazione dati...</p>
          </div>
        ) : (
          <div className="animate-in fade-in duration-300">
            {currentView === 'dashboard' && (
                <div className="space-y-6">
                    <ReceiptScanner onScanComplete={handleScanComplete} />

                    <ExpenseForm 
                      stores={stores} 
                      members={[]} 
                      existingProducts={existingProducts} 
                      productHistory={productHistory} 
                      onAddExpense={handleAddExpense} 
                      isAnalyzing={isAIProcessing} 
                    />

                    <StoreManager onAddStore={(name) => SupabaseService.addStoreToSupabase(familyProfile!.id, {id: crypto.randomUUID(), name}).then(() => setStores(prev => [...prev, {id: crypto.randomUUID(), name}]))} />
                </div>
            )}

            {currentView === 'shopping' && (
                <ShoppingListManager 
                    items={shoppingItems} 
                    stores={stores} 
                    productHistory={productHistory} 
                    onAddItem={handleAddShoppingItem} 
                    onToggleItem={handleToggleShoppingItem} 
                    onDeleteItem={handleDeleteShoppingItem} 
                />
            )}

            {currentView === 'offers' && (
                <OffersFinder 
                    stores={stores}
                    savedCity={offerPrefs.city}
                    savedStores={offerPrefs.selectedStores}
                    notificationsEnabled={offerPrefs.hasEnabledNotifications}
                    onPreferencesChange={(city, selectedStores, hasEnabledNotifications) => {
                        setOfferPrefs({ ...offerPrefs, city, selectedStores, hasEnabledNotifications });
                    }}
                />
            )}

            {currentView === 'history' && (
              <ExpenseList 
                expenses={expenses} 
                stores={stores} 
                categories={categories} 
                onDelete={(id) => SupabaseService.deleteExpenseFromSupabase(id).then(() => setExpenses(prev => prev.filter(e => e.id !== id)))} 
                onEdit={(updated) => {
                  setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e));
                }} 
              />
            )}

            {currentView === 'budget' && (
              <IncomeManager 
                incomes={incomes} 
                expenses={expenses} 
                onAddIncome={handleAddIncome} 
                onDeleteIncome={(id) => SupabaseService.deleteIncomeFromSupabase(id).then(() => setIncomes(prev => prev.filter(i => i.id !== id)))} 
              />
            )}

            {currentView === 'categories' && (
              <CategoryManager 
                categories={categories} 
                onUpdateCategories={(cats) => {setCategories(cats); SupabaseService.syncCategoriesToSupabase(familyProfile!.id, cats);}} 
              />
            )}

            {currentView === 'profile' && familyProfile && (
              <FamilyManager familyProfile={familyProfile} />
            )}
          </div>
        )}
      </main>
    </div>
  );
}

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, Income, CategoryDefinition, ShoppingItem, OfferPreferences, RecurringExpense } from './types';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { StoreManager } from './components/StoreManager';
import { LoginScreen } from './components/LoginScreen';
import { IncomeManager } from './components/IncomeManager';
import { CategoryManager } from './components/CategoryManager';
import { FamilyManager } from './components/FamilyManager';
import { ReceiptScanner } from './components/ReceiptScanner';
import { ShoppingListManager } from './components/ShoppingListManager';
import { OffersFinder } from './components/OffersFinder';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { ReceiptData } from './services/geminiService';
import { categorizeExpense } from './services/geminiService';
import { supabase } from './src/supabaseClient';
import * as SupabaseService from './services/supabaseService';
import { 
  WalletCards, LogOut, Menu, X, Home, History, ChevronRight, Coins, Tag, Cloud, User, Loader2, Users, Database, Sparkles, ShoppingCart, Percent, Repeat, BarChart3, Bell
} from 'lucide-react';

type View = 'dashboard' | 'shopping' | 'offers' | 'recurring' | 'analytics' | 'history' | 'budget' | 'categories' | 'profile';

function App() {
  const [session, setSession] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoadingAuth, setIsLoadingAuth] = useState(true);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [shoppingItems, setShoppingItems] = useState<ShoppingItem[]>([]);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);
  const [categories, setCategories] = useState<CategoryDefinition[]>(DEFAULT_CATEGORIES);
  const [offerPrefs, setOfferPrefs] = useState<OfferPreferences>({
    city: '',
    selectedStores: [],
    lastCheckDate: Date.now(),
    hasEnabledNotifications: false
  });

  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [isLoadingData, setIsLoadingData] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const existingProducts = useMemo(() => Object.keys(productHistory), [productHistory]);
  const activeShoppingCount = useMemo(() => shoppingItems.filter(i => !i.completed).length, [shoppingItems]);

  // Calcolo spese in scadenza
  const dueRecurring = useMemo(() => {
    const today = new Date();
    today.setHours(0,0,0,0);
    return recurringExpenses.filter(exp => {
      const dueDate = new Date(exp.nextDueDate);
      dueDate.setHours(0,0,0,0);
      const diffTime = dueDate.getTime() - today.getTime();
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      return diffDays <= exp.reminderDays;
    });
  }, [recurringExpenses]);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) checkUserFamily(session.user.id);
      else setIsLoadingAuth(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) {
        checkUserFamily(session.user.id);
      } else {
        setIsAuthenticated(false);
        setFamilyProfile(null);
        setIsLoadingAuth(false);
      }
    });
    return () => subscription.unsubscribe();
  }, []);

  const checkUserFamily = async (userId: string) => {
    try {
      const membership = await SupabaseService.getFamilyForUser(userId);
      if (membership) {
        const profile = await SupabaseService.getFamilyProfile(membership.familyId);
        if (profile) {
          setFamilyProfile(profile);
          setIsAuthenticated(true);
        } else {
          setIsAuthenticated(false);
        }
      } else {
        setIsAuthenticated(false);
      }
    } catch (e: any) {
      console.error("Errore inizializzazione:", e);
      setError("Errore sincronizzazione profilo. Riprova più tardi.");
    } finally {
      setIsLoadingAuth(false);
    }
  };

  useEffect(() => {
    if (isAuthenticated && familyProfile?.id) {
      const loadAllData = async () => {
        setIsLoadingData(true);
        try {
          const [exp, inc, sto, cat, shop, rec] = await Promise.all([
            SupabaseService.fetchExpenses(familyProfile.id),
            SupabaseService.fetchIncomes(familyProfile.id),
            SupabaseService.fetchStores(familyProfile.id),
            SupabaseService.fetchCategories(familyProfile.id),
            SupabaseService.fetchShoppingList(familyProfile.id),
            SupabaseService.fetchRecurring(familyProfile.id)
          ]);
          setExpenses(exp || []);
          setIncomes(inc || []);
          setShoppingItems(shop || []);
          setRecurringExpenses(rec || []);
          if (sto && sto.length > 0) setStores(sto);
          if (cat && cat.length > 0) setCategories(cat);
        } catch (e: any) { 
          console.error("Errore caricamento dati:", e);
        } finally {
          setIsLoadingData(false);
        }
      };
      loadAllData();
    }
  }, [isAuthenticated, familyProfile?.id]);

  const handleSetupComplete = async (profile: FamilyProfile) => {
    if (!session?.user) return;
    setIsLoadingData(true);
    try {
      await SupabaseService.createFamilyProfile(profile);
      const name = session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'Utente';
      await SupabaseService.joinFamily(session.user.id, profile.id, name, true);
      setFamilyProfile(profile);
      setIsAuthenticated(true);
    } catch (e: any) {
      alert(`Errore: ${e.message}`);
    } finally {
      setIsLoadingData(false);
    }
  };

  const handleLogout = async () => {
    await SupabaseService.signOut();
    setIsAuthenticated(false);
    setFamilyProfile(null);
    setExpenses([]);
    setIncomes([]);
    setShoppingItems([]);
    setRecurringExpenses([]);
    setIsMenuOpen(false);
    setError(null);
  };

  const handleAddExpense = async (product: string, quantity: number, unitPrice: number, total: number, store: string) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const category = await categorizeExpense(product, store);
      const newExpense: Expense = { 
        id: crypto.randomUUID(), 
        product, 
        quantity, 
        unitPrice, 
        total, 
        store, 
        date: new Date().toISOString(), 
        category, 
        memberId: session?.user?.id 
      };
      setExpenses(prev => [newExpense, ...prev]);
      await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
    } catch (e: any) {
      console.error("Errore salvataggio spesa:", e);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleScanComplete = async (data: ReceiptData) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const newExpenses: Expense[] = [];
      for (const item of data.items) {
        const newExpense: Expense = {
          id: crypto.randomUUID(),
          product: item.product,
          quantity: item.quantity,
          unitPrice: item.unitPrice,
          total: item.total,
          store: data.store || 'Sconosciuto',
          date: data.date ? new Date(data.date).toISOString() : new Date().toISOString(),
          category: item.category || 'Alimentari',
          memberId: session?.user?.id
        };
        await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
        newExpenses.push(newExpense);
      }
      setExpenses(prev => [...newExpenses, ...prev]);
      if (data.store && !stores.some(s => s.name.toLowerCase() === data.store.toLowerCase())) {
        const newStore = { id: crypto.randomUUID(), name: data.store };
        await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
        setStores(prev => [...prev, newStore]);
      }
    } catch (err) {
      console.error("Errore scansione:", err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleAddRecurring = async (product: string, amount: number, store: string, frequency: any, nextDate: string, reminderDays: number) => {
    if (!familyProfile) return;
    const newItem: RecurringExpense = { id: crypto.randomUUID(), product, amount, store, frequency, nextDueDate: nextDate, reminderDays };
    setRecurringExpenses(prev => [...prev, newItem]);
    await SupabaseService.addRecurringToSupabase(familyProfile.id, newItem);
  };

  const handleProcessRecurring = async (rec: RecurringExpense) => {
    // Trasforma la ricorrente in una spesa effettiva
    await handleAddExpense(rec.product, 1, rec.amount, rec.amount, rec.store);
    // Aggiorna la prossima data in base alla frequenza (semplificato)
    const next = new Date(rec.nextDueDate);
    if (rec.frequency === 'mensile') next.setMonth(next.getMonth() + 1);
    else if (rec.frequency === 'settimanale') next.setDate(next.getDate() + 7);
    else if (rec.frequency === 'annuale') next.setFullYear(next.getFullYear() + 1);

    const updated = { ...rec, nextDueDate: next.toISOString().split('T')[0] };
    setRecurringExpenses(prev => prev.map(r => r.id === rec.id ? updated : r));
    // Qui andrebbe un update su Supabase (opzionale per MVP)
  };

  const MenuButton = ({ view, icon, label, badge, colorClass = "" }: { view: View, icon: any, label: string, badge?: number, colorClass?: string }) => (
    <button 
      onClick={() => { setCurrentView(view); setIsMenuOpen(false); }} 
      className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl transition-all ${currentView === view ? 'bg-emerald-100 text-emerald-800 font-bold scale-[1.02]' : 'text-gray-700 hover:bg-gray-100'}`}
    >
      <div className={`relative ${colorClass}`}>
        {React.cloneElement(icon, { className: 'w-6 h-6' })}
        {badge ? (
            <span className="absolute -top-2 -right-2 bg-orange-500 text-white text-[10px] font-bold w-4 h-4 rounded-full flex items-center justify-center border-2 border-white">
                {badge}
            </span>
        ) : null}
      </div>
      <span className="text-lg">{label}</span>
      {currentView === view && <ChevronRight className="w-5 h-5 ml-auto text-emerald-600" />}
    </button>
  );

  if (isLoadingAuth) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50">
      <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
    </div>
  );

  if (!session) return <LoginScreen onSetupComplete={handleSetupComplete} />;
  if (!isAuthenticated && !isLoadingData) return <LoginScreen onSetupComplete={handleSetupComplete} isSupabaseAuth={true} />;

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans pb-24 safe-area-top">
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMenuOpen(true)} className="p-2 -ml-2 text-gray-700 hover:bg-gray-100 rounded-xl">
                <Menu className="w-6 h-6" />
             </button>
             <div className="flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('dashboard')}>
                <WalletCards className="w-6 h-6 text-emerald-600" />
                <h1 className="font-bold text-base text-gray-800 truncate max-w-[150px]">
                  {familyProfile?.familyName || 'Famiglia'}
                </h1>
             </div>
          </div>
          <div className="flex items-center gap-2">
            {dueRecurring.length > 0 && (
                <button onClick={() => setCurrentView('recurring')} className="p-2 text-orange-500 bg-orange-50 rounded-full animate-pulse">
                    <Bell className="w-5 h-5" />
                </button>
            )}
            <button onClick={() => setCurrentView('profile')} className="bg-gray-100 p-1 rounded-full border border-gray-200 overflow-hidden">
               {session?.user?.user_metadata?.avatar_url ? (
                 <img src={session.user.user_metadata.avatar_url} className="w-7 h-7" alt="User" />
               ) : ( <User className="w-5 h-5 text-gray-500 m-1" /> )}
            </button>
          </div>
        </div>
      </header>

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex">
           <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsMenuOpen(false)}></div>
           <div className="relative w-[85%] max-w-xs bg-white h-full shadow-2xl flex flex-col animate-in slide-in-from-left duration-200">
              <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                 <div>
                   <h2 className="font-bold text-xl text-gray-800">Menù</h2>
                   <span className="text-xs text-emerald-600 font-medium flex items-center gap-1 mt-1"><Cloud className="w-3 h-3" /> Sincronizzato</span>
                 </div>
                 <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-gray-200 rounded-full"><X className="w-6 h-6 text-gray-500" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-1">
                 <MenuButton view="dashboard" icon={<Home />} label="Dashboard" />
                 <MenuButton view="shopping" icon={<ShoppingCart />} label="Lista Spesa" badge={activeShoppingCount} colorClass="text-orange-500" />
                 <MenuButton view="offers" icon={<Percent />} label="Caccia Offerte" colorClass="text-red-500" />
                 <MenuButton view="recurring" icon={<Repeat />} label="Scadenze & Ricorrenti" badge={dueRecurring.length} colorClass="text-purple-600" />

                 <div className="my-2 border-t border-gray-100"></div>

                 <MenuButton view="analytics" icon={<BarChart3 />} label="Analisi & Report" colorClass="text-blue-600" />
                 <MenuButton view="budget" icon={<Coins />} label="Bilancio & Entrate" colorClass="text-emerald-600" />
                 <MenuButton view="history" icon={<History />} label="Storico Spese" />

                 <div className="my-2 border-t border-gray-100"></div>

                 <MenuButton view="profile" icon={<Users />} label="Membri Famiglia" />
                 <MenuButton view="categories" icon={<Tag />} label="Categorie Spesa" />

                 <button onClick={handleLogout} className="w-full flex items-center gap-4 px-5 py-4 rounded-xl text-red-600 hover:bg-red-50 mt-4 font-bold transition-colors">
                   <LogOut className="w-6 h-6" /> Esci
                 </button>
              </div>
           </div>
        </div>
      )}

      <main className="max-w-2xl mx-auto px-4 py-6">
        {isLoadingData ? (
          <div className="flex flex-col items-center justify-center py-20">
            <Loader2 className="w-12 h-12 text-emerald-500 animate-spin mb-4" />
          </div>
        ) : (
          <div className="animate-in fade-in duration-300">
            {currentView === 'dashboard' && (
                <div className="space-y-6">
                    <DueExpensesAlert dueExpenses={dueRecurring} onProcessExpense={handleProcessRecurring} />
                    <ReceiptScanner onScanComplete={handleScanComplete} />
                    <AIInsight expenses={expenses} />
                    <ExpenseForm 
                      stores={stores} 
                      members={[]} 
                      existingProducts={existingProducts} 
                      productHistory={productHistory} 
                      onAddExpense={handleAddExpense} 
                      isAnalyzing={isAIProcessing} 
                    />
                    <StoreManager onAddStore={(name) => SupabaseService.addStoreToSupabase(familyProfile!.id, {id: crypto.randomUUID(), name}).then(() => setStores(prev => [...prev, {id: crypto.randomUUID(), name}]))} />
                </div>
            )}

            {currentView === 'shopping' && (
                <ShoppingListManager items={shoppingItems} stores={stores} productHistory={productHistory} onAddItem={handleAddShoppingItem} onToggleItem={SupabaseService.updateShoppingItemInSupabase} onDeleteItem={SupabaseService.deleteShoppingItemFromSupabase} />
            )}

            {currentView === 'offers' && (
                <OffersFinder stores={stores} savedCity={offerPrefs.city} savedStores={offerPrefs.selectedStores} notificationsEnabled={offerPrefs.hasEnabledNotifications} onPreferencesChange={(city, selectedStores, hasEnabledNotifications) => setOfferPrefs({ ...offerPrefs, city, selectedStores, hasEnabledNotifications })} />
            )}

            {currentView === 'recurring' && (
                <RecurringManager recurringExpenses={recurringExpenses} stores={stores} onAddRecurring={handleAddRecurring} onDeleteRecurring={(id) => SupabaseService.deleteRecurringFromSupabase(id).then(() => setRecurringExpenses(prev => prev.filter(r => r.id !== id)))} />
            )}

            {currentView === 'analytics' && (
                <div className="space-y-6">
                    <Analytics expenses={expenses} />
                    <AIInsight expenses={expenses} />
                </div>
            )}

            {currentView === 'history' && (
              <ExpenseList expenses={expenses} stores={stores} categories={categories} onDelete={(id) => SupabaseService.deleteExpenseFromSupabase(id).then(() => setExpenses(prev => prev.filter(e => e.id !== id)))} onEdit={(updated) => setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e))} />
            )}

            {currentView === 'budget' && (
              <IncomeManager incomes={incomes} expenses={expenses} onAddIncome={handleAddIncome} onDeleteIncome={(id) => SupabaseService.deleteIncomeFromSupabase(id).then(() => setIncomes(prev => prev.filter(i => i.id !== id)))} />
            )}

            {currentView === 'categories' && (
              <CategoryManager categories={categories} onUpdateCategories={(cats) => {setCategories(cats); SupabaseService.syncCategoriesToSupabase(familyProfile!.id, cats);}} />
            )}

            {currentView === 'profile' && familyProfile && (
              <FamilyManager familyProfile={familyProfile} />
            )}
          </div>
        )}
      </main>
    </div>
  );
}

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, Income, CategoryDefinition, ShoppingItem, OfferPreferences, RecurringExpense } from './types';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { StoreManager } from './components/StoreManager';
import { LoginScreen } from './components/LoginScreen';
import { IncomeManager } from './components/IncomeManager';
import { CategoryManager } from './components/CategoryManager';
import { FamilyManager } from './components/FamilyManager';
import { ReceiptScanner } from './components/ReceiptScanner';
import { ShoppingListManager } from './components/ShoppingListManager';
import { OffersFinder } from './components/OffersFinder';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { ReceiptData } from './services/geminiService';
import { categorizeExpense } from './services/geminiService';
import { supabase } from './src/supabaseClient';
import * as SupabaseService from './services/supabaseService';
import { 
  WalletCards, LogOut, Menu, X, Home, History, ChevronRight, Coins, Tag, Cloud, User, Loader2, Users, Database, Sparkles, ShoppingCart, Percent, Repeat, BarChart3, Bell
} from 'lucide-react';

type View = 'dashboard' | 'shopping' | 'offers' | 'recurring' | 'analytics' | 'history' | 'budget' | 'categories' | 'profile';

function App() {
  const [session, setSession] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoadingAuth, setIsLoadingAuth] = useState(true);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [shoppingItems, setShoppingItems] = useState<ShoppingItem[]>([]);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);
  const [categories, setCategories] = useState<CategoryDefinition[]>(DEFAULT_CATEGORIES);
  const [offerPrefs, setOfferPrefs] = useState<OfferPreferences>({
    city: '',
    selectedStores: [],
    lastCheckDate: Date.now(),
    hasEnabledNotifications: false
  });

  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [isLoadingData, setIsLoadingData] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const existingProducts = useMemo(() => Object.keys(productHistory), [productHistory]);
  const activeShoppingCount = useMemo(() => shoppingItems.filter(i => !i.completed).length, [shoppingItems]);

  // Calcolo spese in scadenza
  const dueRecurring = useMemo(() => {
    const today = new Date();
    today.setHours(0,0,0,0);
    return recurringExpenses.filter(exp => {
      const dueDate = new Date(exp.nextDueDate);
      dueDate.setHours(0,0,0,0);
      const diffTime = dueDate.getTime() - today.getTime();
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      return diffDays <= exp.reminderDays;
    });
  }, [recurringExpenses]);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) checkUserFamily(session.user.id);
      else setIsLoadingAuth(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) {
        checkUserFamily(session.user.id);
      } else {
        setIsAuthenticated(false);
        setFamilyProfile(null);
        setIsLoadingAuth(false);
      }
    });
    return () => subscription.unsubscribe();
  }, []);

  const checkUserFamily = async (userId: string) => {
    try {
      const membership = await SupabaseService.getFamilyForUser(userId);
      if (membership) {
        const profile = await SupabaseService.getFamilyProfile(membership.familyId);
        if (profile) {
          setFamilyProfile(profile);
          setIsAuthenticated(true);
        } else {
          setIsAuthenticated(false);
        }
      } else {
        setIsAuthenticated(false);
      }
    } catch (e: any) {
      console.error("Errore inizializzazione:", e);
      setError("Errore sincronizzazione profilo. Riprova più tardi.");
    } finally {
      setIsLoadingAuth(false);
    }
  };

  useEffect(() => {
    if (isAuthenticated && familyProfile?.id) {
      const loadAllData = async () => {
        setIsLoadingData(true);
        try {
          const [exp, inc, sto, cat, shop, rec] = await Promise.all([
            SupabaseService.fetchExpenses(familyProfile.id),
            SupabaseService.fetchIncomes(familyProfile.id),
            SupabaseService.fetchStores(familyProfile.id),
            SupabaseService.fetchCategories(familyProfile.id),
            SupabaseService.fetchShoppingList(familyProfile.id),
            SupabaseService.fetchRecurring(familyProfile.id)
          ]);
          setExpenses(exp || []);
          setIncomes(inc || []);
          setShoppingItems(shop || []);
          setRecurringExpenses(rec || []);
          if (sto && sto.length > 0) setStores(sto);
          if (cat && cat.length > 0) setCategories(cat);
        } catch (e: any) { 
          console.error("Errore caricamento dati:", e);
        } finally {
          setIsLoadingData(false);
        }
      };
      loadAllData();
    }
  }, [isAuthenticated, familyProfile?.id]);

  const handleSetupComplete = async (profile: FamilyProfile) => {
    if (!session?.user) return;
    setIsLoadingData(true);
    try {
      await SupabaseService.createFamilyProfile(profile);
      const name = session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'Utente';
      await SupabaseService.joinFamily(session.user.id, profile.id, name, true);
      setFamilyProfile(profile);
      setIsAuthenticated(true);
    } catch (e: any) {
      alert(`Errore: ${e.message}`);
    } finally {
      setIsLoadingData(false);
    }
  };

  const handleLogout = async () => {
    await SupabaseService.signOut();
    setIsAuthenticated(false);
    setFamilyProfile(null);
    setExpenses([]);
    setIncomes([]);
    setShoppingItems([]);
    setRecurringExpenses([]);
    setIsMenuOpen(false);
    setError(null);
  };

  const handleAddExpense = async (product: string, quantity: number, unitPrice: number, total: number, store: string) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const category = await categorizeExpense(product, store);
      const newExpense: Expense = { 
        id: crypto.randomUUID(), 
        product, 
        quantity, 
        unitPrice, 
        total, 
        store, 
        date: new Date().toISOString(), 
        category, 
        memberId: session?.user?.id 
      };
      setExpenses(prev => [newExpense, ...prev]);
      await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
    } catch (e: any) {
      console.error("Errore salvataggio spesa:", e);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleScanComplete = async (data: ReceiptData) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const newExpenses: Expense[] = [];
      for (const item of data.items) {
        const newExpense: Expense = {
          id: crypto.randomUUID(),
          product: item.product,
          quantity: item.quantity,
          unitPrice: item.unitPrice,
          total: item.total,
          store: data.store || 'Sconosciuto',
          date: data.date ? new Date(data.date).toISOString() : new Date().toISOString(),
          category: item.category || 'Alimentari',
          memberId: session?.user?.id
        };
        await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
        newExpenses.push(newExpense);
      }
      setExpenses(prev => [...newExpenses, ...prev]);
      if (data.store && !stores.some(s => s.name.toLowerCase() === data.store.toLowerCase())) {
        const newStore = { id: crypto.randomUUID(), name: data.store };
        await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
        setStores(prev => [...prev, newStore]);
      }
    } catch (err) {
      console.error("Errore scansione:", err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  // Fix: Added missing handleAddShoppingItem to handle adding products to the shopping list.
  const handleAddShoppingItem = async (product: string, store: string) => {
    if (!familyProfile) return;
    const newItem: ShoppingItem = { 
      id: crypto.randomUUID(), 
      product, 
      store, 
      completed: false 
    };
    setShoppingItems(prev => [newItem, ...prev]);
    await SupabaseService.addShoppingItemToSupabase(familyProfile.id, newItem);
  };

  // Fix: Added missing handleAddIncome to handle recording new income entries.
  const handleAddIncome = async (source: string, amount: number, date: string) => {
    if (!familyProfile) return;
    const newIncome: Income = { 
      id: crypto.randomUUID(), 
      source, 
      amount, 
      date 
    };
    setIncomes(prev => [newIncome, ...prev]);
    await SupabaseService.addIncomeToSupabase(familyProfile.id, newIncome);
  };

  const handleAddRecurring = async (product: string, amount: number, store: string, frequency: any, nextDate: string, reminderDays: number) => {
    if (!familyProfile) return;
    const newItem: RecurringExpense = { id: crypto.randomUUID(), product, amount, store, frequency, nextDueDate: nextDate, reminderDays };
    setRecurringExpenses(prev => [...prev, newItem]);
    await SupabaseService.addRecurringToSupabase(familyProfile.id, newItem);
  };

  const handleProcessRecurring = async (rec: RecurringExpense) => {
    // Trasforma la ricorrente in una spesa effettiva
    await handleAddExpense(rec.product, 1, rec.amount, rec.amount, rec.store);
    // Aggiorna la prossima data in base alla frequenza (semplificato)
    const next = new Date(rec.nextDueDate);
    if (rec.frequency === 'mensile') next.setMonth(next.getMonth() + 1);
    else if (rec.frequency === 'settimanale') next.setDate(next.getDate() + 7);
    else if (rec.frequency === 'annuale') next.setFullYear(next.getFullYear() + 1);

    const updated = { ...rec, nextDueDate: next.toISOString().split('T')[0] };
    setRecurringExpenses(prev => prev.map(r => r.id === rec.id ? updated : r));
    // Qui andrebbe un update su Supabase (opzionale per MVP)
  };

  const MenuButton = ({ view, icon, label, badge, colorClass = "" }: { view: View, icon: any, label: string, badge?: number, colorClass?: string }) => (
    <button 
      onClick={() => { setCurrentView(view); setIsMenuOpen(false); }} 
      className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl transition-all ${currentView === view ? 'bg-emerald-100 text-emerald-800 font-bold scale-[1.02]' : 'text-gray-700 hover:bg-gray-100'}`}
    >
      <div className={`relative ${colorClass}`}>
        {React.cloneElement(icon, { className: 'w-6 h-6' })}
        {badge ? (
            <span className="absolute -top-2 -right-2 bg-orange-500 text-white text-[10px] font-bold w-4 h-4 rounded-full flex items-center justify-center border-2 border-white">
                {badge}
            </span>
        ) : null}
      </div>
      <span className="text-lg">{label}</span>
      {currentView === view && <ChevronRight className="w-5 h-5 ml-auto text-emerald-600" />}
    </button>
  );

  if (isLoadingAuth) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50">
      <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
    </div>
  );

  if (!session) return <LoginScreen onSetupComplete={handleSetupComplete} />;
  if (!isAuthenticated && !isLoadingData) return <LoginScreen onSetupComplete={handleSetupComplete} isSupabaseAuth={true} />;

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans pb-24 safe-area-top">
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMenuOpen(true)} className="p-2 -ml-2 text-gray-700 hover:bg-gray-100 rounded-xl">
                <Menu className="w-6 h-6" />
             </button>
             <div className="flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('dashboard')}>
                <WalletCards className="w-6 h-6 text-emerald-600" />
                <h1 className="font-bold text-base text-gray-800 truncate max-w-[150px]">
                  {familyProfile?.familyName || 'Famiglia'}
                </h1>
             </div>
          </div>
          <div className="flex items-center gap-2">
            {dueRecurring.length > 0 && (
                <button onClick={() => setCurrentView('recurring')} className="p-2 text-orange-500 bg-orange-50 rounded-full animate-pulse">
                    <Bell className="w-5 h-5" />
                </button>
            )}
            <button onClick={() => setCurrentView('profile')} className="bg-gray-100 p-1 rounded-full border border-gray-200 overflow-hidden">
               {session?.user?.user_metadata?.avatar_url ? (
                 <img src={session.user.user_metadata.avatar_url} className="w-7 h-7" alt="User" />
               ) : ( <User className="w-5 h-5 text-gray-500 m-1" /> )}
            </button>
          </div>
        </div>
      </header>

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex">
           <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsMenuOpen(false)}></div>
           <div className="relative w-[85%] max-w-xs bg-white h-full shadow-2xl flex flex-col animate-in slide-in-from-left duration-200">
              <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                 <div>
                   <h2 className="font-bold text-xl text-gray-800">Menù</h2>
                   <span className="text-xs text-emerald-600 font-medium flex items-center gap-1 mt-1"><Cloud className="w-3 h-3" /> Sincronizzato</span>
                 </div>
                 <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-gray-200 rounded-full"><X className="w-6 h-6 text-gray-500" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-1">
                 <MenuButton view="dashboard" icon={<Home />} label="Dashboard" />
                 <MenuButton view="shopping" icon={<ShoppingCart />} label="Lista Spesa" badge={activeShoppingCount} colorClass="text-orange-500" />
                 <MenuButton view="offers" icon={<Percent />} label="Caccia Offerte" colorClass="text-red-500" />
                 <MenuButton view="recurring" icon={<Repeat />} label="Scadenze & Ricorrenti" badge={dueRecurring.length} colorClass="text-purple-600" />

                 <div className="my-2 border-t border-gray-100"></div>

                 <MenuButton view="analytics" icon={<BarChart3 />} label="Analisi & Report" colorClass="text-blue-600" />
                 <MenuButton view="budget" icon={<Coins />} label="Bilancio & Entrate" colorClass="text-emerald-600" />
                 <MenuButton view="history" icon={<History />} label="Storico Spese" />

                 <div className="my-2 border-t border-gray-100"></div>

                 <MenuButton view="profile" icon={<Users />} label="Membri Famiglia" />
                 <MenuButton view="categories" icon={<Tag />} label="Categorie Spesa" />

                 <button onClick={handleLogout} className="w-full flex items-center gap-4 px-5 py-4 rounded-xl text-red-600 hover:bg-red-50 mt-4 font-bold transition-colors">
                   <LogOut className="w-6 h-6" /> Esci
                 </button>
              </div>
           </div>
        </div>
      )}

      <main className="max-w-2xl mx-auto px-4 py-6">
        {isLoadingData ? (
          <div className="flex flex-col items-center justify-center py-20">
            <Loader2 className="w-12 h-12 text-emerald-500 animate-spin mb-4" />
          </div>
        ) : (
          <div className="animate-in fade-in duration-300">
            {currentView === 'dashboard' && (
                <div className="space-y-6">
                    <DueExpensesAlert dueExpenses={dueRecurring} onProcessExpense={handleProcessRecurring} />
                    <ReceiptScanner onScanComplete={handleScanComplete} />
                    <AIInsight expenses={expenses} />
                    <ExpenseForm 
                      stores={stores} 
                      members={[]} 
                      existingProducts={existingProducts} 
                      productHistory={productHistory} 
                      onAddExpense={handleAddExpense} 
                      isAnalyzing={isAIProcessing} 
                    />
                    <StoreManager onAddStore={(name) => SupabaseService.addStoreToSupabase(familyProfile!.id, {id: crypto.randomUUID(), name}).then(() => setStores(prev => [...prev, {id: crypto.randomUUID(), name}]))} />
                </div>
            )}

            {currentView === 'shopping' && (
                <ShoppingListManager items={shoppingItems} stores={stores} productHistory={productHistory} onAddItem={handleAddShoppingItem} onToggleItem={SupabaseService.updateShoppingItemInSupabase} onDeleteItem={SupabaseService.deleteShoppingItemFromSupabase} />
            )}

            {currentView === 'offers' && (
                <OffersFinder stores={stores} savedCity={offerPrefs.city} savedStores={offerPrefs.selectedStores} notificationsEnabled={offerPrefs.hasEnabledNotifications} onPreferencesChange={(city, selectedStores, hasEnabledNotifications) => setOfferPrefs({ ...offerPrefs, city, selectedStores, hasEnabledNotifications })} />
            )}

            {currentView === 'recurring' && (
                <RecurringManager recurringExpenses={recurringExpenses} stores={stores} onAddRecurring={handleAddRecurring} onDeleteRecurring={(id) => SupabaseService.deleteRecurringFromSupabase(id).then(() => setRecurringExpenses(prev => prev.filter(r => r.id !== id)))} />
            )}

            {currentView === 'analytics' && (
                <div className="space-y-6">
                    <Analytics expenses={expenses} />
                    <AIInsight expenses={expenses} />
                </div>
            )}

            {currentView === 'history' && (
              <ExpenseList expenses={expenses} stores={stores} categories={categories} onDelete={(id) => SupabaseService.deleteExpenseFromSupabase(id).then(() => setExpenses(prev => prev.filter(e => e.id !== id)))} onEdit={(updated) => setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e))} />
            )}

            {currentView === 'budget' && (
              <IncomeManager incomes={incomes} expenses={expenses} onAddIncome={handleAddIncome} onDeleteIncome={(id) => SupabaseService.deleteIncomeFromSupabase(id).then(() => setIncomes(prev => prev.filter(i => i.id !== id)))} />
            )}

            {currentView === 'categories' && (
              <CategoryManager categories={categories} onUpdateCategories={(cats) => {setCategories(cats); SupabaseService.syncCategoriesToSupabase(familyProfile!.id, cats);}} />
            )}

            {currentView === 'profile' && familyProfile && (
              <FamilyManager familyProfile={familyProfile} />
            )}
          </div>
        )}
      </main>
    </div>
  );
}

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, Income, CategoryDefinition, ShoppingItem, OfferPreferences, RecurringExpense, SyncData } from './types';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { StoreManager } from './components/StoreManager';
import { LoginScreen } from './components/LoginScreen';
import { IncomeManager } from './components/IncomeManager';
import { CategoryManager } from './components/CategoryManager';
import { FamilyManager } from './components/FamilyManager';
import { ReceiptScanner } from './components/ReceiptScanner';
import { ShoppingListManager } from './components/ShoppingListManager';
import { OffersFinder } from './components/OffersFinder';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { DataSync } from './components/DataSync';
import { ReceiptData } from './services/geminiService';
import { categorizeExpense } from './services/geminiService';
import { supabase } from './src/supabaseClient';
import * as SupabaseService from './services/supabaseService';
import { 
  WalletCards, LogOut, Menu, X, Home, History, ChevronRight, Coins, Tag, Cloud, User, Loader2, Users, Database, Sparkles, ShoppingCart, Percent, Repeat, BarChart3, Bell, Share2
} from 'lucide-react';

type View = 'dashboard' | 'shopping' | 'offers' | 'recurring' | 'analytics' | 'history' | 'budget' | 'categories' | 'profile';

function App() {
  const [session, setSession] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoadingAuth, setIsLoadingAuth] = useState(true);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [shoppingItems, setShoppingItems] = useState<ShoppingItem[]>([]);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);
  const [categories, setCategories] = useState<CategoryDefinition[]>(DEFAULT_CATEGORIES);
  const [offerPrefs, setOfferPrefs] = useState<OfferPreferences>({
    city: '',
    selectedStores: [],
    lastCheckDate: Date.now(),
    hasEnabledNotifications: false
  });

  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [isLoadingData, setIsLoadingData] = useState(false);
  const [isSyncModalOpen, setIsSyncModalOpen] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const existingProducts = useMemo(() => Object.keys(productHistory), [productHistory]);
  const activeShoppingCount = useMemo(() => shoppingItems.filter(i => !i.completed).length, [shoppingItems]);

  const dueRecurring = useMemo(() => {
    const today = new Date();
    today.setHours(0,0,0,0);
    return recurringExpenses.filter(exp => {
      const dueDate = new Date(exp.nextDueDate);
      dueDate.setHours(0,0,0,0);
      const diffTime = dueDate.getTime() - today.getTime();
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      return diffDays <= exp.reminderDays;
    });
  }, [recurringExpenses]);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) checkUserFamily(session.user.id);
      else setIsLoadingAuth(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) {
        checkUserFamily(session.user.id);
      } else {
        setIsAuthenticated(false);
        setFamilyProfile(null);
        setIsLoadingAuth(false);
      }
    });
    return () => subscription.unsubscribe();
  }, []);

  const checkUserFamily = async (userId: string) => {
    try {
      const membership = await SupabaseService.getFamilyForUser(userId);
      if (membership) {
        const profile = await SupabaseService.getFamilyProfile(membership.familyId);
        if (profile) {
          setFamilyProfile(profile);
          setIsAuthenticated(true);
        } else {
          setIsAuthenticated(false);
        }
      } else {
        setIsAuthenticated(false);
      }
    } catch (e: any) {
      console.error("Errore inizializzazione:", e);
      setError("Errore sincronizzazione profilo.");
    } finally {
      setIsLoadingAuth(false);
    }
  };

  useEffect(() => {
    if (isAuthenticated && familyProfile?.id) {
      const loadAllData = async () => {
        setIsLoadingData(true);
        try {
          const [exp, inc, sto, cat, shop, rec] = await Promise.all([
            SupabaseService.fetchExpenses(familyProfile.id),
            SupabaseService.fetchIncomes(familyProfile.id),
            SupabaseService.fetchStores(familyProfile.id),
            SupabaseService.fetchCategories(familyProfile.id),
            SupabaseService.fetchShoppingList(familyProfile.id),
            SupabaseService.fetchRecurring(familyProfile.id)
          ]);
          setExpenses(exp || []);
          setIncomes(inc || []);
          setShoppingItems(shop || []);
          setRecurringExpenses(rec || []);
          if (sto && sto.length > 0) setStores(sto);
          if (cat && cat.length > 0) setCategories(cat);
        } catch (e: any) { 
          console.error("Errore caricamento dati:", e);
        } finally {
          setIsLoadingData(false);
        }
      };
      loadAllData();
    }
  }, [isAuthenticated, familyProfile?.id]);

  const handleSetupComplete = async (profile: FamilyProfile) => {
    if (!session?.user) return;
    setIsLoadingData(true);
    try {
      await SupabaseService.createFamilyProfile(profile);
      const name = session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'Utente';
      await SupabaseService.joinFamily(session.user.id, profile.id, name, true);
      setFamilyProfile(profile);
      setIsAuthenticated(true);
    } catch (e: any) {
      alert(`Errore: ${e.message}`);
    } finally {
      setIsLoadingData(false);
    }
  };

  const handleLogout = async () => {
    await SupabaseService.signOut();
    setIsAuthenticated(false);
    setFamilyProfile(null);
    setExpenses([]);
    setIncomes([]);
    setShoppingItems([]);
    setRecurringExpenses([]);
    setIsMenuOpen(false);
    setError(null);
  };

  const handleAddExpense = async (product: string, quantity: number, unitPrice: number, total: number, store: string) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const category = await categorizeExpense(product, store);
      const newExpense: Expense = { 
        id: crypto.randomUUID(), 
        product, 
        quantity, 
        unitPrice, 
        total, 
        store, 
        date: new Date().toISOString(), 
        category, 
        memberId: session?.user?.id 
      };
      setExpenses(prev => [newExpense, ...prev]);
      await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
    } catch (e: any) {
      console.error("Errore salvataggio spesa:", e);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleScanComplete = async (data: ReceiptData) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const newExpenses: Expense[] = [];
      for (const item of data.items) {
        const newExpense: Expense = {
          id: crypto.randomUUID(),
          product: item.product,
          quantity: item.quantity,
          unitPrice: item.unitPrice,
          total: item.total,
          store: data.store || 'Sconosciuto',
          date: data.date ? new Date(data.date).toISOString() : new Date().toISOString(),
          category: item.category || 'Alimentari',
          memberId: session?.user?.id
        };
        await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
        newExpenses.push(newExpense);
      }
      setExpenses(prev => [...newExpenses, ...prev]);
      if (data.store && !stores.some(s => s.name.toLowerCase() === data.store.toLowerCase())) {
        const newStore = { id: crypto.randomUUID(), name: data.store };
        await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
        setStores(prev => [...prev, newStore]);
      }
    } catch (err) {
      console.error("Errore scansione:", err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleAddShoppingItem = async (product: string, store: string) => {
    if (!familyProfile) return;
    const newItem: ShoppingItem = { id: crypto.randomUUID(), product, store, completed: false };
    setShoppingItems(prev => [newItem, ...prev]);
    await SupabaseService.addShoppingItemToSupabase(familyProfile.id, newItem);
  };

  const handleAddIncome = async (source: string, amount: number, date: string) => {
    if (!familyProfile) return;
    const newIncome: Income = { id: crypto.randomUUID(), source, amount, date };
    setIncomes(prev => [newIncome, ...prev]);
    await SupabaseService.addIncomeToSupabase(familyProfile.id, newIncome);
  };

  const handleAddRecurring = async (product: string, amount: number, store: string, frequency: any, nextDate: string, reminderDays: number) => {
    if (!familyProfile) return;
    const newItem: RecurringExpense = { id: crypto.randomUUID(), product, amount, store, frequency, nextDueDate: nextDate, reminderDays };
    setRecurringExpenses(prev => [...prev, newItem]);
    await SupabaseService.addRecurringToSupabase(familyProfile.id, newItem);
  };

  const handleProcessRecurring = async (rec: RecurringExpense) => {
    await handleAddExpense(rec.product, 1, rec.amount, rec.amount, rec.store);
    const next = new Date(rec.nextDueDate);
    if (rec.frequency === 'mensile') next.setMonth(next.getMonth() + 1);
    else if (rec.frequency === 'settimanale') next.setDate(next.getDate() + 7);
    else if (rec.frequency === 'annuale') next.setFullYear(next.getFullYear() + 1);
    const updated = { ...rec, nextDueDate: next.toISOString().split('T')[0] };
    setRecurringExpenses(prev => prev.map(r => r.id === rec.id ? updated : r));
  };

  const handleImportData = (syncData: SyncData) => {
      setExpenses(syncData.expenses);
      setIncomes(syncData.incomes || []);
      setStores(syncData.stores);
      setRecurringExpenses(syncData.recurringExpenses);
      setShoppingItems(syncData.shoppingList);
      if (syncData.categories) setCategories(syncData.categories);
      alert("Dati importati con successo!");
  };

  const MenuButton = ({ view, icon, label, badge, colorClass = "" }: { view: View, icon: any, label: string, badge?: number, colorClass?: string }) => (
    <button 
      onClick={() => { setCurrentView(view); setIsMenuOpen(false); }} 
      className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl transition-all ${currentView === view ? 'bg-emerald-100 text-emerald-800 font-bold scale-[1.02]' : 'text-gray-700 hover:bg-gray-100'}`}
    >
      <div className={`relative ${colorClass}`}>
        {React.cloneElement(icon, { className: 'w-6 h-6' })}
        {badge ? (
            <span className="absolute -top-2 -right-2 bg-orange-500 text-white text-[10px] font-bold w-4 h-4 rounded-full flex items-center justify-center border-2 border-white">
                {badge}
            </span>
        ) : null}
      </div>
      <span className="text-lg">{label}</span>
      {currentView === view && <ChevronRight className="w-5 h-5 ml-auto text-emerald-600" />}
    </button>
  );

  if (isLoadingAuth) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50">
      <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
    </div>
  );

  if (!session) return <LoginScreen onSetupComplete={handleSetupComplete} />;
  if (!isAuthenticated && !isLoadingData) return <LoginScreen onSetupComplete={handleSetupComplete} isSupabaseAuth={true} />;

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans pb-24 safe-area-top">
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMenuOpen(true)} className="p-2 -ml-2 text-gray-700 hover:bg-gray-100 rounded-xl">
                <Menu className="w-6 h-6" />
             </button>
             <div className="flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('dashboard')}>
                <WalletCards className="w-6 h-6 text-emerald-600" />
                <h1 className="font-bold text-base text-gray-800 truncate max-w-[150px]">
                  {familyProfile?.familyName || 'Famiglia'}
                </h1>
             </div>
          </div>
          <div className="flex items-center gap-2">
            {dueRecurring.length > 0 && (
                <button onClick={() => setCurrentView('recurring')} className="p-2 text-orange-500 bg-orange-50 rounded-full animate-pulse">
                    <Bell className="w-5 h-5" />
                </button>
            )}
            <button onClick={() => setCurrentView('profile')} className="bg-gray-100 p-1 rounded-full border border-gray-200 overflow-hidden">
               {session?.user?.user_metadata?.avatar_url ? (
                 <img src={session.user.user_metadata.avatar_url} className="w-7 h-7" alt="User" />
               ) : ( <User className="w-5 h-5 text-gray-500 m-1" /> )}
            </button>
          </div>
        </div>
      </header>

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex">
           <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsMenuOpen(false)}></div>
           <div className="relative w-[85%] max-w-xs bg-white h-full shadow-2xl flex flex-col animate-in slide-in-from-left duration-200">
              <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                 <div>
                   <h2 className="font-bold text-xl text-gray-800">Menù</h2>
                   <span className="text-xs text-emerald-600 font-medium flex items-center gap-1 mt-1"><Cloud className="w-3 h-3" /> Sincronizzato</span>
                 </div>
                 <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-gray-200 rounded-full"><X className="w-6 h-6 text-gray-500" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-1">
                 <MenuButton view="dashboard" icon={<Home />} label="Dashboard" />
                 <MenuButton view="shopping" icon={<ShoppingCart />} label="Lista Spesa" badge={activeShoppingCount} colorClass="text-orange-500" />
                 <MenuButton view="offers" icon={<Percent />} label="Caccia Offerte" colorClass="text-red-500" />
                 <MenuButton view="recurring" icon={<Repeat />} label="Scadenze & Ricorrenti" badge={dueRecurring.length} colorClass="text-purple-600" />

                 <div className="my-2 border-t border-gray-100"></div>

                 <MenuButton view="analytics" icon={<BarChart3 />} label="Analisi & Report" colorClass="text-blue-600" />
                 <MenuButton view="budget" icon={<Coins />} label="Bilancio & Entrate" colorClass="text-emerald-600" />
                 <MenuButton view="history" icon={<History />} label="Storico Spese" />

                 <div className="my-2 border-t border-gray-100"></div>

                 <MenuButton view="profile" icon={<Users />} label="Membri Famiglia" />
                 <MenuButton view="categories" icon={<Tag />} label="Categorie Spesa" />

                 <button onClick={handleLogout} className="w-full flex items-center gap-4 px-5 py-4 rounded-xl text-red-600 hover:bg-red-50 mt-4 font-bold transition-colors">
                   <LogOut className="w-6 h-6" /> Esci
                 </button>
              </div>
           </div>
        </div>
      )}

      <main className="max-w-2xl mx-auto px-4 py-6">
        {isLoadingData ? (
          <div className="flex flex-col items-center justify-center py-20">
            <Loader2 className="w-12 h-12 text-emerald-500 animate-spin mb-4" />
          </div>
        ) : (
          <div className="animate-in fade-in duration-300">
            {currentView === 'dashboard' && (
                <div className="space-y-6">
                    <DueExpensesAlert dueExpenses={dueRecurring} onProcessExpense={handleProcessRecurring} />
                    <ReceiptScanner onScanComplete={handleScanComplete} />
                    <AIInsight expenses={expenses} />
                    <ExpenseForm 
                      stores={stores} 
                      members={[]} 
                      existingProducts={existingProducts} 
                      productHistory={productHistory} 
                      onAddExpense={handleAddExpense} 
                      isAnalyzing={isAIProcessing} 
                    />
                    <StoreManager onAddStore={(name) => SupabaseService.addStoreToSupabase(familyProfile!.id, {id: crypto.randomUUID(), name}).then(() => setStores(prev => [...prev, {id: crypto.randomUUID(), name}]))} />
                </div>
            )}

            {currentView === 'shopping' && (
                <ShoppingListManager items={shoppingItems} stores={stores} productHistory={productHistory} onAddItem={handleAddShoppingItem} onToggleItem={SupabaseService.updateShoppingItemInSupabase} onDeleteItem={SupabaseService.deleteShoppingItemFromSupabase} />
            )}

            {currentView === 'offers' && (
                <OffersFinder stores={stores} savedCity={offerPrefs.city} savedStores={offerPrefs.selectedStores} notificationsEnabled={offerPrefs.hasEnabledNotifications} onPreferencesChange={(city, selectedStores, hasEnabledNotifications) => setOfferPrefs({ ...offerPrefs, city, selectedStores, hasEnabledNotifications })} />
            )}

            {currentView === 'recurring' && (
                <RecurringManager recurringExpenses={recurringExpenses} stores={stores} onAddRecurring={handleAddRecurring} onDeleteRecurring={(id) => SupabaseService.deleteRecurringFromSupabase(id).then(() => setRecurringExpenses(prev => prev.filter(r => r.id !== id)))} />
            )}

            {currentView === 'analytics' && (
                <div className="space-y-6">
                    <Analytics expenses={expenses} />
                    <AIInsight expenses={expenses} />
                </div>
            )}

            {currentView === 'history' && (
              <ExpenseList expenses={expenses} stores={stores} categories={categories} onDelete={(id) => SupabaseService.deleteExpenseFromSupabase(id).then(() => setExpenses(prev => prev.filter(e => e.id !== id)))} onEdit={(updated) => setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e))} />
            )}

            {currentView === 'budget' && (
              <IncomeManager incomes={incomes} expenses={expenses} onAddIncome={handleAddIncome} onDeleteIncome={(id) => SupabaseService.deleteIncomeFromSupabase(id).then(() => setIncomes(prev => prev.filter(i => i.id !== id)))} />
            )}

            {currentView === 'categories' && (
              <CategoryManager categories={categories} onUpdateCategories={(cats) => {setCategories(cats); SupabaseService.syncCategoriesToSupabase(familyProfile!.id, cats);}} />
            )}

            {currentView === 'profile' && familyProfile && (
              <div className="space-y-6">
                <FamilyManager familyProfile={familyProfile} />
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                    <h3 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
                        <Share2 className="w-5 h-5 text-emerald-600" /> Backup & Sincronizzazione manuale
                    </h3>
                    <p className="text-sm text-gray-500 mb-4">Usa questa funzione per trasferire velocemente i dati tra dispositivi diversi tramite codice.</p>
                    <button 
                        onClick={() => setIsSyncModalOpen(true)}
                        className="w-full bg-emerald-50 text-emerald-700 font-bold py-3 rounded-xl border border-emerald-100 hover:bg-emerald-100 transition-all flex items-center justify-center gap-2"
                    >
                        Apri Gestione Sincronizzazione
                    </button>
                </div>
                {isSyncModalOpen && (
                    <DataSync 
                        data={{
                            expenses,
                            incomes,
                            stores,
                            recurringExpenses,
                            shoppingList: shoppingItems,
                            familyProfile,
                            categories
                        }}
                        onImport={handleImportData}
                        onClose={() => setIsSyncModalOpen(false)}
                    />
                )}
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
}

export default App;

import { supabase } from '../src/supabaseClient';
import { Expense, Income, Store, RecurringExpense, ShoppingItem, FamilyProfile, CategoryDefinition, Member } from '../types';

// --- AUTH ---
export const signInWithGoogle = async () => {
  let redirectUrl = window.location.origin;
  if (redirectUrl.endsWith('/')) {
    redirectUrl = redirectUrl.slice(0, -1);
  }

  const { error } = await supabase.auth.signInWithOAuth({
    provider: 'google',
    options: {
      redirectTo: redirectUrl,
    },
  });

  if (error) throw error;
};

export const signUpWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signUp({ email, password });
};

export const signInWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signInWithPassword({ email, password });
};

export const signOut = async () => {
  await supabase.auth.signOut();
};

export const getCurrentUser = async () => {
  const { data: { user } } = await supabase.auth.getUser();
  return user;
};

// --- FAMILY & MEMBERSHIP ---
export const getFamilyForUser = async (userId: string): Promise<{ familyId: string, isAdmin: boolean } | null> => {
  try {
    const { data, error } = await supabase
      .from('family_members')
      .select('family_id, is_admin')
      .eq('user_id', userId)
      .maybeSingle();

    if (error) {
      console.error("Errore query membership:", error.message);
      return null;
    }
    if (!data) return null;
    return { familyId: data.family_id, isAdmin: data.is_admin };
  } catch (err) {
    return null;
  }
};

export const fetchFamilyMembers = async (familyId: string): Promise<Member[]> => {
  const { data, error } = await supabase
    .from('family_members')
    .select('user_id, name, is_admin')
    .eq('family_id', familyId);

  if (error) return [];
  return data.map(m => ({
    id: m.user_id,
    name: m.name,
    color: 'bg-emerald-100 text-emerald-600',
    isAdmin: m.is_admin,
    userId: m.user_id
  }));
};

export const joinFamily = async (userId: string, familyId: string, name: string, isAdmin: boolean = false) => {
  const { error } = await supabase
    .from('family_members')
    .upsert({
      family_id: familyId,
      user_id: userId,
      name: name,
      is_admin: isAdmin
    });

  if (error) {
    throw error;
  }
};

export const getFamilyProfile = async (familyId: string): Promise<FamilyProfile | null> => {
  const { data, error } = await supabase
    .from('families')
    .select('*')
    .eq('id', familyId)
    .maybeSingle();

  if (error || !data) return null;

  return {
    id: data.id,
    familyName: data.family_name,
    members: data.members || [], 
    createdAt: new Date(data.created_at).getTime()
  };
};

export const createFamilyProfile = async (profile: FamilyProfile): Promise<void> => {
  const { error } = await supabase
    .from('families')
    .insert({
      id: profile.id,
      family_name: profile.familyName,
      members: profile.members
    });

  if (error && error.code !== '23505') {
    throw error;
  }
};

