import React, { useState, useMemo, useEffect } from 'react';
import { ShoppingItem, Store } from '../types';
import { ShoppingCart, Plus, Trash2, CheckSquare, Square, History, X, Store as StoreIcon, Filter, Sparkles } from 'lucide-react';

interface ShoppingListManagerProps {
  items: ShoppingItem[];
  stores: Store[];
  productHistory: Record<string, string>; // Map: Product Name -> Last Store Name
  onAddItem: (product: string, store: string) => void;
  onToggleItem: (id: string) => void;
  onDeleteItem: (id: string) => void;
}

export const ShoppingListManager: React.FC<ShoppingListManagerProps> = ({
  items,
  stores,
  productHistory,
  onAddItem,
  onToggleItem,
  onDeleteItem
}) => {
  const [isOpen, setIsOpen] = useState(true); 
  const [showHistoryModal, setShowHistoryModal] = useState(false);

  const [activeStoreFilter, setActiveStoreFilter] = useState<string>('');
  const [newItemProduct, setNewItemProduct] = useState('');
  const [newItemStore, setNewItemStore] = useState(stores[0]?.name || '');

  useEffect(() => {
    if (activeStoreFilter) {
        setNewItemStore(activeStoreFilter);
    }
  }, [activeStoreFilter]);

  const groupedItems = useMemo(() => {
    const groups: Record<string, ShoppingItem[]> = {};
    items.forEach(item => {
      if (!groups[item.store]) groups[item.store] = [];
      groups[item.store].push(item);
    });
    return groups;
  }, [items]);

  const displayedGroups = useMemo(() => {
      if (!activeStoreFilter) return groupedItems;
      const filtered: Record<string, ShoppingItem[]> = {};
      if (groupedItems[activeStoreFilter]) {
          filtered[activeStoreFilter] = groupedItems[activeStoreFilter];
      }
      return filtered;
  }, [groupedItems, activeStoreFilter]);

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (newItemProduct.trim() && newItemStore) {
      onAddItem(newItemProduct.trim(), newItemStore);
      setNewItemProduct('');
    }
  };

  const handleHistorySelect = (product: string, defaultStore: string) => {
    const targetStore = activeStoreFilter || defaultStore;
    // Evita duplicati se l'oggetto è già presente non completato
    if (!items.some(i => i.product.toLowerCase() === product.toLowerCase() && !i.completed)) {
        onAddItem(product, targetStore);
    }
    setShowHistoryModal(false);
  };

  const historyList = useMemo(() => {
    return Object.entries(productHistory).sort((a, b) => a[0].localeCompare(b[0]));
  }, [productHistory]);

  // Suggerimenti rapidi: primi 5 prodotti dello storico non presenti in lista
  const quickSuggestions = useMemo(() => {
    const inList = new Set(items.filter(i => !i.completed).map(i => i.product.toLowerCase()));
    return historyList
        .filter(([prod]) => !inList.has(prod.toLowerCase()))
        .slice(0, 6);
  }, [historyList, items]);

  const activeCount = items.filter(i => !i.completed).length;

  return (
    <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 mb-6">

      <div 
        className="flex justify-between items-center cursor-pointer select-none mb-5"
        onClick={() => setIsOpen(!isOpen)}
      >
        <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
          <ShoppingCart className="w-5 h-5 text-orange-500" />
          Lista della Spesa
          {activeCount > 0 && (
            <span className="bg-orange-100 text-orange-700 text-xs font-bold px-2.5 py-1 rounded-full">
              {activeCount} da prendere
            </span>
          )}
        </h3>
        <button className="text-orange-500 hover:text-orange-700 text-sm font-semibold py-1 px-2">
          {isOpen ? 'Chiudi' : 'Apri'}
        </button>
      </div>

      {isOpen && (
        <div className="animate-in fade-in slide-in-from-top-2 duration-200">

          <div className="mb-5 bg-orange-50 p-4 rounded-xl border border-orange-100">
              <label className="block text-xs font-bold text-orange-800 uppercase mb-3 flex items-center gap-1">
                  <Filter className="w-3.5 h-3.5" />
                  Visualizza prodotti per:
              </label>
              <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
                  <button
                      onClick={() => setActiveStoreFilter('')}
                      className={`whitespace-nowrap px-4 py-2.5 rounded-full text-sm font-semibold transition-colors border shadow-sm ${
                          activeStoreFilter === '' 
                          ? 'bg-orange-500 text-white border-orange-600' 
                          : 'bg-white text-gray-700 border-gray-200 hover:border-orange-300'
                      }`}
                  >
                      Tutti i Negozi
                  </button>
                  {stores.map(store => (
                      <button
                          key={store.id}
                          onClick={() => setActiveStoreFilter(store.name)}
                          className={`whitespace-nowrap px-4 py-2.5 rounded-full text-sm font-semibold transition-colors border shadow-sm ${
                              activeStoreFilter === store.name
                              ? 'bg-orange-500 text-white border-orange-600' 
                              : 'bg-white text-gray-700 border-gray-200 hover:border-orange-300'
                          }`}
                      >
                          {store.name}
                      </button>
                  ))}
              </div>
          </div>

          {/* Suggerimenti rapidi dallo storico */}
          {quickSuggestions.length > 0 && (
            <div className="mb-4">
              <div className="flex items-center gap-1.5 mb-2 px-1">
                <Sparkles className="w-3.5 h-3.5 text-orange-400" />
                <span className="text-xs font-bold text-gray-400 uppercase">Suggeriti dallo storico</span>
              </div>
              <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
                {quickSuggestions.map(([prod, store]) => (
                  <button
                    key={prod}
                    onClick={() => handleHistorySelect(prod, store)}
                    className="flex-shrink-0 bg-white border border-gray-200 hover:border-orange-300 hover:bg-orange-50 px-3 py-2 rounded-xl text-sm font-medium text-gray-700 transition-all flex items-center gap-1.5"
                  >
                    <Plus className="w-3.5 h-3.5 text-orange-400" />
                    {prod}
                  </button>
                ))}
              </div>
            </div>
          )}

          <form onSubmit={handleAdd} className="flex flex-col gap-3 mb-6">
            <div className="flex gap-2">
                <input
                    type="text"
                    value={newItemProduct}
                    onChange={(e) => setNewItemProduct(e.target.value)}
                    placeholder={activeStoreFilter ? `Cosa serve al ${activeStoreFilter}?` : "Cosa serve?"}
                    className="flex-1 rounded-xl border border-gray-300 bg-gray-50 p-3.5 text-base focus:border-orange-500 focus:ring-2 focus:ring-orange-200 outline-none transition-all shadow-sm"
                />
                <button
                    type="button"
                    onClick={() => setShowHistoryModal(true)}
                    className="bg-orange-100 text-orange-600 px-3.5 rounded-xl hover:bg-orange-200 transition-colors border border-orange-200"
                    title="Storico completo"
                >
                    <History className="w-6 h-6" />
                </button>
            </div>
            <div className="flex gap-2">
                <select
                    value={newItemStore}
                    onChange={(e) => setNewItemStore(e.target.value)}
                    className="flex-1 rounded-xl border border-gray-300 bg-gray-50 p-3.5 text-base focus:border-orange-500 focus:ring-2 focus:ring-orange-200 outline-none shadow-sm appearance-none"
                >
                    {stores.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                </select>
                <button
                    type="submit"
                    disabled={!newItemProduct.trim()}
                    className="bg-orange-500 text-white px-5 rounded-xl hover:bg-orange-600 transition-colors disabled:opacity-50 shadow-md active:scale-95"
                >
                    <Plus className="w-6 h-6" />
                </button>
            </div>
          </form>

          <div className="space-y-5">
            {Object.keys(displayedGroups).length === 0 && (
                <div className="text-center py-8 bg-gray-50 rounded-xl border border-dashed border-gray-200">
                    <p className="text-sm text-gray-500 italic">
                        {activeStoreFilter 
                            ? `Nessun prodotto in lista per ${activeStoreFilter}.` 
                            : "La lista della spesa è vuota."}
                    </p>
                </div>
            )}

            {Object.entries(displayedGroups).map(([storeName, storeItems]) => (
              <div key={storeName} className="bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden animate-in fade-in">
                <div className="bg-orange-50 px-4 py-2.5 text-sm font-bold text-orange-800 flex items-center gap-2 border-b border-orange-100">
                  <StoreIcon className="w-4 h-4" /> {storeName}
                </div>
                <div className="divide-y divide-gray-100">
                    {(storeItems as ShoppingItem[]).map(item => (
                        <div key={item.id} className="flex items-center justify-between p-4 hover:bg-gray-50 transition-colors active:bg-gray-100">
                            <div 
                                className="flex items-center gap-3 cursor-pointer flex-1"
                                onClick={() => onToggleItem(item.id)}
                            >
                                {item.completed ? (
                                    <CheckSquare className="w-6 h-6 text-gray-300 flex-shrink-0" />
                                ) : (
                                    <Square className="w-6 h-6 text-orange-500 flex-shrink-0" />
                                )}
                                <span className={`text-lg font-medium ${item.completed ? 'text-gray-400 line-through' : 'text-gray-800'}`}>
                                    {item.product}
                                </span>
                            </div>
                            <button 
                                onClick={() => onDeleteItem(item.id)}
                                className="text-gray-300 hover:text-red-500 p-2 -mr-2"
                            >
                                <Trash2 className="w-5 h-5" />
                            </button>
                        </div>
                    ))}
                </div>
              </div>
            ))}
          </div>

        </div>
      )}

      {showHistoryModal && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 animate-in fade-in backdrop-blur-sm">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm max-h-[85vh] flex flex-col">
                <div className="p-5 border-b border-gray-100 flex justify-between items-center">
                    <h3 className="font-bold text-lg text-gray-800">Storico Prodotti</h3>
                    <button onClick={() => setShowHistoryModal(false)} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200">
                        <X className="w-5 h-5 text-gray-600" />
                    </button>
                </div>
                <div className="p-2 overflow-y-auto flex-1">
                    <div className="space-y-1">
                        {historyList.map(([prod, lastStore]) => (
                            <button
                                key={prod}
                                onClick={() => handleHistorySelect(prod, lastStore)}
                                className="w-full text-left px-5 py-4 hover:bg-orange-50 rounded-xl flex justify-between items-center group border-b border-gray-50 last:border-0"
                            >
                                <span className="text-base font-medium text-gray-800">{prod}</span>
                                <span className="text-xs text-gray-400 bg-gray-100 px-2 py-1 rounded-md group-hover:bg-white">
                                    {activeStoreFilter ? '' : lastStore}
                                </span>
                            </button>
                        ))}
                        {historyList.length === 0 && (
                            <p className="text-center text-gray-500 py-8">Nessun acquisto registrato.</p>
                        )}
                    </div>
                </div>
            </div>
        </div>
      )}

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { RecurringExpense, Frequency, Store } from '../types';
import { Repeat, Plus, Trash2, CalendarClock, Bell, Pencil, Save, X as CloseIcon } from 'lucide-react';

interface RecurringManagerProps {
  recurringExpenses: RecurringExpense[];
  stores: Store[];
  onAddRecurring: (product: string, amount: number, store: string, frequency: Frequency, nextDate: string, reminderDays: number) => void;
  onUpdateRecurring: (updated: RecurringExpense) => void;
  onDeleteRecurring: (id: string) => void;
}

export const RecurringManager: React.FC<RecurringManagerProps> = ({ 
  recurringExpenses, 
  stores, 
  onAddRecurring, 
  onUpdateRecurring,
  onDeleteRecurring 
}) => {
  const [isOpen, setIsOpen] = useState(false);

  // State per editing
  const [editingId, setEditingId] = useState<string | null>(null);
  const [product, setProduct] = useState('');
  const [amount, setAmount] = useState('');
  const [store, setStore] = useState(stores[0]?.name || '');
  const [frequency, setFrequency] = useState<Frequency>('mensile');
  const [nextDate, setNextDate] = useState(new Date().toISOString().split('T')[0]);
  const [reminderDays, setReminderDays] = useState('0');

  useEffect(() => {
    if (!store && stores.length > 0) setStore(stores[0].name);
  }, [stores]);

  const handleEdit = (item: RecurringExpense) => {
    setEditingId(item.id);
    setProduct(item.product);
    setAmount(item.amount.toString());
    setStore(item.store);
    setFrequency(item.frequency);
    setNextDate(item.nextDueDate);
    setReminderDays(item.reminderDays.toString());
    if (!isOpen) setIsOpen(true);
    // Scroll al form
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const resetForm = () => {
    setEditingId(null);
    setProduct('');
    setAmount('');
    setFrequency('mensile');
    setNextDate(new Date().toISOString().split('T')[0]);
    setReminderDays('0');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!product || !amount || !store || !nextDate) return;

    if (editingId) {
        onUpdateRecurring({
            id: editingId,
            product,
            amount: parseFloat(amount),
            store,
            frequency,
            nextDueDate: nextDate,
            reminderDays: parseInt(reminderDays) || 0
        });
    } else {
        onAddRecurring(product, parseFloat(amount), store, frequency, nextDate, parseInt(reminderDays) || 0);
    }

    resetForm();
    if (!editingId) setIsOpen(false);
  };

  return (
    <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 mb-6">
      <div 
        className="flex justify-between items-center cursor-pointer select-none mb-1"
        onClick={() => setIsOpen(!isOpen)}
      >
        <h3 className="text-sm font-semibold text-gray-700 flex items-center gap-2">
          <Repeat className="w-4 h-4 text-purple-600" />
          Spese Ricorrenti & Abbonamenti
        </h3>
        <button className="text-purple-600 hover:text-purple-700 text-xs font-medium">
          {isOpen ? 'Chiudi' : 'Gestisci'}
        </button>
      </div>

      {isOpen && (
        <div className="mt-4 animate-in fade-in slide-in-from-top-2 duration-200">

          <div className="bg-purple-50 p-4 rounded-2xl border border-purple-100 mb-6">
            <h4 className="text-xs font-bold text-purple-800 uppercase mb-4 flex items-center gap-2">
                {editingId ? <Pencil className="w-3.5 h-3.5" /> : <Plus className="w-3.5 h-3.5" />}
                {editingId ? 'Modifica Ricorrenza' : 'Nuova Ricorrenza'}
            </h4>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Nome Servizio</label>
                <input
                  type="text"
                  placeholder="Es. Netflix, Affitto, Palestra"
                  value={product}
                  onChange={(e) => setProduct(e.target.value)}
                  className="w-full rounded-xl border border-gray-300 bg-white p-3 text-sm focus:border-purple-500 outline-none shadow-sm"
                  required
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                   <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Importo</label>
                   <input
                    type="number"
                    step="0.01"
                    placeholder="€"
                    value={amount}
                    onChange={(e) => setAmount(e.target.value)}
                    className="w-full rounded-xl border border-gray-300 bg-white p-3 text-sm focus:border-purple-500 outline-none shadow-sm"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Frequenza</label>
                  <select
                    value={frequency}
                    onChange={(e) => setFrequency(e.target.value as Frequency)}
                    className="w-full rounded-xl border border-gray-300 bg-white p-3 text-sm focus:border-purple-500 outline-none shadow-sm appearance-none"
                  >
                    <option value="settimanale">Settimanale</option>
                    <option value="mensile">Mensile</option>
                    <option value="annuale">Annuale</option>
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Negozio/Ente</label>
                  <select
                    value={store}
                    onChange={(e) => setStore(e.target.value)}
                    className="w-full rounded-xl border border-gray-300 bg-white p-3 text-sm focus:border-purple-500 outline-none shadow-sm appearance-none"
                  >
                    {stores.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                  </select>
                </div>
                <div>
                   <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Prossima Scadenza</label>
                   <input 
                    type="date"
                    value={nextDate}
                    onChange={(e) => setNextDate(e.target.value)}
                    className="w-full rounded-xl border border-gray-300 bg-white p-3 text-sm focus:border-purple-500 outline-none shadow-sm"
                    required
                  />
                </div>
              </div>

              <div className="flex items-end gap-3">
                <div className="flex-1">
                    <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Avviso (giorni prima)</label>
                    <input 
                        type="number"
                        min="0"
                        max="30"
                        value={reminderDays}
                        onChange={(e) => setReminderDays(e.target.value)}
                        className="w-full rounded-xl border border-gray-300 bg-white p-3 text-sm focus:border-purple-500 outline-none shadow-sm text-center"
                    />
                </div>
                <div className="flex gap-2">
                    {editingId && (
                        <button
                            type="button"
                            onClick={resetForm}
                            className="bg-white text-gray-500 border border-gray-300 p-3 rounded-xl hover:bg-gray-50"
                        >
                            <CloseIcon className="w-5 h-5" />
                        </button>
                    )}
                    <button
                        type="submit"
                        className={`px-6 py-3 rounded-xl text-white font-bold transition-all shadow-md active:scale-95 flex items-center gap-2 ${editingId ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-purple-600 hover:bg-purple-700'}`}
                    >
                        {editingId ? <><Save className="w-5 h-5" /> Aggiorna</> : <><Plus className="w-5 h-5" /> Aggiungi</>}
                    </button>
                </div>
              </div>
            </form>
          </div>

          <div className="space-y-3">
            <h4 className="text-xs font-bold text-gray-400 uppercase mb-2 ml-1">Scadenze salvate</h4>
            {recurringExpenses.length > 0 ? (
                recurringExpenses.map((item) => (
                <div key={item.id} className="group relative flex justify-between items-center p-4 bg-white rounded-2xl text-sm border border-gray-100 shadow-sm hover:border-purple-200 transition-all">
                  <div className="flex-1">
                    <div className="font-bold text-gray-800 text-base">{item.product}</div>
                    <div className="text-xs text-gray-500 flex flex-wrap items-center gap-3 mt-1.5">
                      <span className="font-bold text-purple-600 bg-purple-50 px-2 py-0.5 rounded-md border border-purple-100 uppercase">
                        €{item.amount.toFixed(2)} / {item.frequency}
                      </span>
                      <span className="flex items-center gap-1">
                        <CalendarClock className="w-3.5 h-3.5" />
                        {new Date(item.nextDueDate).toLocaleDateString('it-IT')}
                      </span>
                      {item.reminderDays > 0 && (
                         <span className="flex items-center gap-1 text-purple-600 font-bold" title="Preavviso attivo">
                            <Bell className="w-3.5 h-3.5" />
                            -{item.reminderDays}gg
                         </span>
                      )}
                    </div>
                  </div>
                  <div className="flex gap-1 ml-4">
                    <button 
                        onClick={() => handleEdit(item)}
                        className="p-2.5 text-gray-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-colors"
                        title="Modifica"
                    >
                        <Pencil className="w-5 h-5" />
                    </button>
                    <button 
                        onClick={() => onDeleteRecurring(item.id)}
                        className="p-2.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-colors"
                        title="Elimina"
                    >
                        <Trash2 className="w-5 h-5" />
                    </button>
                  </div>
                </div>
              ))
            ) : (
                <div className="text-center py-6 text-gray-400 italic text-xs">
                    Nessuna spesa ricorrente impostata.
                </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, Income, CategoryDefinition, ShoppingItem, OfferPreferences, RecurringExpense, SyncData } from './types';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { StoreManager } from './components/StoreManager';
import { LoginScreen } from './components/LoginScreen';
import { IncomeManager } from './components/IncomeManager';
import { CategoryManager } from './components/CategoryManager';
import { FamilyManager } from './components/FamilyManager';
import { ReceiptScanner } from './components/ReceiptScanner';
import { ShoppingListManager } from './components/ShoppingListManager';
import { OffersFinder } from './components/OffersFinder';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { DataSync } from './components/DataSync';
import { ReceiptData } from './services/geminiService';
import { categorizeExpense } from './services/geminiService';
import { supabase } from './src/supabaseClient';
import * as SupabaseService from './services/supabaseService';
import { 
  WalletCards, LogOut, Menu, X, Home, History, ChevronRight, Coins, Tag, Cloud, User, Loader2, Users, Database, Sparkles, ShoppingCart, Percent, Repeat, BarChart3, Bell, Share2
} from 'lucide-react';

type View = 'dashboard' | 'shopping' | 'offers' | 'recurring' | 'analytics' | 'history' | 'budget' | 'categories' | 'profile';

function App() {
  const [session, setSession] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoadingAuth, setIsLoadingAuth] = useState(true);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [shoppingItems, setShoppingItems] = useState<ShoppingItem[]>([]);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);
  const [categories, setCategories] = useState<CategoryDefinition[]>(DEFAULT_CATEGORIES);
  const [offerPrefs, setOfferPrefs] = useState<OfferPreferences>({
    city: '',
    selectedStores: [],
    lastCheckDate: Date.now(),
    hasEnabledNotifications: false
  });

  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [isLoadingData, setIsLoadingData] = useState(false);
  const [isSyncModalOpen, setIsSyncModalOpen] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const existingProducts = useMemo(() => Object.keys(productHistory), [productHistory]);
  const activeShoppingCount = useMemo(() => shoppingItems.filter(i => !i.completed).length, [shoppingItems]);

  const dueRecurring = useMemo(() => {
    const today = new Date();
    today.setHours(0,0,0,0);
    return recurringExpenses.filter(exp => {
      const dueDate = new Date(exp.nextDueDate);
      dueDate.setHours(0,0,0,0);
      const diffTime = dueDate.getTime() - today.getTime();
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      return diffDays <= exp.reminderDays;
    });
  }, [recurringExpenses]);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) checkUserFamily(session.user.id);
      else setIsLoadingAuth(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) {
        checkUserFamily(session.user.id);
      } else {
        setIsAuthenticated(false);
        setFamilyProfile(null);
        setIsLoadingAuth(false);
      }
    });
    return () => subscription.unsubscribe();
  }, []);

  const checkUserFamily = async (userId: string) => {
    try {
      const membership = await SupabaseService.getFamilyForUser(userId);
      if (membership) {
        const profile = await SupabaseService.getFamilyProfile(membership.familyId);
        if (profile) {
          setFamilyProfile(profile);
          setIsAuthenticated(true);
        } else {
          setIsAuthenticated(false);
        }
      } else {
        setIsAuthenticated(false);
      }
    } catch (e: any) {
      console.error("Errore inizializzazione:", e);
      setError("Errore sincronizzazione profilo.");
    } finally {
      setIsLoadingAuth(false);
    }
  };

  useEffect(() => {
    if (isAuthenticated && familyProfile?.id) {
      const loadAllData = async () => {
        setIsLoadingData(true);
        try {
          const [exp, inc, sto, cat, shop, rec] = await Promise.all([
            SupabaseService.fetchExpenses(familyProfile.id),
            SupabaseService.fetchIncomes(familyProfile.id),
            SupabaseService.fetchStores(familyProfile.id),
            SupabaseService.fetchCategories(familyProfile.id),
            SupabaseService.fetchShoppingList(familyProfile.id),
            SupabaseService.fetchRecurring(familyProfile.id)
          ]);
          setExpenses(exp || []);
          setIncomes(inc || []);
          setShoppingItems(shop || []);
          setRecurringExpenses(rec || []);
          if (sto && sto.length > 0) setStores(sto);
          if (cat && cat.length > 0) setCategories(cat);
        } catch (e: any) { 
          console.error("Errore caricamento dati:", e);
        } finally {
          setIsLoadingData(false);
        }
      };
      loadAllData();
    }
  }, [isAuthenticated, familyProfile?.id]);

  const handleSetupComplete = async (profile: FamilyProfile) => {
    if (!session?.user) return;
    setIsLoadingData(true);
    try {
      await SupabaseService.createFamilyProfile(profile);
      const name = session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'Utente';
      await SupabaseService.joinFamily(session.user.id, profile.id, name, true);
      setFamilyProfile(profile);
      setIsAuthenticated(true);
    } catch (e: any) {
      alert(`Errore: ${e.message}`);
    } finally {
      setIsLoadingData(false);
    }
  };

  const handleLogout = async () => {
    await SupabaseService.signOut();
    setIsAuthenticated(false);
    setFamilyProfile(null);
    setExpenses([]);
    setIncomes([]);
    setShoppingItems([]);
    setRecurringExpenses([]);
    setIsMenuOpen(false);
    setError(null);
  };

  const handleAddExpense = async (product: string, quantity: number, unitPrice: number, total: number, store: string) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const category = await categorizeExpense(product, store);
      const newExpense: Expense = { 
        id: crypto.randomUUID(), 
        product, 
        quantity, 
        unitPrice, 
        total, 
        store, 
        date: new Date().toISOString(), 
        category, 
        memberId: session?.user?.id 
      };
      setExpenses(prev => [newExpense, ...prev]);
      await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
    } catch (e: any) {
      console.error("Errore salvataggio spesa:", e);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleScanComplete = async (data: ReceiptData) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const newExpenses: Expense[] = [];
      for (const item of data.items) {
        const newExpense: Expense = {
          id: crypto.randomUUID(),
          product: item.product,
          quantity: item.quantity,
          unitPrice: item.unitPrice,
          total: item.total,
          store: data.store || 'Sconosciuto',
          date: data.date ? new Date(data.date).toISOString() : new Date().toISOString(),
          category: item.category || 'Alimentari',
          memberId: session?.user?.id
        };
        await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
        newExpenses.push(newExpense);
      }
      setExpenses(prev => [...newExpenses, ...prev]);
      if (data.store && !stores.some(s => s.name.toLowerCase() === data.store.toLowerCase())) {
        const newStore = { id: crypto.randomUUID(), name: data.store };
        await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
        setStores(prev => [...prev, newStore]);
      }
    } catch (err) {
      console.error("Errore scansione:", err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleAddShoppingItem = async (product: string, store: string) => {
    if (!familyProfile) return;
    const newItem: ShoppingItem = { id: crypto.randomUUID(), product, store, completed: false };
    setShoppingItems(prev => [newItem, ...prev]);
    await SupabaseService.addShoppingItemToSupabase(familyProfile.id, newItem);
  };

  const handleAddIncome = async (source: string, amount: number, date: string) => {
    if (!familyProfile) return;
    const newIncome: Income = { id: crypto.randomUUID(), source, amount, date };
    setIncomes(prev => [newIncome, ...prev]);
    await SupabaseService.addIncomeToSupabase(familyProfile.id, newIncome);
  };

  const handleAddRecurring = async (product: string, amount: number, store: string, frequency: any, nextDate: string, reminderDays: number) => {
    if (!familyProfile) return;
    const newItem: RecurringExpense = { id: crypto.randomUUID(), product, amount, store, frequency, nextDueDate: nextDate, reminderDays };
    setRecurringExpenses(prev => [...prev, newItem]);
    await SupabaseService.addRecurringToSupabase(familyProfile.id, newItem);
  };

  const handleUpdateRecurring = async (updated: RecurringExpense) => {
    setRecurringExpenses(prev => prev.map(r => r.id === updated.id ? updated : r));
    await SupabaseService.updateRecurringInSupabase(updated);
  };

  const handleProcessRecurring = async (rec: RecurringExpense) => {
    await handleAddExpense(rec.product, 1, rec.amount, rec.amount, rec.store);
    const next = new Date(rec.nextDueDate);
    if (rec.frequency === 'mensile') next.setMonth(next.getMonth() + 1);
    else if (rec.frequency === 'settimanale') next.setDate(next.getDate() + 7);
    else if (rec.frequency === 'annuale') next.setFullYear(next.getFullYear() + 1);
    const updated = { ...rec, nextDueDate: next.toISOString().split('T')[0] };
    handleUpdateRecurring(updated);
  };

  const handleImportData = (syncData: SyncData) => {
      setExpenses(syncData.expenses);
      setIncomes(syncData.incomes || []);
      setStores(syncData.stores);
      setRecurringExpenses(syncData.recurringExpenses);
      setShoppingItems(syncData.shoppingList);
      if (syncData.categories) setCategories(syncData.categories);
      alert("Dati importati con successo!");
  };

  const MenuButton = ({ view, icon, label, badge, colorClass = "" }: { view: View, icon: any, label: string, badge?: number, colorClass?: string }) => (
    <button 
      onClick={() => { setCurrentView(view); setIsMenuOpen(false); }} 
      className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl transition-all ${currentView === view ? 'bg-emerald-100 text-emerald-800 font-bold scale-[1.02]' : 'text-gray-700 hover:bg-gray-100'}`}
    >
      <div className={`relative ${colorClass}`}>
        {React.cloneElement(icon, { className: 'w-6 h-6' })}
        {badge ? (
            <span className="absolute -top-2 -right-2 bg-orange-500 text-white text-[10px] font-bold w-4 h-4 rounded-full flex items-center justify-center border-2 border-white">
                {badge}
            </span>
        ) : null}
      </div>
      <span className="text-lg">{label}</span>
      {currentView === view && <ChevronRight className="w-5 h-5 ml-auto text-emerald-600" />}
    </button>
  );

  if (isLoadingAuth) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50">
      <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
    </div>
  );

  if (!session) return <LoginScreen onSetupComplete={handleSetupComplete} />;
  if (!isAuthenticated && !isLoadingData) return <LoginScreen onSetupComplete={handleSetupComplete} isSupabaseAuth={true} />;

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans pb-24 safe-area-top">
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMenuOpen(true)} className="p-2 -ml-2 text-gray-700 hover:bg-gray-100 rounded-xl">
                <Menu className="w-6 h-6" />
             </button>
             <div className="flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('dashboard')}>
                <WalletCards className="w-6 h-6 text-emerald-600" />
                <h1 className="font-bold text-base text-gray-800 truncate max-w-[150px]">
                  {familyProfile?.familyName || 'Famiglia'}
                </h1>
             </div>
          </div>
          <div className="flex items-center gap-2">
            {dueRecurring.length > 0 && (
                <button onClick={() => setCurrentView('recurring')} className="p-2 text-orange-500 bg-orange-50 rounded-full animate-pulse">
                    <Bell className="w-5 h-5" />
                </button>
            )}
            <button onClick={() => setCurrentView('profile')} className="bg-gray-100 p-1 rounded-full border border-gray-200 overflow-hidden">
               {session?.user?.user_metadata?.avatar_url ? (
                 <img src={session.user.user_metadata.avatar_url} className="w-7 h-7" alt="User" />
               ) : ( <User className="w-5 h-5 text-gray-500 m-1" /> )}
            </button>
          </div>
        </div>
      </header>

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex">
           <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsMenuOpen(false)}></div>
           <div className="relative w-[85%] max-w-xs bg-white h-full shadow-2xl flex flex-col animate-in slide-in-from-left duration-200">
              <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                 <div>
                   <h2 className="font-bold text-xl text-gray-800">Menù</h2>
                   <span className="text-xs text-emerald-600 font-medium flex items-center gap-1 mt-1"><Cloud className="w-3 h-3" /> Sincronizzato</span>
                 </div>
                 <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-gray-200 rounded-full"><X className="w-6 h-6 text-gray-500" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-1">
                 <MenuButton view="dashboard" icon={<Home />} label="Dashboard" />
                 <MenuButton view="shopping" icon={<ShoppingCart />} label="Lista Spesa" badge={activeShoppingCount} colorClass="text-orange-500" />
                 <MenuButton view="offers" icon={<Percent />} label="Caccia Offerte" colorClass="text-red-500" />
                 <MenuButton view="recurring" icon={<Repeat />} label="Scadenze & Ricorrenti" badge={dueRecurring.length} colorClass="text-purple-600" />

                 <div className="my-2 border-t border-gray-100"></div>

                 <MenuButton view="analytics" icon={<BarChart3 />} label="Analisi & Report" colorClass="text-blue-600" />
                 <MenuButton view="budget" icon={<Coins />} label="Bilancio & Entrate" colorClass="text-emerald-600" />
                 <MenuButton view="history" icon={<History />} label="Storico Spese" />

                 <div className="my-2 border-t border-gray-100"></div>

                 <MenuButton view="profile" icon={<Users />} label="Membri Famiglia" />
                 <MenuButton view="categories" icon={<Tag />} label="Categorie Spesa" />

                 <button onClick={handleLogout} className="w-full flex items-center gap-4 px-5 py-4 rounded-xl text-red-600 hover:bg-red-50 mt-4 font-bold transition-colors">
                   <LogOut className="w-6 h-6" /> Esci
                 </button>
              </div>
           </div>
        </div>
      )}

      <main className="max-w-2xl mx-auto px-4 py-6">
        {isLoadingData ? (
          <div className="flex flex-col items-center justify-center py-20">
            <Loader2 className="w-12 h-12 text-emerald-500 animate-spin mb-4" />
          </div>
        ) : (
          <div className="animate-in fade-in duration-300">
            {currentView === 'dashboard' && (
                <div className="space-y-6">
                    <DueExpensesAlert dueExpenses={dueRecurring} onProcessExpense={handleProcessRecurring} />
                    <ReceiptScanner onScanComplete={handleScanComplete} />
                    <AIInsight expenses={expenses} />
                    <ExpenseForm 
                      stores={stores} 
                      members={[]} 
                      existingProducts={existingProducts} 
                      productHistory={productHistory} 
                      onAddExpense={handleAddExpense} 
                      isAnalyzing={isAIProcessing} 
                    />
                    <StoreManager onAddStore={(name) => SupabaseService.addStoreToSupabase(familyProfile!.id, {id: crypto.randomUUID(), name}).then(() => setStores(prev => [...prev, {id: crypto.randomUUID(), name}]))} />
                </div>
            )}

            {currentView === 'shopping' && (
                <ShoppingListManager items={shoppingItems} stores={stores} productHistory={productHistory} onAddItem={handleAddShoppingItem} onToggleItem={SupabaseService.updateShoppingItemInSupabase} onDeleteItem={SupabaseService.deleteShoppingItemFromSupabase} />
            )}

            {currentView === 'offers' && (
                <OffersFinder stores={stores} savedCity={offerPrefs.city} savedStores={offerPrefs.selectedStores} notificationsEnabled={offerPrefs.hasEnabledNotifications} onPreferencesChange={(city, selectedStores, hasEnabledNotifications) => setOfferPrefs({ ...offerPrefs, city, selectedStores, hasEnabledNotifications })} />
            )}

            {currentView === 'recurring' && (
                <RecurringManager recurringExpenses={recurringExpenses} stores={stores} onAddRecurring={handleAddRecurring} onUpdateRecurring={handleUpdateRecurring} onDeleteRecurring={(id) => SupabaseService.deleteRecurringFromSupabase(id).then(() => setRecurringExpenses(prev => prev.filter(r => r.id !== id)))} />
            )}

            {currentView === 'analytics' && (
                <div className="space-y-6">
                    <Analytics expenses={expenses} />
                    <AIInsight expenses={expenses} />
                </div>
            )}

            {currentView === 'history' && (
              <ExpenseList expenses={expenses} stores={stores} categories={categories} onDelete={(id) => SupabaseService.deleteExpenseFromSupabase(id).then(() => setExpenses(prev => prev.filter(e => e.id !== id)))} onEdit={(updated) => setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e))} />
            )}

            {currentView === 'budget' && (
              <IncomeManager incomes={incomes} expenses={expenses} onAddIncome={handleAddIncome} onDeleteIncome={(id) => SupabaseService.deleteIncomeFromSupabase(id).then(() => setIncomes(prev => prev.filter(i => i.id !== id)))} />
            )}

            {currentView === 'categories' && (
              <CategoryManager categories={categories} onUpdateCategories={(cats) => {setCategories(cats); SupabaseService.syncCategoriesToSupabase(familyProfile!.id, cats);}} />
            )}

            {currentView === 'profile' && familyProfile && (
              <div className="space-y-6">
                <FamilyManager familyProfile={familyProfile} />
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                    <h3 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
                        <Share2 className="w-5 h-5 text-emerald-600" /> Backup & Sincronizzazione manuale
                    </h3>
                    <p className="text-sm text-gray-500 mb-4">Usa questa funzione per trasferire velocemente i dati tra dispositivi diversi tramite codice.</p>
                    <button 
                        onClick={() => setIsSyncModalOpen(true)}
                        className="w-full bg-emerald-50 text-emerald-700 font-bold py-3 rounded-xl border border-emerald-100 hover:bg-emerald-100 transition-all flex items-center justify-center gap-2"
                    >
                        Apri Gestione Sincronizzazione
                    </button>
                </div>
                {isSyncModalOpen && (
                    <DataSync 
                        data={{
                            expenses,
                            incomes,
                            stores,
                            recurringExpenses,
                            shoppingList: shoppingItems,
                            familyProfile,
                            categories
                        }}
                        onImport={handleImportData}
                        onClose={() => setIsSyncModalOpen(false)}
                    />
                )}
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
}

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, Income, CategoryDefinition, ShoppingItem, OfferPreferences, RecurringExpense, SyncData } from './types';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { StoreManager } from './components/StoreManager';
import { LoginScreen } from './components/LoginScreen';
import { IncomeManager } from './components/IncomeManager';
import { CategoryManager } from './components/CategoryManager';
import { FamilyManager } from './components/FamilyManager';
import { ReceiptScanner } from './components/ReceiptScanner';
import { ShoppingListManager } from './components/ShoppingListManager';
import { OffersFinder } from './components/OffersFinder';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { DataSync } from './components/DataSync';
import { ReceiptData } from './services/geminiService';
import { categorizeExpense } from './services/geminiService';
import { supabase } from './src/supabaseClient';
import * as SupabaseService from './services/supabaseService';
import { 
  WalletCards, LogOut, Menu, X, Home, History, ChevronRight, Coins, Tag, Cloud, User, Loader2, Users, Database, Sparkles, ShoppingCart, Percent, Repeat, BarChart3, Bell, Share2
} from 'lucide-react';

type View = 'dashboard' | 'shopping' | 'offers' | 'recurring' | 'analytics' | 'history' | 'budget' | 'categories' | 'profile';

function App() {
  const [session, setSession] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoadingAuth, setIsLoadingAuth] = useState(true);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [shoppingItems, setShoppingItems] = useState<ShoppingItem[]>([]);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);
  const [categories, setCategories] = useState<CategoryDefinition[]>(DEFAULT_CATEGORIES);
  const [offerPrefs, setOfferPrefs] = useState<OfferPreferences>({
    city: '',
    selectedStores: [],
    lastCheckDate: Date.now(),
    hasEnabledNotifications: false
  });

  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [isLoadingData, setIsLoadingData] = useState(false);
  const [isSyncModalOpen, setIsSyncModalOpen] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const existingProducts = useMemo(() => Object.keys(productHistory), [productHistory]);
  const activeShoppingCount = useMemo(() => shoppingItems.filter(i => !i.completed).length, [shoppingItems]);

  const dueRecurring = useMemo(() => {
    const today = new Date();
    today.setHours(0,0,0,0);
    return recurringExpenses.filter(exp => {
      const dueDate = new Date(exp.nextDueDate);
      dueDate.setHours(0,0,0,0);
      const diffTime = dueDate.getTime() - today.getTime();
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      return diffDays <= exp.reminderDays;
    });
  }, [recurringExpenses]);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) checkUserFamily(session.user.id);
      else setIsLoadingAuth(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) {
        checkUserFamily(session.user.id);
      } else {
        setIsAuthenticated(false);
        setFamilyProfile(null);
        setIsLoadingAuth(false);
      }
    });
    return () => subscription.unsubscribe();
  }, []);

  const checkUserFamily = async (userId: string) => {
    try {
      const membership = await SupabaseService.getFamilyForUser(userId);
      if (membership) {
        const profile = await SupabaseService.getFamilyProfile(membership.familyId);
        if (profile) {
          setFamilyProfile(profile);
          setIsAuthenticated(true);
        } else {
          setIsAuthenticated(false);
        }
      } else {
        setIsAuthenticated(false);
      }
    } catch (e: any) {
      console.error("Errore inizializzazione:", e);
      setError("Errore sincronizzazione profilo.");
    } finally {
      setIsLoadingAuth(false);
    }
  };

  useEffect(() => {
    if (isAuthenticated && familyProfile?.id) {
      const loadAllData = async () => {
        setIsLoadingData(true);
        try {
          const [exp, inc, sto, cat, shop, rec] = await Promise.all([
            SupabaseService.fetchExpenses(familyProfile.id),
            SupabaseService.fetchIncomes(familyProfile.id),
            SupabaseService.fetchStores(familyProfile.id),
            SupabaseService.fetchCategories(familyProfile.id),
            SupabaseService.fetchShoppingList(familyProfile.id),
            SupabaseService.fetchRecurring(familyProfile.id)
          ]);
          setExpenses(exp || []);
          setIncomes(inc || []);
          setShoppingItems(shop || []);
          setRecurringExpenses(rec || []);
          if (sto && sto.length > 0) setStores(sto);
          if (cat && cat.length > 0) setCategories(cat);
        } catch (e: any) { 
          console.error("Errore caricamento dati:", e);
        } finally {
          setIsLoadingData(false);
        }
      };
      loadAllData();
    }
  }, [isAuthenticated, familyProfile?.id]);

  const handleSetupComplete = async (profile: FamilyProfile) => {
    if (!session?.user) return;
    setIsLoadingData(true);
    try {
      await SupabaseService.createFamilyProfile(profile);
      const name = session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'Utente';
      await SupabaseService.joinFamily(session.user.id, profile.id, name, true);
      setFamilyProfile(profile);
      setIsAuthenticated(true);
    } catch (e: any) {
      alert(`Errore: ${e.message}`);
    } finally {
      setIsLoadingData(false);
    }
  };

  const handleLogout = async () => {
    await SupabaseService.signOut();
    setIsAuthenticated(false);
    setFamilyProfile(null);
    setExpenses([]);
    setIncomes([]);
    setShoppingItems([]);
    setRecurringExpenses([]);
    setIsMenuOpen(false);
    setError(null);
  };

  const handleAddExpense = async (product: string, quantity: number, unitPrice: number, total: number, store: string) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const category = await categorizeExpense(product, store);
      const newExpense: Expense = { 
        id: crypto.randomUUID(), 
        product, 
        quantity, 
        unitPrice, 
        total, 
        store, 
        date: new Date().toISOString(), 
        category, 
        memberId: session?.user?.id 
      };
      setExpenses(prev => [newExpense, ...prev]);
      await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
    } catch (e: any) {
      console.error("Errore salvataggio spesa:", e);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleScanComplete = async (data: ReceiptData) => {
    if (!familyProfile) return;
    setIsAIProcessing(true);
    try {
      const newExpenses: Expense[] = [];
      for (const item of data.items) {
        const newExpense: Expense = {
          id: crypto.randomUUID(),
          product: item.product,
          quantity: item.quantity,
          unitPrice: item.unitPrice,
          total: item.total,
          store: data.store || 'Sconosciuto',
          date: data.date ? new Date(data.date).toISOString() : new Date().toISOString(),
          category: item.category || 'Alimentari',
          memberId: session?.user?.id
        };
        await SupabaseService.addExpenseToSupabase(familyProfile.id, newExpense);
        newExpenses.push(newExpense);
      }
      setExpenses(prev => [...newExpenses, ...prev]);
      if (data.store && !stores.some(s => s.name.toLowerCase() === data.store.toLowerCase())) {
        const newStore = { id: crypto.randomUUID(), name: data.store };
        await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
        setStores(prev => [...prev, newStore]);
      }
    } catch (err) {
      console.error("Errore scansione:", err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleAddShoppingItem = async (product: string, store: string) => {
    if (!familyProfile) return;
    const newItem: ShoppingItem = { id: crypto.randomUUID(), product, store, completed: false };
    setShoppingItems(prev => [newItem, ...prev]);
    await SupabaseService.addShoppingItemToSupabase(familyProfile.id, newItem);
  };

  const handleToggleShoppingItem = async (id: string) => {
    const item = shoppingItems.find(i => i.id === id);
    if (!item) return;

    const updatedItem = { ...item, completed: !item.completed };
    setShoppingItems(prev => prev.map(i => i.id === id ? updatedItem : i));

    try {
        await SupabaseService.updateShoppingItemInSupabase(updatedItem);
    } catch (err) {
        console.error("Errore toggle shopping item:", err);
        // Rollback on error
        setShoppingItems(prev => prev.map(i => i.id === id ? item : i));
    }
  };

  const handleDeleteShoppingItem = async (id: string) => {
    setShoppingItems(prev => prev.filter(i => i.id !== id));
    try {
        await SupabaseService.deleteShoppingItemFromSupabase(id);
    } catch (err) {
        console.error("Errore delete shopping item:", err);
    }
  };

  const handleAddIncome = async (source: string, amount: number, date: string) => {
    if (!familyProfile) return;
    const newIncome: Income = { id: crypto.randomUUID(), source, amount, date };
    setIncomes(prev => [newIncome, ...prev]);
    await SupabaseService.addIncomeToSupabase(familyProfile.id, newIncome);
  };

  const handleAddRecurring = async (product: string, amount: number, store: string, frequency: any, nextDate: string, reminderDays: number) => {
    if (!familyProfile) return;
    const newItem: RecurringExpense = { id: crypto.randomUUID(), product, amount, store, frequency, nextDueDate: nextDate, reminderDays };
    setRecurringExpenses(prev => [...prev, newItem]);
    await SupabaseService.addRecurringToSupabase(familyProfile.id, newItem);
  };

  const handleUpdateRecurring = async (updated: RecurringExpense) => {
    setRecurringExpenses(prev => prev.map(r => r.id === updated.id ? updated : r));
    await SupabaseService.updateRecurringInSupabase(updated);
  };

  const handleProcessRecurring = async (rec: RecurringExpense) => {
    await handleAddExpense(rec.product, 1, rec.amount, rec.amount, rec.store);
    const next = new Date(rec.nextDueDate);
    if (rec.frequency === 'mensile') next.setMonth(next.getMonth() + 1);
    else if (rec.frequency === 'settimanale') next.setDate(next.getDate() + 7);
    else if (rec.frequency === 'annuale') next.setFullYear(next.getFullYear() + 1);
    const updated = { ...rec, nextDueDate: next.toISOString().split('T')[0] };
    handleUpdateRecurring(updated);
  };

  const handleImportData = (syncData: SyncData) => {
      setExpenses(syncData.expenses);
      setIncomes(syncData.incomes || []);
      setStores(syncData.stores);
      setRecurringExpenses(syncData.recurringExpenses);
      setShoppingItems(syncData.shoppingList);
      if (syncData.categories) setCategories(syncData.categories);
      alert("Dati importati con successo!");
  };

  const MenuButton = ({ view, icon, label, badge, colorClass = "" }: { view: View, icon: any, label: string, badge?: number, colorClass?: string }) => (
    <button 
      onClick={() => { setCurrentView(view); setIsMenuOpen(false); }} 
      className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl transition-all ${currentView === view ? 'bg-emerald-100 text-emerald-800 font-bold scale-[1.02]' : 'text-gray-700 hover:bg-gray-100'}`}
    >
      <div className={`relative ${colorClass}`}>
        {React.cloneElement(icon, { className: 'w-6 h-6' })}
        {badge ? (
            <span className="absolute -top-2 -right-2 bg-orange-500 text-white text-[10px] font-bold h-4 w-4 rounded-full flex items-center justify-center border-2 border-white">
                {badge}
            </span>
        ) : null}
      </div>
      <span className="text-lg">{label}</span>
      {currentView === view && <ChevronRight className="w-5 h-5 ml-auto text-emerald-600" />}
    </button>
  );

  if (isLoadingAuth) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50">
      <Loader2 className="h-10 w-10 text-emerald-600 animate-spin" />
    </div>
  );

  if (!session) return <LoginScreen onSetupComplete={handleSetupComplete} />;
  if (!isAuthenticated && !isLoadingData) return <LoginScreen onSetupComplete={handleSetupComplete} isSupabaseAuth={true} />;

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans pb-24 safe-area-top">
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <button onClick={() => setIsMenuOpen(true)} className="p-2 -ml-2 text-gray-700 hover:bg-gray-100 rounded-xl">
                <Menu className="h-6 w-6" />
             </button>
             <div className="flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('dashboard')}>
                <WalletCards className="h-6 w-6 text-emerald-600" />
                <h1 className="font-bold text-base text-gray-800 truncate max-w-[150px]">
                  {familyProfile?.familyName || 'Famiglia'}
                </h1>
             </div>
          </div>
          <div className="flex items-center gap-2">
            {dueRecurring.length > 0 && (
                <button onClick={() => setCurrentView('recurring')} className="p-2 text-orange-500 bg-orange-50 rounded-full animate-pulse">
                    <Bell className="h-5 w-5" />
                </button>
            )}
            <button onClick={() => setCurrentView('profile')} className="bg-gray-100 p-1 rounded-full border border-gray-200 overflow-hidden">
               {session?.user?.user_metadata?.avatar_url ? (
                 <img src={session.user.user_metadata.avatar_url} className="h-7 w-7" alt="User" />
               ) : ( <User className="h-5 w-5 text-gray-500 m-1" /> )}
            </button>
          </div>
        </div>
      </header>

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex">
           <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsMenuOpen(false)}></div>
           <div className="relative w-[85%] max-w-xs bg-white h-full shadow-2xl flex flex-col animate-in slide-in-from-left duration-200">
              <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                 <div>
                   <h2 className="font-bold text-xl text-gray-800">Menù</h2>
                   <span className="text-xs text-emerald-600 font-medium flex items-center gap-1 mt-1"><Cloud className="h-3 w-3" /> Sincronizzato</span>
                 </div>
                 <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-gray-200 rounded-full"><X className="h-6 w-6 text-gray-500" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-1">
                 <MenuButton view="dashboard" icon={<Home />} label="Dashboard" />
                 <MenuButton view="shopping" icon={<ShoppingCart />} label="Lista Spesa" badge={activeShoppingCount} colorClass="text-orange-500" />
                 <MenuButton view="offers" icon={<Percent />} label="Caccia Offerte" colorClass="text-red-500" />
                 <MenuButton view="recurring" icon={<Repeat />} label="Scadenze & Ricorrenti" badge={dueRecurring.length} colorClass="text-purple-600" />

                 <div className="my-2 border-t border-gray-100"></div>

                 <MenuButton view="analytics" icon={<BarChart3 />} label="Analisi & Report" colorClass="text-blue-600" />
                 <MenuButton view="budget" icon={<Coins />} label="Bilancio & Entrate" colorClass="text-emerald-600" />
                 <MenuButton view="history" icon={<History />} label="Storico Spese" />

                 <div className="my-2 border-t border-gray-100"></div>

                 <MenuButton view="profile" icon={<Users />} label="Membri Famiglia" />
                 <MenuButton view="categories" icon={<Tag />} label="Categorie Spesa" />

                 <button onClick={handleLogout} className="w-full flex items-center gap-4 px-5 py-4 rounded-xl text-red-600 hover:bg-red-50 mt-4 font-bold transition-colors">
                   <LogOut className="h-6 w-6" /> Esci
                 </button>
              </div>
           </div>
        </div>
      )}

      <main className="max-w-2xl mx-auto px-4 py-6">
        {isLoadingData ? (
          <div className="flex flex-col items-center justify-center py-20">
            <Loader2 className="h-12 w-12 text-emerald-500 animate-spin mb-4" />
          </div>
        ) : (
          <div className="animate-in fade-in duration-300">
            {currentView === 'dashboard' && (
                <div className="space-y-6">
                    <DueExpensesAlert dueExpenses={dueRecurring} onProcessExpense={handleProcessRecurring} />
                    <ReceiptScanner onScanComplete={handleScanComplete} />
                    <AIInsight expenses={expenses} />
                    <ExpenseForm 
                      stores={stores} 
                      members={[]} 
                      existingProducts={existingProducts} 
                      productHistory={productHistory} 
                      onAddExpense={handleAddExpense} 
                      isAnalyzing={isAIProcessing} 
                    />
                    <StoreManager onAddStore={(name) => SupabaseService.addStoreToSupabase(familyProfile!.id, {id: crypto.randomUUID(), name}).then(() => setStores(prev => [...prev, {id: crypto.randomUUID(), name}]))} />
                </div>
            )}

            {currentView === 'shopping' && (
                <ShoppingListManager 
                    items={shoppingItems} 
                    stores={stores} 
                    productHistory={productHistory} 
                    onAddItem={handleAddShoppingItem} 
                    onToggleItem={handleToggleShoppingItem} 
                    onDeleteItem={handleDeleteShoppingItem} 
                />
            )}

            {currentView === 'offers' && (
                <OffersFinder stores={stores} savedCity={offerPrefs.city} savedStores={offerPrefs.selectedStores} notificationsEnabled={offerPrefs.hasEnabledNotifications} onPreferencesChange={(city, selectedStores, hasEnabledNotifications) => setOfferPrefs({ ...offerPrefs, city, selectedStores, hasEnabledNotifications })} />
            )}

            {currentView === 'recurring' && (
                <RecurringManager recurringExpenses={recurringExpenses} stores={stores} onAddRecurring={handleAddRecurring} onUpdateRecurring={handleUpdateRecurring} onDeleteRecurring={(id) => SupabaseService.deleteRecurringFromSupabase(id).then(() => setRecurringExpenses(prev => prev.filter(r => r.id !== id)))} />
            )}

            {currentView === 'analytics' && (
                <div className="space-y-6">
                    <Analytics expenses={expenses} />
                    <AIInsight expenses={expenses} />
                </div>
            )}

            {currentView === 'history' && (
              <ExpenseList expenses={expenses} stores={stores} categories={categories} onDelete={(id) => SupabaseService.deleteExpenseFromSupabase(id).then(() => setExpenses(prev => prev.filter(e => e.id !== id)))} onEdit={(updated) => setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e))} />
            )}

            {currentView === 'budget' && (
              <IncomeManager incomes={incomes} expenses={expenses} onAddIncome={handleAddIncome} onDeleteIncome={(id) => SupabaseService.deleteIncomeFromSupabase(id).then(() => setIncomes(prev => prev.filter(i => i.id !== id)))} />
            )}

            {currentView === 'categories' && (
              <CategoryManager categories={categories} onUpdateCategories={(cats) => {setCategories(cats); SupabaseService.syncCategoriesToSupabase(familyProfile!.id, cats);}} />
            )}

            {currentView === 'profile' && familyProfile && (
              <div className="space-y-6">
                <FamilyManager familyProfile={familyProfile} />
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                    <h3 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
                        <Share2 className="h-5 w-5 text-emerald-600" /> Backup & Sincronizzazione manuale
                    </h3>
                    <p className="text-sm text-gray-500 mb-4">Usa questa funzione per trasferire velocemente i dati tra dispositivi diversi tramite codice.</p>
                    <button 
                        onClick={() => setIsSyncModalOpen(true)}
                        className="w-full bg-emerald-50 text-emerald-700 font-bold py-3 rounded-xl border border-emerald-100 hover:bg-emerald-100 transition-all flex items-center justify-center gap-2"
                    >
                        Apri Gestione Sincronizzazione
                    </button>
                </div>
                {isSyncModalOpen && (
                    <DataSync 
                        data={{
                            expenses,
                            incomes,
                            stores,
                            recurringExpenses,
                            shoppingList: shoppingItems,
                            familyProfile,
                            categories
                        }}
                        onImport={handleImportData}
                        onClose={() => setIsSyncModalOpen(false)}
                    />
                )}
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
}

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { ShoppingItem, Store } from '../types';
import { ShoppingCart, Plus, Trash2, CheckSquare, Square, History, X, Store as StoreIcon, Filter, Sparkles } from 'lucide-react';

interface ShoppingListManagerProps {
  items: ShoppingItem[];
  stores: Store[];
  productHistory: Record<string, string>; // Map: Product Name -> Last Store Name
  onAddItem: (product: string, store: string) => void;
  onToggleItem: (id: string) => void;
  onDeleteItem: (id: string) => void;
}

export const ShoppingListManager: React.FC<ShoppingListManagerProps> = ({
  items,
  stores,
  productHistory,
  onAddItem,
  onToggleItem,
  onDeleteItem
}) => {
  const [isOpen, setIsOpen] = useState(true); 
  const [showHistoryModal, setShowHistoryModal] = useState(false);

  const [activeStoreFilter, setActiveStoreFilter] = useState<string>('');
  const [newItemProduct, setNewItemProduct] = useState('');
  const [newItemStore, setNewItemStore] = useState(stores[0]?.name || '');

  useEffect(() => {
    if (activeStoreFilter) {
        setNewItemStore(activeStoreFilter);
    }
  }, [activeStoreFilter]);

  const groupedItems = useMemo(() => {
    const groups: Record<string, ShoppingItem[]> = {};
    items.forEach(item => {
      if (!groups[item.store]) groups[item.store] = [];
      groups[item.store].push(item);
    });

    // Sort each group: active items first, then completed
    Object.keys(groups).forEach(store => {
        groups[store].sort((a, b) => {
            if (a.completed === b.completed) return 0;
            return a.completed ? 1 : -1;
        });
    });

    return groups;
  }, [items]);

  const displayedGroups = useMemo(() => {
      if (!activeStoreFilter) return groupedItems;
      const filtered: Record<string, ShoppingItem[]> = {};
      if (groupedItems[activeStoreFilter]) {
          filtered[activeStoreFilter] = groupedItems[activeStoreFilter];
      }
      return filtered;
  }, [groupedItems, activeStoreFilter]);

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (newItemProduct.trim() && newItemStore) {
      onAddItem(newItemProduct.trim(), newItemStore);
      setNewItemProduct('');
    }
  };

  const handleHistorySelect = (product: string, defaultStore: string) => {
    const targetStore = activeStoreFilter || defaultStore;
    if (!items.some(i => i.product.toLowerCase() === product.toLowerCase() && !i.completed)) {
        onAddItem(product, targetStore);
    }
    setShowHistoryModal(false);
  };

  const historyList = useMemo(() => {
    return Object.entries(productHistory).sort((a, b) => a[0].localeCompare(b[0]));
  }, [productHistory]);

  const quickSuggestions = useMemo(() => {
    const inList = new Set(items.filter(i => !i.completed).map(i => i.product.toLowerCase()));
    return historyList
        .filter(([prod]) => !inList.has(prod.toLowerCase()))
        .slice(0, 6);
  }, [historyList, items]);

  const activeCount = items.filter(i => !i.completed).length;

  return (
    <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 mb-6">

      <div 
        className="flex justify-between items-center cursor-pointer select-none mb-5"
        onClick={() => setIsOpen(!isOpen)}
      >
        <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
          <ShoppingCart className="h-5 w-5 text-orange-500" />
          Lista della Spesa
          {activeCount > 0 && (
            <span className="bg-orange-100 text-orange-700 text-xs font-bold px-2.5 py-1 rounded-full">
              {activeCount} da prendere
            </span>
          )}
        </h3>
        <button className="text-orange-500 hover:text-orange-700 text-sm font-semibold py-1 px-2">
          {isOpen ? 'Chiudi' : 'Apri'}
        </button>
      </div>

      {isOpen && (
        <div className="animate-in fade-in slide-in-from-top-2 duration-200">

          <div className="mb-5 bg-orange-50 p-4 rounded-xl border border-orange-100">
              <label className="block text-xs font-bold text-orange-800 uppercase mb-3 flex items-center gap-1">
                  <Filter className="h-3.5 w-3.5" />
                  Visualizza prodotti per:
              </label>
              <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
                  <button
                      onClick={() => setActiveStoreFilter('')}
                      className={`whitespace-nowrap px-4 py-2.5 rounded-full text-sm font-semibold transition-colors border shadow-sm ${
                          activeStoreFilter === '' 
                          ? 'bg-orange-500 text-white border-orange-600' 
                          : 'bg-white text-gray-700 border-gray-200 hover:border-orange-300'
                      }`}
                  >
                      Tutti i Negozi
                  </button>
                  {stores.map(store => (
                      <button
                          key={store.id}
                          onClick={() => setActiveStoreFilter(store.name)}
                          className={`whitespace-nowrap px-4 py-2.5 rounded-full text-sm font-semibold transition-colors border shadow-sm ${
                              activeStoreFilter === store.name
                              ? 'bg-orange-500 text-white border-orange-600' 
                              : 'bg-white text-gray-700 border-gray-200 hover:border-orange-300'
                      }`}
                      >
                          {store.name}
                      </button>
                  ))}
              </div>
          </div>

          {quickSuggestions.length > 0 && (
            <div className="mb-4">
              <div className="flex items-center gap-1.5 mb-2 px-1">
                <Sparkles className="h-3.5 w-3.5 text-orange-400" />
                <span className="text-xs font-bold text-gray-400 uppercase">Suggeriti dallo storico</span>
              </div>
              <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
                {quickSuggestions.map(([prod, store]) => (
                  <button
                    key={prod}
                    onClick={() => handleHistorySelect(prod, store)}
                    className="flex-shrink-0 bg-white border border-gray-200 hover:border-orange-300 hover:bg-orange-50 px-3 py-2 rounded-xl text-sm font-medium text-gray-700 transition-all flex items-center gap-1.5"
                  >
                    <Plus className="h-3.5 w-3.5 text-orange-400" />
                    {prod}
                  </button>
                ))}
              </div>
            </div>
          )}

          <form onSubmit={handleAdd} className="flex flex-col gap-3 mb-6">
            <div className="flex gap-2">
                <input
                    type="text"
                    value={newItemProduct}
                    onChange={(e) => setNewItemProduct(e.target.value)}
                    placeholder={activeStoreFilter ? `Cosa serve al ${activeStoreFilter}?` : "Cosa serve?"}
                    className="flex-1 rounded-xl border border-gray-300 bg-gray-50 p-3.5 text-base focus:border-orange-500 focus:ring-2 focus:ring-orange-200 outline-none transition-all shadow-sm"
                />
                <button
                    type="button"
                    onClick={() => setShowHistoryModal(true)}
                    className="bg-orange-100 text-orange-600 px-3.5 rounded-xl hover:bg-orange-200 transition-colors border border-orange-200"
                    title="Storico completo"
                >
                    <History className="h-6 w-6" />
                </button>
            </div>
            <div className="flex gap-2">
                <select
                    value={newItemStore}
                    onChange={(e) => setNewItemStore(e.target.value)}
                    className="flex-1 rounded-xl border border-gray-300 bg-gray-50 p-3.5 text-base focus:border-orange-500 focus:ring-2 focus:ring-orange-200 outline-none shadow-sm appearance-none"
                >
                    {stores.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                </select>
                <button
                    type="submit"
                    disabled={!newItemProduct.trim()}
                    className="bg-orange-500 text-white px-5 rounded-xl hover:bg-orange-600 transition-colors disabled:opacity-50 shadow-md active:scale-95"
                >
                    <Plus className="h-6 w-6" />
                </button>
            </div>
          </form>

          <div className="space-y-5">
            {Object.keys(displayedGroups).length === 0 && (
                <div className="text-center py-8 bg-gray-50 rounded-xl border border-dashed border-gray-200">
                    <p className="text-sm text-gray-500 italic">
                        {activeStoreFilter 
                            ? `Nessun prodotto in lista per ${activeStoreFilter}.` 
                            : "La lista della spesa è vuota."}
                    </p>
                </div>
            )}

            {Object.entries(displayedGroups).map(([storeName, storeItems]) => (
              <div key={storeName} className="bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden animate-in fade-in">
                <div className="bg-orange-50 px-4 py-2.5 text-sm font-bold text-orange-800 flex items-center gap-2 border-b border-orange-100">
                  <StoreIcon className="h-4 w-4" /> {storeName}
                </div>
                <div className="divide-y divide-gray-100">
                    {(storeItems as ShoppingItem[]).map(item => (
                        <div key={item.id} className={`flex items-center justify-between p-4 transition-colors ${item.completed ? 'bg-gray-50/50' : 'hover:bg-gray-50'}`}>
                            <div 
                                className="flex items-center gap-3 cursor-pointer flex-1"
                                onClick={() => onToggleItem(item.id)}
                            >
                                {item.completed ? (
                                    <CheckSquare className="h-6 w-6 text-emerald-500 flex-shrink-0" />
                                ) : (
                                    <Square className="h-6 w-6 text-orange-500 flex-shrink-0" />
                                )}
                                <span className={`text-lg font-medium transition-all ${item.completed ? 'text-gray-400 line-through' : 'text-gray-800'}`}>
                                    {item.product}
                                </span>
                            </div>
                            <button 
                                onClick={() => onDeleteItem(item.id)}
                                className="text-gray-300 hover:text-red-500 p-2 -mr-2 transition-colors"
                                title="Rimuovi dalla lista"
                            >
                                <Trash2 className="h-5 w-5" />
                            </button>
                        </div>
                    ))}
                </div>
              </div>
            ))}
          </div>

        </div>
      )}

      {showHistoryModal && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 animate-in fade-in backdrop-blur-sm">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm max-h-[85vh] flex flex-col">
                <div className="p-5 border-b border-gray-100 flex justify-between items-center">
                    <h3 className="font-bold text-lg text-gray-800">Storico Prodotti</h3>
                    <button onClick={() => setShowHistoryModal(false)} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200">
                        <X className="h-5 w-5 text-gray-600" />
                    </button>
                </div>
                <div className="p-2 overflow-y-auto flex-1">
                    <div className="space-y-1">
                        {historyList.map(([prod, lastStore]) => (
                            <button
                                key={prod}
                                onClick={() => handleHistorySelect(prod, lastStore)}
                                className="w-full text-left px-5 py-4 hover:bg-orange-50 rounded-xl flex justify-between items-center group border-b border-gray-50 last:border-0"
                            >
                                <span className="text-base font-medium text-gray-800">{prod}</span>
                                <span className="text-xs text-gray-400 bg-gray-100 px-2 py-1 rounded-md group-hover:bg-white">
                                    {activeStoreFilter ? '' : lastStore}
                                </span>
                            </button>
                        ))}
                        {historyList.length === 0 && (
                            <p className="text-center text-gray-500 py-8">Nessun acquisto registrato.</p>
                        )}
                    </div>
                </div>
            </div>
        </div>
      )}

    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { ShoppingItem, Store } from '../types';
import { ShoppingCart, Plus, Trash2, CheckCircle2, Circle, History, X, Store as StoreIcon, Filter, Sparkles, CheckSquare, Square, Eraser } from 'lucide-react';

interface ShoppingListManagerProps {
  items: ShoppingItem[];
  stores: Store[];
  productHistory: Record<string, string>;
  onAddItem: (product: string, store: string) => void;
  onToggleItem: (id: string) => void;
  onDeleteItem: (id: string) => void;
}

export const ShoppingListManager: React.FC<ShoppingListManagerProps> = ({
  items,
  stores,
  productHistory,
  onAddItem,
  onToggleItem,
  onDeleteItem
}) => {
  const [isOpen, setIsOpen] = useState(true); 
  const [showHistoryModal, setShowHistoryModal] = useState(false);
  const [activeStoreFilter, setActiveStoreFilter] = useState<string>('');
  const [newItemProduct, setNewItemProduct] = useState('');
  const [newItemStore, setNewItemStore] = useState(stores[0]?.name || '');

  useEffect(() => {
    if (activeStoreFilter) {
        setNewItemStore(activeStoreFilter);
    }
  }, [activeStoreFilter]);

  // Dividiamo gli elementi in attivi e completati per una gestione più chiara richiesto dall'utente
  const { activeItems, completedItems } = useMemo(() => {
    const filtered = activeStoreFilter 
      ? items.filter(i => i.store === activeStoreFilter)
      : items;

    return {
      activeItems: filtered.filter(i => !i.completed),
      completedItems: filtered.filter(i => i.completed)
    };
  }, [items, activeStoreFilter]);

  const historyList = useMemo(() => {
    return Object.entries(productHistory).sort((a, b) => a[0].localeCompare(b[0]));
  }, [productHistory]);

  const quickSuggestions = useMemo(() => {
    const inList = new Set(items.filter(i => !i.completed).map(i => i.product.toLowerCase()));
    return historyList
        .filter(([prod]) => !inList.has(prod.toLowerCase()))
        .slice(0, 8);
  }, [historyList, items]);

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (newItemProduct.trim() && newItemStore) {
      onAddItem(newItemProduct.trim(), newItemStore);
      setNewItemProduct('');
    }
  };

  const handleHistorySelect = (product: string, defaultStore: string) => {
    const targetStore = activeStoreFilter || defaultStore;
    onAddItem(product, targetStore);
    setShowHistoryModal(false);
  };

  const handleClearCompleted = () => {
    if (confirm("Vuoi rimuovere definitivamente tutti i prodotti già acquistati?")) {
        completedItems.forEach(item => onDeleteItem(item.id));
    }
  };

  return (
    <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 mb-6">
      <div className="flex justify-between items-center mb-5">
