                <div className="p-5 border-b border-gray-100 flex justify-between items-center">
                    <h3 className="font-bold text-lg text-gray-800">Storico Acquisti</h3>
                    <button onClick={() => setShowHistoryModal(false)} className="p-2 bg-gray-100 rounded-full">
                        <X className="h-5 w-5 text-gray-600" />
                    </button>
                </div>
                <div className="p-2 overflow-y-auto flex-1">
                    {historyList.map(([prod, lastStore]) => (
                        <button
                            key={prod}
                            onClick={() => handleHistorySelect(prod, lastStore)}
                            className="w-full text-left px-5 py-4 hover:bg-orange-50 rounded-2xl flex justify-between items-center group transition-colors"
                        >
                            <div>
                                <div className="text-base font-bold text-gray-800">{prod}</div>
                                <div className="text-[10px] text-gray-400 font-bold uppercase mt-1">{lastStore}</div>
                            </div>
                            <Plus className="w-5 h-5 text-gray-300 group-hover:text-orange-500" />
                        </button>
                    ))}
                    {historyList.length === 0 && <p className="text-center text-gray-400 py-10 italic">Nessuno storico disponibile.</p>}
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { RecurringExpense, Frequency, Store } from '../types';
import { Repeat, Plus, Trash2, CalendarClock, Bell, Pencil, Save, X as CloseIcon } from 'lucide-react';

interface RecurringManagerProps {
  recurringExpenses: RecurringExpense[];
  stores: Store[];
  onAddRecurring: (product: string, amount: number, store: string, frequency: Frequency, nextDate: string, reminderDays: number) => void;
  onUpdateRecurring: (updated: RecurringExpense) => void;
  onDeleteRecurring: (id: string) => void;
}

export const RecurringManager: React.FC<RecurringManagerProps> = ({ 
  recurringExpenses, 
  stores, 
  onAddRecurring, 
  onUpdateRecurring,
  onDeleteRecurring 
}) => {
  const [isOpen, setIsOpen] = useState(false);

  // State per editing
  const [editingId, setEditingId] = useState<string | null>(null);
  const [product, setProduct] = useState('');
  const [amount, setAmount] = useState('');
  const [store, setStore] = useState(stores[0]?.name || '');
  const [frequency, setFrequency] = useState<Frequency>('mensile');
  const [nextDate, setNextDate] = useState(new Date().toISOString().split('T')[0]);
  const [reminderDays, setReminderDays] = useState('0');

  useEffect(() => {
    if (!store && stores.length > 0) setStore(stores[0].name);
  }, [stores]);

  const handleEdit = (item: RecurringExpense) => {
    setEditingId(item.id);
    setProduct(item.product);
    setAmount(item.amount.toString());
    setStore(item.store);
    setFrequency(item.frequency);
    setNextDate(item.nextDueDate);
    setReminderDays(item.reminderDays.toString());
    if (!isOpen) setIsOpen(true);

    // Scroll fluido verso il form
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const resetForm = () => {
    setEditingId(null);
    setProduct('');
    setAmount('');
    setFrequency('mensile');
    setNextDate(new Date().toISOString().split('T')[0]);
    setReminderDays('0');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!product || !amount || !store || !nextDate) return;

    if (editingId) {
        onUpdateRecurring({
            id: editingId,
            product,
            amount: parseFloat(amount),
            store,
            frequency,
            nextDueDate: nextDate,
            reminderDays: parseInt(reminderDays) || 0
        });
    } else {
        onAddRecurring(product, parseFloat(amount), store, frequency, nextDate, parseInt(reminderDays) || 0);
    }

    resetForm();
    if (!editingId) setIsOpen(false);
  };

  return (
    <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 mb-6">
      <div 
        className="flex justify-between items-center cursor-pointer select-none mb-1"
        onClick={() => setIsOpen(!isOpen)}
      >
        <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
          <Repeat className="w-5 h-5 text-purple-600" />
          Spese Ricorrenti
        </h3>
        <button className="text-purple-600 hover:text-purple-700 text-sm font-semibold">
          {isOpen ? 'Chiudi' : 'Gestisci'}
        </button>
      </div>

      {isOpen && (
        <div className="mt-5 animate-in fade-in slide-in-from-top-2 duration-200">

          <div className={`p-5 rounded-2xl border mb-6 transition-all ${editingId ? 'bg-indigo-50 border-indigo-200 shadow-inner' : 'bg-purple-50 border-purple-100'}`}>
            <h4 className={`text-[10px] font-bold uppercase mb-4 flex items-center gap-2 ${editingId ? 'text-indigo-800' : 'text-purple-800'}`}>
                {editingId ? <Pencil className="w-3.5 h-3.5" /> : <Plus className="w-3.5 h-3.5" />}
                {editingId ? 'Modifica Voce Ricorrente' : 'Nuova Scadenza'}
            </h4>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5 ml-1">Servizio / Nome</label>
                <input
                  type="text"
                  placeholder="Es. Netflix, Affitto, Internet"
                  value={product}
                  onChange={(e) => setProduct(e.target.value)}
                  className="w-full rounded-xl border border-gray-300 bg-white p-3 text-base focus:border-purple-500 outline-none shadow-sm"
                  required
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                   <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5 ml-1">Importo (€)</label>
                   <input
                    type="number"
                    step="0.01"
                    placeholder="0.00"
                    value={amount}
                    onChange={(e) => setAmount(e.target.value)}
                    className="w-full rounded-xl border border-gray-300 bg-white p-3 text-base focus:border-purple-500 outline-none shadow-sm"
                    required
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5 ml-1">Frequenza</label>
                  <select
                    value={frequency}
                    onChange={(e) => setFrequency(e.target.value as Frequency)}
                    className="w-full rounded-xl border border-gray-300 bg-white p-3 text-base focus:border-purple-500 outline-none shadow-sm appearance-none"
                  >
                    <option value="settimanale">Settimanale</option>
                    <option value="mensile">Mensile</option>
                    <option value="annuale">Annuale</option>
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5 ml-1">Negozio</label>
                  <select
                    value={store}
                    onChange={(e) => setStore(e.target.value)}
                    className="w-full rounded-xl border border-gray-300 bg-white p-3 text-base focus:border-purple-500 outline-none shadow-sm appearance-none"
                  >
                    {stores.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                  </select>
                </div>
                <div>
                   <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5 ml-1">Data Scadenza</label>
                   <input 
                    type="date"
                    value={nextDate}
                    onChange={(e) => setNextDate(e.target.value)}
                    className="w-full rounded-xl border border-gray-300 bg-white p-3 text-base focus:border-purple-500 outline-none shadow-sm"
                    required
                  />
                </div>
              </div>

              <div className="flex items-end gap-3 pt-2">
                <div className="flex-1">
                    <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5 ml-1">Avviso (gg prima)</label>
                    <input 
                        type="number"
                        min="0"
                        max="30"
                        value={reminderDays}
                        onChange={(e) => setReminderDays(e.target.value)}
                        className="w-full rounded-xl border border-gray-300 bg-white p-3 text-base focus:border-purple-500 outline-none shadow-sm text-center"
                    />
                </div>
                <div className="flex gap-2">
                    {editingId && (
                        <button
                            type="button"
                            onClick={resetForm}
                            className="bg-white text-gray-500 border border-gray-300 p-3 rounded-xl hover:bg-gray-100"
                            title="Annulla"
                        >
                            <CloseIcon className="w-6 h-6" />
                        </button>
                    )}
                    <button
                        type="submit"
                        className={`px-8 py-3 rounded-xl text-white font-bold transition-all shadow-md active:scale-95 flex items-center justify-center gap-2 ${editingId ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-purple-600 hover:bg-purple-700'}`}
                    >
                        {editingId ? <><Save className="w-5 h-5" /> Aggiorna</> : <><Plus className="w-5 h-5" /> Salva</>}
                    </button>
                </div>
              </div>
            </form>
          </div>

          <div className="space-y-3">
            <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1 mb-2">I Tuoi Abbonamenti & Scadenze</h4>
            {recurringExpenses.length > 0 ? (
                recurringExpenses.map((item) => {
                    const isDue = new Date(item.nextDueDate) < new Date();
                    return (
                        <div key={item.id} className={`group relative flex justify-between items-center p-4 bg-white rounded-2xl border shadow-sm hover:shadow-md transition-all ${isDue ? 'border-red-100 bg-red-50/20' : 'border-gray-100'}`}>
                            <div className="flex-1">
                                <div className="font-bold text-gray-800 text-lg flex items-center gap-2">
                                    {item.product}
                                    {isDue && <span className="bg-red-500 w-2 h-2 rounded-full animate-ping"></span>}
                                </div>
                                <div className="text-xs text-gray-500 flex flex-wrap items-center gap-4 mt-2">
                                    <span className="font-bold text-purple-700 bg-purple-100 px-2 py-0.5 rounded-lg border border-purple-200">
                                        €{item.amount.toFixed(2)} / {item.frequency}
                                    </span>
                                    <span className={`flex items-center gap-1.5 font-medium ${isDue ? 'text-red-600' : ''}`}>
                                        <CalendarClock className="w-4 h-4" />
                                        {new Date(item.nextDueDate).toLocaleDateString('it-IT')}
                                    </span>
                                    {item.reminderDays > 0 && (
                                        <span className="flex items-center gap-1.5 text-orange-600 font-bold">
                                            <Bell className="w-4 h-4" />
                                            -{item.reminderDays}gg
                                        </span>
                                    )}
                                </div>
                            </div>
                            <div className="flex gap-2 ml-4">
                                <button 
                                    onClick={() => handleEdit(item)}
                                    className="p-2.5 text-gray-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-colors"
                                    title="Modifica"
                                >
                                    <Pencil className="w-5 h-5" />
                                </button>
                                <button 
                                    onClick={() => onDeleteRecurring(item.id)}
                                    className="p-2.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-colors"
                                    title="Elimina"
                                >
                                    <Trash2 className="w-5 h-5" />
                                </button>
                            </div>
                        </div>
                    );
                })
            ) : (
                <div className="text-center py-10 text-gray-400 italic text-sm">
                    Nessun pagamento ricorrente configurato.
                </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { ShoppingItem, Store } from '../types';
import { ShoppingCart, Plus, Trash2, History, X, Store as StoreIcon, Filter, Sparkles, CheckSquare, Square, Eraser } from 'lucide-react';

interface ShoppingListManagerProps {
  items: ShoppingItem[];
  stores: Store[];
  productHistory: Record<string, string>;
  onAddItem: (product: string, store: string) => void;
  onToggleItem: (id: string) => void;
  onDeleteItem: (id: string) => void;
}

export const ShoppingListManager: React.FC<ShoppingListManagerProps> = ({
  items,
  stores,
  productHistory,
  onAddItem,
  onToggleItem,
  onDeleteItem
}) => {
  const [isOpen, setIsOpen] = useState(true); 
  const [showHistoryModal, setShowHistoryModal] = useState(false);
  const [activeStoreFilter, setActiveStoreFilter] = useState<string>('');
  const [newItemProduct, setNewItemProduct] = useState('');
  const [newItemStore, setNewItemStore] = useState(stores[0]?.name || '');

  useEffect(() => {
    if (activeStoreFilter) {
        setNewItemStore(activeStoreFilter);
    }
  }, [activeStoreFilter]);

  // Suddivisione chiara tra prodotti da acquistare e acquistati
  const { activeItems, completedItems } = useMemo(() => {
    const filtered = activeStoreFilter 
      ? items.filter(i => i.store === activeStoreFilter)
      : items;

    return {
      activeItems: filtered.filter(i => !i.completed),
      completedItems: filtered.filter(i => i.completed)
    };
  }, [items, activeStoreFilter]);

  const historyList = useMemo(() => {
    return Object.entries(productHistory).sort((a, b) => a[0].localeCompare(b[0]));
  }, [productHistory]);

  const quickSuggestions = useMemo(() => {
    const inList = new Set(items.filter(i => !i.completed).map(i => i.product.toLowerCase()));
    return historyList
        .filter(([prod]) => !inList.has(prod.toLowerCase()))
        .slice(0, 8);
  }, [historyList, items]);

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (newItemProduct.trim() && newItemStore) {
      onAddItem(newItemProduct.trim(), newItemStore);
      setNewItemProduct('');
    }
  };

  const handleHistorySelect = (product: string, defaultStore: string) => {
    const targetStore = activeStoreFilter || defaultStore;
    onAddItem(product, targetStore);
    setShowHistoryModal(false);
  };

  const handleClearCompleted = () => {
    if (confirm("Vuoi rimuovere tutti i prodotti segnati come acquistati?")) {
        completedItems.forEach(item => onDeleteItem(item.id));
    }
  };

  return (
    <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 mb-6">
      <div className="flex justify-between items-center mb-5">
        <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
          <ShoppingCart className="h-5 w-5 text-orange-500" />
          Lista della Spesa
          {activeItems.length > 0 && (
            <span className="bg-orange-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full min-w-[20px] text-center">
              {activeItems.length}
            </span>
          )}
        </h3>
        <div className="flex gap-2">
            {completedItems.length > 0 && (
                <button 
                    onClick={handleClearCompleted}
                    className="text-gray-400 hover:text-red-500 p-2 rounded-lg hover:bg-red-50 transition-colors"
                    title="Svuota acquistati"
                >
                    <Eraser className="w-5 h-5" />
                </button>
            )}
            <button 
                onClick={() => setIsOpen(!isOpen)}
                className="text-orange-500 hover:text-orange-700 text-sm font-semibold px-2"
            >
                {isOpen ? 'Nascondi' : 'Mostra'}
            </button>
        </div>
      </div>

      {isOpen && (
        <div className="animate-in fade-in slide-in-from-top-2 duration-200">

          {/* Suggerimenti Veloci dallo Storico */}
          {quickSuggestions.length > 0 && (
            <div className="mb-6">
              <div className="flex items-center gap-1.5 mb-2 px-1">
                <Sparkles className="h-3.5 w-3.5 text-orange-400" />
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Suggerimenti dallo storico</span>
              </div>
              <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2">
                {quickSuggestions.map(([prod, store]) => (
                  <button
                    key={prod}
                    onClick={() => handleHistorySelect(prod, store)}
                    className="flex-shrink-0 bg-orange-50/50 border border-orange-100 hover:border-orange-400 hover:bg-white px-3 py-2 rounded-xl text-sm font-medium text-gray-700 transition-all flex items-center gap-1.5 whitespace-nowrap"
                  >
                    <Plus className="h-3.5 w-3.5 text-orange-500" />
                    {prod}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Selettore Negozio */}
          <div className="mb-5 flex gap-2 overflow-x-auto pb-2 no-scrollbar">
              <button
                  onClick={() => setActiveStoreFilter('')}
                  className={`whitespace-nowrap px-4 py-1.5 rounded-full text-xs font-bold border transition-all ${
                      activeStoreFilter === '' 
                      ? 'bg-orange-500 text-white border-orange-600 shadow-sm' 
                      : 'bg-white text-gray-400 border-gray-200 hover:text-orange-500'
                  }`}
              >
                  TUTTI I NEGOZI
              </button>
              {stores.map(s => (
                  <button
                      key={s.id}
                      onClick={() => setActiveStoreFilter(s.name)}
                      className={`whitespace-nowrap px-4 py-1.5 rounded-full text-xs font-bold border transition-all ${
                          activeStoreFilter === s.name
                          ? 'bg-orange-500 text-white border-orange-600 shadow-sm' 
                          : 'bg-white text-gray-400 border-gray-200 hover:text-orange-500'
                      }`}
                  >
                      {s.name.toUpperCase()}
                  </button>
              ))}
          </div>

          <form onSubmit={handleAdd} className="flex flex-col gap-3 mb-8">
            <div className="flex gap-2">
                <input
                    type="text"
                    value={newItemProduct}
                    onChange={(e) => setNewItemProduct(e.target.value)}
                    placeholder="Cosa vuoi aggiungere?"
                    className="flex-1 rounded-xl border border-gray-300 bg-gray-50 p-3.5 text-base focus:border-orange-500 focus:ring-2 focus:ring-orange-100 outline-none transition-all"
                />
                <button
                    type="button"
                    onClick={() => setShowHistoryModal(true)}
                    className="bg-gray-100 text-gray-400 px-3.5 rounded-xl hover:bg-orange-50 hover:text-orange-500 transition-colors border border-gray-200"
                    title="Apri storico completo"
                >
                    <History className="h-6 w-6" />
                </button>
            </div>
            <div className="flex gap-2">
                <select
                    value={newItemStore}
                    onChange={(e) => setNewItemStore(e.target.value)}
                    className="flex-1 rounded-xl border border-gray-300 bg-gray-50 p-3.5 text-base focus:border-orange-500 outline-none appearance-none"
                >
                    {stores.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                </select>
                <button
                    type="submit"
                    disabled={!newItemProduct.trim()}
                    className="bg-orange-500 text-white px-6 rounded-xl font-bold hover:bg-orange-600 transition-all disabled:opacity-50 active:scale-95 shadow-lg flex items-center justify-center"
                >
                    <Plus className="h-6 w-6" />
                </button>
            </div>
          </form>

          {/* Prodotti da Acquistare */}
          <div className="space-y-3">
            <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1 mb-2">Da Acquistare</h4>
            {activeItems.map(item => (
                <div key={item.id} className="flex items-center justify-between p-4 bg-white rounded-2xl border border-gray-100 shadow-sm hover:border-orange-200 transition-all group animate-in fade-in slide-in-from-left-2">
                    <div className="flex items-center gap-4 cursor-pointer flex-1" onClick={() => onToggleItem(item.id)}>
                        <div className="text-orange-500 group-hover:scale-110 transition-transform">
                           <Square className="w-6 h-6" />
                        </div>
                        <div>
                            <span className="text-lg font-semibold text-gray-800">{item.product}</span>
                            <div className="flex items-center gap-1 text-[10px] text-gray-400 font-bold uppercase mt-0.5">
                                <StoreIcon className="w-3 h-3" /> {item.store}
                            </div>
                        </div>
                    </div>
                    <button onClick={() => onDeleteItem(item.id)} className="p-2 text-gray-300 hover:text-red-500 transition-colors">
                        <Trash2 className="w-5 h-5" />
                    </button>
                </div>
            ))}

            {activeItems.length === 0 && (
                <div className="text-center py-12 bg-gray-50/50 rounded-2xl border border-dashed border-gray-200">
                    <p className="text-sm text-gray-400 italic">Nessun prodotto in lista per questo filtro.</p>
                </div>
            )}

            {/* Prodotti Acquistati */}
            {completedItems.length > 0 && (
                <div className="mt-10 pt-6 border-t border-gray-100">
                    <div className="flex justify-between items-center mb-3">
                        <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Già nel carrello</h4>
                        <span className="text-[10px] bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded-full font-bold">PRESI: {completedItems.length}</span>
                    </div>
                    <div className="space-y-2">
                        {completedItems.map(item => (
                            <div key={item.id} className="flex items-center justify-between p-3 bg-gray-50/50 rounded-xl border border-gray-100 transition-opacity hover:opacity-100 opacity-70">
                                <div className="flex items-center gap-3 cursor-pointer flex-1" onClick={() => onToggleItem(item.id)}>
                                    <CheckSquare className="w-6 h-6 text-emerald-500" />
                                    <span className="text-base font-medium text-gray-400 line-through">{item.product}</span>
                                </div>
                                <button onClick={() => onDeleteItem(item.id)} className="p-2 text-gray-300 hover:text-red-400">
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            )}
          </div>
        </div>
      )}

      {/* Storico Completo Popover */}
      {showHistoryModal && (
        <div className="fixed inset-0 bg-black/70 z-[60] flex items-center justify-center p-4 animate-in fade-in backdrop-blur-sm">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm max-h-[80vh] flex flex-col overflow-hidden">
                <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                    <div className="flex items-center gap-2">
                        <History className="w-5 h-5 text-orange-500" />
                        <h3 className="font-bold text-lg text-gray-800">Cerca nello Storico</h3>
                    </div>
                    <button onClick={() => setShowHistoryModal(false)} className="p-2 bg-white rounded-full shadow-sm hover:bg-gray-100">
                        <X className="h-5 w-5 text-gray-600" />
                    </button>
                </div>
                <div className="p-2 overflow-y-auto flex-1 bg-white">
                    <div className="grid grid-cols-1 gap-1">
                        {historyList.map(([prod, lastStore]) => (
                            <button
                                key={prod}
                                onClick={() => handleHistorySelect(prod, lastStore)}
                                className="w-full text-left px-5 py-4 hover:bg-orange-50 rounded-2xl flex justify-between items-center group transition-all"
                            >
                                <div>
                                    <div className="text-base font-bold text-gray-800 group-hover:text-orange-600">{prod}</div>
                                    <div className="text-[10px] text-gray-400 font-bold uppercase mt-1 flex items-center gap-1">
                                        <StoreIcon className="w-3 h-3" /> {lastStore}
                                    </div>
                                </div>
                                <div className="bg-orange-100 p-2 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity">
                                    <Plus className="w-4 h-4 text-orange-600" />
                                </div>
                            </button>
                        ))}
                        {historyList.length === 0 && (
                            <div className="text-center py-16">
                                <History className="w-12 h-12 text-gray-200 mx-auto mb-3" />
                                <p className="text-sm text-gray-400 italic px-10">Fai la tua prima spesa per costruire lo storico prodotti!</p>
                            </div>
                        )}
                    </div>
                </div>
                <div className="p-4 bg-gray-50 border-t border-gray-100">
