  return (data || []).map((r: any) => ({ 
    id: r.id, 
    product: r.product, 
    amount: Number(r.amount), 
    store: r.store, 
    frequency: r.frequency, 
    nextDueDate: r.next_due_date, 
    reminderDays: r.reminder_days,
    customFields: r.custom_fields || [] // Recupero campi personalizzati
  }));
};

