                {isRegistering ? "Hai già un account? Accedi" : "Nuovo utente? Registrati"}
              </button>
              <button type="button" onClick={() => { setAuthMode('google'); setError(''); setSuccess(''); }} className="text-gray-400 font-bold text-xs">Torna indietro</button>
            </div>
          </form>
        )}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { ShoppingItem, Store } from '../types';
import { ShoppingCart, Plus, Trash2, History, X, Store as StoreIcon, Filter, Sparkles, CheckSquare, Square, Eraser } from 'lucide-react';

interface ShoppingListManagerProps {
  items: ShoppingItem[];
  stores: Store[];
  productHistory: Record<string, string>;
  onAddItem: (product: string, store: string) => void;
  onToggleItem: (id: string) => void;
  onDeleteItem: (id: string) => void;
}

export const ShoppingListManager: React.FC<ShoppingListManagerProps> = ({
  items,
  stores,
  productHistory,
  onAddItem,
  onToggleItem,
  onDeleteItem
}) => {
  const [isOpen, setIsOpen] = useState(true); 
  const [showHistoryModal, setShowHistoryModal] = useState(false);
  const [activeStoreFilter, setActiveStoreFilter] = useState<string>('');
  const [newItemProduct, setNewItemProduct] = useState('');
  const [newItemStore, setNewItemStore] = useState(stores[0]?.name || '');

  // Quando l'utente inizia a scrivere un prodotto, suggeriamo l'ultimo negozio usato se disponibile
  const handleProductInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setNewItemProduct(val);
    if (productHistory[val]) {
        setNewItemStore(productHistory[val]);
    }
  };

  useEffect(() => {
    if (activeStoreFilter) {
        setNewItemStore(activeStoreFilter);
    }
  }, [activeStoreFilter]);

  const { activeItems, completedItems } = useMemo(() => {
    const filtered = activeStoreFilter 
      ? items.filter(i => i.store === activeStoreFilter)
      : items;

    return {
      activeItems: filtered.filter(i => !i.completed),
      completedItems: filtered.filter(i => i.completed)
    };
  }, [items, activeStoreFilter]);

  const historyList = useMemo(() => {
    return Object.entries(productHistory).sort((a, b) => a[0].localeCompare(b[0]));
  }, [productHistory]);

  const quickSuggestions = useMemo(() => {
    const inList = new Set(items.filter(i => !i.completed).map(i => i.product.toLowerCase()));
    return historyList
        .filter(([prod]) => !inList.has(prod.toLowerCase()))
        .slice(0, 10);
  }, [historyList, items]);

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (newItemProduct.trim() && newItemStore) {
      onAddItem(newItemProduct.trim(), newItemStore);
      setNewItemProduct('');
    }
  };

  const handleHistorySelect = (product: string, defaultStore: string) => {
    const targetStore = activeStoreFilter || defaultStore || stores[0]?.name;
    onAddItem(product, targetStore);
    setShowHistoryModal(false);
  };

  const handleClearCompleted = () => {
    if (confirm("Vuoi rimuovere tutti i prodotti segnati come acquistati?")) {
        completedItems.forEach(item => onDeleteItem(item.id));
    }
  };

  return (
    <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 mb-6">
      <div className="flex justify-between items-center mb-5">
        <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
          <ShoppingCart className="h-5 w-5 text-orange-500" />
          Lista della Spesa
          {activeItems.length > 0 && (
            <span className="bg-orange-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full min-w-[20px] text-center">
              {activeItems.length}
            </span>
          )}
        </h3>
        <div className="flex gap-2">
            {completedItems.length > 0 && (
                <button 
                    onClick={handleClearCompleted}
                    className="text-gray-400 hover:text-red-500 p-2 rounded-lg hover:bg-red-50 transition-colors"
                    title="Svuota acquistati"
                >
                    <Eraser className="w-5 h-5" />
                </button>
            )}
            <button 
                onClick={() => setIsOpen(!isOpen)}
                className="text-orange-500 hover:text-orange-700 text-sm font-semibold px-2"
            >
                {isOpen ? 'Nascondi' : 'Mostra'}
            </button>
        </div>
      </div>

      {isOpen && (
        <div className="animate-in fade-in slide-in-from-top-2 duration-200">

          {/* Suggerimenti dallo Storico */}
          {quickSuggestions.length > 0 && (
            <div className="mb-6">
              <div className="flex items-center gap-1.5 mb-2 px-1">
                <Sparkles className="h-3.5 w-3.5 text-orange-400" />
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Più acquistati</span>
              </div>
              <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2">
                {quickSuggestions.map(([prod, store]) => (
                  <button
                    key={prod}
                    onClick={() => handleHistorySelect(prod, store)}
                    className="flex-shrink-0 bg-orange-50/50 border border-orange-100 hover:border-orange-400 hover:bg-white px-3 py-2 rounded-xl text-sm font-medium text-gray-700 transition-all flex flex-col items-start gap-0.5 whitespace-nowrap"
                  >
                    <div className="flex items-center gap-1">
                        <Plus className="h-3 w-3 text-orange-500" />
                        {prod}
                    </div>
                    <span className="text-[9px] text-gray-400 uppercase font-bold">{store}</span>
                  </button>
                ))}
              </div>
            </div>
          )}

          <div className="mb-5 flex gap-2 overflow-x-auto pb-2 no-scrollbar">
              <button
                  onClick={() => setActiveStoreFilter('')}
                  className={`whitespace-nowrap px-4 py-1.5 rounded-full text-xs font-bold border transition-all ${
                      activeStoreFilter === '' 
                      ? 'bg-orange-500 text-white border-orange-600 shadow-sm' 
                      : 'bg-white text-gray-400 border-gray-200 hover:text-orange-500'
                  }`}
              >
                  TUTTI
              </button>
              {stores.map(s => (
                  <button
                      key={s.id}
                      onClick={() => setActiveStoreFilter(s.name)}
                      className={`whitespace-nowrap px-4 py-1.5 rounded-full text-xs font-bold border transition-all ${
                          activeStoreFilter === s.name
                          ? 'bg-orange-500 text-white border-orange-600 shadow-sm' 
                          : 'bg-white text-gray-400 border-gray-200 hover:text-orange-500'
                      }`}
                  >
                      {s.name.toUpperCase()}
                  </button>
              ))}
          </div>

          <form onSubmit={handleAdd} className="flex flex-col gap-3 mb-8">
            <div className="flex gap-2">
                <input
                    type="text"
                    value={newItemProduct}
                    onChange={handleProductInputChange}
                    placeholder="Es. Latte, Uova..."
                    className="flex-1 rounded-xl border border-gray-300 bg-gray-50 p-3.5 text-base focus:border-orange-500 focus:ring-2 focus:ring-orange-100 outline-none transition-all"
                />
                <button
                    type="button"
                    onClick={() => setShowHistoryModal(true)}
                    className="bg-gray-100 text-gray-400 px-3.5 rounded-xl hover:bg-orange-50 hover:text-orange-500 transition-colors border border-gray-200"
                    title="Storico completo"
                >
                    <History className="h-6 w-6" />
                </button>
            </div>
            <div className="flex gap-2">
                <select
                    value={newItemStore}
                    onChange={(e) => setNewItemStore(e.target.value)}
                    className="flex-1 rounded-xl border border-gray-300 bg-gray-50 p-3.5 text-base focus:border-orange-500 outline-none appearance-none"
                >
                    {stores.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                </select>
                <button
                    type="submit"
                    disabled={!newItemProduct.trim()}
                    className="bg-orange-500 text-white px-8 rounded-xl font-bold hover:bg-orange-600 transition-all disabled:opacity-50 active:scale-95 shadow-lg"
                >
                    Aggiungi
                </button>
            </div>
          </form>

          <div className="space-y-3">
            <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1 mb-2">Da Acquistare</h4>
            {activeItems.map(item => (
                <div key={item.id} className="flex items-center justify-between p-4 bg-white rounded-2xl border border-gray-100 shadow-sm group">
                    <div className="flex items-center gap-4 cursor-pointer flex-1" onClick={() => onToggleItem(item.id)}>
                        <div className="text-orange-500">
                           <Square className="w-6 h-6" />
                        </div>
                        <div>
                            <span className="text-lg font-semibold text-gray-800">{item.product}</span>
                            <div className="flex items-center gap-1 text-[10px] text-gray-400 font-bold uppercase mt-0.5">
                                <StoreIcon className="w-3 h-3" /> {item.store}
                            </div>
                        </div>
                    </div>
                    <button onClick={() => onDeleteItem(item.id)} className="p-2 text-gray-300 hover:text-red-500 transition-colors">
                        <Trash2 className="w-5 h-5" />
                    </button>
                </div>
            ))}

            {activeItems.length === 0 && (
                <div className="text-center py-12 bg-gray-50/50 rounded-2xl border border-dashed border-gray-200">
                    <p className="text-sm text-gray-400 italic">Lista vuota.</p>
                </div>
            )}

            {completedItems.length > 0 && (
                <div className="mt-10 pt-6 border-t border-gray-100">
                    <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1 mb-3">Nel carrello</h4>
                    <div className="space-y-2">
                        {completedItems.map(item => (
                            <div key={item.id} className="flex items-center justify-between p-3 bg-gray-50/50 rounded-xl border border-gray-100 opacity-70">
                                <div className="flex items-center gap-3 cursor-pointer flex-1" onClick={() => onToggleItem(item.id)}>
                                    <CheckSquare className="w-6 h-6 text-emerald-500" />
                                    <span className="text-base font-medium text-gray-400 line-through">{item.product}</span>
                                </div>
                                <button onClick={() => onDeleteItem(item.id)} className="p-2 text-gray-300 hover:text-red-400">
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            )}
          </div>
        </div>
      )}

      {showHistoryModal && (
        <div className="fixed inset-0 bg-black/70 z-[60] flex items-center justify-center p-4 animate-in fade-in backdrop-blur-sm">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm max-h-[80vh] flex flex-col overflow-hidden">
                <div className="p-5 border-b border-gray-100 flex justify-between items-center">
                    <h3 className="font-bold text-lg text-gray-800">Storico Acquisti</h3>
                    <button onClick={() => setShowHistoryModal(false)} className="p-2 bg-gray-100 rounded-full">
                        <X className="h-5 w-5 text-gray-600" />
                    </button>
                </div>
                <div className="p-2 overflow-y-auto flex-1">
                    {historyList.map(([prod, lastStore]) => (
                        <button
                            key={prod}
                            onClick={() => handleHistorySelect(prod, lastStore)}
                            className="w-full text-left px-5 py-4 hover:bg-orange-50 rounded-2xl flex justify-between items-center group transition-all"
                        >
                            <div>
                                <div className="text-base font-bold text-gray-800">{prod}</div>
                                <div className="text-[10px] text-gray-400 font-bold uppercase mt-1 flex items-center gap-1">
                                    <StoreIcon className="w-3 h-3" /> {lastStore}
                                </div>
                            </div>
                            <Plus className="w-5 h-5 text-gray-300 group-hover:text-orange-500" />
                        </button>
                    ))}
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, Income, CategoryDefinition, ShoppingItem, OfferPreferences, RecurringExpense, SyncData, CustomField } from './types';
import * as SupabaseService from './services/supabaseService';
import { LoginScreen } from './components/LoginScreen';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { StoreManager } from './components/StoreManager';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { ShoppingListManager } from './components/ShoppingListManager';

function App() {
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [shoppingList, setShoppingList] = useState<ShoppingItem[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Deriva lo storico dei prodotti dalle spese reali per alimentare la Shopping List
  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const handleAddShoppingItem = async (product: string, store: string) => {
    if (!familyProfile) return;
    const newItem: ShoppingItem = { id: crypto.randomUUID(), product, store, completed: false };
    setShoppingList(prev => [...prev, newItem]);
    await SupabaseService.addShoppingItemToSupabase(familyProfile.id, newItem);
  };

  const handleToggleShoppingItem = async (id: string) => {
    const item = shoppingList.find(i => i.id === id);
    if (!item) return;
    const updated = { ...item, completed: !item.completed };
    setShoppingList(prev => prev.map(i => i.id === id ? updated : i));
    await SupabaseService.updateShoppingItemInSupabase(updated);
  };

  const handleDeleteShoppingItem = async (id: string) => {
    setShoppingList(prev => prev.filter(i => i.id !== id));
    await SupabaseService.deleteShoppingItemFromSupabase(id);
  };

  const handleAddRecurring = async (product: string, amount: number, store: string, frequency: any, nextDate: string, reminderDays: number, customFields: CustomField[]) => {
    if (!familyProfile) return;
    const newItem: RecurringExpense = { 
      id: crypto.randomUUID(), 
      product, 
      amount, 
      store, 
      frequency, 
      nextDueDate: nextDate, 
      reminderDays,
      customFields
    };
    setRecurringExpenses(prev => [...prev, newItem]);
    await SupabaseService.addRecurringToSupabase(familyProfile.id, newItem);
  };

  const handleUpdateRecurring = async (updated: RecurringExpense) => {
    setRecurringExpenses(prev => prev.map(r => r.id === updated.id ? updated : r));
    await SupabaseService.updateRecurringInSupabase(updated);
  };

  const handleDeleteRecurring = async (id: string) => {
    setRecurringExpenses(prev => prev.filter(r => r.id !== id));
    await SupabaseService.deleteRecurringFromSupabase(id);
  };

  if (!familyProfile) {
    return <LoginScreen onSetupComplete={setFamilyProfile} isSupabaseAuth={false} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 pb-20">
      <header className="bg-emerald-600 text-white p-6 shadow-lg mb-8">
        <div className="max-w-6xl mx-auto flex justify-between items-center">
          <h1 className="text-2xl font-bold">{familyProfile.familyName}</h1>
          <div className="text-sm bg-white/20 px-3 py-1 rounded-full backdrop-blur-sm">
             ID: <code className="font-mono">{familyProfile.id.split('-')[0]}</code>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 space-y-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-6">
            <ShoppingListManager 
              items={shoppingList}
              stores={stores}
              productHistory={productHistory}
              onAddItem={handleAddShoppingItem}
              onToggleItem={handleToggleShoppingItem}
              onDeleteItem={handleDeleteShoppingItem}
            />

            <DueExpensesAlert 
              dueExpenses={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date())} 
              onProcessExpense={() => {}} 
            />

            <ExpenseForm 
              stores={stores} 
              members={familyProfile.members} 
              existingProducts={Object.keys(productHistory)} 
              productHistory={productHistory} 
              onAddExpense={async (p, q, u, t, s) => {
                  const newExp: Expense = {
                      id: crypto.randomUUID(),
                      product: p, quantity: q, unitPrice: u, total: t, store: s,
                      date: new Date().toISOString(), category: 'Altro'
                  };
                  setExpenses(prev => [newExp, ...prev]);
                  await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
              }} 
              isAnalyzing={isAnalyzing} 
            />

            <ExpenseList 
              expenses={expenses} 
              stores={stores} 
              onDelete={async (id) => {
                  setExpenses(prev => prev.filter(e => e.id !== id));
                  await SupabaseService.deleteExpenseFromSupabase(id);
              }} 
              onEdit={() => {}} 
            />
          </div>

          <div className="space-y-6">
            <RecurringManager 
              recurringExpenses={recurringExpenses}
              stores={stores}
              onAddRecurring={handleAddRecurring}
              onUpdateRecurring={handleUpdateRecurring}
              onDeleteRecurring={handleDeleteRecurring}
            />
            <StoreManager onAddStore={async (name) => {
              const newStore = { id: crypto.randomUUID(), name };
              setStores(prev => [...prev, newStore]);
              await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
            }} />
          </div>
        </div>
        <Analytics expenses={expenses} />
        <AIInsight expenses={expenses} />
      </main>
    </div>
  );
}

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, Income, CategoryDefinition, ShoppingItem, OfferPreferences, RecurringExpense, SyncData, CustomField, Member } from './types';
import * as SupabaseService from './services/supabaseService';
import { LoginScreen } from './components/LoginScreen';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { StoreManager } from './components/StoreManager';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { ShoppingListManager } from './components/ShoppingListManager';
import { Loader2 } from 'lucide-react';

function App() {
  const [user, setUser] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [shoppingList, setShoppingList] = useState<ShoppingItem[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [initialLoading, setInitialLoading] = useState(true);

  // 1. Controllo sessione all'avvio
  useEffect(() => {
    const checkSession = async () => {
      const currentUser = await SupabaseService.getCurrentUser();
      if (currentUser) {
        setUser(currentUser);
        const { data: memberData } = await SupabaseService.getFamilyForUser(currentUser.id);
        if (memberData?.family_id) {
          await loadFamilyData(memberData.family_id);
        }
      }
      setInitialLoading(false);
    };
    checkSession();
  }, []);

  const loadFamilyData = async (familyId: string) => {
    try {
      const [profile, exps, recs, shops, strs] = await Promise.all([
        SupabaseService.getFamilyProfile(familyId),
        SupabaseService.fetchExpenses(familyId),
        SupabaseService.fetchRecurring(familyId),
        SupabaseService.fetchShoppingList(familyId),
        SupabaseService.fetchStores(familyId)
      ]);

      if (profile.data) {
        const members = await SupabaseService.fetchFamilyMembers(familyId);
        setFamilyProfile({
          id: profile.data.id,
          familyName: profile.data.family_name,
          members: members,
          createdAt: new Date(profile.data.created_at).getTime()
        });
      }
      setExpenses(exps);
      setRecurringExpenses(recs);
      setShoppingList(shops);
      if (strs && strs.length > 0) setStores(strs);
    } catch (err) {
      console.error("Errore caricamento dati:", err);
    }
  };

  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const handleAddShoppingItem = async (product: string, store: string) => {
    if (!familyProfile) return;
    const newItem: ShoppingItem = { id: crypto.randomUUID(), product, store, completed: false };
    setShoppingList(prev => [...prev, newItem]);
    await SupabaseService.addShoppingItemToSupabase(familyProfile.id, newItem);
  };

  const handleToggleShoppingItem = async (id: string) => {
    const item = shoppingList.find(i => i.id === id);
    if (!item) return;
    const updated = { ...item, completed: !item.completed };
    setShoppingList(prev => prev.map(i => i.id === id ? updated : i));
    await SupabaseService.updateShoppingItemInSupabase(updated);
  };

  const handleDeleteShoppingItem = async (id: string) => {
    setShoppingList(prev => prev.filter(i => i.id !== id));
    await SupabaseService.deleteShoppingItemFromSupabase(id);
  };

  const handleAddRecurring = async (product: string, amount: number, store: string, frequency: any, nextDate: string, reminderDays: number, customFields: CustomField[]) => {
    if (!familyProfile) return;
    const newItem: RecurringExpense = { 
      id: crypto.randomUUID(), 
      product, 
      amount, 
      store, 
      frequency, 
      nextDueDate: nextDate, 
      reminderDays,
      customFields
    };
    setRecurringExpenses(prev => [...prev, newItem]);
    await SupabaseService.addRecurringToSupabase(familyProfile.id, newItem);
  };

  const handleUpdateRecurring = async (updated: RecurringExpense) => {
    setRecurringExpenses(prev => prev.map(r => r.id === updated.id ? updated : r));
    await SupabaseService.updateRecurringInSupabase(updated);
  };

  const handleDeleteRecurring = async (id: string) => {
    setRecurringExpenses(prev => prev.filter(r => r.id !== id));
    await SupabaseService.deleteRecurringFromSupabase(id);
  };

  const handleSetupComplete = async (profile: FamilyProfile) => {
    // Quando l'utente crea o si unisce a una famiglia
    setFamilyProfile(profile);
    if (user) {
      // Se l'utente è nuovo, lo aggiungiamo come membro
      const { data: memberExists } = await SupabaseService.getFamilyForUser(user.id);
      if (!memberExists) {
        await SupabaseService.joinFamily(user.id, profile.id, user.email.split('@')[0], true);
      }
    }
    await loadFamilyData(profile.id);
  };

  if (initialLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
      </div>
    );
  }

  if (!user || !familyProfile) {
    return <LoginScreen 
      onSetupComplete={handleSetupComplete} 
      onUserLogin={setUser}
      isSupabaseAuth={!!user} 
    />;
  }

  return (
    <div className="min-h-screen bg-gray-50 pb-20">
      <header className="bg-emerald-600 text-white p-6 shadow-lg mb-8">
        <div className="max-w-6xl mx-auto flex justify-between items-center">
          <div>
            <h1 className="text-2xl font-bold">{familyProfile.familyName}</h1>
            <p className="text-xs text-emerald-100 opacity-80">{user?.email}</p>
          </div>
          <div className="flex items-center gap-4">
            <div className="text-sm bg-white/20 px-3 py-1 rounded-full backdrop-blur-sm hidden sm:block">
               ID: <code className="font-mono">{familyProfile.id.split('-')[0]}</code>
            </div>
            <button 
              onClick={async () => {
                await SupabaseService.signOut();
                window.location.reload();
              }}
              className="text-xs font-bold bg-red-500/20 hover:bg-red-500/40 px-3 py-1 rounded-lg transition-colors"
            >
              Esci
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 space-y-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-6">
            <ShoppingListManager 
              items={shoppingList}
              stores={stores}
              productHistory={productHistory}
              onAddItem={handleAddShoppingItem}
              onToggleItem={handleToggleShoppingItem}
              onDeleteItem={handleDeleteShoppingItem}
            />

            <DueExpensesAlert 
              dueExpenses={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date())} 
              onProcessExpense={() => {}} 
            />

            <ExpenseForm 
              stores={stores} 
              members={familyProfile.members} 
              existingProducts={Object.keys(productHistory)} 
              productHistory={productHistory} 
              onAddExpense={async (p, q, u, t, s) => {
                  const newExp: Expense = {
                      id: crypto.randomUUID(),
                      product: p, quantity: q, unitPrice: u, total: t, store: s,
                      date: new Date().toISOString(), category: 'Altro'
                  };
                  setExpenses(prev => [newExp, ...prev]);
                  await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
              }} 
              isAnalyzing={isAnalyzing} 
            />

            <ExpenseList 
              expenses={expenses} 
              stores={stores} 
              onDelete={async (id) => {
                  setExpenses(prev => prev.filter(e => e.id !== id));
                  await SupabaseService.deleteExpenseFromSupabase(id);
              }} 
              onEdit={() => {}} 
            />
          </div>

          <div className="space-y-6">
            <RecurringManager 
              recurringExpenses={recurringExpenses}
              stores={stores}
              onAddRecurring={handleAddRecurring}
              onUpdateRecurring={handleUpdateRecurring}
              onDeleteRecurring={handleDeleteRecurring}
            />
            <StoreManager onAddStore={async (name) => {
              const newStore = { id: crypto.randomUUID(), name };
              setStores(prev => [...prev, newStore]);
              await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
            }} />
          </div>
        </div>
        <Analytics expenses={expenses} />
        <AIInsight expenses={expenses} />
      </main>
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { FamilyProfile } from '../types';
import { Sparkles, Loader2, Mail, Lock, LogIn, UserPlus, AlertCircle, CheckCircle2, ArrowRight } from 'lucide-react';
import { signInWithGoogle, signInWithEmail, signUpWithEmail } from '../services/supabaseService';
import { supabase } from '../src/supabaseClient';

interface LoginScreenProps {
  onSetupComplete: (profile: FamilyProfile) => void;
  onUserLogin?: (user: any) => void;
  isSupabaseAuth?: boolean;
}

export const LoginScreen: React.FC<LoginScreenProps> = ({ onSetupComplete, onUserLogin, isSupabaseAuth }) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [familyName, setFamilyName] = useState('');
  const [familyIdToJoin, setFamilyIdToJoin] = useState('');
  const [mode, setMode] = useState<'create' | 'join'>('create');
  const [authMode, setAuthMode] = useState<'google' | 'email'>('google');
  const [isRegistering, setIsRegistering] = useState(false);

  const handleEmailAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSuccess('');

    try {
      if (isRegistering) {
        const { data, error: signUpErr } = await signUpWithEmail(email, password);
        if (signUpErr) {
            if (signUpErr.message.toLowerCase().includes("user already registered") || signUpErr.status === 422) {
                setError("Questa email è già registrata. Prova ad accedere invece di registrarti.");
                setLoading(false);
                return;
            }
            throw signUpErr;
        }

        if (data.session) {
          setSuccess("Registrazione completata! Accesso in corso...");
          if (onUserLogin) onUserLogin(data.user);
        } else if (data.user) {
          setSuccess("Account creato! Controlla la tua email per confermare l'indirizzo.");
          setTimeout(() => setIsRegistering(false), 3000);
        }
      } else {
        const { data, error: signInErr } = await signInWithEmail(email, password);
        if (signInErr) {
          if (signInErr.message.includes("Invalid login credentials")) {
             throw new Error("Email o password errati. Riprova.");
          }
          if (signInErr.message.includes("Email not confirmed")) {
            throw new Error("L'email non è stata confermata. Controlla la tua posta.");
          }
          throw signInErr;
        }
        if (data.user && onUserLogin) {
          onUserLogin(data.user);
        }
      }
    } catch (err: any) {
      console.error("Auth Error:", err);
      setError(err.message || "Errore durante l'autenticazione.");
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLoading(true);
    setError('');
    try {
      await signInWithGoogle();
    } catch (err: any) {
      setError("Errore login Google. Verifica la configurazione.");
      setLoading(false);
    }
  };

  const handleCreateSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!familyName) return;
    setLoading(true);
    try {
      const familyId = crypto.randomUUID();
      const newProfile: FamilyProfile = {
        id: familyId,
        familyName,
        members: [],
        createdAt: Date.now()
      };

      // Persistiamo su Supabase
      const { error: createErr } = await supabase.from('families').insert({
        id: familyId,
        family_name: familyName,
        created_at: new Date().toISOString()
      });

      if (createErr) throw createErr;

      onSetupComplete(newProfile);
    } catch (err: any) {
      setError("Errore creazione gruppo: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleJoinSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!familyIdToJoin) return;
    setLoading(true);
    setError('');
    try {
      const { data: profile, error: fetchErr } = await supabase
        .from('families')
        .select('*')
        .eq('id', familyIdToJoin.trim())
        .single();

      if (fetchErr || !profile) throw new Error("Codice famiglia non trovato. Verifica di averlo copiato correttamente.");

      onSetupComplete({
        id: profile.id,
        familyName: profile.family_name,
        members: [], // Verranno caricati da App.tsx
        createdAt: new Date(profile.created_at).getTime()
      });
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  if (isSupabaseAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
        <div className="bg-white p-8 rounded-3xl shadow-xl max-w-md w-full border border-gray-100 animate-in fade-in zoom-in">
          <h2 className="text-2xl font-bold text-gray-800 mb-2 text-center">Configurazione Famiglia</h2>
          <p className="text-gray-500 text-sm text-center mb-6">Accesso effettuato! Ora crea un gruppo familiare o unisciti a uno esistente.</p>
          <div className="flex p-1 bg-gray-100 rounded-xl mb-6">
            <button onClick={() => setMode('create')} className={`flex-1 py-2.5 text-sm font-bold rounded-lg transition-all ${mode === 'create' ? 'bg-white text-emerald-700 shadow-sm' : 'text-gray-500'}`}>Crea Nuovo</button>
            <button onClick={() => setMode('join')} className={`flex-1 py-2.5 text-sm font-bold rounded-lg transition-all ${mode === 'join' ? 'bg-white text-emerald-700 shadow-sm' : 'text-gray-500'}`}>Unisciti</button>
          </div>
          {error && <div className="bg-red-50 text-red-600 p-4 rounded-xl text-xs mb-4 border border-red-100 flex items-center gap-2"><AlertCircle className="w-4 h-4" /> {error}</div>}
          {mode === 'create' ? (
            <form onSubmit={handleCreateSubmit} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Nome del Gruppo</label>
                <input type="text" value={familyName} onChange={(e) => setFamilyName(e.target.value)} placeholder="es. Famiglia Rossi" className="w-full rounded-xl border border-gray-300 p-4 outline-none focus:border-emerald-500 bg-gray-50 shadow-sm" required />
              </div>
              <button type="submit" disabled={loading} className="w-full bg-emerald-600 text-white font-bold py-4 rounded-xl shadow-md transition-all hover:bg-emerald-700 active:scale-95 flex items-center justify-center">
                {loading ? <Loader2 className="animate-spin w-5 h-5" /> : 'Crea e Inizia'}
              </button>
            </form>
          ) : (
            <form onSubmit={handleJoinSubmit} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Codice ID Famiglia</label>
                <input type="text" value={familyIdToJoin} onChange={(e) => setFamilyIdToJoin(e.target.value)} placeholder="Incolla il codice ID qui" className="w-full rounded-xl border border-gray-300 p-4 outline-none focus:border-emerald-500 font-mono text-sm bg-gray-50 shadow-sm" required />
              </div>
              <button type="submit" disabled={loading} className="w-full bg-blue-600 text-white font-bold py-4 rounded-xl shadow-md transition-all hover:bg-blue-700 active:scale-95 flex items-center justify-center">
                {loading ? <Loader2 className="animate-spin w-5 h-5" /> : 'Entra nel Gruppo'}
              </button>
            </form>
          )}
          <button 
            onClick={async () => {
              await supabase.auth.signOut();
              window.location.reload();
            }}
            className="w-full mt-6 text-gray-400 text-xs font-medium hover:text-gray-600"
          >
            Usa un altro account
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
      <div className="bg-white p-10 rounded-3xl shadow-2xl max-w-md w-full border border-gray-100 text-center">
        <div className="bg-emerald-500 w-20 h-20 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-xl">
          <Sparkles className="w-10 h-10 text-white" />
        </div>
        <h2 className="text-3xl font-extrabold text-gray-900 mb-2">Spese Famiglia AI</h2>
        <p className="text-gray-500 mb-8">Gestione bilancio in tempo reale.</p>

        {authMode === 'google' ? (
          <div className="space-y-4">
            <button onClick={handleGoogleLogin} disabled={loading} className="w-full flex items-center justify-center gap-4 bg-white border-2 border-gray-100 hover:border-emerald-500 py-4 px-6 rounded-2xl font-bold transition-all shadow-sm">
              {loading ? <Loader2 className="w-6 h-6 animate-spin text-emerald-600" /> : <><img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" alt="Google" className="w-6 h-6" /> Accedi con Google</>}
            </button>
            <div className="relative py-4">
              <div className="absolute inset-0 flex items-center"><span className="w-full border-t border-gray-100"></span></div>
              <div className="relative flex justify-center text-xs uppercase"><span className="bg-white px-2 text-gray-400">Oppure</span></div>
            </div>
            <button onClick={() => setAuthMode('email')} className="w-full flex items-center justify-center gap-2 text-emerald-600 font-bold text-sm bg-emerald-50 py-3 rounded-xl hover:bg-emerald-100 transition-colors">
              <Mail className="w-4 h-4" /> Usa Email e Password
            </button>
          </div>
        ) : (
          <form onSubmit={handleEmailAuth} className="space-y-4 text-left animate-in fade-in slide-in-from-bottom-2">
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Email</label>
              <div className="relative">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="pl-12 w-full rounded-xl border border-gray-300 p-4 outline-none focus:border-emerald-500 bg-gray-50" placeholder="tua@email.com" required />
              </div>
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Password</label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="pl-12 w-full rounded-xl border border-gray-300 p-4 outline-none focus:border-emerald-500 bg-gray-50" placeholder="Minimo 6 caratteri" minLength={6} required />
              </div>
            </div>

            {error && (
                <div className="bg-red-50 text-red-600 p-4 rounded-xl text-xs border border-red-100 flex flex-col gap-2">
                    <div className="flex items-start gap-2">
                        <AlertCircle className="w-4 h-4 mt-0.5 flex-shrink-0" /> 
                        <span>{error}</span>
                    </div>
                    {error.includes("già registrata") && (
                        <button 
                            type="button" 
                            onClick={() => { setIsRegistering(false); setError(''); }}
                            className="bg-red-100 text-red-700 px-3 py-1.5 rounded-lg font-bold flex items-center justify-center gap-2 mt-1"
                        >
                            Passa ad Accedi <ArrowRight className="w-3 h-3" />
                        </button>
                    )}
                </div>
            )}
            {success && <div className="bg-emerald-50 text-emerald-700 p-4 rounded-xl text-xs border border-emerald-100 flex items-start gap-2"><CheckCircle2 className="w-4 h-4 mt-0.5 flex-shrink-0" /> {success}</div>}

            <button type="submit" disabled={loading} className="w-full bg-emerald-600 text-white font-bold py-4 rounded-xl shadow-md flex items-center justify-center gap-2 transition-all hover:bg-emerald-700 active:scale-95">
              {loading ? <Loader2 className="animate-spin w-5 h-5" /> : (isRegistering ? <><UserPlus className="w-5 h-5" /> Crea Account</> : <><LogIn className="w-5 h-5" /> Accedi</>)}
            </button>
            <div className="flex justify-between items-center mt-4 pt-2">
              <button type="button" onClick={() => { setIsRegistering(!isRegistering); setError(''); setSuccess(''); }} className="text-emerald-600 font-bold text-xs hover:underline">
                {isRegistering ? "Hai già un account? Accedi" : "Nuovo utente? Registrati"}
              </button>
              <button type="button" onClick={() => { setAuthMode('google'); setError(''); setSuccess(''); }} className="text-gray-400 font-bold text-xs">Torna indietro</button>
            </div>
          </form>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, 
  Income, CategoryDefinition, ShoppingItem, RecurringExpense, CustomField 
} from './types';
import * as SupabaseService from './services/supabaseService';
import { LoginScreen } from './components/LoginScreen';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { StoreManager } from './components/StoreManager';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { ShoppingListManager } from './components/ShoppingListManager';
import { IncomeManager } from './components/IncomeManager';
import { FamilyManager } from './components/FamilyManager';
import { OffersFinder } from './components/OffersFinder';
import { ReceiptScanner } from './components/ReceiptScanner';
import { 
  LayoutDashboard, ShoppingCart, Receipt, Repeat, BarChart3, 
  Wallet, Percent, Users, LogOut, Menu, X, Loader2 
} from 'lucide-react';

type View = 'dashboard' | 'shopping' | 'spese' | 'ricorrenti' | 'analisi' | 'bilancio' | 'offerte' | 'famiglia';

function App() {
  const [user, setUser] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Data States
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [shoppingList, setShoppingList] = useState<ShoppingItem[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);
  const [initialLoading, setInitialLoading] = useState(true);

  useEffect(() => {
    const initApp = async () => {
      const currentUser = await SupabaseService.getCurrentUser();
      if (currentUser) {
        setUser(currentUser);
        const { data: memberData } = await SupabaseService.getFamilyForUser(currentUser.id);
        if (memberData?.family_id) {
          await loadFamilyData(memberData.family_id);
        }
      }
      setInitialLoading(false);
    };
    initApp();
  }, []);

  const loadFamilyData = async (familyId: string) => {
    try {
      const [profile, exps, recs, shops, strs, incs] = await Promise.all([
        SupabaseService.getFamilyProfile(familyId),
        SupabaseService.fetchExpenses(familyId),
        SupabaseService.fetchRecurring(familyId),
        SupabaseService.fetchShoppingList(familyId),
        SupabaseService.fetchStores(familyId),
        SupabaseService.fetchIncomes(familyId)
      ]);

      if (profile.data) {
        const members = await SupabaseService.fetchFamilyMembers(familyId);
        setFamilyProfile({
          id: profile.data.id,
          familyName: profile.data.family_name,
          members: members,
          createdAt: new Date(profile.data.created_at).getTime()
        });
      }
      setExpenses(exps);
      setRecurringExpenses(recs);
      setShoppingList(shops);
      setIncomes(incs);
      if (strs && strs.length > 0) setStores(strs);
    } catch (err) {
      console.error("Errore caricamento dati:", err);
    }
  };

  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const handleSetupComplete = async (profile: FamilyProfile) => {
    setFamilyProfile(profile);
    if (user) {
      const { data: memberExists } = await SupabaseService.getFamilyForUser(user.id);
      if (!memberExists) {
        await SupabaseService.joinFamily(user.id, profile.id, user.email.split('@')[0], true);
      }
    }
    await loadFamilyData(profile.id);
  };

  const NavItem = ({ view, icon: Icon, label, badge }: { view: View, icon: any, label: string, badge?: number }) => (
    <button
      onClick={() => { setActiveView(view); setIsSidebarOpen(false); }}
      className={`w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all ${
        activeView === view ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-200' : 'text-gray-500 hover:bg-emerald-50 hover:text-emerald-600'
      }`}
    >
      <div className="flex items-center gap-3">
        <Icon className="w-5 h-5" />
        <span className="font-bold text-sm">{label}</span>
      </div>
      {badge !== undefined && badge > 0 && (
        <span className={`text-[10px] px-2 py-0.5 rounded-full font-black ${activeView === view ? 'bg-white text-emerald-600' : 'bg-emerald-600 text-white'}`}>
          {badge}
        </span>
      )}
    </button>
  );

  if (initialLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center">
          <Loader2 className="w-12 h-12 text-emerald-600 animate-spin mx-auto mb-4" />
          <p className="text-gray-500 font-medium">Caricamento Bilancio...</p>
        </div>
      </div>
    );
  }

  if (!user || !familyProfile) {
    return <LoginScreen onSetupComplete={handleSetupComplete} onUserLogin={setUser} isSupabaseAuth={!!user} />;
  }

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return (
          <div className="space-y-6 animate-in fade-in duration-300">
            <ReceiptScanner onScanComplete={async (data) => {
              for (const item of data.items) {
                const newExp: Expense = {
                  id: crypto.randomUUID(),
                  product: item.product, quantity: item.quantity, unitPrice: item.unitPrice, total: item.total,
                  store: data.store || 'Negozio', date: new Date().toISOString(), category: item.category || 'Altro'
                };
                setExpenses(prev => [newExp, ...prev]);
                await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
              }
            }} />
            <DueExpensesAlert 
              dueExpenses={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date())} 
              onProcessExpense={() => setActiveView('ricorrenti')} 
            />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                  <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2">
                    <ShoppingCart className="w-5 h-5 text-orange-500" /> Da comprare oggi
                  </h3>
                  {shoppingList.filter(i => !i.completed).length > 0 ? (
                    <div className="space-y-2">
                      {shoppingList.filter(i => !i.completed).slice(0, 3).map(item => (
                        <div key={item.id} className="flex items-center gap-3 text-sm text-gray-600 bg-gray-50 p-3 rounded-xl border border-gray-100">
                           <div className="w-2 h-2 rounded-full bg-orange-400" />
                           {item.product} <span className="text-[10px] text-gray-400 uppercase font-bold ml-auto">{item.store}</span>
                        </div>
                      ))}
                      <button onClick={() => setActiveView('shopping')} className="w-full py-2 text-xs font-bold text-emerald-600 hover:underline">Vedi tutta la lista</button>
                    </div>
                  ) : (
                    <p className="text-xs text-gray-400 italic">Lista spesa vuota.</p>
                  )}
               </div>
               <AIInsight expenses={expenses} />
            </div>
          </div>
        );
      case 'shopping':
        return (
          <ShoppingListManager 
            items={shoppingList} stores={stores} productHistory={productHistory}
            onAddItem={async (p, s) => {
              const newItem = { id: crypto.randomUUID(), product: p, store: s, completed: false };
              setShoppingList(prev => [...prev, newItem]);
              await SupabaseService.addShoppingItemToSupabase(familyProfile.id, newItem);
            }}
            onToggleItem={async (id) => {
              const item = shoppingList.find(i => i.id === id);
              if (item) {
                const updated = { ...item, completed: !item.completed };
                setShoppingList(prev => prev.map(i => i.id === id ? updated : i));
                await SupabaseService.updateShoppingItemInSupabase(updated);
              }
            }}
            onDeleteItem={async (id) => {
              setShoppingList(prev => prev.filter(i => i.id !== id));
              await SupabaseService.deleteShoppingItemFromSupabase(id);
            }}
          />
        );
      case 'spese':
        return (
          <div className="space-y-6">
            <ExpenseForm 
              stores={stores} members={familyProfile.members} 
              existingProducts={Object.keys(productHistory)} productHistory={productHistory} 
              onAddExpense={async (p, q, u, t, s) => {
                const newExp: Expense = {
                  id: crypto.randomUUID(), product: p, quantity: q, unitPrice: u, total: t, store: s,
                  date: new Date().toISOString(), category: 'Altro'
                };
                setExpenses(prev => [newExp, ...prev]);
                await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
              }} 
              isAnalyzing={false}
            />
            <ExpenseList 
              expenses={expenses} stores={stores} 
              onDelete={async (id) => {
                setExpenses(prev => prev.filter(e => e.id !== id));
                await SupabaseService.deleteExpenseFromSupabase(id);
              }} 
              onEdit={async (updated) => {
                setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e));
                // Nota: Aggiungere updateExpenseToSupabase se necessario
              }} 
            />
          </div>
        );
      case 'bilancio':
        return (
          <IncomeManager 
            incomes={incomes} expenses={expenses} 
            onAddIncome={async (s, a, d) => {
              const newInc = { id: crypto.randomUUID(), source: s, amount: a, date: d };
              setIncomes(prev => [...prev, newInc]);
              await SupabaseService.addIncomeToSupabase(familyProfile.id, newInc);
            }}
            onDeleteIncome={async (id) => {
              setIncomes(prev => prev.filter(i => i.id !== id));
              await SupabaseService.deleteIncomeFromSupabase(id);
            }}
          />
        );
      case 'ricorrenti':
        return (
          <RecurringManager 
            recurringExpenses={recurringExpenses} stores={stores}
            onAddRecurring={async (p, a, s, f, d, r, c) => {
              const newItem = { id: crypto.randomUUID(), product: p, amount: a, store: s, frequency: f, nextDueDate: d, reminderDays: r, customFields: c };
              setRecurringExpenses(prev => [...prev, newItem]);
              await SupabaseService.addRecurringToSupabase(familyProfile.id, newItem);
            }}
            onUpdateRecurring={async (updated) => {
              setRecurringExpenses(prev => prev.map(r => r.id === updated.id ? updated : r));
              await SupabaseService.updateRecurringInSupabase(updated);
            }}
            onDeleteRecurring={async (id) => {
              setRecurringExpenses(prev => prev.filter(r => r.id !== id));
              await SupabaseService.deleteRecurringFromSupabase(id);
            }}
          />
        );
      case 'analisi':
        return <Analytics expenses={expenses} />;
      case 'offerte':
        return <OffersFinder stores={stores} savedCity="" savedStores={[]} notificationsEnabled={false} onPreferencesChange={() => {}} />;
      case 'famiglia':
        return (
          <div className="space-y-6">
            <FamilyManager familyProfile={familyProfile} />
            <StoreManager onAddStore={async (name) => {
              const newStore = { id: crypto.randomUUID(), name };
              setStores(prev => [...prev, newStore]);
              await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
            }} />
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">

      {/* Mobile Header */}
      <header className="md:hidden bg-emerald-600 text-white p-4 flex justify-between items-center sticky top-0 z-40 shadow-md">
        <div className="flex items-center gap-2">
           <div className="bg-white/20 p-2 rounded-lg"><LayoutDashboard className="w-5 h-5" /></div>
           <h1 className="font-black tracking-tight">{familyProfile.familyName}</h1>
        </div>
        <button onClick={() => setIsSidebarOpen(true)} className="p-2 bg-emerald-700 rounded-xl"><Menu className="w-6 h-6" /></button>
      </header>

      {/* Desktop Sidebar / Mobile Drawer */}
      <aside className={`fixed inset-0 z-50 md:relative md:flex md:w-72 bg-white border-r border-gray-100 flex-col shadow-2xl md:shadow-none transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}`}>
        <div className="p-6 flex justify-between items-center border-b border-gray-50">
          <div className="flex items-center gap-3">
             <div className="bg-emerald-600 p-2.5 rounded-2xl shadow-lg shadow-emerald-100 text-white"><LayoutDashboard className="w-6 h-6" /></div>
             <div>
               <h1 className="font-black text-gray-800 tracking-tighter">{familyProfile.familyName}</h1>
               <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{user?.email.split('@')[0]}</p>
             </div>
          </div>
          <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2 text-gray-400"><X className="w-6 h-6" /></button>
        </div>

        <nav className="flex-1 p-4 space-y-1.5 overflow-y-auto">
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavItem view="bilancio" icon={Wallet} label="Bilancio" />
          <NavItem view="spese" icon={Receipt} label="Storico & Spese" />
          <NavItem view="shopping" icon={ShoppingCart} label="Lista Spesa" badge={shoppingList.filter(i => !i.completed).length} />
          <NavItem view="ricorrenti" icon={Repeat} label="Scadenze" badge={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date()).length} />
          <NavItem view="analisi" icon={BarChart3} label="Analisi & Report" />
          <NavItem view="offerte" icon={Percent} label="Caccia Offerte" />
          <NavItem view="famiglia" icon={Users} label="Famiglia & Negozi" />
        </nav>

        <div className="p-4 border-t border-gray-50 space-y-2">
          <button 
            onClick={async () => { await SupabaseService.signOut(); window.location.reload(); }}
            className="w-full flex items-center gap-3 px-4 py-3 text-red-500 font-bold text-sm hover:bg-red-50 rounded-xl transition-colors"
          >
            <LogOut className="w-5 h-5" /> Esci dall'App
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8">
        <div className="mb-6 hidden md:block">
           <h2 className="text-3xl font-black text-gray-800 capitalize tracking-tighter">{activeView.replace('spese', 'Storico Spese')}</h2>
           <p className="text-gray-400 text-sm font-medium">Gestisci il tuo risparmio familiare in tempo reale.</p>
        </div>
        {renderView()}
      </main>

      {/* Mobile Bottom Navigation Bar */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 flex justify-around items-center p-3 z-40 pb-6 safe-area-bottom shadow-[0_-5px_15px_rgba(0,0,0,0.05)]">
         <button onClick={() => setActiveView('dashboard')} className={`p-3 rounded-2xl transition-all ${activeView === 'dashboard' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <LayoutDashboard className="w-6 h-6" />
         </button>
         <button onClick={() => setActiveView('spese')} className={`p-3 rounded-2xl transition-all ${activeView === 'spese' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <Receipt className="w-6 h-6" />
         </button>
         <button onClick={() => setActiveView('shopping')} className={`relative p-3 rounded-2xl transition-all ${activeView === 'shopping' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <ShoppingCart className="w-6 h-6" />
            {shoppingList.filter(i => !i.completed).length > 0 && <span className="absolute top-2 right-2 w-4 h-4 bg-orange-500 text-white text-[9px] font-black rounded-full flex items-center justify-center border-2 border-white">{shoppingList.filter(i => !i.completed).length}</span>}
         </button>
         <button onClick={() => setActiveView('bilancio')} className={`p-3 rounded-2xl transition-all ${activeView === 'bilancio' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <Wallet className="w-6 h-6" />
         </button>
         <button onClick={() => setActiveView('ricorrenti')} className={`p-3 rounded-2xl transition-all ${activeView === 'ricorrenti' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <Repeat className="w-6 h-6" />
         </button>
      </div>

      {/* Backdrop for mobile drawer */}
      {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="fixed inset-0 bg-black/40 backdrop-blur-sm z-40 md:hidden animate-in fade-in duration-300" />}
    </div>
  );
}

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, 
  Income, CategoryDefinition, ShoppingItem, RecurringExpense, CustomField 
} from './types';
import * as SupabaseService from './services/supabaseService';
import { LoginScreen } from './components/LoginScreen';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { StoreManager } from './components/StoreManager';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { ShoppingListManager } from './components/ShoppingListManager';
import { IncomeManager } from './components/IncomeManager';
import { FamilyManager } from './components/FamilyManager';
import { OffersFinder } from './components/OffersFinder';
import { ReceiptScanner } from './components/ReceiptScanner';
import { 
  LayoutDashboard, ShoppingCart, Receipt, Repeat, BarChart3, 
  Wallet, Percent, Users, LogOut, Menu, X, Loader2 
} from 'lucide-react';

type View = 'dashboard' | 'shopping' | 'spese' | 'ricorrenti' | 'analisi' | 'bilancio' | 'offerte' | 'famiglia';

function App() {
  const [user, setUser] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Data States
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [shoppingList, setShoppingList] = useState<ShoppingItem[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);
  const [initialLoading, setInitialLoading] = useState(true);
  const [isFetchingFamily, setIsFetchingFamily] = useState(false);

  // 1. Inizializzazione: Controlla se c'è un utente loggato all'avvio
  useEffect(() => {
    const initApp = async () => {
      const currentUser = await SupabaseService.getCurrentUser();
      if (currentUser) {
        setUser(currentUser);
        // La ricerca della famiglia viene gestita dal secondo useEffect che osserva 'user'
      } else {
        setInitialLoading(false);
      }
    };
    initApp();
  }, []);

  // 2. Reazione al cambio utente: Se l'utente logga, cerca subito la sua famiglia
  useEffect(() => {
    const findUserFamily = async () => {
      if (user && !familyProfile) {
        setIsFetchingFamily(true);
        try {
          const { data: memberData } = await SupabaseService.getFamilyForUser(user.id);
          if (memberData?.family_id) {
            await loadFamilyData(memberData.family_id);
          }
        } catch (err) {
          console.error("Errore ricerca famiglia:", err);
        } finally {
          setIsFetchingFamily(false);
          setInitialLoading(false);
        }
      }
    };
    findUserFamily();
  }, [user]);

  const loadFamilyData = async (familyId: string) => {
    try {
      const [profile, exps, recs, shops, strs, incs] = await Promise.all([
        SupabaseService.getFamilyProfile(familyId),
        SupabaseService.fetchExpenses(familyId),
        SupabaseService.fetchRecurring(familyId),
        SupabaseService.fetchShoppingList(familyId),
        SupabaseService.fetchStores(familyId),
        SupabaseService.fetchIncomes(familyId)
      ]);

      if (profile.data) {
        const members = await SupabaseService.fetchFamilyMembers(familyId);
        setFamilyProfile({
          id: profile.data.id,
          familyName: profile.data.family_name,
          members: members,
          createdAt: new Date(profile.data.created_at).getTime()
        });
      }
      setExpenses(exps);
      setRecurringExpenses(recs);
      setShoppingList(shops);
      setIncomes(incs);
      if (strs && strs.length > 0) setStores(strs);
    } catch (err) {
      console.error("Errore caricamento dati:", err);
    }
  };

  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const handleSetupComplete = async (profile: FamilyProfile) => {
    setFamilyProfile(profile);
    if (user) {
      const { data: memberExists } = await SupabaseService.getFamilyForUser(user.id);
      if (!memberExists) {
        await SupabaseService.joinFamily(user.id, profile.id, user.email.split('@')[0], true);
      }
    }
    await loadFamilyData(profile.id);
  };

  const NavItem = ({ view, icon: Icon, label, badge }: { view: View, icon: any, label: string, badge?: number }) => (
    <button
      onClick={() => { setActiveView(view); setIsSidebarOpen(false); }}
      className={`w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all ${
        activeView === view ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-200' : 'text-gray-500 hover:bg-emerald-50 hover:text-emerald-600'
      }`}
    >
      <div className="flex items-center gap-3">
        <Icon className="w-5 h-5" />
        <span className="font-bold text-sm">{label}</span>
      </div>
      {badge !== undefined && badge > 0 && (
        <span className={`text-[10px] px-2 py-0.5 rounded-full font-black ${activeView === view ? 'bg-white text-emerald-600' : 'bg-emerald-600 text-white'}`}>
          {badge}
        </span>
      )}
    </button>
  );

  if (initialLoading || isFetchingFamily) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center">
          <Loader2 className="w-12 h-12 text-emerald-600 animate-spin mx-auto mb-4" />
          <p className="text-gray-500 font-medium">Verifica account e caricamento dati...</p>
        </div>
      </div>
    );
  }

  // Se l'utente non è loggato O è loggato ma non ha ancora una famiglia, mostriamo il Login/Setup
  if (!user || !familyProfile) {
    return <LoginScreen 
      onSetupComplete={handleSetupComplete} 
      onUserLogin={setUser} 
      isSupabaseAuth={!!user} 
    />;
  }

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return (
          <div className="space-y-6 animate-in fade-in duration-300">
            <ReceiptScanner onScanComplete={async (data) => {
              for (const item of data.items) {
                const newExp: Expense = {
                  id: crypto.randomUUID(),
                  product: item.product, quantity: item.quantity, unitPrice: item.unitPrice, total: item.total,
                  store: data.store || 'Negozio', date: new Date().toISOString(), category: item.category || 'Altro'
                };
                setExpenses(prev => [newExp, ...prev]);
                await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
              }
            }} />
            <DueExpensesAlert 
              dueExpenses={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date())} 
              onProcessExpense={() => setActiveView('ricorrenti')} 
            />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                  <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2">
                    <ShoppingCart className="w-5 h-5 text-orange-500" /> Da comprare oggi
                  </h3>
                  {shoppingList.filter(i => !i.completed).length > 0 ? (
                    <div className="space-y-2">
                      {shoppingList.filter(i => !i.completed).slice(0, 3).map(item => (
                        <div key={item.id} className="flex items-center gap-3 text-sm text-gray-600 bg-gray-50 p-3 rounded-xl border border-gray-100">
                           <div className="w-2 h-2 rounded-full bg-orange-400" />
                           {item.product} <span className="text-[10px] text-gray-400 uppercase font-bold ml-auto">{item.store}</span>
                        </div>
                      ))}
                      <button onClick={() => setActiveView('shopping')} className="w-full py-2 text-xs font-bold text-emerald-600 hover:underline">Vedi tutta la lista</button>
                    </div>
                  ) : (
                    <p className="text-xs text-gray-400 italic">Lista spesa vuota.</p>
                  )}
               </div>
               <AIInsight expenses={expenses} />
            </div>
          </div>
        );
      case 'shopping':
        return (
          <ShoppingListManager 
            items={shoppingList} stores={stores} productHistory={productHistory}
            onAddItem={async (p, s) => {
              const newItem = { id: crypto.randomUUID(), product: p, store: s, completed: false };
              setShoppingList(prev => [...prev, newItem]);
              await SupabaseService.addShoppingItemToSupabase(familyProfile.id, newItem);
            }}
            onToggleItem={async (id) => {
              const item = shoppingList.find(i => i.id === id);
              if (item) {
                const updated = { ...item, completed: !item.completed };
                setShoppingList(prev => prev.map(i => i.id === id ? updated : i));
                await SupabaseService.updateShoppingItemInSupabase(updated);
              }
            }}
            onDeleteItem={async (id) => {
              setShoppingList(prev => prev.filter(i => i.id !== id));
              await SupabaseService.deleteShoppingItemFromSupabase(id);
            }}
          />
        );
      case 'spese':
        return (
          <div className="space-y-6">
            <ExpenseForm 
              stores={stores} members={familyProfile.members} 
              existingProducts={Object.keys(productHistory)} productHistory={productHistory} 
              onAddExpense={async (p, q, u, t, s) => {
                const newExp: Expense = {
                  id: crypto.randomUUID(), product: p, quantity: q, unitPrice: u, total: t, store: s,
                  date: new Date().toISOString(), category: 'Altro'
                };
                setExpenses(prev => [newExp, ...prev]);
                await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
              }} 
              isAnalyzing={false}
            />
            <ExpenseList 
              expenses={expenses} stores={stores} 
              onDelete={async (id) => {
                setExpenses(prev => prev.filter(e => e.id !== id));
                await SupabaseService.deleteExpenseFromSupabase(id);
              }} 
              onEdit={async (updated) => {
                setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e));
                // Nota: Implementare updateExpenseToSupabase in supabaseService se serve modifica persistente
              }} 
            />
          </div>
        );
      case 'bilancio':
        return (
          <IncomeManager 
            incomes={incomes} expenses={expenses} 
            onAddIncome={async (s, a, d) => {
              const newInc = { id: crypto.randomUUID(), source: s, amount: a, date: d };
              setIncomes(prev => [...prev, newInc]);
              await SupabaseService.addIncomeToSupabase(familyProfile.id, newInc);
            }}
            onDeleteIncome={async (id) => {
              setIncomes(prev => prev.filter(i => i.id !== id));
              await SupabaseService.deleteIncomeFromSupabase(id);
            }}
          />
        );
      case 'ricorrenti':
        return (
          <RecurringManager 
            recurringExpenses={recurringExpenses} stores={stores}
            onAddRecurring={async (p, a, s, f, d, r, c) => {
              const newItem = { id: crypto.randomUUID(), product: p, amount: a, store: s, frequency: f, nextDueDate: d, reminderDays: r, customFields: c };
              setRecurringExpenses(prev => [...prev, newItem]);
              await SupabaseService.addRecurringToSupabase(familyProfile.id, newItem);
            }}
            onUpdateRecurring={async (updated) => {
              setRecurringExpenses(prev => prev.map(r => r.id === updated.id ? updated : r));
              await SupabaseService.updateRecurringInSupabase(updated);
            }}
            onDeleteRecurring={async (id) => {
              setRecurringExpenses(prev => prev.filter(r => r.id !== id));
              await SupabaseService.deleteRecurringFromSupabase(id);
            }}
          />
        );
      case 'analisi':
        return <Analytics expenses={expenses} />;
      case 'offerte':
        return <OffersFinder stores={stores} savedCity="" savedStores={[]} notificationsEnabled={false} onPreferencesChange={() => {}} />;
      case 'famiglia':
        return (
          <div className="space-y-6">
            <FamilyManager familyProfile={familyProfile} />
            <StoreManager onAddStore={async (name) => {
              const newStore = { id: crypto.randomUUID(), name };
              setStores(prev => [...prev, newStore]);
              await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
            }} />
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">

      {/* Mobile Header */}
      <header className="md:hidden bg-emerald-600 text-white p-4 flex justify-between items-center sticky top-0 z-40 shadow-md">
        <div className="flex items-center gap-2">
           <div className="bg-white/20 p-2 rounded-lg"><LayoutDashboard className="w-5 h-5" /></div>
           <h1 className="font-black tracking-tight">{familyProfile.familyName}</h1>
        </div>
        <button onClick={() => setIsSidebarOpen(true)} className="p-2 bg-emerald-700 rounded-xl"><Menu className="w-6 h-6" /></button>
      </header>

      {/* Desktop Sidebar / Mobile Drawer */}
      <aside className={`fixed inset-0 z-50 md:relative md:flex md:w-72 bg-white border-r border-gray-100 flex-col shadow-2xl md:shadow-none transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}`}>
        <div className="p-6 flex justify-between items-center border-b border-gray-50">
          <div className="flex items-center gap-3">
             <div className="bg-emerald-600 p-2.5 rounded-2xl shadow-lg shadow-emerald-100 text-white"><LayoutDashboard className="w-6 h-6" /></div>
             <div>
               <h1 className="font-black text-gray-800 tracking-tighter">{familyProfile.familyName}</h1>
               <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{user?.email?.split('@')[0] || 'Utente'}</p>
             </div>
          </div>
          <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2 text-gray-400"><X className="w-6 h-6" /></button>
        </div>

        <nav className="flex-1 p-4 space-y-1.5 overflow-y-auto">
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavItem view="bilancio" icon={Wallet} label="Bilancio" />
          <NavItem view="spese" icon={Receipt} label="Storico & Spese" />
          <NavItem view="shopping" icon={ShoppingCart} label="Lista Spesa" badge={shoppingList.filter(i => !i.completed).length} />
          <NavItem view="ricorrenti" icon={Repeat} label="Scadenze" badge={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date()).length} />
          <NavItem view="analisi" icon={BarChart3} label="Analisi & Report" />
          <NavItem view="offerte" icon={Percent} label="Caccia Offerte" />
          <NavItem view="famiglia" icon={Users} label="Famiglia & Negozi" />
        </nav>

        <div className="p-4 border-t border-gray-50 space-y-2">
          <button 
            onClick={async () => { 
              await SupabaseService.signOut(); 
              setUser(null);
              setFamilyProfile(null);
              window.location.reload(); 
            }}
            className="w-full flex items-center gap-3 px-4 py-3 text-red-500 font-bold text-sm hover:bg-red-50 rounded-xl transition-colors"
          >
            <LogOut className="w-5 h-5" /> Esci dall'App
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8">
        <div className="mb-6 hidden md:block">
           <h2 className="text-3xl font-black text-gray-800 capitalize tracking-tighter">{activeView.replace('spese', 'Storico Spese')}</h2>
           <p className="text-gray-400 text-sm font-medium">Gestisci il tuo risparmio familiare in tempo reale.</p>
        </div>
        {renderView()}
      </main>

      {/* Mobile Bottom Navigation Bar */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 flex justify-around items-center p-3 z-40 pb-6 safe-area-bottom shadow-[0_-5px_15px_rgba(0,0,0,0.05)]">
         <button onClick={() => setActiveView('dashboard')} className={`p-3 rounded-2xl transition-all ${activeView === 'dashboard' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <LayoutDashboard className="w-6 h-6" />
         </button>
         <button onClick={() => setActiveView('spese')} className={`p-3 rounded-2xl transition-all ${activeView === 'spese' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <Receipt className="w-6 h-6" />
         </button>
         <button onClick={() => setActiveView('shopping')} className={`relative p-3 rounded-2xl transition-all ${activeView === 'shopping' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <ShoppingCart className="w-6 h-6" />
            {shoppingList.filter(i => !i.completed).length > 0 && <span className="absolute top-2 right-2 w-4 h-4 bg-orange-500 text-white text-[9px] font-black rounded-full flex items-center justify-center border-2 border-white">{shoppingList.filter(i => !i.completed).length}</span>}
         </button>
         <button onClick={() => setActiveView('bilancio')} className={`p-3 rounded-2xl transition-all ${activeView === 'bilancio' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <Wallet className="w-6 h-6" />
         </button>
         <button onClick={() => setActiveView('ricorrenti')} className={`p-3 rounded-2xl transition-all ${activeView === 'ricorrenti' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <Repeat className="w-6 h-6" />
         </button>
      </div>

      {/* Backdrop for mobile drawer */}
      {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="fixed inset-0 bg-black/40 backdrop-blur-sm z-40 md:hidden animate-in fade-in duration-300" />}
    </div>
  );
}

export default App;

import { supabase } from '../src/supabaseClient';
import { Expense, Income, Store, RecurringExpense, ShoppingItem, FamilyProfile, CategoryDefinition, Member } from '../types';

export const signInWithGoogle = async () => {
  return await supabase.auth.signInWithOAuth({ provider: 'google' });
};

export const signUpWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signUp({ email, password });
};

export const signInWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signInWithPassword({ email, password });
};

export const signOut = async () => {
  return await supabase.auth.signOut();
};

export const getCurrentUser = async () => {
  const { data: { user } } = await supabase.auth.getUser();
  return user;
};

// Usa maybeSingle per evitare errori se la riga non esiste
export const getFamilyForUser = async (userId: string) => {
  const { data, error } = await supabase
    .from('members')
    .select('family_id')
    .eq('user_id', userId)
    .maybeSingle();
  return { data, error };
};

export const fetchFamilyMembers = async (familyId: string) => {
  const { data } = await supabase.from('members').select('*').eq('family_id', familyId);
  return (data || []).map((m: any) => ({
    id: m.id,
    name: m.name,
    color: m.color,
    userId: m.user_id,
    isAdmin: m.is_admin
  }));
};

export const joinFamily = async (userId: string, familyId: string, name: string, isAdmin: boolean = false) => {
  return await supabase.from('members').insert({
    user_id: userId,
    family_id: familyId,
    name,
    is_admin: isAdmin,
    color: 'bg-emerald-500'
  });
};

export const getFamilyProfile = async (familyId: string) => {
  return await supabase.from('families').select('*').eq('id', familyId).maybeSingle();
};

export const fetchExpenses = async (familyId: string) => {
  const { data } = await supabase.from('expenses').select('*').eq('family_id', familyId).order('date', { ascending: false });
  return (data || []).map((e: any) => ({
    id: e.id,
    product: e.product,
    quantity: e.quantity,
    unitPrice: e.unit_price,
    total: e.total,
    store: e.store,
    date: e.date,
    category: e.category,
    memberId: e.member_id
  }));
};

export const addExpenseToSupabase = async (familyId: string, expense: Expense) => {
  await supabase.from('expenses').insert({
    id: expense.id,
    family_id: familyId,
    product: expense.product,
    quantity: expense.quantity,
    unit_price: expense.unitPrice,
    total: expense.total,
    store: expense.store,
    date: expense.date,
    category: expense.category,
    member_id: expense.memberId
  });
};

export const deleteExpenseFromSupabase = async (id: string) => {
  await supabase.from('expenses').delete().eq('id', id);
};

export const fetchIncomes = async (familyId: string) => {
  const { data } = await supabase.from('incomes').select('*').eq('family_id', familyId);
  return (data || []).map((i: any) => ({
    id: i.id,
    source: i.source,
    amount: i.amount,
    date: i.date
  }));
};

export const addIncomeToSupabase = async (familyId: string, income: Income) => {
  await supabase.from('incomes').insert({
    id: income.id,
    family_id: familyId,
    source: income.source,
    amount: income.amount,
    date: income.date
  });
};

export const deleteIncomeFromSupabase = async (id: string) => {
  await supabase.from('incomes').delete().eq('id', id);
};

export const fetchStores = async (familyId: string) => {
  const { data } = await supabase.from('stores').select('*').eq('family_id', familyId);
  return data || [];
};

export const addStoreToSupabase = async (familyId: string, store: Store) => {
  await supabase.from('stores').insert({
    id: store.id,
    family_id: familyId,
    name: store.name
  });
};

export const fetchRecurring = async (familyId: string): Promise<RecurringExpense[]> => {
  const { data } = await supabase.from('recurring_expenses').select('*').eq('family_id', familyId);
  return (data || []).map((r: any) => ({ 
    id: r.id, 
    product: r.product, 
    amount: Number(r.amount), 
    store: r.store, 
    frequency: r.frequency, 
    nextDueDate: r.next_due_date, 
    reminderDays: r.reminder_days,
    customFields: r.custom_fields || [] 
  }));
};

export const addRecurringToSupabase = async (familyId: string, item: RecurringExpense): Promise<void> => {
  await supabase.from('recurring_expenses').insert({ 
    id: item.id, 
    family_id: familyId, 
    product: item.product, 
    amount: item.amount, 
    store: item.store, 
    frequency: item.frequency, 
    next_due_date: item.nextDueDate, 
    reminder_days: item.reminderDays,
    custom_fields: item.customFields 
  });
};

export const updateRecurringInSupabase = async (item: RecurringExpense): Promise<void> => {
  await supabase.from('recurring_expenses').update({ 
    product: item.product, 
    amount: item.amount, 
    store: item.store, 
    frequency: item.frequency, 
    next_due_date: item.nextDueDate, 
    reminder_days: item.reminderDays,
    custom_fields: item.customFields 
  }).eq('id', item.id);
};

export const deleteRecurringFromSupabase = async (id: string) => {
  await supabase.from('recurring_expenses').delete().eq('id', id);
};

export const fetchShoppingList = async (familyId: string) => {
  const { data } = await supabase.from('shopping_list').select('*').eq('family_id', familyId);
  return (data || []).map((s: any) => ({
    id: s.id,
    product: s.product,
    store: s.store,
    completed: s.completed
  }));
};

export const addShoppingItemToSupabase = async (familyId: string, item: ShoppingItem) => {
  await supabase.from('shopping_list').insert({
    id: item.id,
    family_id: familyId,
    product: item.product,
    store: item.store,
    completed: item.completed
  });
};

export const updateShoppingItemInSupabase = async (item: ShoppingItem) => {
  await supabase.from('shopping_list').update({
    completed: item.completed
  }).eq('id', item.id);
};

export const deleteShoppingItemFromSupabase = async (id: string) => {
  await supabase.from('shopping_list').delete().eq('id', id);
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, 
  Income, CategoryDefinition, ShoppingItem, RecurringExpense, CustomField 
} from './types';
import * as SupabaseService from './services/supabaseService';
import { LoginScreen } from './components/LoginScreen';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { StoreManager } from './components/StoreManager';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { ShoppingListManager } from './components/ShoppingListManager';
import { IncomeManager } from './components/IncomeManager';
import { FamilyManager } from './components/FamilyManager';
import { OffersFinder } from './components/OffersFinder';
import { ReceiptScanner } from './components/ReceiptScanner';
import { 
  LayoutDashboard, ShoppingCart, Receipt, Repeat, BarChart3, 
  Wallet, Percent, Users, LogOut, Menu, X, Loader2 
} from 'lucide-react';

type View = 'dashboard' | 'shopping' | 'spese' | 'ricorrenti' | 'analisi' | 'bilancio' | 'offerte' | 'famiglia';

function App() {
  const [user, setUser] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Data States
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [shoppingList, setShoppingList] = useState<ShoppingItem[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);
  const [initialLoading, setInitialLoading] = useState(true);
  const [isFetchingFamily, setIsFetchingFamily] = useState(false);

  // 1. Inizializzazione: Controlla la sessione
  useEffect(() => {
    const initApp = async () => {
      try {
        const currentUser = await SupabaseService.getCurrentUser();
        if (currentUser) {
          setUser(currentUser);
          // La ricerca della famiglia viene fatta nel secondo useEffect
        } else {
          setInitialLoading(false);
        }
      } catch (err) {
        console.error("Init Error:", err);
        setInitialLoading(false);
      }
    };
    initApp();
  }, []);

  // 2. Reazione al cambio utente: Recupera la famiglia
  useEffect(() => {
    const findUserFamily = async () => {
      if (user && !familyProfile) {
        setIsFetchingFamily(true);
        try {
          const { data: memberData } = await SupabaseService.getFamilyForUser(user.id);
          if (memberData?.family_id) {
            await loadFamilyData(memberData.family_id);
          }
        } catch (err) {
          console.error("Errore ricerca famiglia:", err);
        } finally {
          setIsFetchingFamily(false);
          setInitialLoading(false);
        }
      }
    };
    findUserFamily();
  }, [user]);

  const loadFamilyData = async (familyId: string) => {
    try {
      const [profileRes, exps, recs, shops, strs, incs] = await Promise.all([
        SupabaseService.getFamilyProfile(familyId),
        SupabaseService.fetchExpenses(familyId),
        SupabaseService.fetchRecurring(familyId),
        SupabaseService.fetchShoppingList(familyId),
        SupabaseService.fetchStores(familyId),
        SupabaseService.fetchIncomes(familyId)
      ]);

      if (profileRes.data) {
        const members = await SupabaseService.fetchFamilyMembers(familyId);
        setFamilyProfile({
          id: profileRes.data.id,
          familyName: profileRes.data.family_name,
          members: members,
          createdAt: new Date(profileRes.data.created_at).getTime()
        });
      }
      setExpenses(exps);
      setRecurringExpenses(recs);
      setShoppingList(shops);
      setIncomes(incs);
      if (strs && strs.length > 0) setStores(strs);
    } catch (err) {
      console.error("Errore caricamento dati:", err);
    }
  };

  const handleSetupComplete = async (profile: FamilyProfile) => {
    // Questo viene chiamato dopo che LoginScreen ha creato/unito una famiglia
    if (user) {
      // Verifichiamo se l'associazione nel database esiste già
      const { data: memberData } = await SupabaseService.getFamilyForUser(user.id);
      if (!memberData) {
        // Se non esiste, creiamo il legame tra Utente e Famiglia
        await SupabaseService.joinFamily(user.id, profile.id, user.email.split('@')[0], true);
      }
    }
    await loadFamilyData(profile.id);
  };

  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const NavItem = ({ view, icon: Icon, label, badge }: { view: View, icon: any, label: string, badge?: number }) => (
    <button
      onClick={() => { setActiveView(view); setIsSidebarOpen(false); }}
      className={`w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all ${
        activeView === view ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-200' : 'text-gray-500 hover:bg-emerald-50 hover:text-emerald-600'
      }`}
    >
      <div className="flex items-center gap-3">
        <Icon className="w-5 h-5" />
        <span className="font-bold text-sm">{label}</span>
      </div>
      {badge !== undefined && badge > 0 && (
        <span className={`text-[10px] px-2 py-0.5 rounded-full font-black ${activeView === view ? 'bg-white text-emerald-600' : 'bg-emerald-600 text-white'}`}>
          {badge}
        </span>
      )}
    </button>
  );

  if (initialLoading || isFetchingFamily) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center">
          <Loader2 className="w-12 h-12 text-emerald-600 animate-spin mx-auto mb-4" />
          <p className="text-gray-500 font-bold tracking-tight">Sincronizzazione Bilancio...</p>
        </div>
      </div>
    );
  }

  if (!user || !familyProfile) {
    return <LoginScreen 
      onSetupComplete={handleSetupComplete} 
      onUserLogin={setUser} 
      isSupabaseAuth={!!user} 
    />;
  }

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return (
          <div className="space-y-6 animate-in fade-in duration-300">
            <ReceiptScanner onScanComplete={async (data) => {
              for (const item of data.items) {
                const newExp: Expense = {
                  id: crypto.randomUUID(),
                  product: item.product, quantity: item.quantity, unitPrice: item.unitPrice, total: item.total,
                  store: data.store || 'Negozio', date: new Date().toISOString(), category: item.category || 'Altro'
                };
                setExpenses(prev => [newExp, ...prev]);
                await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
              }
            }} />
            <DueExpensesAlert 
              dueExpenses={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date())} 
              onProcessExpense={() => setActiveView('ricorrenti')} 
            />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                  <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2">
                    <ShoppingCart className="w-5 h-5 text-orange-500" /> Da comprare oggi
                  </h3>
                  {shoppingList.filter(i => !i.completed).length > 0 ? (
                    <div className="space-y-2">
                      {shoppingList.filter(i => !i.completed).slice(0, 3).map(item => (
                        <div key={item.id} className="flex items-center gap-3 text-sm text-gray-600 bg-gray-50 p-3 rounded-xl border border-gray-100">
                           <div className="w-2 h-2 rounded-full bg-orange-400" />
                           {item.product} <span className="text-[10px] text-gray-400 uppercase font-bold ml-auto">{item.store}</span>
                        </div>
                      ))}
                      <button onClick={() => setActiveView('shopping')} className="w-full py-2 text-xs font-bold text-emerald-600 hover:underline">Vedi tutta la lista</button>
                    </div>
                  ) : (
                    <p className="text-xs text-gray-400 italic">Lista spesa vuota.</p>
                  )}
               </div>
               <AIInsight expenses={expenses} />
            </div>
          </div>
        );
      case 'shopping':
        return (
          <ShoppingListManager 
            items={shoppingList} stores={stores} productHistory={productHistory}
            onAddItem={async (p, s) => {
              const newItem = { id: crypto.randomUUID(), product: p, store: s, completed: false };
              setShoppingList(prev => [...prev, newItem]);
              await SupabaseService.addShoppingItemToSupabase(familyProfile.id, newItem);
            }}
            onToggleItem={async (id) => {
              const item = shoppingList.find(i => i.id === id);
              if (item) {
                const updated = { ...item, completed: !item.completed };
                setShoppingList(prev => prev.map(i => i.id === id ? updated : i));
                await SupabaseService.updateShoppingItemInSupabase(updated);
              }
            }}
            onDeleteItem={async (id) => {
              setShoppingList(prev => prev.filter(i => i.id !== id));
              await SupabaseService.deleteShoppingItemFromSupabase(id);
            }}
          />
        );
      case 'spese':
        return (
          <div className="space-y-6">
            <ExpenseForm 
              stores={stores} members={familyProfile.members} 
              existingProducts={Object.keys(productHistory)} productHistory={productHistory} 
              onAddExpense={async (p, q, u, t, s) => {
                const newExp: Expense = {
                  id: crypto.randomUUID(), product: p, quantity: q, unitPrice: u, total: t, store: s,
                  date: new Date().toISOString(), category: 'Altro'
                };
                setExpenses(prev => [newExp, ...prev]);
                await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
              }} 
              isAnalyzing={false}
            />
            <ExpenseList 
              expenses={expenses} stores={stores} 
              onDelete={async (id) => {
                setExpenses(prev => prev.filter(e => e.id !== id));
                await SupabaseService.deleteExpenseFromSupabase(id);
              }} 
              onEdit={async (updated) => {
                setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e));
              }} 
            />
          </div>
        );
      case 'bilancio':
        return (
          <IncomeManager 
            incomes={incomes} expenses={expenses} 
            onAddIncome={async (s, a, d) => {
              const newInc = { id: crypto.randomUUID(), source: s, amount: a, date: d };
              setIncomes(prev => [...prev, newInc]);
              await SupabaseService.addIncomeToSupabase(familyProfile.id, newInc);
            }}
            onDeleteIncome={async (id) => {
              setIncomes(prev => prev.filter(i => i.id !== id));
              await SupabaseService.deleteIncomeFromSupabase(id);
            }}
          />
        );
      case 'ricorrenti':
        return (
          <RecurringManager 
            recurringExpenses={recurringExpenses} stores={stores}
            onAddRecurring={async (p, a, s, f, d, r, c) => {
              const newItem = { id: crypto.randomUUID(), product: p, amount: a, store: s, frequency: f, nextDueDate: d, reminderDays: r, customFields: c };
              setRecurringExpenses(prev => [...prev, newItem]);
              await SupabaseService.addRecurringToSupabase(familyProfile.id, newItem);
            }}
            onUpdateRecurring={async (updated) => {
              setRecurringExpenses(prev => prev.map(r => r.id === updated.id ? updated : r));
              await SupabaseService.updateRecurringInSupabase(updated);
            }}
            onDeleteRecurring={async (id) => {
              setRecurringExpenses(prev => prev.filter(r => r.id !== id));
              await SupabaseService.deleteRecurringFromSupabase(id);
            }}
          />
        );
      case 'analisi':
        return <Analytics expenses={expenses} />;
      case 'offerte':
        return <OffersFinder stores={stores} savedCity="" savedStores={[]} notificationsEnabled={false} onPreferencesChange={() => {}} />;
      case 'famiglia':
        return (
          <div className="space-y-6">
            <FamilyManager familyProfile={familyProfile} />
            <StoreManager onAddStore={async (name) => {
              const newStore = { id: crypto.randomUUID(), name };
              setStores(prev => [...prev, newStore]);
              await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
            }} />
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">

      {/* Mobile Header */}
      <header className="md:hidden bg-emerald-600 text-white p-4 flex justify-between items-center sticky top-0 z-40 shadow-md">
        <div className="flex items-center gap-2">
           <div className="bg-white/20 p-2 rounded-lg"><LayoutDashboard className="w-5 h-5" /></div>
           <h1 className="font-black tracking-tight">{familyProfile.familyName}</h1>
        </div>
        <button onClick={() => setIsSidebarOpen(true)} className="p-2 bg-emerald-700 rounded-xl"><Menu className="w-6 h-6" /></button>
      </header>

      {/* Desktop Sidebar / Mobile Drawer */}
      <aside className={`fixed inset-0 z-50 md:relative md:flex md:w-72 bg-white border-r border-gray-100 flex-col shadow-2xl md:shadow-none transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}`}>
        <div className="p-6 flex justify-between items-center border-b border-gray-50">
          <div className="flex items-center gap-3">
             <div className="bg-emerald-600 p-2.5 rounded-2xl shadow-lg shadow-emerald-100 text-white"><LayoutDashboard className="w-6 h-6" /></div>
             <div>
               <h1 className="font-black text-gray-800 tracking-tighter">{familyProfile.familyName}</h1>
               <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{user?.email?.split('@')[0] || 'Utente'}</p>
             </div>
          </div>
          <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2 text-gray-400"><X className="w-6 h-6" /></button>
        </div>

        <nav className="flex-1 p-4 space-y-1.5 overflow-y-auto">
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavItem view="bilancio" icon={Wallet} label="Bilancio" />
          <NavItem view="spese" icon={Receipt} label="Storico & Spese" />
          <NavItem view="shopping" icon={ShoppingCart} label="Lista Spesa" badge={shoppingList.filter(i => !i.completed).length} />
          <NavItem view="ricorrenti" icon={Repeat} label="Scadenze" badge={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date()).length} />
          <NavItem view="analisi" icon={BarChart3} label="Analisi & Report" />
          <NavItem view="offerte" icon={Percent} label="Caccia Offerte" />
          <NavItem view="famiglia" icon={Users} label="Famiglia & Negozi" />
        </nav>

        <div className="p-4 border-t border-gray-50 space-y-2">
          <button 
            onClick={async () => { 
              await SupabaseService.signOut(); 
              setUser(null);
              setFamilyProfile(null);
              window.location.reload(); 
            }}
            className="w-full flex items-center gap-3 px-4 py-3 text-red-500 font-bold text-sm hover:bg-red-50 rounded-xl transition-colors"
          >
            <LogOut className="w-5 h-5" /> Esci dall'App
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8">
        <div className="mb-6 hidden md:block">
           <h2 className="text-3xl font-black text-gray-800 capitalize tracking-tighter">{activeView.replace('spese', 'Storico Spese')}</h2>
           <p className="text-gray-400 text-sm font-medium">Gestisci il tuo risparmio familiare in tempo reale.</p>
        </div>
        {renderView()}
      </main>

      {/* Mobile Bottom Navigation Bar */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 flex justify-around items-center p-3 z-40 pb-6 safe-area-bottom shadow-[0_-5px_15px_rgba(0,0,0,0.05)]">
         <button onClick={() => setActiveView('dashboard')} className={`p-3 rounded-2xl transition-all ${activeView === 'dashboard' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <LayoutDashboard className="w-6 h-6" />
         </button>
         <button onClick={() => setActiveView('spese')} className={`p-3 rounded-2xl transition-all ${activeView === 'spese' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <Receipt className="w-6 h-6" />
         </button>
         <button onClick={() => setActiveView('shopping')} className={`relative p-3 rounded-2xl transition-all ${activeView === 'shopping' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <ShoppingCart className="w-6 h-6" />
            {shoppingList.filter(i => !i.completed).length > 0 && <span className="absolute top-2 right-2 w-4 h-4 bg-orange-500 text-white text-[9px] font-black rounded-full flex items-center justify-center border-2 border-white">{shoppingList.filter(i => !i.completed).length}</span>}
         </button>
         <button onClick={() => setActiveView('bilancio')} className={`p-3 rounded-2xl transition-all ${activeView === 'bilancio' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <Wallet className="w-6 h-6" />
         </button>
         <button onClick={() => setActiveView('ricorrenti')} className={`p-3 rounded-2xl transition-all ${activeView === 'ricorrenti' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <Repeat className="w-6 h-6" />
         </button>
      </div>

      {/* Backdrop for mobile drawer */}
      {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="fixed inset-0 bg-black/40 backdrop-blur-sm z-40 md:hidden animate-in fade-in duration-300" />}
    </div>
  );
}

export default App;

import { supabase } from '../src/supabaseClient';
import { Expense, Income, Store, RecurringExpense, ShoppingItem, FamilyProfile, Member } from '../types';

/* --- AUTHENTICATION --- */
export const signInWithGoogle = async () => {
  return await supabase.auth.signInWithOAuth({ provider: 'google' });
};

export const signUpWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signUp({ email, password });
};

export const signInWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signInWithPassword({ email, password });
};

export const signOut = async () => {
  return await supabase.auth.signOut();
};

export const getCurrentUser = async () => {
  const { data: { user } } = await supabase.auth.getUser();
  return user;
};

/* --- FAMILY & MEMBERS --- */
// Questa è la query fondamentale che mancava o era incompleta
export const getFamilyForUser = async (userId: string) => {
  const { data, error } = await supabase
    .from('members')
    .select('family_id')
    .eq('user_id', userId)
    .maybeSingle(); // Ritorna null se non trova nulla, senza generare errori bloccanti
  return { data, error };
};

export const getFamilyProfile = async (familyId: string) => {
  return await supabase.from('families').select('*').eq('id', familyId).maybeSingle();
};

export const fetchFamilyMembers = async (familyId: string) => {
  const { data } = await supabase.from('members').select('*').eq('family_id', familyId);
  return (data || []).map((m: any) => ({
    id: m.id,
    name: m.name,
    color: m.color,
    userId: m.user_id,
    isAdmin: m.is_admin
  }));
};

export const joinFamily = async (userId: string, familyId: string, name: string, isAdmin: boolean = false) => {
  return await supabase.from('members').insert({
    user_id: userId,
    family_id: familyId,
    name,
    is_admin: isAdmin,
    color: 'bg-emerald-500'
  });
};

/* --- EXPENSES --- */
export const fetchExpenses = async (familyId: string) => {
  const { data } = await supabase
    .from('expenses')
    .select('*')
    .eq('family_id', familyId)
    .order('date', { ascending: false });

  return (data || []).map((e: any) => ({
    id: e.id,
    product: e.product,
    quantity: e.quantity,
    unitPrice: e.unit_price,
    total: e.total,
    store: e.store,
    date: e.date,
    category: e.category,
    memberId: e.member_id
  }));
};

export const addExpenseToSupabase = async (familyId: string, expense: Expense) => {
  return await supabase.from('expenses').insert({
    id: expense.id,
    family_id: familyId,
    product: expense.product,
    quantity: expense.quantity,
    unit_price: expense.unitPrice,
    total: expense.total,
    store: expense.store,
    date: expense.date,
    category: expense.category,
    member_id: expense.memberId
  });
};

export const deleteExpenseFromSupabase = async (id: string) => {
  return await supabase.from('expenses').delete().eq('id', id);
};

/* --- INCOMES (BILANCIO) --- */
export const fetchIncomes = async (familyId: string) => {
  const { data } = await supabase.from('incomes').select('*').eq('family_id', familyId);
  return (data || []).map((i: any) => ({
    id: i.id,
    source: i.source,
    amount: i.amount,
    date: i.date
  }));
};

export const addIncomeToSupabase = async (familyId: string, income: Income) => {
  return await supabase.from('incomes').insert({
    id: income.id,
    family_id: familyId,
    source: income.source,
    amount: income.amount,
    date: income.date
  });
};

export const deleteIncomeFromSupabase = async (id: string) => {
  return await supabase.from('incomes').delete().eq('id', id);
};

/* --- STORES --- */
export const fetchStores = async (familyId: string) => {
  const { data } = await supabase.from('stores').select('*').eq('family_id', familyId);
  return data || [];
};

export const addStoreToSupabase = async (familyId: string, store: Store) => {
  return await supabase.from('stores').insert({
    id: store.id,
    family_id: familyId,
    name: store.name
  });
};

/* --- RECURRING (SCADENZE) --- */
export const fetchRecurring = async (familyId: string): Promise<RecurringExpense[]> => {
  const { data } = await supabase.from('recurring_expenses').select('*').eq('family_id', familyId);
  return (data || []).map((r: any) => ({ 
    id: r.id, 
    product: r.product, 
    amount: Number(r.amount), 
    store: r.store, 
    frequency: r.frequency, 
    nextDueDate: r.next_due_date, 
    reminderDays: r.reminder_days,
    customFields: r.custom_fields || [] 
  }));
};

export const addRecurringToSupabase = async (familyId: string, item: RecurringExpense) => {
  return await supabase.from('recurring_expenses').insert({ 
    id: item.id, 
    family_id: familyId, 
    product: item.product, 
    amount: item.amount, 
    store: item.store, 
    frequency: item.frequency, 
    next_due_date: item.nextDueDate, 
    reminder_days: item.reminderDays,
    custom_fields: item.customFields 
  });
};

export const updateRecurringInSupabase = async (item: RecurringExpense) => {
  return await supabase.from('recurring_expenses').update({ 
    product: item.product, 
    amount: item.amount, 
    store: item.store, 
    frequency: item.frequency, 
    next_due_date: item.nextDueDate, 
    reminder_days: item.reminderDays,
    custom_fields: item.customFields 
  }).eq('id', item.id);
};

export const deleteRecurringFromSupabase = async (id: string) => {
  return await supabase.from('recurring_expenses').delete().eq('id', id);
};

/* --- SHOPPING LIST --- */
export const fetchShoppingList = async (familyId: string) => {
  const { data } = await supabase.from('shopping_list').select('*').eq('family_id', familyId);
  return (data || []).map((s: any) => ({
    id: s.id,
    product: s.product,
    store: s.store,
    completed: s.completed
  }));
};

export const addShoppingItemToSupabase = async (familyId: string, item: ShoppingItem) => {
  return await supabase.from('shopping_list').insert({
    id: item.id,
    family_id: familyId,
    product: item.product,
    store: item.store,
    completed: item.completed
  });
};

export const updateShoppingItemInSupabase = async (item: ShoppingItem) => {
  return await supabase.from('shopping_list').update({
    completed: item.completed
  }).eq('id', item.id);
};

export const deleteShoppingItemFromSupabase = async (id: string) => {
  return await supabase.from('shopping_list').delete().eq('id', id);
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, 
  Income, CategoryDefinition, ShoppingItem, RecurringExpense, CustomField 
} from './types';
import * as SupabaseService from './services/supabaseService';
import { LoginScreen } from './components/LoginScreen';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { StoreManager } from './components/StoreManager';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { ShoppingListManager } from './components/ShoppingListManager';
import { IncomeManager } from './components/IncomeManager';
import { FamilyManager } from './components/FamilyManager';
import { OffersFinder } from './components/OffersFinder';
import { ReceiptScanner } from './components/ReceiptScanner';
import { 
  LayoutDashboard, ShoppingCart, Receipt, Repeat, BarChart3, 
  Wallet, Percent, Users, LogOut, Menu, X, Loader2 
} from 'lucide-react';

type View = 'dashboard' | 'shopping' | 'spese' | 'ricorrenti' | 'analisi' | 'bilancio' | 'offerte' | 'famiglia';

function App() {
  const [user, setUser] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Data States
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [shoppingList, setShoppingList] = useState<ShoppingItem[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);
  const [initialLoading, setInitialLoading] = useState(true);
  const [isFetchingFamily, setIsFetchingFamily] = useState(false);

  // 1. Inizializzazione: Controlla la sessione
  useEffect(() => {
    const initApp = async () => {
      try {
        const currentUser = await SupabaseService.getCurrentUser();
        if (currentUser) {
          setUser(currentUser);
          // La ricerca della famiglia viene attivata dal secondo useEffect
        } else {
          setInitialLoading(false);
        }
      } catch (err) {
        console.error("Errore inizializzazione sessione:", err);
        setInitialLoading(false);
      }
    };
    initApp();
  }, []);

  // 2. Monitoraggio Utente: Se loggato e senza profilo, cercalo nel DB
  useEffect(() => {
    const findExistingFamily = async () => {
      if (user && !familyProfile && !isFetchingFamily) {
        setIsFetchingFamily(true);
        try {
          const { data: memberData } = await SupabaseService.getFamilyForUser(user.id);
          if (memberData?.family_id) {
            console.log("Famiglia esistente trovata:", memberData.family_id);
            await loadFamilyData(memberData.family_id);
          } else {
            console.log("Nessuna famiglia associata per questo account.");
          }
        } catch (err) {
          console.error("Errore ricerca famiglia:", err);
        } finally {
          setIsFetchingFamily(false);
          setInitialLoading(false);
        }
      }
    };
    findExistingFamily();
  }, [user, familyProfile, isFetchingFamily]);

  const loadFamilyData = async (familyId: string) => {
    try {
      const [profileRes, exps, recs, shops, strs, incs] = await Promise.all([
        SupabaseService.getFamilyProfile(familyId),
        SupabaseService.fetchExpenses(familyId),
        SupabaseService.fetchRecurring(familyId),
        SupabaseService.fetchShoppingList(familyId),
        SupabaseService.fetchStores(familyId),
        SupabaseService.fetchIncomes(familyId)
      ]);

      if (profileRes.data) {
        const members = await SupabaseService.fetchFamilyMembers(familyId);
        setFamilyProfile({
          id: profileRes.data.id,
          familyName: profileRes.data.family_name,
          members: members,
          createdAt: new Date(profileRes.data.created_at).getTime()
        });
        setExpenses(exps);
        setRecurringExpenses(recs);
        setShoppingList(shops);
        setIncomes(incs);
        if (strs && strs.length > 0) setStores(strs);
      }
    } catch (err) {
      console.error("Errore caricamento dati famiglia:", err);
    }
  };

  const handleSetupComplete = async (profile: FamilyProfile) => {
    // Chiamato dopo che LoginScreen crea o si unisce a una famiglia
    if (user) {
      const { data: existingLink } = await SupabaseService.getFamilyForUser(user.id);
      if (!existingLink) {
        // Salva il collegamento permanente nel database Supabase
        await SupabaseService.joinFamily(user.id, profile.id, user.email?.split('@')[0] || 'Utente', true);
      }
    }
    await loadFamilyData(profile.id);
  };

  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const NavItem = ({ view, icon: Icon, label, badge }: { view: View, icon: any, label: string, badge?: number }) => (
    <button
      onClick={() => { setActiveView(view); setIsSidebarOpen(false); }}
      className={`w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all ${
        activeView === view ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-200' : 'text-gray-500 hover:bg-emerald-50 hover:text-emerald-600'
      }`}
    >
      <div className="flex items-center gap-3">
        <Icon className="w-5 h-5" />
        <span className="font-bold text-sm">{label}</span>
      </div>
      {badge !== undefined && badge > 0 && (
        <span className={`text-[10px] px-2 py-0.5 rounded-full font-black ${activeView === view ? 'bg-white text-emerald-600' : 'bg-emerald-600 text-white'}`}>
          {badge}
        </span>
      )}
    </button>
  );

  if (initialLoading || isFetchingFamily) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center">
          <Loader2 className="w-12 h-12 text-emerald-600 animate-spin mx-auto mb-4" />
          <p className="text-gray-500 font-bold tracking-tight">Sincronizzazione Account...</p>
        </div>
      </div>
    );
  }

  // Se l'utente non è loggato O non ha ancora una famiglia associata, mostriamo il Login/Setup
  if (!user || !familyProfile) {
    return <LoginScreen 
      onSetupComplete={handleSetupComplete} 
      onUserLogin={setUser} 
      isSupabaseAuth={!!user} 
    />;
  }

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return (
          <div className="space-y-6 animate-in fade-in duration-300">
            <ReceiptScanner onScanComplete={async (data) => {
              for (const item of data.items) {
                const newExp: Expense = {
                  id: crypto.randomUUID(),
                  product: item.product, quantity: item.quantity, unitPrice: item.unitPrice, total: item.total,
                  store: data.store || 'Negozio', date: new Date().toISOString(), category: item.category || 'Altro'
                };
                setExpenses(prev => [newExp, ...prev]);
                await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
              }
            }} />
            <DueExpensesAlert 
              dueExpenses={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date())} 
              onProcessExpense={() => setActiveView('ricorrenti')} 
            />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                  <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2">
                    <ShoppingCart className="w-5 h-5 text-orange-500" /> Da comprare oggi
                  </h3>
                  {shoppingList.filter(i => !i.completed).length > 0 ? (
                    <div className="space-y-2">
                      {shoppingList.filter(i => !i.completed).slice(0, 3).map(item => (
                        <div key={item.id} className="flex items-center gap-3 text-sm text-gray-600 bg-gray-50 p-3 rounded-xl border border-gray-100">
                           <div className="w-2 h-2 rounded-full bg-orange-400" />
                           {item.product} <span className="text-[10px] text-gray-400 uppercase font-bold ml-auto">{item.store}</span>
                        </div>
                      ))}
                      <button onClick={() => setActiveView('shopping')} className="w-full py-2 text-xs font-bold text-emerald-600 hover:underline">Vedi tutta la lista</button>
                    </div>
                  ) : (
                    <p className="text-xs text-gray-400 italic">Lista spesa vuota.</p>
                  )}
               </div>
               <AIInsight expenses={expenses} />
            </div>
          </div>
        );
      case 'shopping':
        return (
          <ShoppingListManager 
            items={shoppingList} stores={stores} productHistory={productHistory}
            onAddItem={async (p, s) => {
              const newItem = { id: crypto.randomUUID(), product: p, store: s, completed: false };
              setShoppingList(prev => [...prev, newItem]);
              await SupabaseService.addShoppingItemToSupabase(familyProfile.id, newItem);
            }}
            onToggleItem={async (id) => {
              const item = shoppingList.find(i => i.id === id);
              if (item) {
                const updated = { ...item, completed: !item.completed };
                setShoppingList(prev => prev.map(i => i.id === id ? updated : i));
                await SupabaseService.updateShoppingItemInSupabase(updated);
              }
            }}
            onDeleteItem={async (id) => {
              setShoppingList(prev => prev.filter(i => i.id !== id));
              await SupabaseService.deleteShoppingItemFromSupabase(id);
            }}
          />
        );
      case 'spese':
        return (
          <div className="space-y-6">
            <ExpenseForm 
              stores={stores} members={familyProfile.members} 
              existingProducts={Object.keys(productHistory)} productHistory={productHistory} 
              onAddExpense={async (p, q, u, t, s) => {
                const newExp: Expense = {
                  id: crypto.randomUUID(), product: p, quantity: q, unitPrice: u, total: t, store: s,
                  date: new Date().toISOString(), category: 'Altro'
                };
                setExpenses(prev => [newExp, ...prev]);
                await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
              }} 
              isAnalyzing={false}
            />
            <ExpenseList 
              expenses={expenses} stores={stores} 
              onDelete={async (id) => {
                setExpenses(prev => prev.filter(e => e.id !== id));
                await SupabaseService.deleteExpenseFromSupabase(id);
              }} 
              onEdit={async (updated) => {
                setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e));
              }} 
            />
          </div>
        );
      case 'bilancio':
        return (
          <IncomeManager 
            incomes={incomes} expenses={expenses} 
            onAddIncome={async (s, a, d) => {
              const newInc = { id: crypto.randomUUID(), source: s, amount: a, date: d };
              setIncomes(prev => [...prev, newInc]);
              await SupabaseService.addIncomeToSupabase(familyProfile.id, newInc);
            }}
            onDeleteIncome={async (id) => {
              setIncomes(prev => prev.filter(i => i.id !== id));
              await SupabaseService.deleteIncomeFromSupabase(id);
            }}
          />
        );
      case 'ricorrenti':
        return (
          <RecurringManager 
            recurringExpenses={recurringExpenses} stores={stores}
            onAddRecurring={async (p, a, s, f, d, r, c) => {
              const newItem = { id: crypto.randomUUID(), product: p, amount: a, store: s, frequency: f, nextDueDate: d, reminderDays: r, customFields: c };
              setRecurringExpenses(prev => [...prev, newItem]);
              await SupabaseService.addRecurringToSupabase(familyProfile.id, newItem);
            }}
            onUpdateRecurring={async (updated) => {
              setRecurringExpenses(prev => prev.map(r => r.id === updated.id ? updated : r));
              await SupabaseService.updateRecurringInSupabase(updated);
            }}
            onDeleteRecurring={async (id) => {
              setRecurringExpenses(prev => prev.filter(r => r.id !== id));
              await SupabaseService.deleteRecurringFromSupabase(id);
            }}
          />
        );
      case 'analisi':
        return <Analytics expenses={expenses} />;
      case 'offerte':
        return <OffersFinder stores={stores} savedCity="" savedStores={[]} notificationsEnabled={false} onPreferencesChange={() => {}} />;
      case 'famiglia':
        return (
          <div className="space-y-6">
            <FamilyManager familyProfile={familyProfile} />
            <StoreManager onAddStore={async (name) => {
              const newStore = { id: crypto.randomUUID(), name };
              setStores(prev => [...prev, newStore]);
              await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
            }} />
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">

      {/* Mobile Header */}
      <header className="md:hidden bg-emerald-600 text-white p-4 flex justify-between items-center sticky top-0 z-40 shadow-md">
        <div className="flex items-center gap-2">
           <div className="bg-white/20 p-2 rounded-lg"><LayoutDashboard className="w-5 h-5" /></div>
           <h1 className="font-black tracking-tight">{familyProfile.familyName}</h1>
        </div>
        <button onClick={() => setIsSidebarOpen(true)} className="p-2 bg-emerald-700 rounded-xl"><Menu className="w-6 h-6" /></button>
      </header>

      {/* Desktop Sidebar / Mobile Drawer */}
      <aside className={`fixed inset-0 z-50 md:relative md:flex md:w-72 bg-white border-r border-gray-100 flex-col shadow-2xl md:shadow-none transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}`}>
        <div className="p-6 flex justify-between items-center border-b border-gray-50">
          <div className="flex items-center gap-3">
             <div className="bg-emerald-600 p-2.5 rounded-2xl shadow-lg shadow-emerald-100 text-white"><LayoutDashboard className="w-6 h-6" /></div>
             <div>
               <h1 className="font-black text-gray-800 tracking-tighter">{familyProfile.familyName}</h1>
               <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{user?.email?.split('@')[0] || 'Utente'}</p>
             </div>
          </div>
          <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2 text-gray-400"><X className="w-6 h-6" /></button>
        </div>

        <nav className="flex-1 p-4 space-y-1.5 overflow-y-auto">
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavItem view="bilancio" icon={Wallet} label="Bilancio" />
          <NavItem view="spese" icon={Receipt} label="Storico & Spese" />
          <NavItem view="shopping" icon={ShoppingCart} label="Lista Spesa" badge={shoppingList.filter(i => !i.completed).length} />
          <NavItem view="ricorrenti" icon={Repeat} label="Scadenze" badge={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date()).length} />
          <NavItem view="analisi" icon={BarChart3} label="Analisi & Report" />
          <NavItem view="offerte" icon={Percent} label="Caccia Offerte" />
          <NavItem view="famiglia" icon={Users} label="Famiglia & Negozi" />
        </nav>

        <div className="p-4 border-t border-gray-50 space-y-2">
          <button 
            onClick={async () => { 
              await SupabaseService.signOut(); 
              setUser(null);
              setFamilyProfile(null);
              window.location.reload(); 
            }}
            className="w-full flex items-center gap-3 px-4 py-3 text-red-500 font-bold text-sm hover:bg-red-50 rounded-xl transition-colors"
          >
            <LogOut className="w-5 h-5" /> Esci dall'App
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8">
        <div className="mb-6 hidden md:block">
           <h2 className="text-3xl font-black text-gray-800 capitalize tracking-tighter">{activeView.replace('spese', 'Storico Spese')}</h2>
           <p className="text-gray-400 text-sm font-medium">Gestisci il tuo risparmio familiare in tempo reale.</p>
        </div>
        {renderView()}
      </main>

      {/* Mobile Bottom Navigation Bar */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 flex justify-around items-center p-3 z-40 pb-6 safe-area-bottom shadow-[0_-5px_15px_rgba(0,0,0,0.05)]">
         <button onClick={() => setActiveView('dashboard')} className={`p-3 rounded-2xl transition-all ${activeView === 'dashboard' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <LayoutDashboard className="w-6 h-6" />
         </button>
         <button onClick={() => setActiveView('spese')} className={`p-3 rounded-2xl transition-all ${activeView === 'spese' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <Receipt className="w-6 h-6" />
         </button>
         <button onClick={() => setActiveView('shopping')} className={`relative p-3 rounded-2xl transition-all ${activeView === 'shopping' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <ShoppingCart className="w-6 h-6" />
            {shoppingList.filter(i => !i.completed).length > 0 && <span className="absolute top-2 right-2 w-4 h-4 bg-orange-500 text-white text-[9px] font-black rounded-full flex items-center justify-center border-2 border-white">{shoppingList.filter(i => !i.completed).length}</span>}
         </button>
         <button onClick={() => setActiveView('bilancio')} className={`p-3 rounded-2xl transition-all ${activeView === 'bilancio' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <Wallet className="w-6 h-6" />
         </button>
         <button onClick={() => setActiveView('ricorrenti')} className={`p-3 rounded-2xl transition-all ${activeView === 'ricorrenti' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}>
            <Repeat className="w-6 h-6" />
         </button>
      </div>

      {/* Backdrop for mobile drawer */}
      {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="fixed inset-0 bg-black/40 backdrop-blur-sm z-40 md:hidden animate-in fade-in duration-300" />}
    </div>
  );
}

export default App;

import { supabase } from '../src/supabaseClient';
import { Expense, Income, Store, RecurringExpense, ShoppingItem, FamilyProfile, Member } from '../types';

/* --- AUTHENTICATION --- */
export const signInWithGoogle = async () => {
  return await supabase.auth.signInWithOAuth({ provider: 'google' });
};

export const signUpWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signUp({ email, password });
};

export const signInWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signInWithPassword({ email, password });
};

export const signOut = async () => {
  return await supabase.auth.signOut();
};

export const getCurrentUser = async () => {
  const { data: { user } } = await supabase.auth.getUser();
  return user;
};

/* --- FAMILY & MEMBERS --- */
export const getFamilyForUser = async (userId: string) => {
  // Query pulita per trovare la famiglia associata all'ID utente
  const { data, error } = await supabase
    .from('members')
    .select('family_id')
    .eq('user_id', userId)
    .maybeSingle();
  return { data, error };
};

export const getFamilyProfile = async (familyId: string) => {
  return await supabase.from('families').select('*').eq('id', familyId).maybeSingle();
};

export const fetchFamilyMembers = async (familyId: string) => {
  const { data } = await supabase.from('members').select('*').eq('family_id', familyId);
  return (data || []).map((m: any) => ({
    id: m.id,
    name: m.name,
    color: m.color,
    userId: m.user_id,
    isAdmin: m.is_admin
  }));
};

export const joinFamily = async (userId: string, familyId: string, name: string, isAdmin: boolean = false) => {
  return await supabase.from('members').insert({
    user_id: userId,
    family_id: familyId,
    name,
    is_admin: isAdmin,
    color: 'bg-emerald-500'
  });
};

/* --- DATA FETCHING --- */
export const fetchExpenses = async (familyId: string) => {
  const { data } = await supabase.from('expenses').select('*').eq('family_id', familyId).order('date', { ascending: false });
  return (data || []).map((e: any) => ({
    id: e.id, product: e.product, quantity: e.quantity, unitPrice: e.unit_price, total: e.total,
    store: e.store, date: e.date, category: e.category, memberId: e.member_id
  }));
};

export const addExpenseToSupabase = async (familyId: string, expense: Expense) => {
  return await supabase.from('expenses').insert({
    id: expense.id, family_id: familyId, product: expense.product, quantity: expense.quantity,
    unit_price: expense.unitPrice, total: expense.total, store: expense.store, date: expense.date,
    category: expense.category, member_id: expense.memberId
  });
};

export const deleteExpenseFromSupabase = async (id: string) => {
  return await supabase.from('expenses').delete().eq('id', id);
};

export const fetchIncomes = async (familyId: string) => {
  const { data } = await supabase.from('incomes').select('*').eq('family_id', familyId);
  return (data || []).map((i: any) => ({ id: i.id, source: i.source, amount: i.amount, date: i.date }));
};

export const addIncomeToSupabase = async (familyId: string, income: Income) => {
  return await supabase.from('incomes').insert({
    id: income.id, family_id: familyId, source: income.source, amount: income.amount, date: income.date
  });
};

export const deleteIncomeFromSupabase = async (id: string) => {
  return await supabase.from('incomes').delete().eq('id', id);
};

export const fetchStores = async (familyId: string) => {
  const { data } = await supabase.from('stores').select('*').eq('family_id', familyId);
  return data || [];
};

export const addStoreToSupabase = async (familyId: string, store: Store) => {
  return await supabase.from('stores').insert({ id: store.id, family_id: familyId, name: store.name });
};

export const fetchRecurring = async (familyId: string): Promise<RecurringExpense[]> => {
  const { data } = await supabase.from('recurring_expenses').select('*').eq('family_id', familyId);
  return (data || []).map((r: any) => ({ 
    id: r.id, product: r.product, amount: Number(r.amount), store: r.store, frequency: r.frequency, 
    nextDueDate: r.next_due_date, reminderDays: r.reminder_days, customFields: r.custom_fields || [] 
  }));
};

export const addRecurringToSupabase = async (familyId: string, item: RecurringExpense) => {
  return await supabase.from('recurring_expenses').insert({ 
    id: item.id, family_id: familyId, product: item.product, amount: item.amount, store: item.store, 
    frequency: item.frequency, next_due_date: item.nextDueDate, reminder_days: item.reminderDays, custom_fields: item.customFields 
  });
};

export const updateRecurringInSupabase = async (item: RecurringExpense) => {
  return await supabase.from('recurring_expenses').update({ 
    product: item.product, amount: item.amount, store: item.store, frequency: item.frequency, 
    next_due_date: item.nextDueDate, reminder_days: item.reminderDays, custom_fields: item.customFields 
  }).eq('id', item.id);
};

export const deleteRecurringFromSupabase = async (id: string) => {
  return await supabase.from('recurring_expenses').delete().eq('id', id);
};

export const fetchShoppingList = async (familyId: string) => {
  const { data } = await supabase.from('shopping_list').select('*').eq('family_id', familyId);
  return (data || []).map((s: any) => ({ id: s.id, product: s.product, store: s.store, completed: s.completed }));
};

export const addShoppingItemToSupabase = async (familyId: string, item: ShoppingItem) => {
  return await supabase.from('shopping_list').insert({
    id: item.id, family_id: familyId, product: item.product, store: item.store, completed: item.completed
  });
};

export const updateShoppingItemInSupabase = async (item: ShoppingItem) => {
  return await supabase.from('shopping_list').update({ completed: item.completed }).eq('id', item.id);
};

export const deleteShoppingItemFromSupabase = async (id: string) => {
  return await supabase.from('shopping_list').delete().eq('id', id);
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, 
  Income, CategoryDefinition, ShoppingItem, RecurringExpense, CustomField 
} from './types';
import * as SupabaseService from './services/supabaseService';
import { LoginScreen } from './components/LoginScreen';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { StoreManager } from './components/StoreManager';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { ShoppingListManager } from './components/ShoppingListManager';
import { IncomeManager } from './components/IncomeManager';
import { FamilyManager } from './components/FamilyManager';
import { OffersFinder } from './components/OffersFinder';
import { ReceiptScanner } from './components/ReceiptScanner';
import { 
  LayoutDashboard, ShoppingCart, Receipt, Repeat, BarChart3, 
  Wallet, Percent, Users, LogOut, Menu, X, Loader2 
} from 'lucide-react';

type View = 'dashboard' | 'shopping' | 'spese' | 'ricorrenti' | 'analisi' | 'bilancio' | 'offerte' | 'famiglia';

function App() {
  const [user, setUser] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Data States
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [shoppingList, setShoppingList] = useState<ShoppingItem[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);

  // Loading States
  const [isReady, setIsReady] = useState(false);

  // 1. Inizializzazione Sessione e Caricamento Dati
  useEffect(() => {
    const initApp = async () => {
      try {
        const currentUser = await SupabaseService.getCurrentUser();
        if (currentUser) {
          setUser(currentUser);
          const { data: memberData } = await SupabaseService.getFamilyForUser(currentUser.id);
          if (memberData?.family_id) {
            await loadFamilyData(memberData.family_id);
          }
        }
      } catch (err) {
        console.error("Errore inizializzazione:", err);
      } finally {
        setIsReady(true); // Sblocca SEMPRE l'app qui
      }
    };
    initApp();
  }, []);

  const loadFamilyData = async (familyId: string) => {
    try {
      const [profileRes, exps, recs, shops, strs, incs] = await Promise.all([
        SupabaseService.getFamilyProfile(familyId),
        SupabaseService.fetchExpenses(familyId),
        SupabaseService.fetchRecurring(familyId),
        SupabaseService.fetchShoppingList(familyId),
        SupabaseService.fetchStores(familyId),
        SupabaseService.fetchIncomes(familyId)
      ]);

      if (profileRes.data) {
        const members = await SupabaseService.fetchFamilyMembers(familyId);
        setFamilyProfile({
          id: profileRes.data.id,
          familyName: profileRes.data.family_name,
          members: members,
          createdAt: new Date(profileRes.data.created_at).getTime()
        });
        setExpenses(exps);
        setRecurringExpenses(recs);
        setShoppingList(shops);
        setIncomes(incs);
        if (strs && strs.length > 0) setStores(strs);
      }
    } catch (err) {
      console.error("Errore caricamento dati:", err);
    }
  };

  const handleSetupComplete = async (profile: FamilyProfile) => {
    if (user) {
      const { data: existingLink } = await SupabaseService.getFamilyForUser(user.id);
      if (!existingLink) {
        await SupabaseService.joinFamily(user.id, profile.id, user.email?.split('@')[0] || 'Utente', true);
      }
    }
    await loadFamilyData(profile.id);
  };

  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const NavItem = ({ view, icon: Icon, label, badge }: { view: View, icon: any, label: string, badge?: number }) => (
    <button
      onClick={() => { setActiveView(view); setIsSidebarOpen(false); }}
      className={`w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all ${
        activeView === view ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-200' : 'text-gray-500 hover:bg-emerald-50 hover:text-emerald-600'
      }`}
    >
      <div className="flex items-center gap-3">
        <Icon className="w-5 h-5" />
        <span className="font-bold text-sm">{label}</span>
      </div>
      {badge !== undefined && badge > 0 && (
        <span className={`text-[10px] px-2 py-0.5 rounded-full font-black ${activeView === view ? 'bg-white text-emerald-600' : 'bg-emerald-600 text-white'}`}>
          {badge}
        </span>
      )}
    </button>
  );

  if (!isReady) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center">
          <Loader2 className="w-12 h-12 text-emerald-600 animate-spin mx-auto mb-4" />
          <p className="text-gray-500 font-bold tracking-tight">Sincronizzazione Account...</p>
        </div>
      </div>
    );
  }

  if (!user || !familyProfile) {
    return <LoginScreen 
      onSetupComplete={handleSetupComplete} 
      onUserLogin={(u) => { setUser(u); window.location.reload(); }} // Ricarichiamo per attivare l'init pulito
      isSupabaseAuth={!!user} 
    />;
  }

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return (
          <div className="space-y-6 animate-in fade-in duration-300">
            <ReceiptScanner onScanComplete={async (data) => {
              for (const item of data.items) {
                const newExp: Expense = {
                  id: crypto.randomUUID(),
                  product: item.product, quantity: item.quantity, unitPrice: item.unitPrice, total: item.total,
                  store: data.store || 'Negozio', date: new Date().toISOString(), category: item.category || 'Altro'
                };
                setExpenses(prev => [newExp, ...prev]);
                await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
              }
            }} />
            <DueExpensesAlert 
              dueExpenses={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date())} 
              onProcessExpense={() => setActiveView('ricorrenti')} 
            />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                  <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2">
                    <ShoppingCart className="w-5 h-5 text-orange-500" /> Da comprare oggi
                  </h3>
                  {shoppingList.filter(i => !i.completed).length > 0 ? (
                    <div className="space-y-2">
                      {shoppingList.filter(i => !i.completed).slice(0, 3).map(item => (
                        <div key={item.id} className="flex items-center gap-3 text-sm text-gray-600 bg-gray-50 p-3 rounded-xl border border-gray-100">
                           <div className="w-2 h-2 rounded-full bg-orange-400" />
                           {item.product} <span className="text-[10px] text-gray-400 uppercase font-bold ml-auto">{item.store}</span>
                        </div>
                      ))}
                      <button onClick={() => setActiveView('shopping')} className="w-full py-2 text-xs font-bold text-emerald-600 hover:underline">Vedi tutta la lista</button>
                    </div>
                  ) : (
                    <p className="text-xs text-gray-400 italic">Lista spesa vuota.</p>
                  )}
               </div>
               <AIInsight expenses={expenses} />
            </div>
          </div>
        );
      case 'shopping':
        return (
          <ShoppingListManager 
            items={shoppingList} stores={stores} productHistory={productHistory}
            onAddItem={async (p, s) => {
              const newItem = { id: crypto.randomUUID(), product: p, store: s, completed: false };
              setShoppingList(prev => [...prev, newItem]);
              await SupabaseService.addShoppingItemToSupabase(familyProfile.id, newItem);
            }}
            onToggleItem={async (id) => {
              const item = shoppingList.find(i => i.id === id);
              if (item) {
                const updated = { ...item, completed: !item.completed };
                setShoppingList(prev => prev.map(i => i.id === id ? updated : i));
                await SupabaseService.updateShoppingItemInSupabase(updated);
              }
            }}
            onDeleteItem={async (id) => {
              setShoppingList(prev => prev.filter(i => i.id !== id));
              await SupabaseService.deleteShoppingItemFromSupabase(id);
            }}
          />
        );
      case 'spese':
        return (
          <div className="space-y-6">
            <ExpenseForm 
              stores={stores} members={familyProfile.members} 
              existingProducts={Object.keys(productHistory)} productHistory={productHistory} 
              onAddExpense={async (p, q, u, t, s) => {
                const newExp: Expense = {
                  id: crypto.randomUUID(), product: p, quantity: q, unitPrice: u, total: t, store: s,
                  date: new Date().toISOString(), category: 'Altro'
                };
                setExpenses(prev => [newExp, ...prev]);
                await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
              }} 
              isAnalyzing={false}
            />
            <ExpenseList 
              expenses={expenses} stores={stores} 
              onDelete={async (id) => {
                setExpenses(prev => prev.filter(e => e.id !== id));
                await SupabaseService.deleteExpenseFromSupabase(id);
              }} 
              onEdit={async (updated) => {
                setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e));
              }} 
            />
          </div>
        );
      case 'bilancio':
        return (
          <IncomeManager 
            incomes={incomes} expenses={expenses} 
            onAddIncome={async (s, a, d) => {
              const newInc = { id: crypto.randomUUID(), source: s, amount: a, date: d };
              setIncomes(prev => [...prev, newInc]);
              await SupabaseService.addIncomeToSupabase(familyProfile.id, newInc);
            }}
            onDeleteIncome={async (id) => {
              setIncomes(prev => prev.filter(i => i.id !== id));
              await SupabaseService.deleteIncomeFromSupabase(id);
            }}
          />
        );
      case 'ricorrenti':
        return (
          <RecurringManager 
            recurringExpenses={recurringExpenses} stores={stores}
            onAddRecurring={async (p, a, s, f, d, r, c) => {
              const newItem = { id: crypto.randomUUID(), product: p, amount: a, store: s, frequency: f, nextDueDate: d, reminderDays: r, customFields: c };
              setRecurringExpenses(prev => [...prev, newItem]);
              await SupabaseService.addRecurringToSupabase(familyProfile.id, newItem);
            }}
            onUpdateRecurring={async (updated) => {
              setRecurringExpenses(prev => prev.map(r => r.id === updated.id ? updated : r));
              await SupabaseService.updateRecurringInSupabase(updated);
            }}
            onDeleteRecurring={async (id) => {
              setRecurringExpenses(prev => prev.filter(r => r.id !== id));
              await SupabaseService.deleteRecurringFromSupabase(id);
            }}
          />
        );
      case 'analisi':
        return <Analytics expenses={expenses} />;
      case 'offerte':
        return <OffersFinder stores={stores} savedCity="" savedStores={[]} notificationsEnabled={false} onPreferencesChange={() => {}} />;
      case 'famiglia':
        return (
          <div className="space-y-6">
            <FamilyManager familyProfile={familyProfile} />
            <StoreManager onAddStore={async (name) => {
              const newStore = { id: crypto.randomUUID(), name };
              setStores(prev => [...prev, newStore]);
              await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
            }} />
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">
      <header className="md:hidden bg-emerald-600 text-white p-4 flex justify-between items-center sticky top-0 z-40 shadow-md">
        <div className="flex items-center gap-2">
           <div className="bg-white/20 p-2 rounded-lg"><LayoutDashboard className="w-5 h-5" /></div>
           <h1 className="font-black tracking-tight">{familyProfile.familyName}</h1>
        </div>
        <button onClick={() => setIsSidebarOpen(true)} className="p-2 bg-emerald-700 rounded-xl"><Menu className="w-6 h-6" /></button>
      </header>

      <aside className={`fixed inset-0 z-50 md:relative md:flex md:w-72 bg-white border-r border-gray-100 flex-col shadow-2xl md:shadow-none transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}`}>
        <div className="p-6 flex justify-between items-center border-b border-gray-50">
          <div className="flex items-center gap-3">
             <div className="bg-emerald-600 p-2.5 rounded-2xl shadow-lg shadow-emerald-100 text-white"><LayoutDashboard className="w-6 h-6" /></div>
             <div>
               <h1 className="font-black text-gray-800 tracking-tighter">{familyProfile.familyName}</h1>
               <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{user?.email?.split('@')[0] || 'Utente'}</p>
             </div>
          </div>
          <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2 text-gray-400"><X className="w-6 h-6" /></button>
        </div>
        <nav className="flex-1 p-4 space-y-1.5 overflow-y-auto">
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavItem view="bilancio" icon={Wallet} label="Bilancio" />
          <NavItem view="spese" icon={Receipt} label="Storico & Spese" />
          <NavItem view="shopping" icon={ShoppingCart} label="Lista Spesa" badge={shoppingList.filter(i => !i.completed).length} />
          <NavItem view="ricorrenti" icon={Repeat} label="Scadenze" badge={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date()).length} />
          <NavItem view="analisi" icon={BarChart3} label="Analisi & Report" />
          <NavItem view="offerte" icon={Percent} label="Caccia Offerte" />
          <NavItem view="famiglia" icon={Users} label="Famiglia & Negozi" />
        </nav>
        <div className="p-4 border-t border-gray-50 space-y-2">
          <button onClick={async () => { await SupabaseService.signOut(); window.location.reload(); }} className="w-full flex items-center gap-3 px-4 py-3 text-red-500 font-bold text-sm hover:bg-red-50 rounded-xl transition-colors">
            <LogOut className="w-5 h-5" /> Esci dall'App
          </button>
        </div>
      </aside>

      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8">
        {renderView()}
      </main>

      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 flex justify-around items-center p-3 z-40 pb-6 safe-area-bottom shadow-[0_-5px_15px_rgba(0,0,0,0.05)]">
         <button onClick={() => setActiveView('dashboard')} className={`p-3 rounded-2xl transition-all ${activeView === 'dashboard' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}><LayoutDashboard className="w-6 h-6" /></button>
         <button onClick={() => setActiveView('spese')} className={`p-3 rounded-2xl transition-all ${activeView === 'spese' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}><Receipt className="w-6 h-6" /></button>
         <button onClick={() => setActiveView('shopping')} className={`relative p-3 rounded-2xl transition-all ${activeView === 'shopping' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}><ShoppingCart className="w-6 h-6" />{shoppingList.filter(i => !i.completed).length > 0 && <span className="absolute top-2 right-2 w-4 h-4 bg-orange-500 text-white text-[9px] font-black rounded-full flex items-center justify-center border-2 border-white">{shoppingList.filter(i => !i.completed).length}</span>}</button>
         <button onClick={() => setActiveView('bilancio')} className={`p-3 rounded-2xl transition-all ${activeView === 'bilancio' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}><Wallet className="w-6 h-6" /></button>
         <button onClick={() => setActiveView('ricorrenti')} className={`p-3 rounded-2xl transition-all ${activeView === 'ricorrenti' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}><Repeat className="w-6 h-6" /></button>
      </div>
      {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="fixed inset-0 bg-black/40 backdrop-blur-sm z-40 md:hidden animate-in fade-in duration-300" />}
    </div>
  );
}

export default App;

import { supabase } from '../src/supabaseClient';
import { Expense, Income, Store, RecurringExpense, ShoppingItem, FamilyProfile, Member } from '../types';

/* --- AUTHENTICATION --- */
export const signInWithGoogle = async () => {
  return await supabase.auth.signInWithOAuth({ provider: 'google' });
};

export const signUpWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signUp({ email, password });
};

export const signInWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signInWithPassword({ email, password });
};

export const signOut = async () => {
  return await supabase.auth.signOut();
};

export const getCurrentUser = async () => {
  const { data: { user } } = await supabase.auth.getUser();
  return user;
};

/* --- FAMILY & MEMBERS --- */
export const getFamilyForUser = async (userId: string) => {
  // Cerchiamo nella tabella members se questo user_id è già associato a una famiglia
  const { data, error } = await supabase
    .from('members')
    .select('family_id')
    .eq('user_id', userId)
    .maybeSingle();
  return { data, error };
};

export const getFamilyProfile = async (familyId: string) => {
  return await supabase.from('families').select('*').eq('id', familyId).maybeSingle();
};

export const fetchFamilyMembers = async (familyId: string) => {
  const { data } = await supabase.from('members').select('*').eq('family_id', familyId);
  return (data || []).map((m: any) => ({
    id: m.id,
    name: m.name,
    color: m.color,
    userId: m.user_id,
    isAdmin: m.is_admin
  }));
};

export const createFamilyAndJoin = async (userId: string, familyName: string, userEmail: string) => {
  const familyId = crypto.randomUUID();

  // 1. Crea la famiglia
  const { error: famError } = await supabase.from('families').insert({
    id: familyId,
    family_name: familyName,
    created_at: new Date().toISOString()
  });

  if (famError) throw famError;

  // 2. Aggiungi l'utente come amministratore
  const { error: memError } = await supabase.from('members').insert({
    user_id: userId,
    family_id: familyId,
    name: userEmail.split('@')[0],
    is_admin: true,
    color: 'bg-emerald-500'
  });

  if (memError) throw memError;

  return familyId;
};

export const joinFamily = async (userId: string, familyId: string, name: string, isAdmin: boolean = false) => {
  return await supabase.from('members').insert({
    user_id: userId,
    family_id: familyId,
    name,
    is_admin: isAdmin,
    color: 'bg-emerald-500'
  });
};

/* --- DATA FETCHING --- */
export const fetchExpenses = async (familyId: string) => {
  const { data } = await supabase.from('expenses').select('*').eq('family_id', familyId).order('date', { ascending: false });
  return (data || []).map((e: any) => ({
    id: e.id, product: e.product, quantity: e.quantity, unitPrice: e.unit_price, total: e.total,
    store: e.store, date: e.date, category: e.category, memberId: e.member_id
  }));
};

export const addExpenseToSupabase = async (familyId: string, expense: Expense) => {
  return await supabase.from('expenses').insert({
    id: expense.id, family_id: familyId, product: expense.product, quantity: expense.quantity,
    unit_price: expense.unitPrice, total: expense.total, store: expense.store, date: expense.date,
    category: expense.category, member_id: expense.memberId
  });
};

export const deleteExpenseFromSupabase = async (id: string) => {
  return await supabase.from('expenses').delete().eq('id', id);
};

export const fetchIncomes = async (familyId: string) => {
  const { data } = await supabase.from('incomes').select('*').eq('family_id', familyId);
  return (data || []).map((i: any) => ({ id: i.id, source: i.source, amount: i.amount, date: i.date }));
};

export const addIncomeToSupabase = async (familyId: string, income: Income) => {
  return await supabase.from('incomes').insert({
    id: income.id, family_id: familyId, source: income.source, amount: income.amount, date: income.date
  });
};

export const deleteIncomeFromSupabase = async (id: string) => {
  return await supabase.from('incomes').delete().eq('id', id);
};

export const fetchStores = async (familyId: string) => {
  const { data } = await supabase.from('stores').select('*').eq('family_id', familyId);
  return data || [];
};

export const addStoreToSupabase = async (familyId: string, store: Store) => {
  return await supabase.from('stores').insert({ id: store.id, family_id: familyId, name: store.name });
};

export const fetchRecurring = async (familyId: string): Promise<RecurringExpense[]> => {
  const { data } = await supabase.from('recurring_expenses').select('*').eq('family_id', familyId);
  return (data || []).map((r: any) => ({ 
    id: r.id, product: r.product, amount: Number(r.amount), store: r.store, frequency: r.frequency, 
    nextDueDate: r.next_due_date, reminderDays: r.reminder_days, customFields: r.custom_fields || [] 
  }));
};

export const addRecurringToSupabase = async (familyId: string, item: RecurringExpense) => {
  return await supabase.from('recurring_expenses').insert({ 
    id: item.id, family_id: familyId, product: item.product, amount: item.amount, store: item.store, 
    frequency: item.frequency, next_due_date: item.nextDueDate, reminder_days: item.reminderDays, custom_fields: item.customFields 
  });
};

export const updateRecurringInSupabase = async (item: RecurringExpense) => {
  return await supabase.from('recurring_expenses').update({ 
    product: item.product, amount: item.amount, store: item.store, frequency: item.frequency, 
    next_due_date: item.nextDueDate, reminder_days: item.reminderDays, custom_fields: item.customFields 
  }).eq('id', item.id);
};

export const deleteRecurringFromSupabase = async (id: string) => {
  return await supabase.from('recurring_expenses').delete().eq('id', id);
};

export const fetchShoppingList = async (familyId: string) => {
  const { data } = await supabase.from('shopping_list').select('*').eq('family_id', familyId);
  return (data || []).map((s: any) => ({ id: s.id, product: s.product, store: s.store, completed: s.completed }));
};

export const addShoppingItemToSupabase = async (familyId: string, item: ShoppingItem) => {
  return await supabase.from('shopping_list').insert({
    id: item.id, family_id: familyId, product: item.product, store: item.store, completed: item.completed
  });
};

export const updateShoppingItemInSupabase = async (item: ShoppingItem) => {
  return await supabase.from('shopping_list').update({ completed: item.completed }).eq('id', item.id);
};

export const deleteShoppingItemFromSupabase = async (id: string) => {
  return await supabase.from('shopping_list').delete().eq('id', id);
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, 
  Income, CategoryDefinition, ShoppingItem, RecurringExpense, CustomField 
} from './types';
import * as SupabaseService from './services/supabaseService';
import { LoginScreen } from './components/LoginScreen';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { StoreManager } from './components/StoreManager';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { ShoppingListManager } from './components/ShoppingListManager';
import { IncomeManager } from './components/IncomeManager';
import { FamilyManager } from './components/FamilyManager';
import { OffersFinder } from './components/OffersFinder';
import { ReceiptScanner } from './components/ReceiptScanner';
import { 
  LayoutDashboard, ShoppingCart, Receipt, Repeat, BarChart3, 
  Wallet, Percent, Users, LogOut, Menu, X, Loader2 
} from 'lucide-react';

type View = 'dashboard' | 'shopping' | 'spese' | 'ricorrenti' | 'analisi' | 'bilancio' | 'offerte' | 'famiglia';

function App() {
  const [user, setUser] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [shoppingList, setShoppingList] = useState<ShoppingItem[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);

  const [isReady, setIsReady] = useState(false);

  // 1. Inizializzazione Sessione e Caricamento Automatico Famiglia
  useEffect(() => {
    const initApp = async () => {
      try {
        const currentUser = await SupabaseService.getCurrentUser();
        if (currentUser) {
          setUser(currentUser);
          // Cerchiamo se l'utente è già membro di una famiglia
          const { data: memberData } = await SupabaseService.getFamilyForUser(currentUser.id);

          if (memberData?.family_id) {
            console.log("Membro trovato per la famiglia:", memberData.family_id);
            await loadFamilyData(memberData.family_id);
          } else {
            console.log("Nessun membro trovato. L'utente deve creare o unirsi a una famiglia.");
          }
        }
      } catch (err) {
        console.error("Errore inizializzazione account:", err);
      } finally {
        setIsReady(true);
      }
    };
    initApp();
  }, []);

  const loadFamilyData = async (familyId: string) => {
    try {
      const [profileRes, exps, recs, shops, strs, incs] = await Promise.all([
        SupabaseService.getFamilyProfile(familyId),
        SupabaseService.fetchExpenses(familyId),
        SupabaseService.fetchRecurring(familyId),
        SupabaseService.fetchShoppingList(familyId),
        SupabaseService.fetchStores(familyId),
        SupabaseService.fetchIncomes(familyId)
      ]);

      if (profileRes.data) {
        const members = await SupabaseService.fetchFamilyMembers(familyId);
        setFamilyProfile({
          id: profileRes.data.id,
          familyName: profileRes.data.family_name,
          members: members,
          createdAt: new Date(profileRes.data.created_at).getTime()
        });
        setExpenses(exps);
        setRecurringExpenses(recs);
        setShoppingList(shops);
        setIncomes(incs);
        if (strs && strs.length > 0) setStores(strs);
      }
    } catch (err) {
      console.error("Errore caricamento dati famiglia:", err);
    }
  };

  const handleSetupComplete = async (profile: FamilyProfile) => {
    // Questo viene chiamato solo quando un utente crea o si unisce manualmente
    await loadFamilyData(profile.id);
  };

  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const NavItem = ({ view, icon: Icon, label, badge }: { view: View, icon: any, label: string, badge?: number }) => (
    <button
      onClick={() => { setActiveView(view); setIsSidebarOpen(false); }}
      className={`w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all ${
        activeView === view ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-200' : 'text-gray-500 hover:bg-emerald-50 hover:text-emerald-600'
      }`}
    >
      <div className="flex items-center gap-3">
        <Icon className="w-5 h-5" />
        <span className="font-bold text-sm">{label}</span>
      </div>
      {badge !== undefined && badge > 0 && (
        <span className={`text-[10px] px-2 py-0.5 rounded-full font-black ${activeView === view ? 'bg-white text-emerald-600' : 'bg-emerald-600 text-white'}`}>
          {badge}
        </span>
      )}
    </button>
  );

  if (!isReady) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center">
          <Loader2 className="w-12 h-12 text-emerald-600 animate-spin mx-auto mb-4" />
          <p className="text-gray-500 font-bold tracking-tight">Sincronizzazione Account...</p>
        </div>
      </div>
    );
  }

  if (!user || !familyProfile) {
    return <LoginScreen 
      onSetupComplete={handleSetupComplete} 
      onUserLogin={(u) => { 
        setUser(u);
        // Invece di reload, lo stato isReady gestirà il controllo famiglia al prossimo render/effect
      }} 
      isSupabaseAuth={!!user} 
    />;
  }

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return (
          <div className="space-y-6 animate-in fade-in duration-300">
            <ReceiptScanner onScanComplete={async (data) => {
              for (const item of data.items) {
                const newExp: Expense = {
                  id: crypto.randomUUID(),
                  product: item.product, quantity: item.quantity, unitPrice: item.unitPrice, total: item.total,
                  store: data.store || 'Negozio', date: new Date().toISOString(), category: item.category || 'Altro'
                };
                setExpenses(prev => [newExp, ...prev]);
                await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
              }
            }} />
            <DueExpensesAlert 
              dueExpenses={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date())} 
              onProcessExpense={() => setActiveView('ricorrenti')} 
            />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                  <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2">
                    <ShoppingCart className="w-5 h-5 text-orange-500" /> Da comprare oggi
                  </h3>
                  {shoppingList.filter(i => !i.completed).length > 0 ? (
                    <div className="space-y-2">
                      {shoppingList.filter(i => !i.completed).slice(0, 3).map(item => (
                        <div key={item.id} className="flex items-center gap-3 text-sm text-gray-600 bg-gray-50 p-3 rounded-xl border border-gray-100">
                           <div className="w-2 h-2 rounded-full bg-orange-400" />
                           {item.product} <span className="text-[10px] text-gray-400 uppercase font-bold ml-auto">{item.store}</span>
                        </div>
                      ))}
                      <button onClick={() => setActiveView('shopping')} className="w-full py-2 text-xs font-bold text-emerald-600 hover:underline">Vedi tutta la lista</button>
                    </div>
                  ) : (
                    <p className="text-xs text-gray-400 italic">Lista spesa vuota.</p>
                  )}
               </div>
               <AIInsight expenses={expenses} />
            </div>
          </div>
        );
      case 'shopping':
        return (
          <ShoppingListManager 
            items={shoppingList} stores={stores} productHistory={productHistory}
            onAddItem={async (p, s) => {
              const newItem = { id: crypto.randomUUID(), product: p, store: s, completed: false };
              setShoppingList(prev => [...prev, newItem]);
              await SupabaseService.addShoppingItemToSupabase(familyProfile.id, newItem);
            }}
            onToggleItem={async (id) => {
              const item = shoppingList.find(i => i.id === id);
              if (item) {
                const updated = { ...item, completed: !item.completed };
                setShoppingList(prev => prev.map(i => i.id === id ? updated : i));
                await SupabaseService.updateShoppingItemInSupabase(updated);
              }
            }}
            onDeleteItem={async (id) => {
              setShoppingList(prev => prev.filter(i => i.id !== id));
              await SupabaseService.deleteShoppingItemFromSupabase(id);
            }}
          />
        );
      case 'spese':
        return (
          <div className="space-y-6">
            <ExpenseForm 
              stores={stores} members={familyProfile.members} 
              existingProducts={Object.keys(productHistory)} productHistory={productHistory} 
              onAddExpense={async (p, q, u, t, s) => {
                const newExp: Expense = {
                  id: crypto.randomUUID(), product: p, quantity: q, unitPrice: u, total: t, store: s,
                  date: new Date().toISOString(), category: 'Altro'
                };
                setExpenses(prev => [newExp, ...prev]);
                await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
              }} 
              isAnalyzing={false}
            />
            <ExpenseList 
              expenses={expenses} stores={stores} 
              onDelete={async (id) => {
                setExpenses(prev => prev.filter(e => e.id !== id));
                await SupabaseService.deleteExpenseFromSupabase(id);
              }} 
              onEdit={async (updated) => {
                setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e));
              }} 
            />
          </div>
        );
      case 'bilancio':
        return (
          <IncomeManager 
            incomes={incomes} expenses={expenses} 
            onAddIncome={async (s, a, d) => {
              const newInc = { id: crypto.randomUUID(), source: s, amount: a, date: d };
              setIncomes(prev => [...prev, newInc]);
              await SupabaseService.addIncomeToSupabase(familyProfile.id, newInc);
            }}
            onDeleteIncome={async (id) => {
              setIncomes(prev => prev.filter(i => i.id !== id));
              await SupabaseService.deleteIncomeFromSupabase(id);
            }}
          />
        );
      case 'ricorrenti':
        return (
          <RecurringManager 
            recurringExpenses={recurringExpenses} stores={stores}
            onAddRecurring={async (p, a, s, f, d, r, c) => {
              const newItem = { id: crypto.randomUUID(), product: p, amount: a, store: s, frequency: f, nextDueDate: d, reminderDays: r, customFields: c };
              setRecurringExpenses(prev => [...prev, newItem]);
              await SupabaseService.addRecurringToSupabase(familyProfile.id, newItem);
            }}
            onUpdateRecurring={async (updated) => {
              setRecurringExpenses(prev => prev.map(r => r.id === updated.id ? updated : r));
              await SupabaseService.updateRecurringInSupabase(updated);
            }}
            onDeleteRecurring={async (id) => {
              setRecurringExpenses(prev => prev.filter(r => r.id !== id));
              await SupabaseService.deleteRecurringFromSupabase(id);
            }}
          />
        );
      case 'analisi':
        return <Analytics expenses={expenses} />;
      case 'offerte':
        return <OffersFinder stores={stores} savedCity="" savedStores={[]} notificationsEnabled={false} onPreferencesChange={() => {}} />;
      case 'famiglia':
        return (
          <div className="space-y-6">
            <FamilyManager familyProfile={familyProfile} />
            <StoreManager onAddStore={async (name) => {
              const newStore = { id: crypto.randomUUID(), name };
              setStores(prev => [...prev, newStore]);
              await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
            }} />
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">
      <header className="md:hidden bg-emerald-600 text-white p-4 flex justify-between items-center sticky top-0 z-40 shadow-md">
        <div className="flex items-center gap-2">
           <div className="bg-white/20 p-2 rounded-lg"><LayoutDashboard className="w-5 h-5" /></div>
           <h1 className="font-black tracking-tight">{familyProfile.familyName}</h1>
        </div>
        <button onClick={() => setIsSidebarOpen(true)} className="p-2 bg-emerald-700 rounded-xl"><Menu className="w-6 h-6" /></button>
      </header>

      <aside className={`fixed inset-0 z-50 md:relative md:flex md:w-72 bg-white border-r border-gray-100 flex-col shadow-2xl md:shadow-none transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}`}>
        <div className="p-6 flex justify-between items-center border-b border-gray-50">
          <div className="flex items-center gap-3">
             <div className="bg-emerald-600 p-2.5 rounded-2xl shadow-lg shadow-emerald-100 text-white"><LayoutDashboard className="w-6 h-6" /></div>
             <div>
               <h1 className="font-black text-gray-800 tracking-tighter">{familyProfile.familyName}</h1>
               <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{user?.email?.split('@')[0] || 'Utente'}</p>
             </div>
          </div>
          <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2 text-gray-400"><X className="w-6 h-6" /></button>
        </div>
        <nav className="flex-1 p-4 space-y-1.5 overflow-y-auto">
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavItem view="bilancio" icon={Wallet} label="Bilancio" />
          <NavItem view="spese" icon={Receipt} label="Storico & Spese" />
          <NavItem view="shopping" icon={ShoppingCart} label="Lista Spesa" badge={shoppingList.filter(i => !i.completed).length} />
          <NavItem view="ricorrenti" icon={Repeat} label="Scadenze" badge={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date()).length} />
          <NavItem view="analisi" icon={BarChart3} label="Analisi & Report" />
          <NavItem view="offerte" icon={Percent} label="Caccia Offerte" />
          <NavItem view="famiglia" icon={Users} label="Famiglia & Negozi" />
        </nav>
        <div className="p-4 border-t border-gray-50 space-y-2">
          <button onClick={async () => { await SupabaseService.signOut(); window.location.reload(); }} className="w-full flex items-center gap-3 px-4 py-3 text-red-500 font-bold text-sm hover:bg-red-50 rounded-xl transition-colors">
            <LogOut className="w-5 h-5" /> Esci dall'App
          </button>
        </div>
      </aside>

      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8">
        {renderView()}
