         <button onClick={() => setActiveView('spese')} className={`p-3 rounded-2xl transition-all ${activeView === 'spese' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}><Receipt className="w-6 h-6" /></button>
         <button onClick={() => setActiveView('shopping')} className={`relative p-3 rounded-2xl transition-all ${activeView === 'shopping' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}><ShoppingCart className="w-6 h-6" />{shoppingList.filter(i => !i.completed).length > 0 && <span className="absolute top-2 right-2 w-4 h-4 bg-orange-500 text-white text-[9px] font-black rounded-full flex items-center justify-center border-2 border-white">{shoppingList.filter(i => !i.completed).length}</span>}</button>
         <button onClick={() => setActiveView('bilancio')} className={`p-3 rounded-2xl transition-all ${activeView === 'bilancio' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}><Wallet className="w-6 h-6" /></button>
         <button onClick={() => setActiveView('ricorrenti')} className={`p-3 rounded-2xl transition-all ${activeView === 'ricorrenti' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}><Repeat className="w-6 h-6" /></button>
      </div>
      {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="fixed inset-0 bg-black/40 backdrop-blur-sm z-40 md:hidden animate-in fade-in duration-300" />}
    </div>
  );
}

export default App;

import React, { useMemo } from 'react';
import { Expense } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { Calendar, TrendingUp } from 'lucide-react';

interface AnalyticsProps {
  expenses: Expense[];
}

const COLORS = ['#059669', '#10B981', '#34D399', '#6EE7B7', '#A7F3D0', '#D1FAE5'];
const ITALIAN_MONTHS = ['Gennaio', 'Febbraio', 'Marzo', 'Aprile', 'Maggio', 'Giugno', 'Luglio', 'Agosto', 'Settembre', 'Ottobre', 'Novembre', 'Dicembre'];

export const Analytics: React.FC<AnalyticsProps> = ({ expenses }) => {

  const storeData = useMemo(() => {
    const totals: Record<string, number> = {};
    expenses.forEach(e => {
      totals[e.store] = (totals[e.store] || 0) + e.total;
    });
    return Object.keys(totals).map(store => ({
      name: store,
      value: parseFloat(totals[store].toFixed(2))
    })).sort((a, b) => b.value - a.value);
  }, [expenses]);

  const categoryData = useMemo(() => {
    const totals: Record<string, number> = {};
    expenses.forEach(e => {
      totals[e.category] = (totals[e.category] || 0) + e.total;
    });
    return Object.keys(totals).map(cat => ({
      name: cat,
      importo: parseFloat(totals[cat].toFixed(2))
    })).sort((a, b) => b.importo - a.importo).slice(0, 5);
  }, [expenses]);

  const totalSpent = useMemo(() => expenses.reduce((acc, curr) => acc + curr.total, 0), [expenses]);

  const monthlyData = useMemo(() => {
    const totals: Record<string, number> = {};
    expenses.forEach(e => {
      const date = new Date(e.date);
      const key = `${date.getFullYear()}-${date.getMonth()}`; // Key is "YYYY-MM"
      totals[key] = (totals[key] || 0) + e.total;
    });

    return Object.entries(totals)
      .map(([key, total]) => {
        const [year, monthIndex] = key.split('-').map(Number);
        return {
          year,
          monthIndex,
          name: `${ITALIAN_MONTHS[monthIndex]} ${year}`,
          total,
        };
      })
      .sort((a, b) => {
        if (a.year !== b.year) {
          return b.year - a.year; // Sort by year descending
        }
        return b.monthIndex - a.monthIndex; // Then by month descending
      });
  }, [expenses]);

  if (expenses.length === 0) {
    return (
      <div className="text-center py-16 bg-white rounded-2xl border border-gray-100 shadow-sm">
          <h3 className="text-xl font-bold text-gray-900">Nessun dato da analizzare</h3>
          <p className="text-gray-500 mt-2 text-base">Aggiungi delle spese per vedere i report.</p>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8">
      {/* Total Summary Card */}
       <div className="bg-emerald-600 rounded-2xl shadow-lg p-6 text-white flex flex-col justify-between min-h-[12rem]">
         <div>
            <span className="text-emerald-100 text-sm uppercase tracking-wider font-semibold flex items-center gap-2">
                <TrendingUp className="w-4 h-4" />
                Totale Speso Complessivo
            </span>
         </div>
         <div>
            <h2 className="text-4xl md:text-5xl font-bold">€{totalSpent.toFixed(2)}</h2>
            <p className="text-emerald-100 text-xs mt-1">{expenses.length} transazioni registrate</p>
         </div>
      </div>

      {/* Monthly Summary Card */}
      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 flex flex-col min-h-[12rem]">
          <h3 className="text-sm font-bold text-gray-700 uppercase tracking-wide flex items-center gap-2 mb-3 flex-shrink-0">
              <Calendar className="w-4 h-4 text-emerald-600" />
              Riepilogo Mensile
          </h3>
          <div className="flex-1 overflow-y-auto pr-2 -mr-2 space-y-2">
            {monthlyData.map(month => (
              <div key={month.name} className="flex justify-between items-center text-sm bg-gray-50/80 p-3 rounded-lg border border-gray-100">
                <span className="font-semibold text-gray-600">{month.name}</span>
                <span className="font-bold text-gray-800">€{month.total.toFixed(2)}</span>
              </div>
            ))}
          </div>
      </div>

      {/* Category Chart */}
      <div className="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-gray-100 h-72 md:h-80 lg:col-span-1">
        <h3 className="text-sm font-bold text-gray-700 mb-4 uppercase tracking-wide">Top Categorie</h3>
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={categoryData} layout="vertical" margin={{ top: -10, right: 10, left: 0, bottom: -10 }}>
            <XAxis type="number" hide />
            <YAxis type="category" dataKey="name" width={90} tick={{fontSize: 11}} interval={0} axisLine={false} tickLine={false} />
            <Tooltip 
              contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }}
              cursor={{fill: '#f3f4f6'}}
            />
            <Bar dataKey="importo" fill="#10B981" radius={[0, 4, 4, 0]} barSize={16} />
          </BarChart>
        </ResponsiveContainer>
      </div>

      {/* Store Chart */}
      <div className="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-gray-100 h-72 md:h-80 lg:col-span-1">
        <h3 className="text-sm font-bold text-gray-700 mb-4 uppercase tracking-wide">Spesa per Negozio</h3>
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={storeData}
              cx="50%"
              cy="50%"
              innerRadius={50}
              outerRadius={70}
              fill="#8884d8"
              paddingAngle={5}
              dataKey="value"
              labelLine={false}
              label={({ cx, cy, midAngle, innerRadius, outerRadius, percent }) => {
                if (percent < 0.05) return null; // Hide small labels
                const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
                const x = cx + (radius + 15) * Math.cos(-midAngle * (Math.PI / 180));
                const y = cy + (radius + 15) * Math.sin(-midAngle * (Math.PI / 180));
                return (
                  <text x={x} y={y} fill="#374151" textAnchor={x > cx ? 'start' : 'end'} dominantBaseline="central" fontSize={11}>
                    {`${(percent * 100).toFixed(0)}%`}
                  </text>
                );
              }}
            >
              {storeData.map((_, index) => (
                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
              ))}
            </Pie>
            <Tooltip contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }} />
            <Legend verticalAlign="bottom" height={36} iconType="circle" wrapperStyle={{fontSize: '11px', paddingTop: '20px' }} />
          </PieChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { RecurringExpense, Frequency, Store, CustomField } from '../types';
import { Repeat, Plus, Trash2, CalendarClock, Bell, Pencil, Save, X as CloseIcon, Info, LayoutList } from 'lucide-react';

interface RecurringManagerProps {
  recurringExpenses: RecurringExpense[];
  stores: Store[];
  onAddRecurring: (product: string, amount: number, store: string, frequency: Frequency, nextDate: string, reminderDays: number, customFields: CustomField[]) => void;
  onUpdateRecurring: (updated: RecurringExpense) => void;
  onDeleteRecurring: (id: string) => void;
}

const FrequencyBadge = ({ freq }: { freq: Frequency }) => {
  const colors: Record<string, string> = {
    settimanale: 'bg-blue-100 text-blue-700 border-blue-200',
    mensile: 'bg-purple-100 text-purple-700 border-purple-200',
    annuale: 'bg-indigo-100 text-indigo-700 border-indigo-200'
  };
  return (
    <span className={`text-[9px] px-2 py-0.5 rounded-full border font-black uppercase tracking-tighter ${colors[freq] || 'bg-gray-100 text-gray-600'}`}>
      {freq}
    </span>
  );
};

export const RecurringManager: React.FC<RecurringManagerProps> = ({ 
  recurringExpenses, 
  stores, 
  onAddRecurring, 
  onUpdateRecurring,
  onDeleteRecurring 
}) => {
  const [isOpen, setIsOpen] = useState(false);

  // State per form principale
  const [editingId, setEditingId] = useState<string | null>(null);
  const [product, setProduct] = useState('');
  const [amount, setAmount] = useState('');
  const [store, setStore] = useState(stores[0]?.name || '');
  const [frequency, setFrequency] = useState<Frequency>('mensile');
  const [nextDate, setNextDate] = useState(new Date().toISOString().split('T')[0]);
  const [reminderDays, setReminderDays] = useState('0');

  // State per campi personalizzati
  const [customFields, setCustomFields] = useState<CustomField[]>([]);
  const [newFieldLabel, setNewFieldLabel] = useState('');
  const [newFieldValue, setNewFieldValue] = useState('');

  useEffect(() => {
    if (!store && stores.length > 0) setStore(stores[0].name);
  }, [stores]);

  const handleEdit = (item: RecurringExpense) => {
    setEditingId(item.id);
    setProduct(item.product);
    setAmount(item.amount.toString());
    setStore(item.store);
    setFrequency(item.frequency);
    setNextDate(item.nextDueDate);
    setReminderDays(item.reminderDays.toString());
    setCustomFields(item.customFields || []);
    if (!isOpen) setIsOpen(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const resetForm = () => {
    setEditingId(null);
    setProduct('');
    setAmount('');
    setFrequency('mensile');
    setNextDate(new Date().toISOString().split('T')[0]);
    setReminderDays('0');
    setCustomFields([]);
    setNewFieldLabel('');
    setNewFieldValue('');
  };

  const handleAddCustomField = () => {
    if (newFieldLabel.trim() && newFieldValue.trim()) {
      setCustomFields([...customFields, { label: newFieldLabel.trim(), value: newFieldValue.trim() }]);
      setNewFieldLabel('');
      setNewFieldValue('');
    }
  };

  const removeCustomField = (index: number) => {
    setCustomFields(customFields.filter((_, i) => i !== index));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!product || !amount || !store || !nextDate) return;

    if (editingId) {
        onUpdateRecurring({
            id: editingId,
            product,
            amount: parseFloat(amount),
            store,
            frequency,
            nextDueDate: nextDate,
            reminderDays: parseInt(reminderDays) || 0,
            customFields
        });
    } else {
        onAddRecurring(product, parseFloat(amount), store, frequency, nextDate, parseInt(reminderDays) || 0, customFields);
    }

    resetForm();
    if (!editingId) setIsOpen(false);
  };

  return (
    <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 mb-6">
      <div 
        className="flex justify-between items-center cursor-pointer select-none mb-1"
        onClick={() => setIsOpen(!isOpen)}
      >
        <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
          <Repeat className="w-5 h-5 text-purple-600" />
          Spese Ricorrenti
        </h3>
        <button className="text-purple-600 hover:text-purple-700 text-sm font-semibold">
          {isOpen ? 'Chiudi' : 'Gestisci'}
        </button>
      </div>

      {isOpen && (
        <div className="mt-5 animate-in fade-in slide-in-from-top-2 duration-200">

          <div className={`p-5 rounded-2xl border mb-6 transition-all ${editingId ? 'bg-indigo-50 border-indigo-200 shadow-inner' : 'bg-purple-50 border-purple-100'}`}>
            <h4 className={`text-[10px] font-bold uppercase mb-4 flex items-center gap-2 ${editingId ? 'text-indigo-800' : 'text-purple-800'}`}>
                {editingId ? <Pencil className="w-3.5 h-3.5" /> : <Plus className="w-3.5 h-3.5" />}
                {editingId ? 'Modifica Voce Ricorrente' : 'Nuova Scadenza'}
            </h4>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5 ml-1">Servizio / Nome</label>
                <input
                  type="text"
                  placeholder="Es. Affitto, Netflix, Fibra"
                  value={product}
                  onChange={(e) => setProduct(e.target.value)}
                  className="w-full rounded-xl border border-gray-300 bg-white p-3.5 text-base focus:border-purple-500 outline-none shadow-sm"
                  required
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                   <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5 ml-1">Importo (€)</label>
                   <input
                    type="number"
                    step="0.01"
                    placeholder="0.00"
                    value={amount}
                    onChange={(e) => setAmount(e.target.value)}
                    className="w-full rounded-xl border border-gray-300 bg-white p-3.5 text-base focus:border-purple-500 outline-none shadow-sm"
                    required
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5 ml-1">Frequenza</label>
                  <select
                    value={frequency}
                    onChange={(e) => setFrequency(e.target.value as Frequency)}
                    className="w-full rounded-xl border border-gray-300 bg-white p-3.5 text-base focus:border-purple-500 outline-none shadow-sm appearance-none"
                  >
                    <option value="settimanale">Settimanale</option>
                    <option value="mensile">Mensile</option>
                    <option value="annuale">Annuale</option>
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5 ml-1">Negozio</label>
                  <select
                    value={store}
                    onChange={(e) => setStore(e.target.value)}
                    className="w-full rounded-xl border border-gray-300 bg-white p-3.5 text-base focus:border-purple-500 outline-none shadow-sm appearance-none"
                  >
                    {stores.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                  </select>
                </div>
                <div>
                   <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5 ml-1">Data Scadenza</label>
                   <input 
                    type="date"
                    value={nextDate}
                    onChange={(e) => setNextDate(e.target.value)}
                    className="w-full rounded-xl border border-gray-300 bg-white p-3.5 text-base focus:border-purple-500 outline-none shadow-sm"
                    required
                  />
                </div>
              </div>

              {/* Sezione Campi Personalizzati */}
              <div className="bg-white/50 p-4 rounded-xl border border-purple-100/50 mt-4">
                <label className="block text-[10px] font-bold text-purple-400 uppercase mb-3 flex items-center gap-1">
                  <LayoutList className="w-3 h-3" /> Campi Personalizzati (Es. Codice, Note, Targa)
                </label>

                <div className="space-y-2 mb-3">
                  {customFields.map((field, index) => (
                    <div key={index} className="flex items-center justify-between bg-white px-3 py-2 rounded-lg border border-purple-50 shadow-sm animate-in zoom-in-95">
                      <div className="text-sm">
                        <span className="font-bold text-purple-700">{field.label}:</span> <span className="text-gray-600">{field.value}</span>
                      </div>
                      <button type="button" onClick={() => removeCustomField(index)} className="text-red-300 hover:text-red-500">
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                </div>

                <div className="flex gap-2">
                  <input
                    type="text"
                    placeholder="Etichetta (es. Note)"
                    value={newFieldLabel}
                    onChange={(e) => setNewFieldLabel(e.target.value)}
                    className="flex-1 rounded-lg border border-gray-200 p-2 text-xs focus:border-purple-300 outline-none"
                  />
                  <input
                    type="text"
                    placeholder="Valore"
                    value={newFieldValue}
                    onChange={(e) => setNewFieldValue(e.target.value)}
                    className="flex-1 rounded-lg border border-gray-200 p-2 text-xs focus:border-purple-300 outline-none"
                  />
                  <button
                    type="button"
                    onClick={handleAddCustomField}
                    className="bg-purple-100 text-purple-600 p-2 rounded-lg hover:bg-purple-200 transition-colors"
                  >
                    <Plus className="w-4 h-4" />
                  </button>
                </div>
              </div>

              <div className="flex items-end gap-3 pt-2">
                <div className="flex-1">
                    <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5 ml-1">Avviso (gg prima)</label>
                    <input 
                        type="number"
                        min="0"
                        max="30"
                        value={reminderDays}
                        onChange={(e) => setReminderDays(e.target.value)}
                        className="w-full rounded-xl border border-gray-300 bg-white p-3.5 text-base focus:border-purple-500 outline-none shadow-sm text-center font-bold"
                    />
                </div>
                <div className="flex gap-2">
                    {editingId && (
                        <button
                            type="button"
                            onClick={resetForm}
                            className="bg-white text-gray-500 border border-gray-300 p-3.5 rounded-xl hover:bg-gray-100 transition-colors shadow-sm"
                            title="Annulla"
                        >
                            <CloseIcon className="w-6 h-6" />
                        </button>
                    )}
                    <button
                        type="submit"
                        className={`px-8 py-3.5 rounded-xl text-white font-bold transition-all shadow-lg active:scale-95 flex items-center justify-center gap-2 ${editingId ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-purple-600 hover:bg-purple-700'}`}
                    >
                        {editingId ? <><Save className="w-5 h-5" /> Aggiorna</> : <><Plus className="w-5 h-5" /> Salva</>}
                    </button>
                </div>
              </div>
            </form>
          </div>

          <div className="space-y-3">
            <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1 mb-2">Abbonamenti & Pagamenti Registrati</h4>
            {recurringExpenses.length > 0 ? (
                recurringExpenses.map((item) => {
                    const isDue = new Date(item.nextDueDate) < new Date();
                    return (
                        <div key={item.id} className={`group relative flex flex-col p-4 bg-white rounded-2xl border shadow-sm hover:shadow-md transition-all ${isDue ? 'border-red-200 bg-red-50/20' : 'border-gray-100'}`}>
                            <div className="flex justify-between items-start">
                                <div className="flex-1">
                                    <div className="font-bold text-gray-800 text-lg flex items-center gap-2 flex-wrap">
                                        {item.product}
                                        <FrequencyBadge freq={item.frequency} />
                                        {isDue && <span className="bg-red-500 text-[10px] text-white px-2 py-0.5 rounded-full animate-pulse font-bold">SCADUTO</span>}
                                    </div>
                                    <div className="text-xs text-gray-500 flex flex-wrap items-center gap-4 mt-2 font-medium">
                                        <span className="font-bold text-purple-700 bg-purple-50 px-2 py-0.5 rounded-lg border border-purple-100">
                                            €{item.amount.toFixed(2)}
                                        </span>
                                        <span className={`flex items-center gap-1.5 ${isDue ? 'text-red-600 font-bold' : ''}`}>
                                            <CalendarClock className="w-4 h-4" />
                                            {new Date(item.nextDueDate).toLocaleDateString('it-IT')}
                                        </span>
                                        {item.reminderDays > 0 && (
                                            <span className="flex items-center gap-1.5 text-orange-600 font-bold">
                                                <Bell className="w-4 h-4" />
                                                -{item.reminderDays}gg
                                            </span>
                                        )}
                                    </div>
                                </div>
                                <div className="flex gap-1 ml-4">
                                    <button 
                                        onClick={() => handleEdit(item)}
                                        className="p-3 text-gray-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all"
                                        title="Modifica"
                                    >
                                        <Pencil className="w-5 h-5" />
                                    </button>
                                    <button 
                                        onClick={() => onDeleteRecurring(item.id)}
                                        className="p-3 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all"
                                        title="Elimina"
                                    >
                                        <Trash2 className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>

                            {/* Visualizzazione Campi Personalizzati nella Card */}
                            {item.customFields && item.customFields.length > 0 && (
                              <div className="mt-3 flex flex-wrap gap-2 pt-3 border-t border-gray-50">
                                {item.customFields.map((field, fIdx) => (
                                  <div key={fIdx} className="bg-gray-50 text-[10px] px-2 py-1 rounded-md border border-gray-100 flex items-center gap-1 shadow-sm">
                                    <Info className="w-3 h-3 text-purple-400" />
                                    <span className="font-bold text-gray-500">{field.label}:</span>
                                    <span className="text-gray-700">{field.value}</span>
                                  </div>
                                ))}
                              </div>
                            )}
                        </div>
                    );
                })
            ) : (
                <div className="text-center py-12 text-gray-400 italic text-sm border-2 border-dashed border-gray-100 rounded-2xl">
                    Nessuna scadenza ricorrente configurata.
                </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  DEFAULT_STORES, DEFAULT_CATEGORIES, Expense, Store, FamilyProfile, 
  Income, CategoryDefinition, ShoppingItem, RecurringExpense, CustomField 
} from './types';
import * as SupabaseService from './services/supabaseService';
import { LoginScreen } from './components/LoginScreen';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { Analytics } from './components/Analytics';
import { AIInsight } from './components/AIInsight';
import { StoreManager } from './components/StoreManager';
import { RecurringManager } from './components/RecurringManager';
import { DueExpensesAlert } from './components/DueExpensesAlert';
import { ShoppingListManager } from './components/ShoppingListManager';
import { IncomeManager } from './components/IncomeManager';
import { FamilyManager } from './components/FamilyManager';
import { OffersFinder } from './components/OffersFinder';
import { ReceiptScanner } from './components/ReceiptScanner';
import { 
  LayoutDashboard, ShoppingCart, Receipt, Repeat, BarChart3, 
  Wallet, Percent, Users, LogOut, Menu, X, Loader2 
} from 'lucide-react';

type View = 'dashboard' | 'shopping' | 'spese' | 'ricorrenti' | 'analisi' | 'bilancio' | 'offerte' | 'famiglia';

function App() {
  const [user, setUser] = useState<any>(null);
  const [familyProfile, setFamilyProfile] = useState<FamilyProfile | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [recurringExpenses, setRecurringExpenses] = useState<RecurringExpense[]>([]);
  const [shoppingList, setShoppingList] = useState<ShoppingItem[]>([]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [stores, setStores] = useState<Store[]>(DEFAULT_STORES);

  const [offerPreferences, setOfferPreferences] = useState({
    city: '',
    selectedStores: [] as string[],
    notificationsEnabled: false,
  });

  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    try {
      const savedPrefs = localStorage.getItem('familyAppOfferPreferences');
      if (savedPrefs) {
        setOfferPreferences(JSON.parse(savedPrefs));
      }
    } catch(e) {
      console.error("Failed to load offer preferences", e);
    }
  }, []);

  useEffect(() => {
    const initApp = async () => {
      try {
        const currentUser = await SupabaseService.getCurrentUser();
        if (currentUser) {
          setUser(currentUser);
          const { data: memberData } = await SupabaseService.getFamilyForUser(currentUser.id);
          if (memberData?.family_id) {
            await loadFamilyData(memberData.family_id);
          }
        }
      } catch (err) {
        console.error("Errore inizializzazione:", err);
      } finally {
        setIsReady(true);
      }
    };
    initApp();
  }, []);

  const loadFamilyData = async (familyId: string) => {
    try {
      const [profileRes, exps, recs, shops, strs, incs] = await Promise.all([
        SupabaseService.getFamilyProfile(familyId),
        SupabaseService.fetchExpenses(familyId),
        SupabaseService.fetchRecurring(familyId),
        SupabaseService.fetchShoppingList(familyId),
        SupabaseService.fetchStores(familyId),
        SupabaseService.fetchIncomes(familyId)
      ]);

      if (profileRes.data) {
        const members = await SupabaseService.fetchFamilyMembers(familyId);
        setFamilyProfile({
          id: profileRes.data.id,
          familyName: profileRes.data.family_name,
          members: members,
          createdAt: new Date(profileRes.data.created_at).getTime()
        });
        setExpenses(exps);
        setRecurringExpenses(recs);
        setShoppingList(shops);
        setIncomes(incs);
        if (strs && strs.length > 0) setStores(strs);
      }
    } catch (err) {
      console.error("Errore caricamento dati:", err);
    }
  };

  const handleSetupComplete = async (profile: FamilyProfile) => {
    await loadFamilyData(profile.id);
  };

  const handlePreferencesChange = (city: string, selectedStores: string[], notificationsEnabled: boolean) => {
    const newPrefs = { city, selectedStores, notificationsEnabled };
    setOfferPreferences(newPrefs);
    try {
      localStorage.setItem('familyAppOfferPreferences', JSON.stringify(newPrefs));
    } catch(e) {
      console.error("Failed to save offer preferences", e);
    }
  };

  const productHistory = useMemo(() => {
    const history: Record<string, string> = {};
    [...expenses].reverse().forEach(exp => {
      history[exp.product] = exp.store;
    });
    return history;
  }, [expenses]);

  const NavItem = ({ view, icon: Icon, label, badge }: { view: View, icon: any, label: string, badge?: number }) => (
    <button
      onClick={() => { setActiveView(view); setIsSidebarOpen(false); }}
      className={`w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all ${
        activeView === view ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-200' : 'text-gray-500 hover:bg-emerald-50 hover:text-emerald-600'
      }`}
    >
      <div className="flex items-center gap-3">
        <Icon className="w-5 h-5" />
        <span className="font-bold text-sm">{label}</span>
      </div>
      {badge !== undefined && badge > 0 && (
        <span className={`text-[10px] px-2 py-0.5 rounded-full font-black ${activeView === view ? 'bg-white text-emerald-600' : 'bg-emerald-600 text-white'}`}>
          {badge}
        </span>
      )}
    </button>
  );

  if (!isReady) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center">
          <Loader2 className="w-12 h-12 text-emerald-600 animate-spin mx-auto mb-4" />
          <p className="text-gray-500 font-bold tracking-tight">Accesso in corso...</p>
        </div>
      </div>
    );
  }

  if (!user || !familyProfile) {
    return <LoginScreen 
      onSetupComplete={handleSetupComplete} 
      onUserLogin={(u) => { 
        setUser(u);
        SupabaseService.getFamilyForUser(u.id).then(({data}) => {
          if (data?.family_id) loadFamilyData(data.family_id);
        });
      }} 
      isSupabaseAuth={!!user} 
    />;
  }

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return (
          <div className="space-y-6 animate-in fade-in duration-300">
            <ReceiptScanner onScanComplete={async (data) => {
              for (const item of data.items) {
                const newExp: Expense = {
                  id: crypto.randomUUID(),
                  product: item.product, quantity: item.quantity, unitPrice: item.unitPrice, total: item.total,
                  store: data.store || 'Negozio', date: new Date().toISOString(), category: item.category || 'Altro'
                };
                setExpenses(prev => [newExp, ...prev]);
                try {
                  await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
                } catch (e: any) {
                  console.error(e);
                }
              }
            }} />
            <DueExpensesAlert 
              dueExpenses={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date())} 
              onProcessExpense={() => setActiveView('ricorrenti')} 
            />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                  <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2">
                    <ShoppingCart className="w-5 h-5 text-orange-500" /> Da comprare oggi
                  </h3>
                  {shoppingList.filter(i => !i.completed).length > 0 ? (
                    <div className="space-y-2">
                      {shoppingList.filter(i => !i.completed).slice(0, 3).map(item => (
                        <div key={item.id} className="flex items-center gap-3 text-sm text-gray-600 bg-gray-50 p-3 rounded-xl border border-gray-100">
                           <div className="w-2 h-2 rounded-full bg-orange-400" />
                           {item.product} <span className="text-[10px] text-gray-400 uppercase font-bold ml-auto">{item.store}</span>
                        </div>
                      ))}
                      <button onClick={() => setActiveView('shopping')} className="w-full py-2 text-xs font-bold text-emerald-600 hover:underline">Vedi tutta la lista</button>
                    </div>
                  ) : (
                    <p className="text-xs text-gray-400 italic">Lista spesa vuota.</p>
                  )}
               </div>
               <AIInsight expenses={expenses} />
            </div>
          </div>
        );
      case 'shopping':
        return (
          <ShoppingListManager 
            items={shoppingList} stores={stores} productHistory={productHistory}
            onAddItem={async (p, s) => {
              const newItem = { id: crypto.randomUUID(), product: p, store: s, completed: false };
              setShoppingList(prev => [...prev, newItem]);
              try {
                await SupabaseService.addShoppingItemToSupabase(familyProfile.id, newItem);
              } catch (e) {
                console.error(e);
              }
            }}
            onToggleItem={async (id) => {
              const item = shoppingList.find(i => i.id === id);
              if (item) {
                const updated = { ...item, completed: !item.completed };
                setShoppingList(prev => prev.map(i => i.id === id ? updated : i));
                try {
                  await SupabaseService.updateShoppingItemInSupabase(updated);
                } catch (e) {
                  console.error(e);
                }
              }
            }}
            onDeleteItem={async (id) => {
              setShoppingList(prev => prev.filter(i => i.id !== id));
              try {
                await SupabaseService.deleteShoppingItemFromSupabase(id);
              } catch (e) {
                console.error(e);
              }
            }}
          />
        );
      case 'spese':
        return (
          <div className="space-y-6">
            <ExpenseForm 
              stores={stores} members={familyProfile.members} 
              existingProducts={Object.keys(productHistory)} productHistory={productHistory} 
              onAddExpense={async (p, q, u, t, s) => {
                const newExp: Expense = {
                  id: crypto.randomUUID(), product: p, quantity: q, unitPrice: u, total: t, store: s,
                  date: new Date().toISOString(), category: 'Altro'
                };
                setExpenses(prev => [newExp, ...prev]);
                try {
                  await SupabaseService.addExpenseToSupabase(familyProfile.id, newExp);
                } catch (e: any) {
                  alert("Errore salvataggio spesa: " + e.message);
                }
              }} 
              isAnalyzing={false}
            />
            <ExpenseList 
              expenses={expenses} stores={stores} 
              onDelete={async (id) => {
                setExpenses(prev => prev.filter(e => e.id !== id));
                try {
                  await SupabaseService.deleteExpenseFromSupabase(id);
                } catch (e) {
                  console.error(e);
                }
              }} 
              onEdit={async (updated) => {
                setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e));
              }} 
            />
          </div>
        );
      case 'bilancio':
        return (
          <IncomeManager 
            incomes={incomes} expenses={expenses} 
            onAddIncome={async (s, a, d) => {
              const newInc = { id: crypto.randomUUID(), source: s, amount: a, date: d };
              setIncomes(prev => [...prev, newInc]);
              try {
                await SupabaseService.addIncomeToSupabase(familyProfile.id, newInc);
              } catch (e) {
                console.error(e);
              }
            }}
            onDeleteIncome={async (id) => {
              setIncomes(prev => prev.filter(i => i.id !== id));
              try {
                await SupabaseService.deleteIncomeFromSupabase(id);
              } catch (e) {
                console.error(e);
              }
            }}
          />
        );
      case 'ricorrenti':
        return (
          <RecurringManager 
            recurringExpenses={recurringExpenses} stores={stores}
            onAddRecurring={async (p, a, s, f, d, r, c) => {
              const newItem = { id: crypto.randomUUID(), product: p, amount: a, store: s, frequency: f, nextDueDate: d, reminderDays: r, customFields: c };
              // Ottimismo UI
              setRecurringExpenses(prev => [...prev, newItem]);
              try {
                await SupabaseService.addRecurringToSupabase(familyProfile.id, newItem);
              } catch (error: any) {
                console.error("Errore salvataggio ricorrente:", error);
                // Alert più dettagliato per capire COSA esattamente fallisce
                const technicalDetail = error.message || error.details || "Errore sconosciuto";
                alert(`ERRORE SUPABASE: ${technicalDetail}\n\nAssicurati che la tabella 'recurring_expenses' esista e che le policy RLS permettano l'inserimento.`);
                // Rollback UI
                setRecurringExpenses(prev => prev.filter(item => item.id !== newItem.id));
              }
            }}
            onUpdateRecurring={async (updated) => {
              const originalState = [...recurringExpenses];
              setRecurringExpenses(prev => prev.map(r => r.id === updated.id ? updated : r));
              try {
                await SupabaseService.updateRecurringInSupabase(updated);
              } catch (error: any) {
                console.error(error);
                alert("Errore aggiornamento: " + error.message);
                setRecurringExpenses(originalState);
              }
            }}
            onDeleteRecurring={async (id) => {
              const itemToDelete = recurringExpenses.find(r => r.id === id);
              if (!itemToDelete) return;
              setRecurringExpenses(prev => prev.filter(r => r.id !== id));
              try {
                await SupabaseService.deleteRecurringFromSupabase(id);
              } catch(error: any) {
                console.error(error);
                alert("Errore eliminazione: " + error.message);
                setRecurringExpenses(prev => [...prev, itemToDelete]);
              }
            }}
          />
        );
      case 'analisi':
        return <Analytics expenses={expenses} />;
      case 'offerte':
        return <OffersFinder 
          stores={stores} 
          savedCity={offerPreferences.city} 
          savedStores={offerPreferences.selectedStores} 
          notificationsEnabled={offerPreferences.notificationsEnabled} 
          onPreferencesChange={handlePreferencesChange} 
        />;
      case 'famiglia':
        return (
          <div className="space-y-6">
            <FamilyManager familyProfile={familyProfile} />
            <StoreManager onAddStore={async (name) => {
              const newStore = { id: crypto.randomUUID(), name };
              setStores(prev => [...prev, newStore]);
              try {
                await SupabaseService.addStoreToSupabase(familyProfile.id, newStore);
              } catch (e) {
                console.error(e);
              }
            }} />
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">
      <header className="md:hidden bg-emerald-600 text-white p-4 flex justify-between items-center sticky top-0 z-40 shadow-md">
        <div className="flex items-center gap-2">
           <div className="bg-white/20 p-2 rounded-lg"><LayoutDashboard className="w-5 h-5" /></div>
           <h1 className="font-black tracking-tight">{familyProfile.familyName}</h1>
        </div>
        <button onClick={() => setIsSidebarOpen(true)} className="p-2 bg-emerald-700 rounded-xl"><Menu className="w-6 h-6" /></button>
      </header>

      <aside className={`fixed inset-0 z-50 md:relative md:flex md:w-72 bg-white border-r border-gray-100 flex-col shadow-2xl md:shadow-none transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}`}>
        <div className="p-6 flex justify-between items-center border-b border-gray-50">
          <div className="flex items-center gap-3">
             <div className="bg-emerald-600 p-2.5 rounded-2xl shadow-lg shadow-emerald-100 text-white"><LayoutDashboard className="w-6 h-6" /></div>
             <div>
               <h1 className="font-black text-gray-800 tracking-tighter">{familyProfile.familyName}</h1>
               <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{user?.email?.split('@')[0] || 'Utente'}</p>
             </div>
          </div>
          <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2 text-gray-400"><X className="w-6 h-6" /></button>
        </div>
        <nav className="flex-1 p-4 space-y-1.5 overflow-y-auto">
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavItem view="bilancio" icon={Wallet} label="Bilancio" />
          <NavItem view="spese" icon={Receipt} label="Storico & Spese" />
          <NavItem view="shopping" icon={ShoppingCart} label="Lista Spesa" badge={shoppingList.filter(i => !i.completed).length} />
          <NavItem view="ricorrenti" icon={Repeat} label="Scadenze" badge={recurringExpenses.filter(r => new Date(r.nextDueDate) <= new Date()).length} />
          <NavItem view="analisi" icon={BarChart3} label="Analisi & Report" />
          <NavItem view="offerte" icon={Percent} label="Caccia Offerte" />
          <NavItem view="famiglia" icon={Users} label="Famiglia & Negozi" />
        </nav>
        <div className="p-4 border-t border-gray-50 space-y-2">
          <button onClick={async () => { await SupabaseService.signOut(); window.location.reload(); }} className="w-full flex items-center gap-3 px-4 py-3 text-red-500 font-bold text-sm hover:bg-red-50 rounded-xl transition-colors">
            <LogOut className="w-5 h-5" /> Esci dall'App
          </button>
        </div>
      </aside>

      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8">
        {renderView()}
      </main>

      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 flex justify-around items-center p-3 z-40 pb-6 safe-area-bottom shadow-[0_-5px_15px_rgba(0,0,0,0.05)]">
         <button onClick={() => setActiveView('dashboard')} className={`p-3 rounded-2xl transition-all ${activeView === 'dashboard' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}><LayoutDashboard className="w-6 h-6" /></button>
         <button onClick={() => setActiveView('spese')} className={`p-3 rounded-2xl transition-all ${activeView === 'spese' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}><Receipt className="w-6 h-6" /></button>
         <button onClick={() => setActiveView('shopping')} className={`relative p-3 rounded-2xl transition-all ${activeView === 'shopping' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}><ShoppingCart className="w-6 h-6" />{shoppingList.filter(i => !i.completed).length > 0 && <span className="absolute top-2 right-2 w-4 h-4 bg-orange-500 text-white text-[9px] font-black rounded-full flex items-center justify-center border-2 border-white">{shoppingList.filter(i => !i.completed).length}</span>}</button>
         <button onClick={() => setActiveView('bilancio')} className={`p-3 rounded-2xl transition-all ${activeView === 'bilancio' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}><Wallet className="w-6 h-6" /></button>
         <button onClick={() => setActiveView('ricorrenti')} className={`p-3 rounded-2xl transition-all ${activeView === 'ricorrenti' ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}><Repeat className="w-6 h-6" /></button>
      </div>
      {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="fixed inset-0 bg-black/40 backdrop-blur-sm z-40 md:hidden animate-in fade-in duration-300" />}
    </div>
  );
}

export default App;

import { supabase } from '../supabaseClient';
import { Expense, Income, Store, RecurringExpense, ShoppingItem, FamilyProfile, Member } from '../types';

/* --- AUTHENTICATION --- */
export const signInWithGoogle = async () => {
  return await supabase.auth.signInWithOAuth({ provider: 'google' });
};

export const signUpWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signUp({ email, password });
};

export const signInWithEmail = async (email: string, password: string) => {
  return await supabase.auth.signInWithPassword({ email, password });
};

export const signOut = async () => {
  return await supabase.auth.signOut();
};

export const getCurrentUser = async () => {
  try {
    const { data: { user }, error } = await supabase.auth.getUser();
    if (error) return null;
    return user;
  } catch (err) {
    return null;
  }
};

/* --- FAMILY & MEMBERS --- */
export const getFamilyForUser = async (userId: string) => {
  try {
    const { data, error } = await supabase
      .from('members')
      .select('family_id')
      .eq('user_id', userId)
      .maybeSingle();

    if (error) {
      console.error("Errore recupero associazione famiglia:", error.message);
      return { data: null, error };
    }
    return { data, error: null };
  } catch (err: any) {
    return { data: null, error: err };
  }
};

export const getFamilyProfile = async (familyId: string) => {
  return await supabase.from('families').select('*').eq('id', familyId).maybeSingle();
};

export const fetchFamilyMembers = async (familyId: string) => {
  const { data, error } = await supabase.from('members').select('*').eq('family_id', familyId);
  if (error) {
    console.error("Errore recupero membri:", error.message);
    return [];
  }
  return (data || []).map((m: any) => ({
    id: m.id,
    name: m.name,
    color: m.color,
    userId: m.user_id,
    isAdmin: m.is_admin
  }));
};

export const createFamilyAndJoin = async (userId: string, familyName: string, userEmail: string) => {
  const { data: existing } = await getFamilyForUser(userId);
  if (existing?.family_id) return existing.family_id;

  const familyId = crypto.randomUUID();

  const { error: famError } = await supabase.from('families').insert({
    id: familyId,
    family_name: familyName,
    created_at: new Date().toISOString()
  });

  if (famError) throw famError;

  const { error: memError } = await supabase.from('members').insert({
    user_id: userId,
    family_id: familyId,
    name: userEmail.split('@')[0],
    is_admin: true,
    color: 'bg-emerald-500'
  });

  if (memError) throw memError;

  return familyId;
};

export const joinFamily = async (userId: string, familyId: string, name: string, isAdmin: boolean = false) => {
  const { data: existing } = await getFamilyForUser(userId);
  if (existing) return { data: existing, error: null };

  return await supabase.from('members').insert({
    user_id: userId,
    family_id: familyId,
    name,
    is_admin: isAdmin,
    color: 'bg-emerald-500'
  });
};

/* --- DATA FETCHING --- */
export const fetchExpenses = async (familyId: string) => {
  const { data, error } = await supabase.from('expenses').select('*').eq('family_id', familyId).order('date', { ascending: false });
  if (error) return [];
  return (data || []).map((e: any) => ({
    id: e.id, product: e.product, quantity: e.quantity, unitPrice: e.unit_price, total: e.total,
    store: e.store, date: e.date, category: e.category, memberId: e.member_id
  }));
};

export const addExpenseToSupabase = async (familyId: string, expense: Expense) => {
  const { error } = await supabase.from('expenses').insert({
    id: expense.id, family_id: familyId, product: expense.product, quantity: expense.quantity,
    unit_price: expense.unitPrice, total: expense.total, store: expense.store, date: expense.date,
    category: expense.category, member_id: expense.memberId
  });
  if (error) throw error;
